window.__D("text/zohar/c024",{"p":[[9520011915,"<p>פָּתַח וְאָמַר, (ויקרא ו׳:י״ח) זֹאת תּוֹרַת הָעוֹלָה הִיא הָעוֹלָה, אָמַר רַבִּי שִׁמְעוֹן, כְּתִיב, (תהילים ל״ו:ז׳) אָדָם וּבְהֵמָה תּוֹשִׁיעַ יְיָ'. עוֹלָה סְלִיקוּ וּקְשִׁירוּ דְּכְּנְסֶת יִשְׂרָאֵל לְעֵילָּא, וְדִבּוּקָא דִּילָהּ בְּגוֹ עָלְמָא דְּאָתֵי, לְמֶהוֵי כֹּלָּא חַד. אִקְרֵי עוֹלָה קֹדֶשׁ קֳדָשִׁים. וּבְגִין כַּךְ אִקְרֵי עוֹלָה, דְּסַלְּקָא וְאִתְעַטְּרָא לְמֶהֱוֵי כֹּלָּא חַד. בְּקִשּׁוּרָא חֲדָא בְּחִדוּ.</p>\n<p>וּבְגִין דְּסַלְּקָא לְעֵילָּא לְעֵילָּא, כְּתִיב זֹאת תּוֹרַת הָעוֹלָה. רָזָא דְּכַר וְנוּקְבָּא כַּחֲדָא, תּוֹרָה שֶׁבִּכְתָּב וְתוֹרָה שֶׁבְּעַל פֶּה. הָעוֹלָה: דְּסַלְּקָא גּוֹ עָלְמָא דְּאָתֵי, לְאִתְקַשְּׁרָא בְּגַוֵיהּ, דְּאִקְרֵי קֹדֶשׁ הַקֳּדָשִׁים וַדַּאי, וְעוֹלָה נָמֵי קֹדֶשׁ הַקֳּדָשִׁים הִיא.</p>\n<p>וּבְגִין כַּךְ, סִדּוּרָא דִּנְכִיסוּ דִּילָהּ לִסְטַר צָפוֹן, דְּאִיהוּ סְטָר שְׂמָאלָא. דְּהַאי תּוֹרָה שֶׁבְּעַל פֶּה לָא סַלְּקָא בַּחֲבִיבוּתָא, אֶלָּא כַּד אַתְעַר סִטְרָא דְּצָפוֹן, דִּכְתִּיב, (שיר השירים ב׳:ו׳) שְׂמֹאלוֹ תַּחַת לְרֹאשִׁי וִימִינוֹ תְּחַבְּקֵנִי, וּכְדֵין אִיהִי סַלְּקָא בַּחֲבִיבוּתָא, וְאִתְעַטְּרָא בִּימִינָא, וְאִתְחֲבָּרַת בְּאֶמְצָעִיתָא, וְאִתְנְהִיר כֹּלָּא, מֵרָזָא דְּקֹדֶשׁ הַקֳּדָשִׁים, וְדָא מִגּוֹ רָזָא דְּאָדָם, בִּרְעוּ דְּכַהֲנָא, וּבְשִׁירָתָא דְּלֵיוָאֵי, וּבִצְלוֹתָא דְּיִשְׂרָאֵל.</p>\n<p>וְהָא אוֹקִימְנָא, דְּעוֹלָה קֹדֶשׁ הַקֳּדָשִׁים, בְּרָזָא דְּרוּחַ עִלָּאָה, בְּגִין דִּתְלַת רוּחִין קְשִׁירִין כַּחֲדָא, רוּחַ תַּתָּאָה, דְּאִקְרֵי (ויקרא ס\"א ע\"א) רוּחַ הַקֹּדֶשׁ רוּחַ דִּלְגוֹ בְּאֶמְצָעִיתָא דְּאִקְרֵי רוּחַ חָכְמָה וּבִינָה. וְכֵן אִקְרֵי רוּחַ תַּתָּאָה, אֲבָל הַאי אִקְרֵי רוּחַ דְּנָפִיק מִגּוֹ שׁוֹפָר, כָּלוּל בְּאֶשָּׁא וּבְמַּיָא. רוּחַ עִלָּאָה, דְּאִיהוּ סָתִים בַּחֲשָׁאי, דְּבֵיהּ קַיְימָן כָּל רוּחִין קַדִּישִׁין, וְכָל אַנְפִּין נְהִירִין. וּבְגִין כַּךְ, אַהֲדְרַת עוֹלָה רוּחַ מַמָּשׁ.</p>\n<p>וּלְבָתַר, מֵרָזָא דִּבְהֵמָה, מִסְתַּפְּקֵי וְאִתְּזָנוּ, לְאִתְקַשְּׁרָא רוּחַ אַחֲרָא דְּאִיהוּ גּוֹ מְסָאֲבוּ, מֵאִינּוּן תַּרְבִּין וְשַׁמְנוּנִין כְּמָה דְּאִתְּמַר. בְּגִין כָּךְ, עוֹלָה קֹדֶשׁ הַקֳּדָשִׁים, שְׁאַר קָרְבָּנִין לְמֶעְבַּד שְׁלָמָא בְּעָלְמָא, כֻּלְּהוּ מִכַּמָּה סִטְרִין, וּמָארֵי דִּינִין (נ\"א לאתעברא) לְאִתְעַרְבָא (נ\"א לאתעטרא) וּלְאִתְנַהֲרָא מִגּוֹ רְעוּתָא לְאִתְבַּסְּמָא, אִקְרוּן קֳדָשִׁים קַלִים, בְּגִין דְּלָא מִתְעַטְּרָא לְעֵילָּא <Nonei></i>לְעֵילָּא בְּקֹּדֶשׁ הַקָּדָשִׁים, וְעַל דָּא אִינּוּן קֳדָשִׁים קַלִים, וּנְכִיסוּ דִּילְהוֹן בְּכָל אֲתָר כְּמָה דְּאוֹקִימְנָא. אֲבָל עוֹלָה דְּאִיהוּ רָזָא דְּקֹדֶשׁ הַקָּדָשִׁים, לָאו אִיהוּ כִּשְׁאַר קָרְבָּנִין, דְּכָל עוֹבָדָהָא קֹדֶשׁ.</p>\n<p>תָּא חֲזֵי, מַה כְּתִיב (ויקרא ו׳:ג׳) וְלָבַשׁ הַכֹּהֵן מִדוֹ בַד, אִלֵּין לְבוּשִׁין מְיַיחֲדִין לִקְדוּשָּׁה. בַּד: יְחִידָאי, מְיַחֲדָא לִקְדוּשָּׁה. וּכְתִיב בִּגְדֵי קֹדֶשׁ הֵם וְרָחַץ בַּמַּיִם אֶת בְּשָׂרוֹ וּלְבֵשָׁם. מַאי טַעֲמָא. (דא קדש) אֶלָּא רָזָא דְּמִלָּה כִּדְקַאמְרָן, דְּאִיהִי קֹדֶשׁ הַקָּדָשִׁים, דְּסַלְּקָא כֹּלָּא וְאִתְעַטְּרָא בְּקֹּדֶשׁ הַקָּדָשִׁים, בְּקִשּׁוּרָא חֲדָא. וּלְבָתַר מַפְנֵי וְאַעְבַּר רוּחַ מִסְאֲבָא דְּסָאִיב כֹּלָּא, דְּלָא שַׁלְטָא, וְלָא יִתְקְרִיב גּוֹ מַקְדְּשָׁא, וְאִתְעֲבָּר מִכָּל סִטְרֵי קוּדְשָׁא, וְאִשְׁתְּאַר כֹּלָּא קֹדֶשׁ בִּקְדוּשָּׁה יְחִידָאי.</p>\n<p>וְאָמַר רִבִּי שִׁמְעוֹן, הָא אִתְּמַר (רס\"ב ע\"ב, רמ\"ד ע\"ב) דִּכְתִּיב, (תהילים ל״ו:ז׳) אָדָם וּבְהֵמָה תּוֹשִׁיעַ יְיָ'. וְהָכִי סָלְּקָא רָזָא דְּאָדָם, מִסִּטְרָא דְּאָדָם וַדַּאי. בְּהֵמָה, מִסִּטְרָא דִּבְהֵמָה. וּבְגִין כָּךְ כְּתִיב, (ויקרא א׳:ב׳) אָדָם כִּי יַקְרִיב מִכֶּם, אָדָם וַדַּאי, דְּדָא קָרְבָּנֵיהּ לְעֵילָּא, לְקַשְּׁרָא קִשְׁרָא בְּרָזָא דְּאָדָם. וּלְבָתַר מִן הַבְּהֵמָה, וְכֹלָּא אִיהוּ בְּרָזָא דְּאָדָם וּבְהֵמָה. וְדָא הוּא רָזָא דְּאִצְטְרִיךְ לְקָרְבָּנָא, אָדָם וּבְהֵמָה כִּדְקַאמְרָן. תָּא חֲזֵי, כַּד בָּרָא קוּדְשָׁא בְּרִיךְ הוּא עָלְמָא, הָכִי עֲבַד אָדָם וּבְהֵמָה.</p>\n<p>וְאִי תֵּימָא, וְהָא כְּתִיב (בראשית א׳:כ׳) וְעוֹף יְעוֹפֵף עַל הָאָרֶץ, דְּהָא מִנַּיְיהוּ מְקָרְבִין קָרְבָּנִין, וַאֲפִילּוּ עוֹלָה, כְּמָה דִּכְתִּיב, (ויקרא א׳:י״ד) וְאִם מִן הָעוֹף עוֹלָה קָרְבָּנוֹ. תָּא חֲזֵי, מִכָּל אִינּוּן עוֹפֵי, לָא מְקָרְבִין אֶלָּא תּוֹרִים וּבְנֵי יוֹנָה, (אלא רזא דא) מַה דְּאִתְכְּשַׁר בְּדָא, פָּסִיל בְּדָא דָּא יְמִינָא, וְדָא שְׂמָאלָא.</p>\n<p>אֲבָל רָזָא דָּא הָא אוֹקִימְנָא, כְּתִיב וְעוֹף יְעוֹפֵף עַל הָאָרֶץ, דְּאִינּוּן רָזָא דִּרְתִיכָא, וּבְהוּ אִסְתַּלָּק רוּחַ הַקֹּדֶשׁ, לְסַלְּקָא לְעֵילָּא, דְּאִינּוּן תְּרֵי, חַד לִימִינָא, וְחַד לִשְׂמָאלָא, עוֹף לִימִינָא, וְדָא מִיכָאֵל. יְעוֹפֵף, לִשְׂמָאלָא, וְדָא (בראשית מ\"ו ע\"א) גַּבְרִיאֵל. דָּא לִימִינָא וְדָא לִשְׂמָאלָא. וּבְגִין כָּךְ, מְקָרְבִין תְּרֵין אִלֵּין, לְסַלְּקָא רוּחַ קוּדְשָׁא, וּשְׂמָאלָא מְעַטֵּר וְזָיִין לְתַתָּא, לְהַהוּא סְטָר שְׂמָאלָא. וִימִינָא לִימִינָא וְאִתְקַשְּׁרָא אִתְּתָא בְּבַעְלָהּ, לְמֶהֱוֵי חַד, וְכֹלָּא אִסְתַּלָּק וְאִתְקָשַׁר כַּחֲדָא לְעֵילָּא וְתַתָּא, וְקוּדְשָׁא בְּרִיךְ הוּא אִסְתַּלָּק בִּלְחוֹדוֹי וְאִתָּקַף.</p>\n<p>וּבְסִפְרֵי קַדְמָאֵי, מִסְכְּנָא, לָא יָהִיב חוּלָקָא לְאַתְּזָנָא, אֶלָּא לְעֵילָּא לְאִתְקַשְּׁרָא, אֲבָל כֹּלָּא לְעֵילָּא וְתַתָּא מִתְקָשַׁר, כָּל חַד וְחַד לְסִטְרֵיהּ כְּדְקָא יֵאוֹת, וְהָא אוֹקִימְנָא. (ויקרא כ\"ו ע\"ב)</p>\n<p>רִבִּי אֶלְעָזָר שָׁאִיל לְרִבִּי שִׁמְעוֹן, אָמַר, הָא קִשּׁוּרָא דְּכֹלָּא (נ\"א דעולה), אִתְקָשַׁר בְּקֹּדֶשׁ הַקָּדָשִׁים, לְאִתְנַהֲרָא. אִתְדַּבְּקוּתָא דִּרְעוּתָא דְּכַהֲנָא וְלֵיוָאֵי וְיִשְׂרָאֵל לְעֵילָּא, עַד הֵיכָן (רמ\"ד ע\"ב, רי\"ג ע\"ב) אִיהוּ סַלְּקָא.</p>\n<p>אֲמַר לֵיהּ, הָא אוֹקִימְנָא, עַד אֵין סוֹף, דְּכָל קִשּׁוּרָא וְיִחוּדָא וּשְׁלִימוּ, לְאַצְנְעָא בְּהַהוּא צְנִיעוּ, דְּלָא אִתְדַּבָּק, וְלָא אִתְיְידַע, דְּרַעֲוָא דְּכָל רַעֲוִין בֵּיהּ, אֵין סוֹף לָא קַיְּימָא לְאוֹדָעָא, וְלַאו לְמֶעְבַּד סוֹף, וְלָאו לְמֶעְבַּד רֹאשׁ, כְּמָה דְּאָיִן קַדְמָאָה אַפִּיק רֹאשׁ וְסוֹף. מַאן רֹאשׁ. דָּא נְקוּדָה עִלָּאָה, דְּאִיהוּ רֵישָׁא דְּכֹלָּא סְתִימָאָה, דְּקַיְּימָא גּוֹ מַחֲשָׁבָה. וְעָבִיד סוֹף, דְּאִקְרֵי (קהלת יב) סוֹף דָּבָר. אֲבָל לְהָתָם, אֵין סוֹף.</p>\n<p>לָאו רְעוּתִין, לָאו נְהוֹרִין, לָאו בּוּצִינִין, בְּהַהוּא אֵין סוֹף, כָּל אִלֵּין בּוּצִינִין וּנְהוֹרִין, תַּלְיָין לְאִתְקַיְּימָא בְּהוּ, וְלָא קַיְימָא לְאִתְדַּבְּקָא מַאן דְּיָדַע וְלָא יָדַע, לָאו אִיהוּ אֶלָּא רְעוּ עִלָּאָה, סְתִימָא דְּכָל סְתִימִין, אָיִן. (צו כ\"ו ע\"ב)</p>\n<p>וְכַד נְקוּדָה עִלָּאָה, וְעָלְמָא דְּאָתֵי, אִסְתְּלָקוּ, לָא יַדְעֵי בַּר רֵיחָא, כְּמַאן דְּאָרַח בְּרֵיחָא וְאִתְבָּסָם. וְלָאו דָּא נַיְיחָא נִחוֹחַ, דְּהָא כְּתִיב (ויקרא כ״ו:ל״א) וְלֹא אָרִיחַ בָּרִיחַ נִיחֹחֲכֶם, דְּהָא רֵיחַ נִיחֹחַ, רֵיחָא דִּרְעוּתָא דְּכָל הָנֵי רְעוּתָא דִּצְלוֹתָא, וּרְעוּתָא דְּשִׁירָתָא, וּרְעוּתָא דְּכַהֲנָא, דְּכֻלְּהוּ רָזָא דְּאָדָם. כְּדֵין כֻּלְּהוּ אִתְעָבִידוּ רְעוּתָא חֲדָא, וְהַהוּא אִקְרֵי נִיחֹחַ, רַעֲוָא, כְּתַרְגּוּמוֹ. כְּדֵין כֹּלָּא אִתְקָשַׁר וְאִתְנְהִיר כַּחֲדָא, כְּדְקָא יֵאוֹת, כְּמָה דְּאִתְּמַר.</p>\n<p>וְעַל דָּא אִתְיְיהִיבַת הַאי סִטְרָא אַחֲרָא, בִּידָא דְּכַהֲנָא, דִּכְתִּיב, (ויקרא ו׳:ב׳) צַו אֶת אַהֲרֹן <Nonei></i>וְאֶת בָּנָיו לֵאמֹר, רָזָא הָכָא, דְּהָא אוֹקִימְנָא לֵית צַו אֶלָּא עֲבוֹדַת כּוֹכָבִים וּמַזָּלוֹת, וְהָכָא אִתְיְיהִיבַת לֵיהּ, לְאִתּוֹקְדָא הַהִיא מַחֲשָׁבָה רָעָה, וּלְאַעְבְּרָא לָהּ מִגּוֹ קוּדְשָׁא, בְּהַאי רְעוּתָא דְּסַלְּקָא לְעֵילָּא, וּבְהָא תְּנָנָא, וְתַרְבִּין דְּאִתּוֹקְדָן. בְּגִין לְאִתְעַבְּרָא מִן קוּדְשָׁא. וְהַאי צַו, בִּרְשׁוּתַיְיהוּ קַיְּימָא, לְאַפְרָשָׁא לָהּ מִן קוּדְשָׁא, מִגּוֹ הַאי קָרְבָּנָא. וְאִי תֵּימָא (במדבר כח) צַו אֶת בְּנִי יִשְׂרָאֵל. הָכִי נָמֵי, דְּהָא בִּרְשׁוּתַיְיהוּ קַיְּימָא, (ד\"א לאפרשא לה מן קדושה) כָּל זִמְנָא דְּעַבְדֵי רְעוּתָא דְּמָארֵיהוֹן, דְּלָא יַכְלָא לְשַׁלְּטָאָה עָלַיְיהוּ.</p>\n<p>וְהַאי קְרָא כֹּלָּא, אַתְיָא לְאַחֲזָאָה רָזָא דְּמִלָּה, לְאַעְטְּרָא לְהַהוּא רוּחַ קוּדְשָׁא, לְעֵילָּא לְעֵילָּא, וּלְאַפְרְשָׁא לָהּ לְדָא רוּחַ טוּמְאָה, לְנַחְתָּא לָהּ לְתַתָּא לְתַתָּא, דָּא בִּרְעוּתָא וּבִצְלוֹתָא כִּדְקַאמְרָן, וְדָא בְּעוֹבָדָא, כֹּלָּא כִּדְקָחָזֵי לֵיהּ.</p>\n<p>וְהַאי קְרָא מוֹכַח עָלַיְיהוּ, דִּכְתִּיב, צַו אֶת אַהֲרֹן וְאֶת בָּנָיו לֵאמֹר. צַו: דָּא עֲבוֹדַת כּוֹכָבִים וּמַזָּלוֹת רוּחַ מִסְאֲבָא. לֵאמֹר: (נח ס' ע\"א) דָּא אִתְּתָא, דְּאִקְרֵי (משלי לא) יִרְאַת יְיָ'. כְּתִיב הָכָא לֵאמֹר, וּכְתִיב הָתָם לֵאמֹר (ירמיהו ג׳:א׳) הֵן יְשַׁלַּח אִישׁ אֶת אִשְׁתּוֹ, וְהָא אוּקְמוּהָ. וּבְגִין כָּךְ, כֹּלָּא אִתְּמַר, וְכַהֲנָא קַיְּימָא לְאַתְקְנָא כֹּלָּא, בְּרָזָא (רמ\"ד ע\"ב) דְּאָדָם וּבְהֵמָה. זַכָּאָה חוּלָקֵיהוֹן דְּצַדִּיקַיָּיא, בְּעָלְמָא דֵּין, וּבְעָלְמָא דְּאָתֵי, לְאִינּוּן יַדְעֵי אָרְחֵי דְּאוֹרַיְיתָא, וְאַזְלֵי בָּהּ בְּאֹרַח קְשׁוֹט, עָלַיְיהוּ כְּתִיב, (ישעיהו ל״ח:ט״ז) יְיָ' עֲלֵיהֶם יִחְיוּ. מַאי עֲלֵיהֶם. אִלֵּין אָרְחוֹי דְּאוֹרַיְיתָא. יִחְיוּ, יִתְקַיְימוּ בְּהַאי עָלְמָא, וּבְעָלְמָא דְּאָתֵי.</p>\n<p>תָּא חֲזֵי, כְּתִיב זֹאת תּוֹרַת הָעוֹלָה, אָמַר רִבִּי חִיָיא, הַאי קְרָא אוֹקִימְנָא לֵיהּ בְּהַאי גַּוְונָא, זֹאת תּוֹרַת: דָּא כְּנֶסֶת יִשְׂרָאֵל. הָעוֹלָה: דְּאִיהִי סַלְקַת וְאִתְעַטְּרַת לְעֵילָּא לְעֵילָּא, לְאִתְקַשְּׁרָא כְּדְקָא יֵאוֹת, עַד אֲתָר דְּאִקְרֵי קֹדֶשׁ הַקָּדָשִׁים.</p>\n<p>דָּבָר אַחֵר, זֹאת תּוֹרַת: דָּא כְּנֶסֶת יִשְׂרָאֵל. הָעוֹלָה: דָּא מַחֲשָׁבָה רָעָה, דְּאִיהִי סַלְּקָא עַל רְעוּתָא דְּבַר נָשׁ, לְאַסְטָאָה לֵיהּ מֵאוֹרְחָא דִּקְשׁוֹט. הִיא הָעוֹלָה, הִיא הִיא דְּסַלְּקָא, וְאַסְטִיאַת לֵיהּ לְבַר נָשׁ, בָּעֵי לְאוֹקְדָא לֵיהּ בְּנוּרָא, בְּגִין דְּלָא יִתְיָיהִיב לָהּ דּוּכְתָּא (נ\"א לאסטאה) לְאַסְגָּאָה.</p>\n<p>וּבְגִין כָּךְ, עַל מוֹקְדָה עַל הַמִּזְבֵּחַ כָּל הַלַּיְלָה, מַאן לַיְלָה, דָּא כְּנֶסֶת יִשְׂרָאֵל. (דאיהי זאת בגין) דְּאַתְיָא לְדַכְּאָה לֵיהּ לְבַר נָשׁ, מֵהַהוּא רְעוּתָא. עַל מוֹקְדָה. בְּגִין דִּי נָהָר דִּינוּר, אִיהוּ אֲתָר לְאוֹקְדָא לְכָל אִינּוּן, דְּלָא קַיְימֵי בְּקִיּוּמַיְיהוּ, דְּהָא עָאלִין לוֹן בְּהַהוּא נוֹרָא דְּדָלִיק, וּמְעַבְּרֵי שׁוּלְטָנֵהוֹן מֵעָלְמָא. וּבְגִין דְּלָא יִשְׁלוֹט, אִצְטְרִיךְ עַל מוֹקְדָה עַל הַמִּזְבֵּחַ כָּל הַלַּיְלָה, וְאִתְכַּפְיָיא וְלָא שַׁלְטָא.</p>\n<p>וְעַל דָּא, כַּד אִתְכַּפְיָיא הַאי, סַלְּקָא כְּנֶסֶת יִשְׂרָאֵל, דְּאִיהִי רוּחַ קוּדְשָׁא, דְּסַלְּקָא וְאִתְעַטְּרָא לְעֵילָּא, דְּהָא סְלִיקוּ דִּילָהּ, כַּד אִתְכַּפְיָיא הַאי חֵילָא אַחֲרָא, וְאִתְפַּרְשָׁא מִינָּהּ. וּבְגִין כָּךְ, בָּעֵינָן בְּרָזָא דְּקָרְבְּנָא, לְאַפְרָשָׁא לְהַאי סִטְרָא מֵרוּחַ קוּדְשָׁא, וּלְמֵיהַב לָהּ חוּלָקָא, בְּגִין דְּרוּחַ קוּדְשָׁא אִסְתַּלָּק לְעֵילָּא.</p>\n<p>וְתָא חֲזֵי, בְּזִמְנָא דְּאִתְבְּנֵי בֵּי מַקְדְּשָׁא, וְאִתְעָבִיד. אִתְכַּפְיָיא סִטְרָא אַחֲרָא, וְאִסְתַּלָּק מֵעָלְמָא. וְכַד אִסְתַּלָּק מֵעָלְמָא, וְאִתְּקַם מַשְׁכְּנָא עַל יְדָא דְּמֹשֶׁה, כְּדֵין אִתְּקַם לְעֵילָּא וְתַתָּא. הֲדָא הוּא דִכְתִיב, וַיָּקֶם מֹשֶׁה אֶת הַמִּשְׁכָּן. מַאי וַיָּקֶם. אֶלָּא דְּאוֹקִים לָהּ, לְאִסְתַּלְּקָא לְעֵילָּא לְעֵילָּא. וְעַל דָּא, וַיָּקֶם מֹשֶׁה, מַאן דְּהֲוָה מָאִיךְ אוּקְמֵיהּ, כְּמַאן דְּאוֹקִים לְמַאן דְּנָפִיל. כְּגַוְונָא דָּא, לְזִמְנָא דְּאָתֵי כְּתִיב (עמוס ט׳:י״א) אָקִים אֶת סֻכַּת דָּוִד הַנּוֹפֶלֶת.</p>\n<p>כְּתִיב, (עמוס ה׳:ב׳) נָפְלָה לֹא תוֹסִיף קוּם בְּתוּלַת יִשְׂרָאֵל, מַאי לא תּוֹסִיף קוּם. (משמע דחד זמנא אחרא קמת) אֶלָּא בְּזִמְנָא אַחֲרָא קָמַת. הִיא קָמַת מִגַּרְמָהּ, וְלָא אוֹקִים לָהּ קוּדְשָׁא בְּרִיךְ הוּא. דְּהָא בְּגָלוּתָא דְּמִצְרַיִם, קוּדְשָׁא בְּרִיךְ הוּא אוֹקִים לָהּ, וְעֲבַד כַּמָה נִסִּין, בְּגִין לְאַקָּמָא לָהּ, וּבְגָלוּתָא דְּבָבֶל הוּא לָא אוֹקִים לָהּ, בְּגִין דְּלָא עֲבַד לוֹן נִסִּים, דְּגָרִים חוֹבָה, אֶלָּא הִיא קָמַת. וּסְלִיקוּ בְּנֵי גּוֹלָה, כְּאִינּוּן דְּלָא הֲוָה לוֹן פָּרוֹקָא, וְלָא הֲוָה תִּיאוּבְתָּא דְקוּדְשָׁא בְּרִיךְ הוּא עָלַיְיהוּ, בְּגִין דְּגָרַם הַהוּא חוֹבָא, <Nonei></i>דְּאִינּוּן נָשִׁים נָכְרִיּוֹת.</p>\n<p>וְעַל דָּא, קוּדְשָׁא בְּרִיךְ הוּא לָא אוֹקִים לָהּ לִכְנְסֶת יִשְׂרָאֵל, וְלָא עָבֵד לָהּ נִסִּין וּגְבוּרָאן בְּהַהוּא זִמְנָא כְּדְקָא יֵאוֹת. אֲבָל לְזִמְנָא דְּאָתֵי, לֹא תוֹסִיף קוּם כְּתִיב, לָא תּוֹסִיף, קוּם מִגַּרְמָהּ, אֶלָּא קוּדְשָׁא בְּרִיךְ הוּא יוֹקִים לָהּ, דִּכְתִּיב אָקִים אֶת סוּכַּת דָּוִד הַנּוֹפֶלֶת. וּכְתִיב (ירמיהו ל׳:ט׳) וְאֵת דָּוִד מַלְכָּם אֲשֶׁר אָקִים לָהֶם. וּבְגִין כַּךְ כְּתִיב הָכָא, וַיָּקֶם מֹשֶׁה אֶת הַמִּשְׁכָּן. וַיָּקֶם מֹשֶׁה וְגוֹ'.</p>\n<p>תָּא חֲזֵי, כַּד אוֹקִים לֵיהּ מֹשֶׁה לְמַשְׁכְּנָא, אִתְּקַם מַשְׁכְּנָא אַחֲרָא עִמֵּיהּ. וּמַשְׁכְּנָא עִלָּאָה, אוֹקִים (נ\"א אוקיר) וְסָעִיד כֹּלָּא, בְּגִין דְּמַשְׁכְּנָא עִלָּאָה, סָתִים וְגָנִיז אִיהוּ לְעֵילָּא לְעֵילָּא. וּמַשְׁכְּנָא אַחֲרָא אִתְּקַם עַל מַשְׁכְּנָא דִּלְתַתָּא וְקַיְּימָא עָלֵּיהּ, (ס\"א עמיה. ומשכנא עילאה ההוא דסתים וגניז לעילא לעילא אוקים וסעיד כלא. ומשכנא אחרא ההוא אתקם על ידא דמשכנא דלתתא קיימא עליה) בְּחֵילָא דְּהַהוּא מַשְׁכְּנָא עִלָּאָה עַל כֹּלָּא. וְכַמָּה דְּאִתְּקַם מַשְׁכְּנָא דִּלְתַתָּא עַל יְדָא דְּמֹשֶׁה, אוּף הָכִי לְעֵילָּא, עַל יְדֵי דְּהַהוּא דְבָּנֵי דְּמֹשֶׁה (נ\"א דרגא דמשה). מְנָלָן. דִּכְתִּיב, וַיָּקֶם מֹשֶׁה אֶת הַמִּשְׁכָּן. אֶת דַּיְיקָא, לְאִתְחֲזָּאָה דִּתְרֵי מַשְׁכְּנִין בְּרָזָא דְּמֹשֶׁה אִתְּקָנוּ (נ\"א אתקמו).</p>\n<p>אָמַר רִבִּי יוֹסֵי, וְכִי וַיָּקֶם מֹשֶׁה, וְהָא כֹּלָּא עַד לָא אִתְתָּקַּן, וְקִימָה לָאו אִיהוּ אֶלָּא כַּד אִשְׁתְּלִים כֹּלָּא, וְעָאל שַׁיְיפָא בְּשַׁיְיפֵיהּ, מַאי וַיָּקֶם. אָמַר רִבִּי יִצְחָק, בִּתְלַת סִטְרִין אוֹקִים מֹשֶׁה יַת מַשְׁכְּנָא, מַה כְּתִיב וַיָּקֶם מֹשֶׁה אֶת הַמִּשְׁכָּן, וַיִתֵּן אֶת אֲדָנָיו, וַיָּשֶׂם אֶת קְרָשָׁיו. בְּהָנִי תְּלַת סִטְרֵי, אוֹקִים מֹשֶׁה יַת מַשְׁכְּנָא. וּבְהָנֵי תְּלַת סִטְרֵי, אִסְתַּלָּק מַשְׁכְּנָא. וְאִתְכַּפְיָיא סִטְרָא אַחֲרָא. ועֲבוֹדָה זָרָה, כַּד אוֹקִים מֹשֶׁה לְהַאי סִטְרָא, אִתְכַּפְיָיא סִטְרָא אַחֲרָא. בְּגִין כָּךְ מֹשֶׁה אוֹקִים לֵיהּ וְלָא אַחֲרָא.</p>\n<p>תָּא חֲזֵי, כְּתִיב וַיִתֵּן אֶת אֲדָנָיו, בְּהַהִיא שַׁעֲתָא אִזְדַּעְזָע סָמָאֵ\"ל מֵאַתְרִיהּ, וְאַרְבְּעִין רְתִיכִין דְּעִמֵּיהּ, וְעָרַק אַרְבַּע מֵאָה פַּרְסֵי, גּוֹ טְסִירוּ דְּנוּקְבָּא דְּעַפְרָא. אָעִיל מֹשֶׁה אִינּוּן סַמְכִין, וְאִתָּקִיף סִטְרָא דָּא, כְּדֵין אִינּוּן סַמְכִין דְּסִטְרָא אַחֲרָא, נָפְלוּ וְאִתְרְפוּ.</p>\n<p>פָּתַח וְאָמַר, בַּיוֹם הַהוּא אָקִים אֶת סֻכַּת דָּוִד הַנּוֹפֶלֶת וְגוֹ', מַאי בַּיוֹם הַהוּא. בְּיוֹמָא דְּקוּדְשָׁא בְּרִיךְ הוּא יַעְבִּיד דִּינָא בְּעָלְמָא, וְיִפְקוֹד עַל חַיָּיבֵי עָלְמָא כְּעוֹבָדֵיהוֹן. דְּהָא לֵית קִימָה לִכְנֶסֶת יִשְׂרָאֵל מֵעַפְרָא, בְּעוֹד דְּאִינּוּן חַיָּיבִין דְּיִשְׂרָאֵל יְקוּמוּן בְּעָלְמָא. מַה כְּתִיב לְעֵילָּא, (עמוס ט׳:י׳) בַּחֶרֶב יָמוּתוּ כֹּל חֲטָּאֵי עַמִּי הָאוֹמְרִים לא תַגִישׁ וְתַקְדִּים בַּעֲדֵנוּ הָרָעָה. מַה כְּתִיב בַּתְרֵיהּ, בַּיוֹם הַהוּא אָקִים אֶת סֻכַּת דָּוִד הַנּוֹפֶלֶת וְגוֹ'.</p>\n<p>הַאי קְרָא אִית לְאִסְתַּכְּלָא בֵּיהּ, (עמוס) אֶת פִּרְצֵיהֶן, אֶת פִּרְצָהּ מִבָּעֵי לֵיהּ. וַהֲרִיסוֹתָיו, וַהֲרִיסוֹתֶיהָ מִבָּעֵי לֵיהּ. אֶלָּא וְגָדַרְתִּי אֶת פִּרְצֵיהֶן מִמַּאן, מֵאִינּוּן חַיָּיבִין, דִּכְתִּיב בַּחֶרֶב יָמוּתוּ כֹּל חַטָּאֵי עַמִּי, דְּהָא כְּדֵין יִתְעֲבִיד פִּרְצָן בְּיִשְׂרָאֵל, וְעַל דָּא וְגָדַרְתִּי אֶת פִּרְצֵיהֶן. וַהֲרִיסוֹתָיו אָקִים, הֲרִיסוֹתָיו דְּמַאן, הֲרִיסוֹתָיו דְּסוּכַּת דָּוִד. (ממאן מדוד) בְּגִין, דְּכַד אִתָּקַף מַלְכוּ חַיָּיבָא בְּעָלְמָא, כְּדֵין הַאי מַלְכוּ קַדִּישָׁא אִתְרַפֵי, וְסֻכַּת דָּוִד אַסְתִּיר בִּנְיָינָא דִּילֵיהּ, וְעַל דָּא וַהֲרִיסוֹתָיו אָקִים.</p>\n<p>דְּהָא תָּנֵינָן, כָּל זִמְנָא דְּהַאי אִתָּקַף, הַאי אִתְרַפֵי. דָּא מַלְיָא, וְדָא חָרְבָה. וּבְגִין כָּךְ, עַד הַהוּא יוֹמָא, מַלְכוּ חַיָּיבָא יִתְקַף. בְּהַהוּא יוֹמָא, יִתָּקַף וְיוֹקִים לָהּ קוּדְשָׁא בְּרִיךְ הוּא, לְהַאי מַלְכוּ קַדִּישָׁא. וְעַל דָּא וַהֲרִיסוֹתָיו אָקִים. וּבְנִיתִיהָ כִּימֵי עוֹלָם, מַאי וּבְנִיתִיהָ כִּימֵי עוֹלָם. הַיְינוּ דִּכְתִּיב, (ישעיהו ל׳:כ״ו) וְהָיָה אוֹר הַלְּבָנָה כְּאוֹר הַחַמָּה וְגוֹ'.</p>\n<p>(שמות לט) וַיָּקֶם מֹשֶׁה אֶת הַמִּשְׁכָּן, בְּמַאי אוֹקִים לֵיהּ. דִּכְתִּיב וַיִתֵּן אֶת אֲדָנָיו וְיָהַב אִינּוּן סַמְכִין דִּתְחוֹתֵיהּ, לְקַיְּימָא עָלַיְיהוּ, וּלְאַסְחֲרָא בְּהוּ אִינּוּן צִירִים דְּפִתְחִין. בְּגִין דְּאִינּוּן סַמְכִין דִּתְחוֹתַיְיהוּ, אִינּוּן קִיוּמָא לְאַסְחֲרָא. אֲמַאי וַיִתֵּן. אַתְקִיף וְאַתְקִין לוֹן בְּתוּקְפוֹי. בְּהַהִיא שַׁעֲתָא אַעְדִּיוּ אִינּוּן סַמְכִין אַחֲרָנִין דְּסִטְרָא אַחֲרָא.</p>\n<p>תָּא חֲזֵי, כְּתִיב (תהילים קל״ז:ז׳) זְכוֹר יְיָ' לִבְנִי אֱדוֹם אֶת יוֹם יְרוּשָׁלַ ם הָאוֹמְרִים עָרוּ עָרוּ עַד הַיְסוֹד בָּה. וְעַל דָּא זַמִּין קוּדְשָׁא בְּרִיךְ הוּא לְמִבְנֵי יְסוֹדֵי יְרוּשָׁלַ ם, מִיְסוֹדִין אַחֲרָנִין, דְּיִשְׁלְטוּן עַל כֹּלָּא. וּמַאן אִינּוּן. סַפִּירִין. דִּכְתִּיב, (ישעיהו נ״ד:י״א) וִיסַדְתִּיךְ בַּסַּפִּירִים, דְּאִלֵּין אִינּוּן יְסוֹדִין, וְסַמְכִין תַּקִּיפִין וְעִלָּאִין, דְּלֵית לְהוּ חֲלִישׁוּ כְּקַדְמָאֵי. מַאי טַעֲמָא. בְּגִין דְּאֲבָנִין <Nonei></i>קַדְמָאִין מֵאִינּוּן יְסוֹדֵי, יָכִילוּ שְׁאַר עַמִּין לְמִשְׁלַט עָלַיְיהוּ. מַאי טַעֲמָא. בְּגִין דְּלֵית בְּהוּ נְהִירוּ עִלָּאָה, כְּדְקָא יֵאוֹת. אֲבָל אִלֵּין, יְהוֹן נְהִירִין מִגּוֹ נְהִירוּ עִלָּאָה, וּמְשַׁקְּעָאן גּוֹ תְּהוֹמֵי, דְּלָא יַכְלִין לְשַׁלְּטָאָה עָלַיְיהוּ. וְאִלֵּין אִינּוּן סַפִּירִין, דְּיִנְהֲרוּן לְעֵילָּא וְתַתָּא. (ואי תימא) בְּגִין דִּבְהַהוּא זִמְנָא, יִתּוֹסַף נְהִירוּ עִלָּאָה, לְעֵילָּא וְתַתָּא.</p>\n<p>וְאִי תֵּימָא אִינּוּן יְסוֹדֵי קַדְמָאֵי, יִתְבַטְּלוּן. הָא כְּתִיב (ישעיהו נ״ד:י״א) הִנֵּה אָנֹכִי מַרְבִּיץ בַּפּוּךְ אֲבָנַיִךְ. מַרְבִּיץ לְאַתְקְנָא תְּבִירָא. מַאי בַּפּוּךְ. כְּמָה דְאַתְּ אָמֵר (מלכים ב ט׳:ל׳) וַתָּשֶׂם בַּפּוּךְ עֵינֶיהָ. אֲבָנִים אִית דְּאִקְרוּן פּוּךְ. מַאי טַעֲמָא הַאי. אָמַר רִבִּי אֶלְעָזָר רָזָא אִיהוּ, וְרָזָא דָּא לִמְחַצְדֵי חַקְלָא אִתְיְיהִיב לְמִנְדַּע.</p>\n<p>תָּא חֲזֵי, אִינּוּן אֲבָנִין דִּיְסוֹדֵי צִיּוֹן וִיְרוּשָׁלַם, חַס וְשָׁלוֹם דִּשְׁלִיטוּ עָלַיְיהוּ שְׁאַר עַמִּין, וְלָא אוֹקְדוּ לוֹן, וְלָא אִתּוֹקְדוּן, אֶלָּא כֻּלְּהוּ אִתְגְּנִיזוּ, וְגָנִיז לוֹן קוּדְשָׁא בְּרִיךְ הוּא, וְכָל אִינּוּן יְסוֹדֵי בֵּיתָא קַדִּישָׁא כֻּלְּהוּ אִתְגְּנִיזוּ, וְלָא אִתְאֲבִידוּ מִנַּיְיהוּ אֲפִילּוּ חַד. וְכַד יֶהְדַּר קוּדְשָׁא בְּרִיךְ הוּא וְיוֹקִים לָהּ לִיְרוּשָׁלַם עַל אַתְרֵיהּ, אִינּוּן יְסוֹדֵי אֲבָנִין קַדְמָאֵי, יָהַדְרוּן לְאַתְרַיְיהוּ, וְלָא יַשְׁלִיט בְּהוּ עֵינָא אַחֲרָא (נ\"א בישא), בַּר בְּזִמְנָא דְּיִכְחוֹל בַּר נָשׁ עֵינוֹי בְּהַהוּא פּוּכָא, וְיִמְלֵי עֵינֵיהּ מִנֵּיהּ, וּכְדֵין יֶחֱמֵי כָּל אֲבָנִין וְכָל יְסוֹדֵי יְרוּשָׁלַ ם, מְתֻקְּנָן עַל אַתְרַיְיהוּ, דְּלָא שָׁלִיטוּ בְּהוּ שְׁאַר עַמִּין, וְכָל אִינּוּן אֲבָנִין יְקָרִין אַחֲרָנִין, וְכָל אִינּוּן בִּנְיָינִי אֲבָנִין, כֻּלְּהוּ קַיְימֵי עַל קִיוּמַיְיהוּ.</p>\n<p>וּכְדֵין (ישעיהו נ״ב:ח׳) כִּי עַיִן בְּעַיִן יִרְאוּ בְּשׁוּב יְיָ' צִיּוֹן. מַאי בְּשׁוּב יְיָ'. אֶלָּא כַּד שְׁלִיטוּ עָלָהּ שְׁאַר עַמִּין, קוּדְשָׁא בְּרִיךְ הוּא סָלִיק לָהּ לְעֵילָּא, וּבְהַהוּא זִמְנָא אִיהוּ יֶהְדַּר לָהּ לְאַתְרָהּ, דִּכְתִּיב בְּשׁוּב יְיָ' צִיּוֹן. בְּשׁוּב יְיָ' וַדַּאי.</p>\n<p>וְתָא חֲזֵי, כָּל מַאן דְּאַסְתִּים מִן עֵינָא, וְלָא אִתְיְיהִיב רְשׁוּ לְשַׁלְּטָאָה בֵּיהּ עֵינָא, לָא יַכְלִין לְמִשְׁלַט בֵּיהּ עֵינָא, בַּר בְּכִחְלָא דְּעֵינָא, בְּמִלִּין יְדִיעָאן. וּבְגִין כָּךְ, הִנִּה אָנֹכִי מַרְבִּיץ בַּפּוּךְ אֲבָנַיִךְ. וְתָּא חֲזֵי, כָּל אִלֵּין אֲבָנִין יִתְקַיְּימוּן בְּאַתְרַיְיהוּ, וְלֶהֱווֹ יִסוֹדִין כְּקַדְמֵיתָא, וִיסוֹדֵי סַפִּירִין (אחרנין) יִתְקַיְּימוּן בַּאֲתָר אַחֲרָא סָחֲרָנָא, לְפוּתְיָא וּלְאַרְכָּא, הֲדָא הוּא דִכְתִיב וִיסַדְתִּיךְ בַּסַּפִּירִים.</p>\n<p>בְּזִמְנָא דְּיוֹקִים קוּדְשָׁא בְּרִיךְ הוּא לְבֵיתֵיהּ, בְּהַהוּא זִמְנָא מַה כְּתִיב, (ישעיהו כ״ה:ח׳) בִּלַּע הַמָּוֶת לָנֶצַח. בִּלַּע, כִּדְאָמְרִינָן (איכה ב) בִּלַּע יְיָ' וְלֹא חָמַל, הַהוּא כּוֹס דְּשָׁתָה הַאי, יִשְׁתֶּה הַאי.</p>\n<p>וְאִי תֵּימָא, הַהוּא בִּלַּע אִיהוּ לִזְמַן יְדִיעָא וְקָצִיב כְּיִשְׂרָאֵל, לָאו הָכִי. כְּתִיב לָנֶצַח, מַאי לָנֶצַח. לְדָרֵי דָּרִין. וְלָאו כְּיִשְׂרָאֵל, וְלָאו כְּהַהוּא זִמְנָא דְּאוֹקִים מֹשֶׁה יַת מַשְׁכְּנָא. אֶלָּא לָנֶצַח לְעָלְמִין.</p>\n<p>וּכְדֵין קוּדְשָׁא בְּרִיךְ הוּא יוֹקִים לָהּ לִכְּנְסֶת יִשְׂרָאֵל, וְאִיהוּ יוֹקִים סַמְכִין, וְסֵיפֵי, וְכָל אִינּוּן תִּקְרֵי בֵּיתָא, בְּתִקּוּנוֹי, (ס\"א בתקיפו) לְעָלַם וּלְעָלְמֵי עָלְמַיָּא. וּכְתִיב (ישעיהו נ״ד:ב׳) הַרְחִיבִי מְקוֹם אָהֳלֵךְ וְגוֹ', בְּגִין דְּיִתְבְלַע סִטְרָא אַחֲרָא, וְלָא יְקוּם לְעָלְמִין וּכְדֵין, (ישעיהו כ״ה:ח׳) וְחֶרְפַּת עַמּוֹ יָסִיר מֵעַל כָּל הָאָרֶץ כִּי יְיָ' דִּבֵּר.</p>\n<p>(שמות לט) וַיָּקֶם מֹשֶׁה אֶת הַמִּשְׁכָּן, בְּהַהוּא זִמְנָא דְּאִלֵּין סַמְכִין אִתְּקָמוּ, וְאִתְיְיהִיבוּ בְּאַתְרַיְיהוּ, הַהוּא זִמְנָא אִתְרְפוּ וְאִתְעֲבָרוּ מֵאַתְרַיְיהוּ סַמְכִין בַּאֲתָר סְטָר אַחֲרָא, וְעַל דָּא, וְיִּתֵּן אֶת אֲדָנָיו.</p>\n<p>מַאי וְיִּתֵּן. אֶלָּא אוֹלִיפְנָא, דְּחָמָא מֹשֶׁה לְקַמֵּיהּ לְסָמָאֵ\"ל חַיָּיבָא, דְּהֲוָה אָזִיל לְגַבֵּיהּ לְקַטְרְגָא לֵיהּ, וּכְדֵין אַתְקִיף בֵּיהּ מֹשֶׁה, וְקָשִׁיר לֵיהּ קַמֵּיהּ, וְאוֹקִים לֵיהּ לְמַשְׁכְּנָא, וְיָהַב לְסַמְכוֹי. דִּכְתִּיב וְיִּתֵּן אֶת אֲדָנָיו. וְיִּתֵּן: בִּתְקִיפוּ, דְּלָא יָכִיל בַּר נָשׁ אַחֲרָא לְשַׁלְּטָאָה עָלֵיהּ, וּלְמֵיהַב סַמְכִין בְּאַתְרַיְיהוּ, כְּמֹשֶׁה. דְּהָא בִּתְקִיפוּ רַב, אוֹקִים לֵיהּ מֹשֶׁה.</p>\n<p>בְּהַהוּא יוֹמָא דְּאִתְּקַם מַשְׁכְּנָא, כַּד שָׁאֲרִי מֹשֶׁה לְאַקָּמָא לֵיהּ, בְּחַד בְּנִיסָן הֲוָה, וּבְהַהוּא זִמְנָא, תְּקִיפוּ דְסִטְרָא אַחֲרָא הֲוָה בְּעָלְמָא, דְּהָא בְּיוֹמֵי דְּנִיסָן, רֵישׁ תּוֹרָא בְּדִיקוּלָא (סליק לאגרא). תָּנֵינָן. וּבְנִיסָן שָׁארֵי מֹשֶׁה, וְחָמָא לֵיהּ לְסָמָאֵ\"ל, אָזִיל סַחֲרָנֵיהּ, לְעַרְבְּבָא לֵיהּ, וְאִתְגַּבָּר עָלֵיהּ מֹשֶׁה, וּכְדֵין, וַיִּתֵּן אֶת אֲדָנָיו. שָׁארֵי הוּא וְיָהַב לְתַתָּא, וְשָׁארִי מַאן דְּשָׁארִי וְיָהַב <Nonei></i>לְעֵילָּא דָּא לָקֳבֵל דָּא.</p>\n<p>בְּיוֹמָא דְּאִתְּקַם הַאי מַשְׁכְּנָא לְתַתָּא, אִתְּקַם מַשְׁכְּנָא אַחֲרָא קַדִּישָׁא לְעֵילָּא, וּמַשְׁכְּנָא עִלָּאָה טָמִיר וְגָנִיז, אַפִּיק נְהוֹרִין לְכָל סְטָר, וְאִתְנָהַרוּן עָלְמִין.</p>\n<p>רִבִּי יוֹסֵי שָׁאִיל לְרִבִּי שִׁמְעוֹן, אֲמַר לֵיהּ, תְּלַת מַשְׁכְּנִין חֲמֵינָן בַּקְּרָא, דִּכְתִּיב, (במדבר ט׳:ט״ו) וּבְיוֹם הָקִים אֶת הַמִּשְׁכָּן, כִּסָּה הֶעָנָן אֶת הַמִּשְׁכָּן לְאֹהֶל הָעֵדוּת, וּבָעֶרֶב יִהְיֶה עַל הַמִּשְׁכָּן כְּמַרְאֵה אֵשׁ עַד בֹּקֶר, הָא תְּלַת מַשְׁכְּנִין הָכָא. וַאֲמַאי מַשְׁכְּנָא, וְלָא בַּיִת, דְּהָא בַּיִת אִצְטְרִיךְ וְלָא מִשְׁכָּן.</p>\n<p>פָּתַח וְאָמַר, (ישעיהו ס״ו:א׳) כֹּה אָמַר יְיָ' הַשָּׁמַיִם כִּסְאִי וְגוֹ'. תָּא חֲזֵי, קוּדְשָׁא בְּרִיךְ הוּא אִתְרְעֵי בְּהוּ בְּיִשְׂרָאֵל לְאַחֲסַנְתֵּיהּ וְעַדְבֵיהּ, וְקָרִיב לוֹן לְגַבֵּיהּ. וְהָא אוֹקִימְנָא דְּעֲבַד מִנַּיְיהוּ דַּרְגִּן יְדִיעָן בְּהַאי עָלְמָא, כְּגַוְונָא דִּלְעֵילָּא, לְשַׁכְלְלָא עָלְמִין כֻּלְּהוּ כְּחַד, עֵילָּא וְתַתָּא. דִּכְתִּיב הַשָּׁמַיִם כִּסְאִי וְהָאָרֶץ הֲדוֹם רַגְלָי לְשַׁכְלְלָא עֵילָּא וְתַתָּא לְמֶהוֵי חַד.</p>\n<p>תָּא חֲזֵי, הַשָּׁמַיִם כִּסְאִי, דָּא רְקִיעָא דְּיַעֲקֹב שַׁרְיָא בֵּיהּ, דְּאִיהוּ דִּיּוּקְנָא עִלָּאָה, לְכוּרְסְיָיא (ס\"א כורסייא עלאה לדיוקנא) עִלָּאָה קַדִּישָׁא. וְהָאָרֶץ הֲדוֹם רַגְלָי, דָּא רְקִיעָא דְּדָוִד מַלְכָּא שַׁרְיָא בֵּיהּ, לְאִתְהֲנָאָה מִזִּיוָא דְּאַסְפָקָלַרְיָא דְּנַהֲרָא. וּבְגִין דְּבָעֵי לְאִתְפַּשְׁטָא יַתִּיר לְתַתָּא אָמַר הֲדוֹם רַגְלָי. אֵיזֶה בַיִת אֲשֶׁר תִּבְנוּ לִי, דָּא בִּנְיַן בֵּית מַקְדְּשָׁא. וְאֵיזֶה מָקוֹם מְנוּחָתִי, דָּא בֵּית קֹדֶשׁ הַקָּדָשִׁים דִּלְתַתָּא.</p>\n<p>אֲבָל תָּא חֲזֵי, כָּל זִמְנָא דְּאָזְלוּ יִשְׂרָאֵל בְּמַדְבְּרָא, הֲוָה לְהוּ מִשְׁכָּן, עַד דְּאָתוּ לְשִׁילֹה, וַהֲוָה תַּמָּן. וְדָא אִיהוּ רָזָא, לְאַמְשָׁכָא דָּא בְּדָא, וּלְאַעֲלָא דָּא בְּדָא, לְאִתְקַשְּׁרָא דָּא בְּדָא, בְּגִין לְאַנְהָרָא. אֲבָל לָאו לְנַיְיחָא. דְּהָא לָאו נַיְיחָא, בַּר כַּד אִתְבְּנֵי בֵּי מַקְדְּשָׁא, בְּיוֹמוֹי דִּשְׁלֹמֹה מַלְכָּא, דְּהָא כְּדֵין אִיהוּ מְנוּחָה לְעֵילָּא וְתַתָּא. בְּגִין דְּתַמָּן תְּקִיפוּ דְּנַיְיחָא, וְלָא לְנַטְלָא מֵאֲתָר לַאֲתָר.</p>\n<p>וּבְגִין כַּךְ אִית מִשְׁכָּן, וְאִית בַּיִת. מִשְׁכָּן: כְּמָה דְּאַתְּ אָמֵר, (ויקרא כ״ו:י״א) וְנָתַתִּי מִשְׁכָּנִי בְּתוֹכְכֶם וְלא תִגְעַל נַפְשִׁי אֶתְכֶם. מַאי מִשְׁכָּנִי. מִשְׁכְּנוֹתָיו דְּקוּדְשָׁא בְּרִיךְ הוּא, דְּלִהווֹן גַּבַּיְיהוּ דְּיִשְׂרָאֵל. מַאי טַעֲמָא. בְּגִין דִּכְתִּיב וְלֹא תִגְעַל נַפְשִׁי אֶתְכֶם.</p>\n<p>מַה בֵּין הַאי לְהַאי. אֶלָּא מִשְׁכָּן, כְּמַלְכָּא דְּאָתֵי לְגַבֵּי רְחִימֵיהּ, וְלָא מַיְיתֵי כָּל אֻכְלוּסִין דִּילֵיהּ עִמֵּיהּ, בְּגִין דְּלָא לְאַטְרְחָא עָלֵיהּ, אִיהוּ אָתֵי לְגַבֵּיהּ בִּזְעֵיר חֵילִין. בַּיִת: דְּכָל חֵילִין וְכָל (ויקרא ב' ע\"ב) אֹכְלוֹסִין דִּילֵיהּ, כֻּלְּהוּ אַיְיתֵי עִמֵּיהּ, לְדַיְּירָא בְּהַהוּא בֵּיתָא, וְדָא אִיהוּ בֵּין מִשְׁכָּן וּבֵין בַּיִת. בֵּית הַמִּקְדָּשׁ, אִיהוּ דִּיּוּרָא דְּנַיְיחָא לְעָלְמִין, בְּכָל אִינּוּן רְתִיכִין, בְּכָל אִינּוּן דִּיוּקְנִין, בְּכָל אִינּוּן עוֹבָדִין, כְּגַוְונָא דִּלְעֵילָּא. לְתַבְּרָא (ד\"א לחברא) עוֹבָדִין דִּלְתַתָּא, כְּגַוְונָא דִּלְעֵילָּא. מִשְׁכָּן, בִּזְעֵיר דִּיוּקְנִין, בִּזְעִירִין עוֹבָדִין, לְנַטְלָא מֵאֲתָר לַאֲתָר, וְכֹלָּא בְּרָזָא דִּלְעֵילָּא.</p>\n<p>תָּא חֲזֵי, כַּד פָּקִיד קוּדְשָׁא בְּרִיךְ הוּא לְמֹשֶׁה עַל מַשְׁכְּנָא, לָא הֲוָה יָכִיל לְמֵיקָם בֵּיהּ, עַד דְקוּדְשָׁא בְּרִיךְ הוּא אַחְמֵי לֵיהּ כֹּלָּא בְּדִיוּקְנֵיהּ, כָּל מִלָּה וּמִלָּה. בְּמָּה אַחְזֵי לֵיהּ. בְּאֶשָּׁא חִוָּורָא, וּבְאֶשָּׁא אוּכָמָא, וּבְאֶשָּׁא סוּמָקָא, וּבְאֶשָּׁא יְרוֹקָא. מַה כְּתִיב, (שמות כ״ה:מ׳) וּרְאֵה וַעֲשֵׂה כְּתַבְנִיתָם אֲשֶׁר אַתָּה מָרְאֶה בָּהָר. עִם כָּל דָּא אַקְשֵׁי לֵיהּ לְמֹשֶׁה.</p>\n<p>תָּא חֲזֵי, אַף עַל גַּב דְּאַחְזֵי לֵיהּ עֵינָא בְּעֵינָא לָא בָּעָא מֹשֶׁה לְמֶעְבַּד. וְאִי תֵּימָא דְּאִיהוּ לָא יָדַע לְמֶעְבַּד, אוֹ חָכְמְתָא לָא הֲוָה עִמֵּיהּ. תָּא חֲזֵי, בְּצַלְאֵל וְאָהֳלִיאָב, וְכָל אִינּוּן שְׁאַר אַחֲרָנִין, אַף עַל גַּב דְּלָא חָמוּ כְּמֹשֶׁה, מַה כְּתִיב, וַיַּרְא מֹשֶׁה אֶת כָּל הַמְּלָאכָה וְהִנִּה עָשׂוּ אוֹתָהּ וְגוֹ', אִי אִינּוּן דְּלָא חָמוּ, עָבְדוּ כַּךְ. מֹשֶׁה דְּחָמָא, עַל אַחַת כַּמָה וְכַמָּה. אֶלָּא מֹשֶׁה, אַף עַל גַּב דְּאִסְתַּלָּק מִן מַשְׁכְּנָא מֵעֲבִידָתָא, כֹּלָּא הֲוָה בִּידֵיהּ, וְעַל יְדֵיהּ, וְאִיהוּ אִקְרֵי עַל שְׁמֵיהּ, וְעַל דָּא כְּתִיב וּרְאֵה וַעֲשֵׂה.</p>\n<p>דָּבָר אַחֵר, מֹשֶׁה אִסְתַּלָּק מִן דָּא, וְיָהִיב דּוּכְתֵּיהּ לְאַחֲרָא, עַד דְּאָמַר לֵיהּ קוּדְשָׁא <Nonei></i>בְּרִיךְ הוּא (שמות ל״א:ב׳) רְאֵה קָרָאתִי בְשֵׁם בְּצַלְאֵל, וְאִתּוֹ אָהֳלִיאָב. וּכְתִיב וְעָשָׂה בְּצַלְאֵל וְאָהֳלִיאָב וְכֹל אִישׁ חֲכַם לֵב. אִי יְקָרָא דָּא, הֲוָה דְּמֹשֶׁה, דְּאִיהוּ יַעְבִּיד לֵיהּ, יִתְקְיָּים בֵּיהּ תָּדִיר. (ס\"א יתיר תדיר)</p>\n<p>וְעִם כָּל דָּא, כֵּיוָן דְּאִיהוּ פָּקִיד, וּבְפִקוּדֵיהּ יִתְעֲבִיד, אִיהוּ עָבִיד כֹּלָּא. תּוּ, כָּל עֲבִידְתָּא לָא קַיְּימָא, אֶלָּא בְּסִיוּמָא דְּעוֹבָדָא, וְעַל דָּא, וַיָּקֶם מֹשֶׁה אֶת הַמִּשְׁכָּן. בָּעוּ לְאַקָּמָא לֵיהּ כָּל אִינּוּן חַכִּימֵי לִבָּא, וְלָא הֲוָה מִתְקַיֵּים, בְּגִין יְקָרֵיהּ דְּמֹשֶׁה, עַד דְּאָתָא מֹשֶׁה, וְאוֹקִים לֵיהּ. וְהָא אוּקְמוּהָ.</p>"],[9520011916,"<p>(שמות מ׳:י״ח) וַיָּקֶם מֹשֶׁה אֶת הַמִּשְׁכָּן רִבִּי יְהוּדָה פָּתַח, (מיכה ז׳:ח׳) אַל תִּשְׂמְחִי אוֹיַבְתִּי לִי כִּי נָפַלְתִּי קָמְתִּי וְגוֹ'. מַאן אוֹיַבְתִּי לִי. דְּבָבוּ דְּמַלְכוּ חַיָּיבָא בְּמַלְכוּת קַדִּישָׁא. וְהַאי קְרָא כְּנֶסֶת יִשְׂרָאֵל אָמַר לֵיהּ, אַל תִּשְׂמְחִי אוֹיַבְתִּי לִי כִּי נָפַלְתִּי קָמְתִּי, מַה דְּלֵית לָךְ הָכִי (נ\"א לה הכי) לְמַלְכוּ אַחֲרָא, דְּכֵיוָן דְּתִפּוֹל לָא תָּקוּם לְעָלְמִין. אֲבָל כְּנֶסֶת יִשְׂרָאֵל, אַף עַל גַּב דְּנַפְלַת, תָּקוּם וְקָמַת שְׁאַר זִמְנִין. דִּכְתִּיב כִּי נָפַלְתִּי קָמְתִּי.</p>\n<p>דְּהָא כַּמָה זִמְנִין נַפְלַת כְּנֶסֶת יִשְׂרָאֵל בְּגָלוּתָא, וְיָתְבָא בֵּין אִינּוּן מָארֵי דְּבָבוּ, וּשְׁאַר עַמִּין קָמוּ עָלַיְיהוּ דְּיִשְׂרָאֵל לְשֵׁיצָאָה לוֹן מֵעָלְמָא, (ולא יכילו) כְּמָה דְאַתְּ אָמֵר, (תהילים פ״ג:ד׳) עַל עַמְּךָ יַעֲרִימוּ סוֹד, וּכְתִיב כִּי נוֹעֲצוּ לֵב יַחְדָּיו וְגוֹ', אָמְרוּ לְכוּ וְנַכְחִידֵם מִגּוֹי. וְעִם כָּל דָּא, אַף עַל גַּב דִּשְׁאַר עַמִּין קָמוּ עָלַיְיהוּ, קוּדְשָׁא בְּרִיךְ הוּא לָא אֲנָח לוֹן בִּידַיְיהוּ, וְאִי נָפְלוּ קָמוּ, דִּכְתִּיב כִּי נָפַלְתִּי קָמְתִּי. דְּהָא קוּדְשָׁא בְּרִיךְ הוּא אָקִים לָהּ תָּדִיר.</p>\n<p>וּזְמִינָא כְּנֶסֶת יִשְׂרָאֵל, לוֹמַר בְּהַהוּא זִמְנָא דְקוּדְשָׁא בְּרִיךְ הוּא יוֹקִים לָהּ מֵעַפְרָא דְּגָלוּתָא, וְתִסְתָּלַק מִנֵּיהּ, אַל תִּשְׂמְחִי אוֹיַבְתִּי לִי כִּי נָפַלְתִּי קָמְתִּי. כִּי נָפַלְתִּי בְּגָלוּתָא, וְאִשְׁתַּעְבְּדוּ בָּנַי, קָמְתִּי בְּהַאי זִמְנָא. וּבְגִין כַּךְ, בְּהַהוּא זִמְנָא דְּאַפִּיק מֹשֶׁה לוֹן לְיִשְׂרָאֵל, כַּד עָבֵד לוֹן קוּדְשָׁא בְּרִיךְ הוּא אִינּוּן נִסִּין וּגְבוּרָאן דְּעָבַד לוֹן. כְּדֵין וַיָּקֶם מֹשֶׁה אֶת הַמִּשְׁכָּן כְּתִיב, דְּהָא עַל יְדָא דְּמֹשֶׁה אִתְּקַם בְּכָל זִמְנָא.</p>"],[9520011917,"<p>רִבִּי שִׁמְעוֹן פָּתַח וְאָמַר, (יחזקאל א׳:כ״א) בְּלֶכְתָּם יֵלֵכוּ וְגוֹ'. בְּלֶכְתָּם יֵלֵכוּ וּבְעָמְדָם יַעֲמֹדוּ. הַאי קְרָא אִית לְאִסְתַּכְּלָא בֵּיהּ. בְּלֶכְתָּם יֵלֵכוּ, וְכִי לָא יְדַעְנָא דְּהָא בְּלֶכְתָּם יֵלֵכוּ, וּבְעָמְדָם יַעֲמֹדוּ. אֶלָּא בְּלֶכְתָּם דְּמַאן. בְּלֶכְתָּם דְּחַיּוֹת. דְּכַד אִינּוּן אַזְלִין, אִינּוּן אוֹפַנִּים יֵלֵכוּ. כְּמָה דְאַתְּ אָמֵר וּבְלֶכֶת הַחַיּוֹת יֵלְכוּ הָאוֹפַנִּים אֶצְלָם. וְעַל דָּא בְּלֶכְתָּם יֵלֵכוּ וּבְעָמְדָם יַעֲמֹדוּ, בְּגִין דְּכָל מַטַלְנֵיהוֹן דְּאִינּוּן אוֹפַנִּים, לָאו אִינּוּן אֶלָּא בְּמַטְלָנִין דְּחַיּוֹת, וְקִיּוּמָא דִּילְהוֹן לָא קַיְימֵי בְּאַתְרַיְיהוּ, אֶלָּא כֹּלָּא תַּלְיָא בַּחַיוֹת. וְכֵן כְּתִיב וּבְהִנָּשֵׂא הַחַיּוֹת מֵעַל הָאָרֶץ יִנָּשְׂאוּ הָאוֹפַנִּים לְעֻמָּתָם בְּגִין דְּחַיּוֹת וְאוֹפַנִּים כַּחֲדָא אַזְלִין.</p>\n<p>וְתָּא חֲזֵי, עֶשְׂרִין וְאַרְבַּע מַשְׁקּוֹפִין, דְּמַטְרָנִין עִלָּאִין קַיְימִין גּוֹ מַשְׁקוֹפָא חֲדָא דְּבִסְטַר מִזְרָח. לְהַאי פִּתְחָא, נַטְרִין אַרְבַּע וְעֶשְׂרִין מִשְׁמָרוֹת, טְמִירִין גּוֹ תּוּקְפָּא דְּשַׁלְהוֹבָא, דְּעַטָרָא וְסָחֲרָא לְגוֹ הַהוּא מַשְׁקוֹפָא מֵהַהוּא סִטְרָא דְּמִזְרָח.</p>\n<p>וְאַרְבַּע וְעֶשְׂרִין סַמְכִין תְּחוֹתַיְיהוּ, וְעַל אִלֵּין סַמְכִין קַיְימִין עֶשְׂרִין וְאַרְבַּע עַמּוּדִין, וְאִלֵּין אִינּוּן דְּקַיְימִין תָּדִיר, וְלָא פַּרְחִין גּוֹ אֲוֵירָא כְּאִינּוּן אַחֲרָנִין, וְאִלֵּין אִינּוּן דְּאִקְרוּן עוֹמְדִים, כְּמָה דְאַתְּ אָמֵר, (זכריה ג׳:ז׳) וְנָתַתִּי לָךְ מַהְלְכִים בֵּין הָעוֹמְדִים הָאֵלֶּה. וְאִלֵּין עַמּוּדִים, קַיְימִין עַל אִינּוּן סַמְכִין, בְּהוּ סָחֲרָן לְאִתְקַיְּימָא בְּדוּכְתַּיְיהוּ.</p>\n<p>כַּד אִלֵּין עַמּוּדִים קַיְימִין עַל קִיוּמַיְיהוּ, כֻּלְּהוּ שַׁלִּיטִין דְּקַיְימִין עָלַיְיהוּ, מְעַפְפֵי וְטָסִין כָּל עָלְמָא, וְאַשְׁגְּחָן עַיְינִין. וְאִינּוּן דְּצַיְיתִי קַלִין, סַלְּקִין מִלִּין לְעֵילָּא, כְּמָה דְּאַתְּ אָמֵר (קהלת י׳:כ׳) כִּי עוֹף הַשָּׁמַיִם יוֹלִיךְ אֶת הַקּוֹל. וּבְגִין כַּךְ, אִינּוּן סַמְכִין קַיְימִין בְּקִיּוּמָא תָּדִיר.</p>\n<p>תָּא חֲזֵי, בְּלֶכְתָּם יֵלֵכוּ כִּדְקַאמְרָן. וּבְהִנָּשְּׂאָם מֵעַל הָאָרֶץ יִנָּשְׂאוּ הָאוֹפַנִּים <Nonei></i>לְעוּמָּתָם. דְּהָא כְּמָה דְּאִלֵּין חַיוֹת נַטְלִין וְסַלְּקִין, הָכִי אִינּוּן. מַאי טַעֲמָא. בְּגִין, כִּי רוּחַ הַחַיָּה בָּאוֹפַנִּים. רוּחַ הַחַיָּה, רוּחַ קוּדְשָׁא, דְּנָשִׁיב וּבָטַשׁ בְּכֻלְּהוּ אוֹפַנִּים, לְמֵהַךְ. אִשְׁתְּכַח, דְּכָל מַאן דְּאִיהוּ בְּדַרְגָּא עִלָּאָה, אִיהוּ נָטִיל לְמַאן דְּנָטִיל לֵיהּ. תָּא חֲזֵי, דְּאָרוֹן אִיהוּ הֲוָה נָטִיל לְמַאן דְּנָטִיל לֵיהּ. אוּף הָכָא, חַיוֹת, אִינּוּן נַטְלִין לָאוֹפַנִּים.</p>\n<p>וְאִי תֵּימָא כִּי רוּחַ הַחַיָּה בָּאוֹפַנִּים כְּתִיב. הָכִי נָמֵי, דָּא חַיָּה, דְּאִיהוּ לִסְטַר יְמִינָא, לִסְטַר שְׂמָאלָא, וְלִסְטָר קָמָא, וְלִסְטָר אֲחוֹרָא, וְדָא אִיהִי חַיָּה, וְאִלֵּין אִינּוּן חַיוֹת.</p>\n<p>כְּתִיב (יחזקאל י׳:כ׳) הִיא הַחַיָּה אֲשֶׁר רָאִיתִי תַּחַת אֱלהֵי יִשְׂרָאֵל בִּנְהָר כְּבָר, דָּא הִיא חַיָּה דִּמְרַבָּע לְאַרְבַּע סִטְרִין דְּעָלְמָא. וְדָא אִיהִי דְּקַיְּימָא כּוּרְסְיָיא, לְדִיּוּקְנָא דְּאָדָם. כְּמָה דִּכְתִּיב, וְעַל דְּמוּת הַכִּסֵּא דְּמוּת כְּמַרְאֵה אָדָם עָלָיו מִלְמָעְלָה. וְכֹלָּא לְהַהוּא דַּרְגָּא עִלָּאָה קַדִּישָׁא סְתִימָאָה, דְּאִקְרֵי אֱלֹהֵי יִשְׂרָאֵל.</p>\n<p>וְדָא חַיָּה דִּלְתַתָּא, דְּקַיְּימָא תְּחוֹת כֻּלְּהוּ חֵיוָון עִלָּאִין קַדִּישִׁין. בְּגִין דְּאִית חֵיוָון עִלָּאִין אִלֵּין עַל אִלֵּין. כּוּרְסְיָיא דִּתְחוֹת אֱלֹהֵי יִשְׂרָאֵל, דָּא דִּיּוּקְנָא דְּיַעֲקֹב. וְכוּרְסְיָיא דִּלְתַתָּא, דָּא דִּיּוּקְנָא דְּדָוִד. אִיהִי דִּמְרַבְּעָא לְאַרְבַּע סִטְרִין דְּעָלְמָא. וּבְגִין כַּךְ רוּחָא נָפִיק מִלְּעֵילָּא, וְנָגִיד וְאִתְמְשַׁךְ מִדַּרְגָּא לְדַרְגָּא, עַד דְּבָטַשׁ בְּכֻלְּהוּ תַּתָּאֵי דִּלְתַתָּא, וְהַהוּא רוּחָא אַנְהִיג לְכֹלָּא, וְאַתְקִין תִּקּוּנָא דְּכֻלְּהוּ לְאַתְקְנָא.</p>\n<p>(ס\"א בההוא גוונא ממש דאית תקונא לעילא בההוא וכו') וּבְהַהוּא גַּוְונָא מַמָּשׁ, אִתְתָּקַּן לְתַתָּא. מַה כְּתִיב לְעֵילָּא, כִּי רוּחַ הַחַיָּה בָּאוֹפַנִּים. וּכְתִיב אֶל אֲשֶׁר יִהְיֶה שָּׁמָּה הָרוּחַ לָלֶכֶת יֵלְכוּ. לְתַתָּא מַה כְּתִיב, וַיָּקֶם מֹשֶׁה אֶת הַמִּשְׁכָּן. בְּמָּה. (ס\"א למאי) לְמֶהֱוֵי רוּחַ דְּהַהוּא דַּרְגָּא דִּלְתַתָּא, בְּהַהוּא דִּיּוּקְנָא דְּהַהוּא רוּחַ עִלָּאָה, הִיא הַחַיָּה אֲשֶׁר רָאִיתִי תַּחַת אֱלֹהֵי יִשְׂרָאֵל, וּמֵהַאי חַיָּה נָפְקָא רוּחָא לְאַתְקְנָא כֹּלָּא. הָכִי נָמֵי מֹשֶׁה. הִיא הַחַיָּה דְּיָהַב רוּחָא לְתַתָּא, לְאַתְקְנָא כֹּלָּא. בְּגִין כָּךְ כְּתִיב, וַיָּקֶם, וַיִתֵּן, וַיָּשֶׂם. וּבְכֹלָּא שַׁוִּי רוּחָא, לְאַתְקְנָא כֹּלָּא.</p>"],[9520011918,"<p>תָּא חֲזֵי, בְּקַדְמִיתָא, בְּמַשְׁכְּנָא דְּעֲבַד מֹשֶׁה, אִיהוּ אַתְקִין לֵיהּ, בְּרָזָא דְּהַהוּא דַּרְגָּא עִלָּאָה דְּאִיהוּ קַיְּימָא בֵּיהּ. בְּמַקְדְּשָׁא דְּעָבַד שְׁלֹמֹה, אִיהוּ תַּקִּין לֵיהּ, בְּרָזָא דְּהַהוּא נָהָר דְּנָפִיק מֵעֵדֶן, דְּאִיהוּ שְׁלָמָא דְּבֵיתָא, וְאִיהוּ נַיְיחָא דְּבֵיתָא. וְעַל דָּא בְּרָזָא דְּמַשְׁכְּנָא, אִיהוּ קוּרְבָּא דַּחֲבִיבוּתָא, בְּדַּרְגָּא (ס\"א ברזא) דְּגוּפָא, הַהוּא דַּרְגָּא דְּמֹשֶׁה, קַיְּימָא בֵּיהּ קוּרְבָּא דַּחֲבִיבוּתָא, וְלָאו דְּנַיְיחָא. כַּד אָתָא שְׁלמֹה, וְאַתְקִין מַקְדְּשָׁא, הַהוּא מַקְדְּשָׁא אִתְתָּקַּן, בְּרָזָא דַּחֲבִיבוּ דְּנַיְיחָא. וְעַל דָּא כְּתִיב בִּשְׁלֹמֹה, (דברי הימים א כ״ב:ט׳) הוּא יִהְיֶה אִישׁ מְנוּחָה.</p>\n<p>וּבְגִין כָּךְ, דָּא אַתְקִין בְּחַד דַּרְגָּא, וְדָא אַתְקִין בְּחַד דַּרְגָּא, דִּיּוּקְנָא דְּהַאי בְּהַאי, וְרָזָא דָּא, (בראשית ל״ז:ב׳) אֵלֶּה תּוֹלְדוֹת יַעֲקֹב יוֹסֵף.</p>\n<p>שֵׁירוּתָא דְּשָׁאֲרִי מֹשֶׁה, לְאַתְקְנָא בְּהַאי אֲתָר, דְּאִיהוּ סִטְרָא דִּקְדוּשָּׁה אוֹקִים קִימָה דִּנְקוּדָה דְּקַיְּימָא בְּאֶמְצָעִיתָא, דְּהֲוָה חָשׁוּךְ וְשָׁקוּעַ בְּאַתְרֵיהּ, וְלָא אִתְחָזֵי, וְלָא נָהִיר כְּלַל, וְשֵׁירוּתָא דְּכֹלָּא אוֹקִים לָהּ לְהַאי נְקוּדָה, דְּאִשְׁתְּקָעַת בְּאַתְרָהָא. וּלְבָתַר לְכָל אַחֲרָא, דְּאִיהוּ בִּנְיָינָא דְּהַאי נְקוּדָה.</p>\n<p>וְאִם הַאי נְקוּדָה לָא אִתְתָּקַּן (נ\"א אתתקם) בְּקַדְמִיתָא, כָּל מַאן דְּאִתְפָּשַּׁט מִנָּהּ, לָא יָכִיל לְאִתְתַּקְנָא. וְכֵיוָן דְּהַאי נְקוּדָה אִתְּקָמַת וְאִתְנְהִירַת, כְּדֵין, כָּל שְׁאַר תִּקּוּנָא אַחֲרָא אִתְתָּקַּן, וְאִתְיְישָׁבַת בְּדוּכְתָּהּ. וְעַל דָּא, וַיָּקֶם מֹשֶׁה אֶת הַמִּשְׁכָּן. (את) דָּא נְקוּדָה דַּהֲוַות חֲשׁוֹכָא וּשְׁקִיעָא בְּאַתְרֵיהּ. וּלְבָתַר, וַיִּתֵּן אֶת אֲדָנָיו, אִינּוּן סַמְכִין דְּאִינּוּן מִכָּאן וּמִכָּאן. (בגין דאית אדנים ואית אדנים) וְכֻלְּהוּ הֲווֹ מֵאָה לְחֶשְׁבֹּנָא, וְכֻלְּהוּ אִתְפְּלָגוּ לְאַתְרַיְיהוּ, דִּכְתִּיב, מְאַת אֲדָנִים לִמְאַת הַכִּכָּר כִּכָּר לָאָדֶן.</p>\n<p>וְאִלֵּין אֲדָנִים <Nonei></i>הָא אוֹקִימְנָא, אֲבָל לָא כְּתִיב בְּהוּ קִימָה, אֶלָּא וַיִּתֵּן, נְתִינָה לְשַׁוָּואָה עָלַיְיהוּ מַה דְּאִצְטְרִיךְ, בְּגִין דְּאִית תַּתָּאִין וְעִלָּאִין, רְכִיבִין דָּא עַל דָּא. וְעַל דָּא כְּתִיב בְּהוּ נְתִינָה.</p>\n<p>בְּהַהִיא שַׁעֲתָא דְּהַאי נְקוּדָה אִתְּקָמַת, אִשְׁתְּקָעַת סִטְרָא אַחֲרָא. וְלָא אִתְמָחַת כְּלַל, דְּהָא לָא אִתְמְחֵי, אֶלָּא לְהַהוּא זִמְנָא דְּאָתֵי, דְּאִתְמְחֵי מֵעָלְמָא, כְּמָה דְּאִתְּמַר, אִתְּקַם דָּא וְאִשְׁתְּקָעַת דָּא.</p>\n<p>(שמות מ׳:י״ח) וַיִּתֵּן אֶת אֲדָנָיו, כְּדֵין שָׁאֲרִי לְאִתַּתְקְפָא הַאי סִטְרָא (ד\"א רוחא) דִּקְדוּשָּׁה וְכַד אִתְיְיהִיבוּ אִלֵּין סַמְכִין, אִשְׁתְּקָעוּ כֻּלְּהוּ דְּסִטְרָא אַחֲרָא, וְעָאלוּ בְּנוּקְבָּא דִּתְהוֹמָא רַבָּא. בְּגִין דְּאִסְתַּלָּק הַאי סִטְרָא דִּקְדוּשָּׁה עִלָּאָה, וְאִיהוּ חוּלָקָא לְאִסְתַּלְּקָא, וּכְדֵין הַאי סִטְרָא אַחֲרָא אִשְׁתְּקַע, וְעָאל בְּהַהוּא נוּקְבָּא דִּתְהוֹמָא.</p>\n<p>וְאִלְמָלֵא דְּיִשְׂרָאֵל חָאבוּ, (בקדמיתא) לָא יָכִיל לְשַׁלְּטָאָה בְּעָלְמָא יַתִּיר. וּלְבָתַר אוּף הָכִי חָאבוּ, וְאַמְשִׁיכוּ לֵיהּ עָלַיְיהוּ כְּקַדְמֵיתָא. וּמֵהַהוּא יוֹמָא, לָא הֲוָה עֵיטָא, אֶלָּא לְמֵיהַב חוּלָקָא לְהַהוּא סִטְרָא אַחֲרָא בְּכֹלָּא, בְּרָזָא דְּקָרְבְּנִין וּנְסָכִין וְעִלָּוָון. וְתָּא חֲזֵי בְּגִין כָּךְ עוֹלָה אִתּוֹקְדָא כֹּלָּא בְּאֶשָּׁא, לְאַכְפְּיָיא הַאי סִטְרָא, וּלְאִסְתַּלְּקָא סִטְרָא דִּקְדוּשָּׁה, וּבְגִין כַּךְ כַּד מֹשֶׁה אוֹקִים לַאֲתָר דָּא. אִשְׁתְּקַע אֲתָר דָּא.</p>\n<p>תָּא חֲזֵי וַיָּקֶם מֹשֶׁה, הַאי סִטְרָא דִּקְדוּשָּׁה. וְאִשְׁתְּקַע סִטְרָא אַחֲרָא מְסַאֲבָא. וַיִּתֵּן. לְהַאי סִטְרָא דִּקְדוּשָּׁה, וְאִתְרַפְיָא הַאי סִטְרָא אַחֲרָא מְסַאֲבָא. וַיָּשֶׂם, לְהַאי סִטְרָא דִּקְדוּשָּׁה, וְאִתְכַּפְיָא הַאי סִטְרָא אַחֲרָא דִּמְסָאֲבָא. וּלְבָתַר אַהְדָּר וַיִתֵּן אֶת בְּרִיחָיו.</p>\n<p>וּלְבָתַר וַיָּקֶם. מַאי טַעְמָא. בְּגִין דִּיְהֵא שֵׁירוּתָא וְסִיּוּמָא בְּקִימָה, שָׁאֲרִי בְּקִימָה, וְסִיֵּים בְּקִימָה. בְּגִין דִּבְכֹלָּא בָּעֵי קִימָה, שֵׁירוּתָא וְסִיּוּמָא. קִימָה בְּשֵׁירוּתָא דְּסִטְרָא אַחֲרָא אִתְרַפֵי. וְדָא, אִיהוּ קִימָה לְסִטְרָא דִּקְדוּשָּׁה, בְּגִין לְאִתְקַיְּימָא וּלְאִסְתַּלְּקָא לְעֵילָּא, לְמֶהוֵי אִתְקַשְׁרוּתָא חֲדָא כְּדְקָא יֵאוֹת. בְּגִין דְּכָל זִמְנָא דִּקְדוּשָּׁה שַׁלְטָא וְסַלְּקָא, מְסָאֲבוּ שָׁפִיל, וּמָאִיךְ לְתַתָּא.</p>"],[9520011919,"<p>רֵישָׁא דִּנְקוּדָה, דְּקַיְּימָא תְּחוֹת דַּרְגִּין דִּי בְּסִטְרָא אַחֲרָא, אִיהוּ רִישׁ דַּרְגָּא דִּלְבַר, רֵישָׁא דִּדְכוּרָא, וְקַיְּימָא רָכִיב עַל חַד גָּמָל, אִיהוּ רֵישָׁא לְבַר דְּחַד עִרְבוּבָא דְּחֹשֶׁךְ דְּאִתְפָּשַּׁט.</p>\n<p>דְּכַד תְּנָנָא נָפְקָא מִגּוֹ רוּגְזָא תַּקִּיף, אִתְפָּשַּׁט הַהוּא תְּנָנָא, וְאָזִיל רוּגְזָא בָּתַר רוּגְזָא, דָּא עַל דָּא, וְדָא רָכִיב וְשָׁלִיט עַל דָּא, בְּחֵיזוּ דִּדְכַר וְנוּקְבָּא לְמֶהוֵי כֹּלָּא רוּגְזָא תַּקִּיף.</p>\n<p>וְכַד שָׁאֲרִי תְּנָנָא לְאִתְפַּשְּׁטָא, דָּחִיק מִגּוֹ רוּגְזָא בִּדְחִיקוּ דְּחָד נְקוּדָה לְאִתְפַּשְּׁטָא, וּלְבָתַר אִתְפָּשַּׁט תְּנָנָא (ק\"ל ע\"א) דְּרוּגְזָא בְּעַקִּימוּ, כְּחַד חִוְיָא חַכִּים לְאַבְאָשָׁא.</p>\n<p>רֵישָׁא דְּנָפְקָא לְאִתְפַּשְּׁטָא, אִיהוּ דַּרְגָּא דְּאִיהוּ חָשׁוּךְ, סָלִיק וְנָחִית, אָזִיל וְשָׁאט, וְנָח בְּדוּכְתֵּיהּ, וְקַיְּימָא דַּרְגָּא לְאִתְיַישְּׁבָא, מֵהַהוּא תְּנָנָא דְּנָפִיק מִגּוֹ רוּגְזָא, וְאִיהוּ צֵל. צִלָּא, עַל אֲתָר אַחֲרָא דְּאִקְרֵי מָוֶת. וְכַד מִתְחַבְּרָן תַּרְוַויְיהוּ כַּחֲדָא, אִקְרֵי (ויצא ק\"ס ע\"ב) צַלְמָוֶת, וְהָא אוֹקִימְנָא, תְּרִין דַּרְגִּין אִינּוּן דְּמִתְחַבְּרָאן כַּחֲדָא.</p>\n<p>הַאי צֵל, אִיהוּ שֵׁירוּתָא דִּנְקוּדָה תַּתָּאָה דִּלְבַר, חֲשׁוֹכָא דִּמְרַחָקָא מִנְקוּדָה קַדִּישָׁא, דְּקַיְּימָא בְּאֶמְצָעִיתָא. וְהַאי אִיהוּ נְקוּדָה, דְּלָא קַיְּימָא, וְלָא אִתְרְשִׁימַת בְּגַוְונָהָא. וּמִינָהּ אִתְפַּשְּׁטַת פְּשִׁיטוּ לְבַר וּלְתַתָּא. וְאִיהִי אִשְׁתְּקָעַת וְלָא אִתְחֲזִיאַת, וְלָא אִתְרְשִׁימַת.</p>\n<p>הַאי אִתְפַּשְּׁטַת לְתַתָּא, לִימִינָא וְלִשְׂמָאלָא, וְאִתְפַּשְׁטַת בְּאֶמְצָעִיתָא, גּוֹ חָשׁוּךְ, קָבֵל אֶלֶף וּמֵאָה. תְּרֵין סַמְכִין מִתְגַּלְּפִין לְסִטְרָא דָּא, וּלְסִטְרָא דָּא, אִתְפָּשַּׁט חֲשׁוֹכָא, בְּגוֹ גּוָֹון אוּכָם וְלָא אוּכָם, דְּהָא לֵית לֵיהּ גּוָֹון לְאִתְקַיְּימָא בֵּיהּ. וּבְהַהוּא פְּשִׁיטוּ, קַיְימִין חֲשׁוּכִין אִינּוּן דְּשִׁמְּשׁוּ בְּמִצְרַיִם, דִּכְתִּיב (שמות י׳:כ״ג) לא רְאוּ אִישׁ אֶת אָחִיו וְלֹא קָמוּ אִישׁ מִתַּחְתָּיו שְׁלֹשֶׁת יָמִים. וּכְתִיב וְיָמֵשׁ חֹשֶׁךְ.</p>\n<p><Nonei></i>הַאי פְּשִׁיטוּ, אִתְפָּשַׁט בְּכַמָּה זִינִין, מְשַׁנְיָין אִלֵּין גּוֹ אִלֵּין. גּוֹ הַהוּא פְּשִׁיטוּ, נָפְקָא חַד זִהֲרָא דְּאִצְטְבַּע בְּדַהֲבָא, וְדָא אִיהוּ דַּהֲבָא סוּמָקָא. אִתְפָּשַׁט הַאי זִהֲרָא, וְחָפֵי חָשׁוּךְ דְּרִישָׁא, וְאִיהוּ דַּהֲבָא, דְּאִתְכְּלִיל בֵּיהּ חֲשׁוֹכָא.</p>\n<p>הַאי חֲשׁוֹכָא אִתְפָּשַׁט לִימִינָא וְלִשְׂמָאלָא. וּמִגּוֹ אִלֵּין תְּרֵין סִטְרִין, נָפְקָא חַד גַּוְונָא דְּכַסְפָּא, דְּלָא זָהִיר. אִתְפָּשַׁט הַאי גּוָֹון דִּכְסַף, וְחָפֵי חֲשׁוֹכָא, וְאִתְכְּלִיל דָּא בְּדָא, וְנָחִית לְתַתָּא.</p>\n<p>אִתְפָּשַׁט חֲשׁוֹכָא, וְקַיְימָן תְּרֵין חֲשׁוּכִין, רֵישׁ אוּכָמָא דְּקַיְימִין, (ד\"א דנפקין) וּמִתַּמָּן מִתְפָּשַּׁט וְנָפִיק חַד גּוָֹון דִּנְחֹשֶׁת.</p>\n<p>וּמִתַּמָּן אִתְפָּשַּׁט לְתַתָּא, הַהוּא חָשׁוּךְ, וְקָאִים קַיְּימָא, וְנָפִיק חַד גּוָֹון אוּכָם חֵיזוּ דְּפַרְזְלָא. וְכֹלָּא בְּרָזָא דַּחֲשׁוֹכָא.</p>\n<p>מִבֵּין תְּרֵין קַיְימִין, נָפִיק קַיָּימָא חַד, חָשׁוּךְ בַּחֲשׁוֹכָא, וְכָל אִלֵּין גַּוְונִין אִתְחָזוּן בֵּיהּ. וְהַאי אִיהוּ עָרְלָה, דְּאַנְהִיג דְּכַר לִנְקֵבָה, לְאִזְדַּוְּוגָא כַּחֲדָא, לְמֶהֱוֵי חַד.</p>\n<p>הָנֵי קַיְימִין, בְּז' דַּרְגִּין רַבְרְבִין (דכרין) יְדִיעָאן. דַּרְגָּא קַדְמָאָה, אִיהוּ דַּרְגָּא דְּקָאִים בְּסִטְרָא דְּהַאי חֲשׁוֹכָא. דָּא חֲשׁוֹכָא סַלְּקָא, גּוֹ טְמִירוּ דִּתְנָנָא דְּאֶשָּׁא, הַאי כָּלִיל בְּגָוֶון תְּנָנָא, וּבְגָוֶון אֶשָּׁא, וּבְגָוֶון אוּכָם. אִלֵּין תְּלַת גַּוְונִין, מִתְפָּרְשָׁן לְכַמָּה סִטְרִין, לְאִתְעַקְּמָא בְּעִמְקֵי עָלְמָא.</p>\n<p>גּוָֹון תְּנָנָא הַאי, נַחְתָּא לְעָלְמָא, וְאָעִיל לְכַמָּה סִטְרִין, וְדָא אִתְפָּשַׁט בְּעָלְמָא, וְאַסְטֵי לְרוּחֵי בְּנֵי נָשָׁא בִּרְגִּיזוּ, לְאַסְטָאָה אָרְחַיְיהוּ, וּלְאִתְתַּקְּפָא בְּרוּגְזַיְיהוּ. וְעַל דָּא כְּתִיב, (תהילים פ״א:י׳-י״א) לֹא יִהְיֶה בְךָ אֵל זָר וְלֹא תִשְׁתַּחֲוֶה לְאֵל נֵכָר. לֹא יִהְיֶה בְךָ אֵל זָר דָּא דְּכוּרָא. וְלֹא תִשְׁתַּחֲוֶה לְאֵל נֵכָר דָּא נוּקְבָּא. הַאי אִיהוּ רוּגְזָא דְּשַׁלְטָא וְאִתָּקַף בְּעָלְמָא, וְעָאל בְּגוֹ בְּנֵי נָשָׁא, וְאַתְקִיף לוֹן לְאַבְאָשָׁא.</p>\n<p>גּוָֹון אֶשָּׁא, הַאי גַּוְונָא נַחְתָּא לְעָלְמָא, וְעָאל לְכַמָּה סִטְרִין, לְאַבְאָשָׁא, לְקָטְלָא, וּלְאוֹשְׁדָא דָּמִין, וּלְקַפְּחָא לִבְנֵי נָשָׁא. וְעַל דָּא כְּתִיב, (משלי א׳:י״א) אִם יֹאמְרוּ לְכָה אִתָּנוּ נֶאֶרְבָה לְדָם נִצְפְּנָה לְנָקִי חִנָּם. בְּגִין דְּאִית אוֹשְׁדֵי דָּמִין לְמַגָּנָא, וְקַטְלֵי לְמַגָּנָא. וְאִית דְּאוֹשְׁדֵי דָּמִין וְקַטְלֵי בִּקְרָבָא, וְהַאי מִסִּטְרָא דִּדְכוּרָא וְהַאי מִסִּטְרָא דְּנוּקְבָּא. סִטְרָא דִּדְכוּרָא אוֹשִׁיד דָּמִין לְמַגָּנָא, כִּדְקַאמְרָן. סִטְרָא דְּנוּקְבָּא, לְאַגָּחָא קְרָבִין, וּלְאִתְקַטְּלָא אִלֵּין בְּאִלֵּין, וְכָל קְרָבִין וְקַטוֹלִין אִלֵּין בְּאִלֵּין, מֵהַהוּא סִטְרָא דְּנוּקְבָּא קָא אַתְיָין.</p>\n<p>גּוָֹון אוּכָם, הַאי גַּוְונָא נַחְתָּא לְעָלְמָא, וְנַחְתָּא לְאִתְמַנָאָה עַל כָּל פְּצוּעִין, וּמַחְיָין, וּתְפִיסוּ דְּגוּפִין, וּצְלִיבוּ, וַחֲנִיקוּ, לְאַבְאָשָׁא תָּדִיר לִבְנֵי נָשָׁא. אִלֵּין תְּלַת גַּוְונִין, מִתְפָּרְשָׁן לְכַמָּה סִטְרִין דְּעָלְמָא, וְאִתְפַּשְּׁטָן גּוֹ בְּנֵי עָלְמָא.</p>\n<p>גּוָֹון תְּנָנָא נַחְתָּא בְּעָלְמָא, וְהַאי אִיהוּ גּוָֹון קַדְמָאָה, דְּנָפְקָא מִגּוֹ נְקוּדָה דְּשָׁקִיעַ מֵהַהוּא צֵל דְּקָאָמַרָן, דְּאִיהוּ סָמָאֵ\"ל, דְּקָא רָכִיב עַל גָּמָל, כְּמָה דְּאִתְּמַר, וְהַאי גּוָֹון תְּנָנָא אִקְרֵי קַצְפִּיאֵ\"ל רַבְרְבָא. וְהַאי אִיהוּ רוּגְזָא דִּבְנֵי נָשָׁא, דְּאַתְקִיפוּ לִבָּא בְּרוּגְזָא.</p>\n<p>תְּחוֹת הַאי, מְמָנָן אֶלֶף וְשִׁית מֵאָה חֲבִילִין, דְּאִינּוּן רוּגְזָא דְּגוּפָיְיהוּ דִּבְנֵי נָשָׁא. בְּגִין דְּאִית רוּגְזָא דְּשַׁלְטָא בְּעָלְמָא לְמֶעְבַּד דִּינָא. אֲבָל הַאי (סטרא) אִיהוּ רוּגְזָא, דְּשַׁלְטָא וְעָאל בְּגוּפַיְיהוּ דִּבְנִי נָשָׁא, דְּאִתְרְגִיזוּ בְּהַאי רוּגְזָא. וְהַאי רוּגְזָא, אִיהוּ יְסוֹדָא דְּכָל שְׁאַר גְּוָונֵי, לְמֶעְבַּד בְּהוּ, בִּנְיָינָא לְאַבְאָשָׁא, בְּגִין דְּהַאי תְּנָנָא, נָפְקָא מִגּוֹ רוּגְזָא דְּאֶשָּׁא עִלָּאָה, דִּמְלַהֲטָא, וְהַאי אִיהוּ קַדְמָאָה לְהַהוּא אֶשָּׁא.</p>\n<p>אַרְבַּע רוּגְזֵי מִתְפָּרְשָׁאן מֵהַהוּא רוּגְזָא. רוּגְזָא קַדְמָאָה, אִקְרֵי רֹגֶז וְדָא אִיהוּ דְּאַרְגִּיז לִבַּיְיהוּ דִּבְנֵי נָשָׁא, וְדָא אִיהוּ דְּנַחְתָּא וְאַזְלָא וְסַטְיָא לִבְנֵי נָשָׁא, וְאִתְרְגִיזוּ בְּרוּגְזַיְיהוּ. וְדָא אִיהוּ דְּאַמְשִׁיךְ מְחַבְּלָא עַל עָלְמָא. (ועל דא כתיב (חבקוק ג׳:ב׳) ברוגז רחם תזכור)</p>\n<p>רוּגְזָא תִּנְיָינָא, הַאי אִיהוּ נַחְתָּא לְעָלְמָא, וְשָׁאט וְאִתְפָּשַּׁט לְכָל סִטְרִין, וְהַאי אִקְרֵי שִׂנְאָה. וְהַאי נַחְתָּא וְעָאל בִּבְנֵי נָשָׁא, וְהַאי כֵּיוָן דְּעָאל, אִקְרֵי מְחַבְּלָא שְׁתִיקָא <Nonei></i>וְהַאי אִיהוּ רָגְזָא דְּשָׁתִיק, וְהַאי אִיהוּ דְּאִשְׁתַּתֵּף בְּהַהוּא אֲתָר דְּנוּקְבָּא. וְהַאי אִיהוּ רוּגְזָא דִּשְׁתִיקָה, דְּקַיְּימָא בְּעַקִּימוּ. הַאי קַשְׁיָא מִכֻּלְּהוּ, בְּגִין דְּאִיהוּ כְּגַוְונָא דְּחִוְיָא, דְּשָׁתִיק תָּדִיר, וְקָטִיל לְבָתַר.</p>\n<p>רוּגְזָא תְּלִיתָאָה, הַאי אִיהוּ רוּגְזָא בְּהִפּוּכָא מִקַּדְמָאָה, דְּאַזְלָא וְאִתָּקַף וְלָא שָׁתִיק, אֶלָּא אִתְגְּלֵי הַהוּא רוּגְזָא, וְכָל מַאן דְּאִתְגְּלֵי הָכִי אִתְּבַר כָּל מַה דְּאִתְגְּלֵי וְלָא שָׁתִיק, הָכִי אִתְּבַּר, וְהָכִי אִקְרֵי רוּגְזָא תְּבִירָא.</p>\n<p>רוּגְזָא רְבִיעָאָה, שֵׁירוּתָא תַּקִּיף, סוֹפָא תָּבִיר. וְעַל דָּא הַאי אִיהוּ רוּגְזָא, דִּמְהַפְכָא מִן קַדְמַיְיתָא. בְּגִין כַּךְ, הַאי אִיהוּ סִטְרָא תְּבִירָא מִכֻּלְּהוּ. וְעַל דָּא, כֹּלָּא אִיהוּ בְּדַרְגָּא קַדְמָאָה.</p>\n<p>דַּרְגָּא תִּנְיָינָא, אִיהוּ דַּרְגָּא דְּנָפִיק מֵחֲשׁוֹכָא, וְהַאי אִיהוּ גּוָֹון חֲשׁוּךְ, דְּקַיְּימָא מִגּוֹ הַאי חֲשׁוֹכָא בְּגִין דְּכֹלָּא קַיְּימָא מִגּוֹ חֲשׁוֹכָא. וְקַיְּימָא בְּדַרְגִּין יְדִיעָאן. וְהַאי אִתְפָּשַׁט לְתַתָּא בִּגְוָונִין יְדִיעָאן.</p>\n<p>בְּדַרְגָּא דָּא, קַיְימִין תְּלַת מֵאָה סִטְרִין, מִתְפָּרְשִׁין דָּא מִן דָּא, וְכֻלְּהוּ כְּלִילָן דָּא בְּדָא. וְאַף עַל גַּב דִּמְשַׁנְיָין דָּא מִן דָּא, וְאִתְגַּבְּרָן (ד\"א ואנהרן) דָּא מִן דָּא, כֹּלָּא כָּלִיל דָּא בְּדָא. וּבְגִין כַּךְ, כָּל דַּרְגִּין יְדִיעָאן בְּהַאי סִטְרָא לְאַבְאָשָׁא.</p>\n<p>מֵהָכָא נַפְקֵי כָּל אִלֵּין מְחַבְּלִין דְּשַׁטְיָין בְּעָלְמָא, וְעַבְדֵי דִּינָא בְּאִתְגַּלְיָיא (ד\"א בעלמא), עַל עוֹבָדִין סְתִימִין דְּאִתְעָבֵידוּ גּוֹ חָשׁוּךְ בִּטְמִירוּ, וְאִינּוּן שַׁטְיָין בְּעָלְמָא, וְעַבְדֵי דִּינָא בְּאִתְגַּלְיָיא בְּהוּ. וּבְגִין כַּךְ, כָּל אִלֵּין דְּשַׁטְיָין בְּעָלְמָא, וְעַבְדֵי דִּינָא בְּאִתְגַּלְיָיא, כֻּלְּהוּ קַיְימִין בְּקָבְלֵייהוּ דִּבְנֵי נָשָׁא, לְאִתְעַתְּדָא תָּדִיר, גַּבֵּי אִינּוּן חוֹבִין טְמִירִין דְּקָאָמַרָן, וְאִינּוּן דְּאִקְרוּן אַף וְחֵמָּה, מִתְחַבְּרָן עִמְּהוֹן וְעַבְדֵי דִּינָא עָלַיְיהוּ דִּבְנֵי נָשָׁא. הַאי אִתְעָבִיד בְּעָלְמָא, מֵאִלֵּין מָארֵי דְּדִינָא כִּדְקַאמְרָן.</p>\n<p>דַּרְגָּא דָּא קַיְּימָא גּוֹ חֲשׁוֹכָא וְאֶשָּׁא, דְּאִיהוּ רָזָא חֲדָא, וּמִגּוֹ דַּרְגָּא דָּא, מִתְפָּרְשָׁן כַּמָה דַּרְגִּין תַּקִּיפִין (גברין) דְּקַיְימָן תְּחוֹת סִטְרָא דִּרְקִיעָא חֲדָא, דְּאִקְרֵי רְקִיעָא אוּכָמָא. דַּרְגָּא תְּלִיתָאָה, הַאי אִיהוּ רְקִיעָא, דְּמִתְפַּשְּׁטָא עַל כָּל אִינּוּן דַּרְגִּין, דְּאִינּוּן סוּמָקִין כְּוַורְדָּא. וְאִלֵּין אִקְרוּן דְּרוֹעִין דְּהַאי סִטְרָא.</p>\n<p>תְּחוֹת אִלֵּין, מִתְפַּשְּׁטִין לְתַתָּא דַּרְגִּין, עַד דְּמָטוּ לְגוֹ דַּרְגָּא תְּלִיתָאָה (ס\"א ההוא רקיעא אוכמא) בְּגִין דְּאִלֵּין דִּי בְּדַרְגָּא תִּנְיָינָא, נַפְקֵי מִגּוֹ הַהוּא רְקִיעָא אוּכָמָא, וְשַׁטְיָין בְּעָלְמָא.</p>\n<p>אִלֵּין מִימִינָא, וְאִלֵּין מִשְּׂמָאלָא. אִלֵּין דִּימִינָא, מִתְפָּרְשָׁן לִתְלַת סִטְרִין, דְּאִינּוּן (ויחי רמ\"א ע\"א) תְּלַת קִשְׁרִין. וְאִלֵּין דִּשְׂמָאלָא, מִתְפָּרְשָׁן לִתְלַת סִטְרִין, דְּאִינּוּן תְּלַת קִשְׁרִין אַחֲרָנִין.</p>\n<p>קִשְׁרָא קַדְמָאָה, קַיְּימָא לְעֵילָּא. וּתְנָנָא חֲשׁוֹכָא בְּרוּגְזָא, אִתְקָשַׁר בֵּיהּ. הַאי קִשְׁרָא, אִית בָּהּ תְּלַת גַּוְונִין חֲשׁוֹכִין, וּמְשַׁנְיָין דָּא מִן דָּא, וְאִתְכְּלִילוּ דָּא בְּדָא. וְהַאי קִשְׁרָא, אִיהוּ כָּפִיף, וְלָא אִתְפָּשַׁט (ס\"א אתכפייא), בַּר לְזִמְנִין יְדִיעָאן, הַאי אִקְרֵי עֶבְרָ\"ה.</p>\n<p>וְאִיהוּ קַיְּימָא בְּלָא שְׁכִיכוּ, בְּגִין דְּלָא שָׁכִיךְ, בַּר בְּזִמְנָא דְּיִשְׂרָאֵל מְקָרְבִין קָרְבָּנָא לְתַתָּא, בְּגִין דִּבְהַהוּא זִמְנָא אִשְׁתְּכַּךְ הַהוּא רוּגְזָא, וְאִתְכַּפְיָיא לְתַתָּא, וְאִתְחַלָּשׁ רוּגְזֵיהּ. (ד\"א תוקפיה) וְלָא יָכִיל לְשַׁלְּטָאָה וּלְאַתְּקְפָא. וְכַד אִתְחֲלָשׁ הַאי, כְּדֵין קִשְׁרָא תִּנְיָינָא, דְּאִיהוּ בְּאֶמְצָעִיתָא לָא יָכִיל לְנַטְלָא וּלְאַנְהָגָא.</p>\n<p>קִשְׁרָא תִּנְיָינָא, דָּא הוּא דְּאִקְרֵי זַעַם, הַאי קִשְׁרָא אִיהוּ דְּנָטִיל מֵאֲתָר לַאֲתָר, וְאַנְהִיג לְכָל שְׁאַר קִשְׁרִין, וְכָל שְׁאַר קִשְׁרִין כֻּלְּהוּ, אִתְנַהֲגָן בֵּיהּ, וְכֻלְּהוּ אִתָּקָפוּ בְּהַאי קִשְׁרָא. הַאי אִיהוּ דְּמַנְהִיג כָּל צַעְרִין לְעָלְמָא, בְּגִין דְּכַד אִתְחַבָּר בְּדַרְגָּא אַחֲרָא, לְחַבְּקָא לְנוּקְבָּא, כְּדֵין נַחְתֵּי לְעָלְמָא, כָּל צַעְרִין, וְכָל דַּחֲקִין, וְכָל עָאקוּ, דְּהָא לָא יָכִילוּ לְשַׁלְטָאָה דָּא בְּלָא דָּא. וְכֻלְּהוּ דַּרְגִּין, אִתְיְיהִיבוּ לְנוּקְבָּא, לְשַׁלְּטָאָה, וּלְמִסְטֵי עָלְמָא, וְאִי לָאו דְּרָכִיב דָּא עַל דָּא, וְאִתְחַבָּר דָּא בְּדָא, לָא יַכְלִין לְשַׁלְּטָאָה.</p>\n<p>תָּא חֲזֵי, כַּד הֲוָה אָדָם בְּגִנְתָּא דְּעֵדֶן, לְאִשְׁתַּדְּלָא בְּפוּלְחָנָא דְּמָארֵיהּ. נָחַת הַאי סָמָאֵ\"ל, וְכָל <Nonei></i>אִינּוּן דַּרְגִּין דְּבֵיהּ, וַהֲוָה רָכִיב עַל הַהוּא חִוְיָא בִּישָׁא, בְּגִין לְאַסְטָאָה לוֹן. בְּגִין דְּהַהוּא חִוְיָא דְּהֲוָה קָאִים תְּחוֹתֵיהּ, אִיהוּ עֲקִימָא לְאַסְטָאָה, בְּנֵי נָשָׁא, וּלְפַתָּאָה לוֹן. בְּגִין דִּכְתִּיב, (משלי ה׳:ג׳) כִּי נֹפֶת תִּטֹּפְנָה שִׂפְתֵי זָרָה וְחָלָק מִשֶּׁמֶן חִכָּהּ. וְדָא יָהִיב חֵילָא, וְדָא עָבִיד אוּמָנוּתָא בְּעָלְמָא, וְדָא בְּלָא דָּא לָא יַכְלֵי לְשַׁלְּטָאָה.</p>\n<p>בְּגִין כָּךְ, כַּד הַהוּא קִשְׁרָא דְּאֶמְצָעִיתָא, אִתְחַבָּר בְּנוּקְבָּא, כְּדֵין נַחְתֵּי דִּינִין, וְכָל דַּחֲקִין לְעָלְמָא וְכַד הַאי לָא אִתְתָּקַּף דְּלָא נָטִיל, כֹּלָּא אִתְּבַר וְאִתְכַּפְיָיא, דְּלָא יָכִיל לְשַׁלְּטָאָה. וְעַל דָּא, כֹּלָּא אִתְּבַּר וְאִתְכַּפְיָיא, בְּרָזָא דְּקָרְבְּנִין דִּלְתַתָּא. וְסַלְּקָא מַאן דְּסַלְּקָא, לְאִתְעַטְּרָא לְעֵילָּא, וּלְאִתְבָּרְכָא מֵעִמְקָא עִלָּאָה, דְּנָהִיר לְכָל אַנְפִּין.</p>\n<p>קִשְׁרָא תְּלִיתָאָה הַאי אִיהוּ תַּקִּיפָא בִּתְקִיפוּ יַתִּיר, וְהַאי אִקְרֵי צָרָ\"ה, בְּגִין דְּמֵהַאי נַפְקֵי שׁוּלְטָנוּ, לְאַשְׁרָאָה דַּחֲקִין, וּלְמֶעְבַּד עָאקוּ לִבְנֵי נָשָׁא. וְרָזָא דִּתְלַת קִשְׁרִין אִלֵּין, דִּכְתִּיב, (תהילים ע״ח:מ״ט) עֶבְרָה וְזַעַם וְצָרָה. אִלֵּין תְּלַת קִשְׁרִין דִּימִינָא.</p>\n<p>תְּלַת קִשְׁרִין דִּשְׂמָאלָא, כַּד מִתְתַּקְפֵי כַּחֲדָא, כְּדֵין הַהִיא שְׂמָאלָא אִקְרֵי, (תהילים ע״ח:מ״ט) מִשְׁלַחַ\"ת מַלְאֲכֵי רָעִים. בְּגִין דְּמֵהַאי שְׂמָאלָא, אִשְׁתָּדָרוּ לְתַתָּא, וְנַטְלֵי תּוּקְפָּא, כָּל אִינּוּן מַלְאֲכִין בִּישִׁין, אִינּוּן דְּנַפְקֵי מִסִּטְרָא דִּלְתַתָּא, כִּדְקַאמְרָן. וְכָל דָּא מִגּוֹ דַּרְגָּא תִּנְיָינָא וְדַרְגָּא תְּלִיתָאָה.</p>\n<p>דַּרְגָּא רְבִיעָאָה, הַאי דַּרְגָּא קַיְּימָא, מִגּוֹ עֲקִימוּ דְּרוּגְזָא, גּוָֹון אֶשָּׁא. וְהַאי אִקְרֵי אֶמְצָעִיתָא. דְּאִיהוּ גּוּפָא, דְּקַיְּימָא בֵּין תְּרֵין דְּרוֹעִין. הָכָא אִית לַהֲטָא, דִּמְלַהֲטָא בְּסוּמָקָא כְּוַורְדָּא. מֵהָכָא נַפְקֵי תְּקִיפוּ לְנַחְתָּא לְתַתָּא, לְאַתְקְפָא לְאוֹשָדָא דָּמִין. בְּגִין דְּהַאי אִיהוּ דְּיָהִיב רְשׁוּ וְשׁוּלְטָנָא לְתַתָּא, לְאַתְקְפָא וּלְאוֹשְׁדָא דָּמִין. הַאי נְבִיעַ לְנוּקְבָּא, וְדָא אִצְטְרִיךְ לְדָא, כְּמָה דְּאִצְטְרִיךְ גּוּפָא לְנַפְשָׁא, וְנַפְשָׁא לָא עָבִיד אוּמָנוּתָא, אֶלָּא בְּגוּפָא. וְעַל דָּא, כָּל חֵילָא, וְכָל תְּקִיפוּ, מֵהָכָא נָפִיק, לְאַתְקְפָא, וּלְמֶעְבַּד אוּמָנוּתָא בְּעָלְמָא, לְאַבְאָשָׁא. כְּנוּקְבָּא דִּמְקַבְּלָא מִן דְּכוּרָא תָּדִיר.</p>\n<p>בְּכָל דַּרְגָּא וְדַרְגָּא, וּבְכָל קִשְׁרָא וְקִשְׁרָא, אִית כַּמָה מְמָנָן, וְכַמָה טְרִיקֵי חֲבִילִין, דְּכֻלְּהוּ אִתְנָהֲגָן בְּגִינַיְיהוּ, וְכֻלְּהוּ דְּאִתְנָהֲגָן בְּגִינַיְיהוּ, כֻּלְּהוּ לְתַתָּא, דְּאִינּוּן חַיָּילִין דִּי בְּנוּקְבָּא, וְכֻלְּהוּ אִית לוֹן דַּרְגָּא יְדִיעָא לְעֵילָּא לְאִתְנָהֲגָא בֵּיהּ.</p>\n<p>כְּמָה דְּאִית לְסִטְרָא עִלָּאָה קַדִּישָׁא, הֵיכָלִין יְדִיעָאן, לְגַבֵּי דַּרְגִּין עִלָאִין, לְאִתְכַּלְּלָא אִלֵּין בְּאִלֵּין, הָכִי נָמֵי לְתַתָּא (ס\"א בחשוכא) בְּהִפּוּכָא, בְּסִטְרָא אַחֲרָא, אִית דַּרְגִּין, לְגַבֵּי אִינּוּן הֵיכָלִין דְּנוּקְבָּא, לְאִתְכַּלְּלָא אִלֵּין בְּאִלֵּין.</p>\n<p>בְּהַאי דַּרְגָּא, דְּאִיהוּ רְבִיעָאָה, קַיְימָן דִּינִין בִּישִׁין, לְנַחְתָּא לְתַתָּא, וּלְאִתְמַסְרָא לְאִינּוּן דְּעַבְדִין דִּינָא בִּישָׁא תַּקִּיפָא. מֵהָכָא יַנְקֵי תּוּקְפָּא דִּילְהוֹן, לְאַתְקְפָא, וּלְאַשְׁלְמָא הַהוּא דִּינָא דְּעַבְדֵי. וּבְגִין כָּךְ, כָּל הָנִי דַּרְגִּין כְּלִילָן בְּהוּ, בְּכָל אִינּוּן הֵיכָלִין תַּתָּאִין, דְּלִסְטַר נוּקְבָּא דִּלְתַתָּא. זַכָּאָה חוּלָקֵיהוֹן דְּצַדִּיקַיָּיא, דְּסָטוּ אָרְחַיְיהוּ מֵאוֹרְחָא דָּא, וְאַזְלֵי בָּתַר דַּחַלְתָּא דְקוּדְשָׁא בְּרִיךְ הוּא, לְאִתְקַדְּשָׁא בִּקְדוּשָּׁה דְּמָארֵיהוֹן, זַכָּאִין אִינּוּן בְּעָלְמָא דֵּין, וּבְעָלְמָא דְּאָתֵי.</p>\n<p>דַּרְגָּא חֲמִישָׁאָה. הַאי דַּרְגָּא אִתְפְּלִיג לִתְרֵין דַּרְגִּין (ס\"א סטרין) יְמִינָא, וּשְׂמָאלָא. (רל\"ב ע\"ב) וְאִלֵּין אִקְרוּן שׁוֹקִין, מִתְדַּבְּקָן לְאַבְאָשָׁא וּלְמִרְדַּף. בְּגִין דְּהָכָא תְּקִיפוּ דִּרְדִיפוּ. דְּכָל מַרְעִין, וְכָל בִּישִׁין, דְּרַדְפֵי בַּתְרַיְיהוּ דְּחַיָּיבַיָּא. וְכַד דִּינָא (ס\"א דרגא) דָּא אִתְקְרִיב, כְּדֵין הָרָצִים יָצְאוּ דְּחוּפִים. וְאִינּוּן רָצִים אִינּוּן לְתַתָּא, לְמִרְהַט לְאַבְאָשָׁא. וְכָל אִינּוּן אִקְרוּן רוֹדְפִים, וְעַל דָּא כְּתִיב (איכה ד׳:י״ט) קַלִּים הָיוּ רוֹדְפֵנוּ מִנִּשְׁרֵי שָׁמָיִם.</p>\n<p>הַאי דַּרְגָּא אִתְפְּלַג לִתְרֵין סִטְרִין, לִימִינָא וְלִשְׂמָאלָא. תְּלַת קִשְׁרִין אִינּוּן לִימִינָא. וּתְלַת (ויחי רמ\"א ע\"א) קִשְׁרִין אִינּוּן לִשְׂמָאלָא, וְאִלֵּין קִשְׁרִין, וְאִינּוּן קִשְׁרִין דְּקָאָמַרָן, כֻּלְּהוּ מִסְתַּכְּלָן לַאֲחוֹרָא. בְּגִין דְּאִינּוּן קִשְׁרִין עִלָּאִין <Nonei></i>קַדִּישִׁין, כֻּלְּהוּ (ויצא קכ\"ד) מִסְתַּכְּלָן לְגוֹ פְּנִימָאֵי לְגוּפָא, כְּמָה דְאַתְּ אָמֵר (מלכים א ז׳:כ״ה) וְכָל אֲחוֹרֵיהֶם בָּיְתָה. וְאִלֵּין כֻּלְּהוּ מִסְתַּכְּלָן לַאֲחוֹרָא.</p>\n<p>מַה בֵּין הַאי לְהַאי. אֶלָּא אִלֵּין קִשְׁרִין, עִלָּאִין קַדִּישִׁין כֻּלְּהוּ בְּרָזָא דְּאָדָם, וּבְגִין דְּכֹלָּא אִיהוּ בְּרָזָא דְּאָדָם, כָּל אֲחוֹרֵיהֶם בָּיְתָה כְּתִיב. וְאִלֵּין קִשְׁרִין אַחֲרָנִין דְּקָאָמַרָן, אִינּוּן קִשְׁרִין דְּאֶמְצָעִיתָא, כֻּלְּהוּ מִסְתַּכְּלָן לַאֲחוֹרָא, וְאִלֵּין אִינּוּן בְּרָזָא דִּבְהֵמָה. וּבְגִין כָּךְ כָּל אֲחוֹרֵיהֶם לַאֲחוֹרָא. וְרָזָא דָּא כְּמָה (רל\"ט ע\"ב) דְּאוֹקִימְנָא, (תהילים ל״ו:ז׳) אָדָם וּבְהֵמָה תּוֹשִׁיעַ יְיָ'. דָּא בְּסִטְרָא דְּאָדָם, וְדָא בְּסִטְרָא דִּבְהֵמָה. וְקָרְבָּנָא הָכִי סַלְּקָא, אָדָם וּבְהֵמָה.</p>\n<p>קִשְׁרָא קַדְמָאָה, בֵּיהּ קַיְּימָא גַּוְונָא דַּחֲשׁוֹכָא גּוֹ עוּרְפְלָא, (ס\"א גו טהירא דעורפילא) דְּצָמַח בְּאִתְלַטְיָיא תְּחוֹת אַבְנָא דְּקַיְּימָא עָלֵיהּ, דְּלָא צָמַח. וְהַאי קַיְּימָא עָלַיְיהוּ דְּזַכָּאֵי, דְּאִית בְּהוּ זַכְיָין, וְלָא אִית בְּהוּ זְכוּ דַּאֲבָהָתָא לְאִתַּתְקְפָא בְּהוּ, וּלְאַגָּנָא עָלַיְיהוּ.</p>\n<p>וְקַשְׁרִין אַחֲרָנִין, רַדְפֵי בָּתַר חַיָּיבַיָּא דְּסָטוּ אָרְחַיְיהוּ מִקַּדְמַת דְּנָא, וְרַדְפֵי אֲבַתְרַיְיהוּ, וְכָל אִינּוּן דִּרְשִׁימוּ אִתְחָזֵי בְּהוּ לְאִשְׁתְּמוֹדְעָא. בְּגִין דְּכָל אִינּוּן דְּאִתְחָזוּן לְאִתְעָנְּשָׁא, חַד מַלְאָכָא, שְׁלִיחָא קַדִּישָׁא, דִּי מִסִּטְרָא דִּגְבוּרָה, נָחִית וְרָשִׁים בְּהוּ רְשִׁימָא, וְהַהוּא רְשִׁימָא אִשְׁתְּמוֹדָע לְעֵילָּא, לְגַבֵּי כָּל אִינּוּן מָארֵיהוֹן דְּדִינָא. וְכַד הַהוּא רְשִׁימָא אִשְׁתְּמוֹדַע לְגַבַּיְיהוּ, מַאן דְּאִתְחָזֵי לְמַרְעִין, אַלְקֵי לֵיהּ בְּמַרְעִין. מַאן דְּאִתְחָזֵי לְמַכְאוֹבִין, וְלִשְׁאַר עוֹנָשִׁין, כֹּלָּא חָמָאן בְּהַהוּא רְשִׁימוּ.</p>\n<p>וּבְגִין דָּא, אִינּוּן קִשְׁרִין כֻּלְּהוּ קַיְימוּ לַאֲחוֹרָא, וּבַעֲטֵי בְּאִינּוּן דְּבַעֲטֵי בְּמָארֵיהוֹן, וּבְכָל אִינּוּן דְּאִתְחָזוּן לְבַעֲטָא בְּהוּ. בַּר צַדִּיקֵי וַחֲסִידֵי וְאִית לוֹן זְכוּ דַּאֲבָהָן, דְּמַרְעִין רַדְפִין אֲבַתְרַיְיהוּ, דְּאִלֵּין לָא שַׁלְטֵי בְּהוּ, וְלָא אָתֵי לוֹן מַרְעִין מִסִּטְרָא דָּא.</p>\n<p>וְאִי תֵּימָא, מֵאָן אֲתָר אָתֵי לוֹן מַרְעִין. תָּא חֲזֵי כְּתִיב, (ישעיהו נ״ג:י׳) וַיְיָ' חָפֵץ דַּכְּאוֹ הֶחלִי. וַיְיָ' חָפֵץ, דַּכְּאוֹ, אִתְרְעֵי לְמַחֲאָה לֵיהּ, וּלְמֵיהַב לֵיהּ מַרְעִין, בְּגִין לְזַכָּאָה לוֹן לְעָלְמָא דְּאָתֵי, וְלָא מִסִּטְרָא אַחֲרָא, וְאִלֵּין אִקְרוּן יִסּוּרִין דְּאַהֲבָה, וְכֹלָּא בְּחַד מַתְקְלָא דְּקוּדְשָׁא סַלְּקָא.</p>\n<p>דַּרְגָּא שְׁתִיתָאָה. הַאי אִקְרֵי עָרְלָה. וְדָא, וְכָל אִינּוּן דַּרְגִּין תַּתָּאִין, לְתַתָּא, כֻּלְּהוּ אִקְרוּן עָרְלָה, בְּגִין דְּיַנְקֵי מִסִּטְרָא דָּא. וְהַאי אִיהוּ גּוֹ רָזָא דְּנָחָ\"שׁ בָּרִיחַ. וְהַאי יָנִיק, לְהַהוּא נָחָ\"שׁ עֲקַלָּתוֹ\"ן. וְכֻלְּהוּ דַּרְגִּין אַחֲרָנִין, דְּאִתְאַחֲדָן בְּהַאי סִטְרָא, אִקְרוּן גּוּהַרְקֵי דְּעָרְלָה. וְכֹלָּא בְּרָזָא חֲדָא קָא אַזְלֵי.</p>\n<p>וְתָּא חֲזֵי, עַל דָּא, כָּל אִינּוּן אִילָנִין דְּאִתְנְטָעוּ בְּאַרְעָא, עַד לָא אִשְׁתְּרָשׁוּ, שַׁרְיָא עָלַיְיהוּ רוּחָא מִסִּטְרָא דְּהַאי עָרְלָה, וְעַל דָּא כְּתִיב, (ויקרא י״ט:כ״ג) וַעֲרַלְתֶּם עָרְלָתוֹ אֶת פִּרְיוֹ שָׁלשׁ שָׁנִים יִהְיֶה לָכֶם עֲרֵלִים לֹא יֵאָכֵל. בְּגִין דְקוּדְשָׁא בְּרִיךְ הוּא, חֲבִיבוּתָא דְּיִשְׂרָאֵל תָּדִיר לְגַבֵּיהּ, וְרָחִיק לוֹן, מִכָּל אוֹרְחִין בִּישִׁין, וְסִטְרִין בִּישִׁין וּמְסָאֲבִין, לְאִתְדַּבְּקָא בְּסִטְרָא דִּקְדוּשָּׁה. זַכָּאִין אִינּוּן בְּהַאי עָלְמָא וְזַכָּאִין אִינּוּן בְּעָלְמָא דְּאָתֵי.</p>"],[9520011920,"<p><Noneb>היכלות מסטרא דקדושה</b> אָמַר רִבִּי שִׁמְעוֹן, הָא תָּנֵינָן בְּאִינּוּן הֵיכָלִין, דְּאִינּוּן קַיְימִין, לְסַדְּרָא סִדּוּרָא דִּשְׁבָחָא דְקוּדְשָׁא בְּרִיךְ הוּא בֵּין סִדּוּרָא דְּקַיְּימָא בְּמִלָּה בֵּין סִדּוּרָא דְּקַיְּימָא בִּרְעוּתָא. בְּגִין דְּאִית סִדּוּרָא דְּקַיְּימָא בְּמִלָּה, וְאִית סִדּוּרָא דְּקַיְּימָא בִּרְעוּתָא וְכַוָּונָה דְּלִבָּא, לְמִנְדַּע וּלְאִסְתַּכְּלָא, בְּגִין לְאִסְתַּכְּלָא לְעֵילָּא לְעֵילָּא עַד אֵין סוֹף, דְּתַמָּן (קל\"ט ע\"א) תְּקִיעוּ דְּכָל רְעוּתִין וּמַחֲשָׁבִין, וְלָא קַיְימִין בְּמִלָּה כְּלַל, אֶלָּא כְּמָה דְּאִיהוּ סָתִים, הָכִי כָּל מִלּוֹי בִּסְתִימוּ.</p>\n<p>תָּא חֲזֵי (בראשית מ\"א ע\"א) הַאי דְּאַמָרָן בְּאִינּוּן הֵיכָלִין כֻּלְּהוּ (נ\"א תליין), כָּל אִינּוּן סִדּוּרִין אִינּוּן כְּלָלָא חֲדָא, בְּגִין לְאִתְכַּלְּלָא תַּתָּאֵי בְּעִלָּאֵי.</p>\n<p>אֲבָל תָּא חֲזֵי, מֹשֶׁה כַּד סִדֵּר צְלוֹתֵיהּ בְּגִינֵיהוֹן דְּיִשְׂרָאֵל, אָרִיךְ בְּהַאי צְלוֹתָא, בְּגִין דְּאִיהִי צְלוֹתָא דְּקַיְּימָא לְעֵילָּא. וְכַד סִדֵּר צְלוֹתֵיהּ בִּקְצִירוּ דְּאַחְתֵּיהּ, לָא אָרִיךְ בָּהּ, בְּגִין דְּקַיְּימָא לְתַתָּא. דִּכְתִּיב, (במדבר י״ב:י״ג) אֵל נָא רְפָא נָא לָהּ, ולָא אָרִיךְ יַתִּיר, בְּגִין (בראשית צ\"א ע\"ב) דְּאִיהוּ מָארֵי דְּבֵיתָא, וּפָקִיד בֵּיתֵיהּ כַּדְקָא חֲזִי, <Nonei></i>וּבְגִין כָּךְ לָא אָרִיךְ יַתִּיר בְּבָעוּתֵיהּ. (נ\"א ועל דא כולהו) וְכֻלְּהוּ סִדּוּרִין, לְאַשְׁרָאָה שְׁכִינְתָּא בְּעָלְמָא, כְּמָה דְּאוֹקִימְנָא בְּכָל אִינּוּן (שאר) הֵיכָלִין דְּקָאָמַרָן.</p>\n<p>רַבִּי שִׁמְעוֹן קָם וְאָמַר, זַכָּאָה חוּלָקָא דִּילָךְ אָדָם קַדְמָאָה, בְּרִירָא דְּכָל נִבְרָאִין, דְּקַיְימִין בְּעָלְמָא, דְּרַבֵּי לָךְ קוּדְשָׁא בְּרִיךְ הוּא עַל כֹּלָּא, וְאָעִיל לָךְ בְּגִנְתָּא דְּעֵדֶן, וְאַתְקִין לָךְ ז' חוּפּוֹת בֵּיהּ, לְאִשְׁתַּעְשְׁעָא בְּעִנּוּגָא דְּנֹעַם עִלָּאָה, כְּמָה דְאַתְּ אָמֵר (תהילים כ״ז:ד׳) לַחֲזוֹת בְּנֹעַם יְיָ' וּלְבַקֵּר בְּהֵיכָלוֹ. לַחֲזוֹת בְּנֹעַם יְיָ' לְעֵילָּא. וּלְבַקֵּר בְּהֵיכָלוֹ לְתַתָּא. לַחֲזוֹת בְּנוֹעַם יְיָ', בְּאִינּוּן שִׁבְעָה רְקִיעִין לְעֵילָּא, וּלְבַקֵּר בְּהֵיכָלוֹ בְּאִינּוּן שִׁבְעָה רְקִיעִין דִּלְתַתָּא, וְאִלֵּין קַיְימִין אִלֵּין לָקֳבֵל אִלֵּין.</p>\n<p>וּבְכֻלְּהוּ קָמְת בְּגִנְתָּא דְּעֵדֶן. אִינּוּן שִׁבְעָה חוּפּוֹת עִלָּאִין קַדִּישִׁין, קַיְימוּ עֲלָךְ לְעֵילָּא, לְאִתְעַטְּרָא בְּהוּ. וְאִינּוּן ז' תַּתָּאִין, קָמְת בְּהוּ לְאִשְׁתַּעְשְׁעָא בְּהוּ, וּבְכֻלְּהוּ אַשְׁלִים לָךְ מָארָךְ, לְמֶהֱוֵי שְׁלִים בְּכֹלָּא.</p>\n<p>עַד דְּאִתְדְּחוּ רַגְלָךְ, בָּתַר עֵיטָא דְּהַהוּא חִוְיָא בִּישָׁא, וְאִתְתַּרָכְת מִגִּנְתָּא דְּעֵדֶן, וְגַרָמְת מוֹתָא לָךְ, וּלְכָל עָלְמָא, בְּגִין דְּשַׁבָקְת אִלֵּין עִדּוּנִין דִּלְעֵילָּא וְתַתָּא, וְאִתְמַשָּׁכְת בָּתַר אִינּוּן כִּסוּפִין מִסְאָבִין, דְּאִקְרוּן (איוב כ׳:ט״ז) רֹאשׁ פְּתָנִים, דְּגוּפָא מָשִׁיךְ בְּהוּ, וְלָא רוּחָא. כְּמָה דְאַתְּ אָמֵר, (דברים ל״ב:ל״ג) וְרֹאשׁ פְּתָנִים אַכְזָר. וּכְתִיב עֲנָבֵימוֹ עִנְּבֵי רֹאשׁ. עַד דְּאָתָא אַבְרָהָם חֲסִידָא, וְשָׁארִי לְאַתְקְנָא עָלְמָא, וְעָאל גּוֹ מְהֵימְנוּתָא קַדִּישָׁא, וְאַתְקִן לְעֵילָּא וְתַתָּא, בְּאִינּוּן רְקִיעִין עִלָּאִין, וּבְאִינּוּן רְקִיעִין תַּתָּאִין.</p>\n<p>אִינּוּן תַּתָּאִין, הֵיכָלִין לְאִינּוּן רְקִיעִין עִלָּאִין, לְאִתְאַחֲדָא דָּא בְּדָא, וּלְאִתְקַשְּׁרָא דָּא בְּדָא, כְּמָה דְּאוֹקִימְנָא בְּאִינּוּן הֵיכָלִין דְּקָאָמַרָן. וְאַף עַל גַּב דְּאוֹקִימְנָא הָתָם גּוֹ כְּלָלָא, הָכָא אִית לָן לְפַרְטָא מִלִּין, וּלְאַתְקְנָא לְיִחוּדָא כְּדְקָא יֵאוֹת, בְּגִין דְּלָא יִטְעוּן חַבְרַיָּיא, וְיֵהָכוּן בְּאֹרַח מֵישָׁר, כְּמָה דִּכְתִּיב (הושע י״ד:י׳) כִּי יְשָׁרִים דַּרְכֵי יְיָ' וְצַדִּיקִים יֵלְכוּ בָּם וְגוֹ'.</p>"],[9520011921,"<p><Noneb>היכל לבנת הספיר יסוד ועטרה</b> הֵיכָלָא קַדְמָאָה. שֵׁירוּתָא גּוֹ מְהֵימְנוּתָא, וְהַאי אִיהוּ שֵׁירוּתָא לְרָזָא דִּמְהֵימְנוּתָא, וּבְדַרְגִין דְּחֵיזוּ דִּמְהֵימְנוּתָא. נְבִיאֵי קְשׁוֹט, הֲווֹ חָמָאן מִגּוֹ דָּא אַסְפָקָלַרְיָא דְּאֵינָה מְאִירָה, וּבְגִין דְּהַאי אִיהוּ שֵׁירוּתָא דִּמְהֵימְנוּתָא, כְּתִיב (הושע א׳:ב׳) תְּחִלַּת דִּבֶּר יְיָ' בְּהוֹשֵׁעַ. דְּחָמָא מִגּוֹ דַּרְגָא דָּא, דְּאִיהוּ שֵׁירוּתָא דְּכָל דַּרְגִּין לְסַלְּקָא לְעֵילָּא, וְסוֹפָא דְּכָל דַּרְגִּין לְנַחְתָּא לְתַתָּא.</p>\n<p>וּבְגִין דְּהוֹשֵׁעַ חָמָא מִגּוֹ שֵׁירוּתָא דָּא, סוֹפָא דְּכָל דַּרְגִּין, אִצְטְרִיךְ לְנַטְלָא הַאי אֵשֶׁת זְנוּנִים, בְּגִין דְּיִשְׂרָאֵל אִתְדָּחוּ וְאִתְמְשָׁכוּ מִתַמָּן לְתַתָּא, לְגַבֵּי הַהוּא אֲתָר דְּאִקְרֵי אֵשֶׁת זְנוּנִים, בְּגִין דְּשַׁבְקוּ, וְלָא אִתְדָּבָּקוּ בְּהַאי אֵשֶׁת חַיִל. וְחָמָא מִתַמָּן כָּל אִינּוּן הֵיכָלִין דְּאִינּוּן בְּסִטְרָא מְסַאֲבָא. (דאית ליה)</p>\n<p>הֵיכָלִין דִּמְסָאֲבָא, כֻּלְּהוּ מִסְאָבִין לְמַאן דְּאִתְדָּבַּק בְּהוֹן, וְעַל דָּא כְּתִיב, קַח לְךָ אֵשֶׁת זְנוּנִים וְגוֹ'. וְכִי נְבִיאָה דִּקְשׁוֹט אִצְטְרִיךְ לְדָא. אֶלָּא, בְּגִין דְּאָסִיר לֵיהּ לְבַר נָשׁ לְאַעֲלָא בְּאִינּוּן הֵיכָלִין, בְּגִין דְּלָא יִתְמְשַׁךְ אֲבַתְרַיְיהוּ, כְּגַוְונָא דְּעָבַד נֹחַ, דִּכְתִּיב, (בראשית ט׳:כ״א) וַיֵּשְׁתְּ מִן הַיַּיִן וַיִּשְׁכָּר וַיִּתְגַּל.</p>\n<p>וְהוֹשֵׁעַ דָּחִיל לְאִסְתַּכְּלָא בְּאִינּוּן הֵיכָלִין דְּאִסְתְּאָבוּ בְּהוּ יִשְׂרָאֵל וְאִתְדְּבָּקוּ, דְּלָא יִתְמְשַׁךְ אֲבַתְרַיְיהוּ, כְּמָה דִּכְתִּיב בְּנֹחַ וַיֵּשְׁתְּ מִן הַיַּיִן וַיִּשְׁכָּר וַיִּתְגַּל. עַד דְּאָמַר לֵיהּ, קַח לְךָ אֵשֶׁת זְנוּנִים וְיַלְדֵי זְנוּנִים. וּכְתִיב וַיֵּלֶךְ וַיִּקַּח אֶת גֹּמֶר בַּת דִּבְלָיִם. לְמִנְדַּע בְּמָה דְּאִתְדְּבָּקוּ וְאִסְתְּאָבוּ, וְשָׁבְקוּ רָזָא דִּמְהֵימְנוּתָא, בְּגִין (רמ\"ג ע\"א) אֵל נִכָר. וְעַל דָּא, חָמָא מִגוֹ הֵיכָלָא דָּא, שֵׁירוּתָא דְּכָל דַּרְגִּין.</p>\n<p>הֵיכָלָא דָּא, שֵׁירוּתָא דְּכֹלָּא, לְסַלְּקָא בְּדַרְגִּין. הַאי הֵיכָלָא, אִיהוּ מָדוֹרָא דְּקַיְּימָא בִּנְהִירוּ. לְאִתְעַטְּרָא בְּדַרְגּוֹי, לְאִסְתַּכְּלָא בְּאִינּוּן דַּרְגִּין עִלָּאִין, דִּכְתִּיב, (שמות כ״ד:י׳) וַיִּרְאוּ אֵת אֱלֹהֵי יִשְׂרָאֵל.</p>\n<p>בְּהַאי הֵיכָלָא, חַד מְמָנָא שַׁמָשָׁא טָהֲרִיאֵ\"ל שְׁמֵיהּ. וְאִיהוּ קַיְּימָא עַל פִּתְחָא דְּהַהוּא הֵיכָלָא, וְכָל נִשְׁמָתִין דְּסַלְּקִין, קַיְּימָא הַאי מְמָנָא בְּהַאי פִּתְחָא, וְכַמָּה מְמָנָן אַחֲרָנִין עִמֵּיהּ, כֻּלְּהוּ אֶשָּׁא דִּמְלַהֲטָא, וְשַׁרְבִיטִין דְּאֶשָּׁא (רי\"ב ע\"א) בִּידַיְיהוּ, וְכֻלְּהוּ <Nonei></i>מָארֵי דְּעַיְינִין. הַאי מְמָנָא קַיְּימָא בְּסִטְרָא דָּא, אִי זַכָאַת הַאי נִשְׁמְתָא לְמֵיעַל, הַאי מְמָנָא פָּתַח פִּתְחָא וְעָאלַת.</p>\n<p>וְאִי לָא זַכָּאַת, הַהוּא מְמָנָא אַחֲרָא דְּקַיְּימָא בְּסִטְרָא אַחֲרָא, זַמִּין, וְכַמָּה אֶלֶף וְרִבְבָן גַּרְדִּינֵי נִימוּסִין עִמֵּיהּ. דָּחֵי לָהּ הַהוּא מְמָנָא אַחֲרָא קַדִּישָׁא, וְנָקִיט לָהּ הַאי אַחֲרָא, דִּי בְּסִטְרָא דִּמְסָאֲבָא, וְאָעִיל לָהּ גּוֹ אִינּוּן הֵיכָלֵי מִסְאֲבֵי. וְכָל אִינּוּן גַּרְדִּינֵי נִימוּסִין אַחְדֵּי לָהּ, עַד דְּנַחְתֵּי לָהּ לַגֵיהִנָּם, וְאִתְדָּנַת תַּמָּן תְּרֵיסָר יַרְחֵי. תִּקּוּנָא דְּהַהוּא סִטְרָא אַחֲרָא, בֵּי דִּינָא לְאַתְדְּנָא בְּהוּ חַיָּיבַיָּא.</p>\n<p>כְּגַוְונָא דָּא, הַהוּא מְמָנָא קַדִישָׁא, דְּקַיְּימָא עַל הַהוּא פִּתְחָא, כָּל אִינּוּן צְלוֹתִין, דְּבַקְעֵי אֲוִירִין וּרְקִיעִין, לְמֵיעָאל קַמֵּי מַלְכָּא, אִי צְלוֹתָא דְּסַגִיאִין אִינּוּן, פָּתַח פִּתְחָא, וְאָעִיל הַהוּא צְלוֹתָא עַד דְּאִתְעָבֵידוּ כָּל צְלוֹתִין דְּעָלְמָא, עֲטָרָא בְּרֵישָׁא דְּצַדִיק חַי עָלְמִין, כְּמָה דְּאוּקְמוּהָ.</p>\n<p>וְאִי צְלוֹתָא דְּיָחִיד, סַלְּקָא עַד דְּמָטֵי לְפִתְחָא דְּהֵיכָלָא דָּא, דְּהַאי מְמָנָא קַיְּימָא בֵּיהּ. אִי יָאָה הַהִיא צְלוֹתָא, לְאַעֲלָא קַמֵּי מַלְכָּא קַדִישָׁא (יאות), מִיַּד פָּתַח פִּתְחָא, וְאָעִיל לָהּ. וְאִי לָא יָאָה, דָּחֵי לָהּ לְבַר, וְנַחְתָא וְאִתְּשַׁטְיָא בְּעָלְמָא, וְקַיְּימָא גּוֹ רְקִיעָא תַּתָּאָה מֵאִינּוּן רְקִיעִין דִּלְתַתָּא, דִּמְדָבְרֵי גּוֹ עָלְמָא, וּבְהַהוּא רְקִיעָא, קַיְּימָא חַד מְמָנָא דִּי שְׁמֵיהּ סָהֲדִיאֵ\"ל, וּמְמָנָא עַל הַאי רְקִיעָא. וְנָטִיל כָּל הָנֵי צְלוֹתִין דְּאִתְדַחְיָין, דְּאִקְרוּן צְלוֹתֵי פְּסִילָאן וְגָנִיז לוֹן, עַד דְּאִתְּדָּן (נ\"א דתב) הַהוּא בַּר נָשׁ.</p>\n<p>אִי תָּב לְגַבֵי מָארֵיהּ כְּדְקָא יֵאוֹת, וְצַלֵּי צְלוֹתָא אַחֲרָא זַכָּאָה, הַהִיא צְלוֹתָא זַכָּאָה כַּד סַלְּקָא, נָטִיל הַהוּא מְמָנָא סָהֲדִיאֵ\"ל הַאי צְלוֹתָא, וְסָלִיק לָהּ לְעֵילָּא, עַד דְּאִעְרַע בְּהַהִיא צְלוֹתָא זַכָּאָה, וְסַלְּקִין וְאִתְעָרְבוּן כַּחֲדָא, וְעָאלִין קַמֵּי מַלְכָּא קַדִישָׁא.</p>\n<p>וּלְזִמְנִין אִתְדַחְיָא הַהִיא צְלוֹתָא, בְּגִין דְּהַהוּא בַּר נָשׁ אִתְמְשָׁךְ בָּתַר סִטְרָא אַחֲרָא, וְאִיהוּ אִסְתְּאַב בְּהַהוּא סִטְרָא, וְנָטִיל לָהּ הַהוּא מְמָנָא דִּי בְּהַהוּא סִטְרָא אַחֲרָא מְסַאֲבָא. וּכְדֵין קַיְּימָא הַהוּא סִטְרָא אַחֲרָא מְסַאֲבָא. סָלִיק וְאַדְכַּר חוֹבוֹי דְּהַהוּא בַּר נָשׁ קָמֵי קוּדְשָׁא בְּרִיךְ הוּא, וְאַסְטֵי עָלֵיהּ לְעֵילָּא. וְעַל דָּא, כָּל צְלוֹתִין, וְכָל נִשְׁמָתִין, כַּד סַלְּקִין, כֻּלְּהוֹן סַלְּקִין וְקַיְימָן קָמֵי הֵיכָלָא דָּא. וְהַאי מְמָנָא קַיְּימָא עַל פִּתְחָא דְּהֵיכָלָא דָּא, לְאַעֲלָא נִשְׁמָתִין וּצְלוֹתִין, אוֹ לְדַחְיָיא לוֹן לְבַר.</p>\n<p>לְעֵילָּא מֵהַאי פִּתְחָא, אִית פִּתְחָא אַחֲרָא, דְקוּדְשָׁא בְּרִיךְ הוּא חָתִיר לָהּ וְאִתְפְּתַח תְּלַת זִמְנֵי בְּיוֹמָא, וְלָא אַנְעִיל, וְקַיְּימָא לְאִינּוּן מָארֵיהוֹן דְּתִיוּבְתָא, דִּי אוֹשְׁדִין דִּמְעָה בִּצְלוֹתְהוֹן קָמֵי מָארֵיהוֹן. וְכָל תַּרְעִין וּפִתְחִין נִנְעָלוּ, עַד דְּעַיְילֵי בִּרְשׁוּתָא, בַּר תַּרְעִין אִלֵּין, דְּאִקְרוּן שַׁעְרֵי דִּמְעָה.</p>\n<p>וְכַד הַאי צְלוֹתָא דְּדִמְעָה סַלְּקָא לְעֵילָּא, לְאַעֲלָא בְּאִינּוּן תַּרְעִין, אִזְדָּמַן הַהוּא אוֹפָן דְּקַיְּימָא עַל שִׁית מֵאָה חֵיוָון רַבְרְבָן, וְרַחֲמִיאֵ\"ל שְׁמֵיהּ, וְנָטִיל הַהִיא צְלוֹתָא, בְּאִינּוּן דִּמְעִין, צְלוֹתָא עָאלַת וְאִתְקָשָּׁרַת לְעֵילָּא. וְאִינּוּן דִּמְעִין אִשְׁתָּאֲרוּ הָכָא, וּרְשִׁימִין בְּהַאי פִּתְחָא.</p>\n<p>וְאִית דִּמְעִין אַחֲרָנִין, וּרְשִׁימִין תָּדִיר עַל כֹּל אִינּוּן רְתִיכִין עִלָּאִין, דְּלָא אִתְמְחוּן (ס\"א אתחמון). אִלֵּין אִינּוּן דִּמְעִין, דְּאוֹשְׁדוּ לְעֵילָּא וְתַתָא, כַּד אִתְחָרַב בֵּי מַקְדְשָׁא, דִּכְתִיב (ישעיהו ל״ג:ז׳) הֵן אֶרְאֶלָּם צָעֲקוּ חוּצָה מַלְאֲכֵי שָׁלוֹם מַר יִבְכָּיוּן. וְאִינּוּן דִּמְעִין דְּאוֹשְׁדִין עַל צַדִיקַיָּיא, וְזַכָּאִין, כַּד מִסְתַּלְּקֵי מֵעָלְמָא. כֻּלְּהוּ נַטְלֵי לוֹן אִינּוּן רְתִיכִין, וְעַרְבֵי לוֹן בְּאִינּוּן דִּמְעִין, דְּאִתוֹשְׁדוּ עַל חָרִיבוּ דְּבֵי מַקְדְשָׁא וְעַל דָּא כְּתִיב, (ישעיהו כ״ה:ח׳) וּמָחָה יְיָ' אֱלהִים דִּמְעָה מֵעַל כָּל פָּנִים. מַאן פָּנִים. אִלֵּין רְתִיכִין עִלָּאִין קַדִישִׁין. וּלְבָתַר וְחֶרְפַּת עַמּוֹ יָסִיר מֵעַל כָּל הָאָרֶץ כִּי יְיָ' דִּבֵּר.</p>\n<p>בְּהַאי הֵיכָלָא, אִית רוּחַ דְּאִקְרֵי (רל\"ג ע\"א) סִטוּטְרִיָ\"ה, וְהַאי אִיהוּ חֵיזוּ סָפִירָא, דְּנָצִיץ לְכָל עֵיבָר, וְהַאי אִיהוּ דְּקַיְּימָא לִתְרֵין סִטְרִין, וּמֵאִלֵּין מִתְפָּרְשָׁאן נְצִיצִין כִּנְצִיצוּ דְּשַׁרְגָא, כְּמָה (בראשית ע\"א) דְּאוֹקִימְנָא בְּכַמָּה סִטְרִין. וְכַמָּה <Nonei></i>גַּוְונִין מְלַהֲטָן מֵהַאי בְּסִטְרָא דִּימִינָא.</p>\n<p>כַּד הַהוּא רְקִיעָא עִלָּאָה, נָהָר דְּנָגִיד וְנָפִיק מֵעֵדֶן, אַפִיק נִשְׁמָתִין, לְאַעֲלָא גּוֹ הֵיכָלָא שְׁבִיעָאָה לְעֵילָּא, הַהוּא הֵיכָלָא שְׁבִיעָאָה נָקִיט לוֹן. וְכַד נַפְקֵי אִינּוּן נִשְׁמָתִין קַדִישִׁין, מִגוֹ הַהוּא הֵיכָלָא שְׁבִיעָאָה, נַחְתִין עַד דְּמָטוּן לְהַאי הֵיכָלָא, וְנָקִיט לוֹן הַאי רוּחָא קַדִישָׁא סִטְטוּרִיָ\"ה (סטוטרי\"ה) שְׁמֵיהּ, דְּאִיהוּ לִימִינָא. וְכָל אִינּוּן נִשְׁמָתִין דְּכוּרִין, דְּאִינּוּן זְמִינִין לְאִתְפָּרְחָא בְּזַכָּאִין דְּכוּרִין, לִימִינָא כֻּלְּהוּ נָקִיט לוֹן, וּמִתְעַכְּבֵי תַּמָּן, עַד דְּאִתְכְּלִילוּ בְּנִשְׁמָתִין דְּנוּקְבֵי.</p>\n<p>מֵהַאי רוּחָא נָפְקָא (ר\"ס ע\"א) רוּחָא אַחֲרָא, לִשְׂמָאלָא. דְּאִתְחָזֵי וְאִתְגְּנִיז וְאִתְכְּלִיל בְּהַאי רוּחָא קַדְמָאָה, וְאִינּוּן חַד, כְּלִילָן דָּא בְּדָא. וְהַאי רוּחָא אַחֲרָא, אִקְרֵי אַדִירִיָּ\"הּ סָנוּגְיָ\"א. סניגי\"ה (נ\"א סנוגיא סטניה) הַאי אִיהוּ רוּחָא לִשְׂמָאלָא. וְהַאי קַיְּימָא, דְּכַד תִּיאוּבְתָּא דְּהֵיכָלָא שְׁבִיעָאָה לְאִתְדַּבְּקָא (רנ\"ח ע\"א) בְּהַהוּא נָהָר דְּנָגִיד וְנָפִיק, הַהוּא רְעוּתָא דְּסַלְּקָא מִתַּתָּא לְעֵילָּא, עָבְדָא נִשְׁמָתִין בִּרְעוּתָא דִּילֵיהּ, וְאִינּוּן נוּקְבֵי.</p>\n<p>וְכַד רְעוּתָא דְּהַהוּא נָהָר, נַחְתָּא וְאִתְדַּבְּקָא מֵעֵילָּא לְתַתָּא, עַבְדִּין נִשְׁמָתִין דְּכוּרִין. רְעוּתָא דִּלְעֵילָּא עָבִיד דְּכוּרִין. רְעוּתָא דִּלְתַּתָּא עָבִיד נוּקְבִין.</p>\n<p>וְכַד אִלֵּין נִשְׁמָתִין נוּקְבִין נָפְקִין מִגּוֹ הַהוּא הֵיכָלָא שְׁבִיעָאָה, נַחְתִּין (ס\"א נפקין) עַד דְּמָטוּ לְהַאי רוּחָא שְׂמָאלָא, דְּאִקְרֵי אַדִּירִיָּ\"הּ. וְאִקְרֵי לִבְנַ\"ת הַסַּפִּי\"ר. כְּמָה דְּאוֹקִימְנָא בְּסִטְרִין אַחֲרָנִין.</p>\n<p>כֵּיוָן דְּמָטוּ לְהַאי רוּחָא אִינּוּן נִשְׁמָתִין נוּקְבִין, נַקְטָא לוֹן הַאי רוּחָא, וְקַיְימָאן בֵּיהּ. וּלְבָתַר אִתְכְּלִילוּ רוּחָא דָּא דִּשְׂמָאלָא, בְּרוּחָא דָּא דִּימִינָא. וּכְדֵין אִתְעָבִידוּ אִינּוּן נִשְׁמָתִין, כְּלִילָן דְּכַר וְנוּקְבָּא כַּחֲדָא (מזדווגן) וּפַרְחָאן מֵהַאי הֵיכָלָא וְאִתְפָּרְשָׁן בִּבְנֵי נָשָׁא. (כד אתא לאתכללא) כָּל חַד כְּפוּם אָרְחֵיהּ, וּלְבָתַר מִזְדַּוְּוגָן כַּחֲדָא.</p>\n<p>(כד אתא לאתכללא) רוּחָא דָּא דִּשְׂמָאלָא בִּימִינָא, בָּטַשׁ דָּא בְּדָא לְאִתְכַּלְּלָא. וְנַפְקֵי נְצִיצִין דְּמִתְפַּשְּׁטֵי לְכָל עֵיבָר, וְאִתְעָבִידוּ אִינּוּן אוֹפַנִּים מִנַּיְיהוּ, מֵאִינּוּן נְצִיצִין דְּנַפְקֵי מִגּוֹ רוּחָא שְׂמָאלָא, דִּכְתִּיב בְּהוּ, (יחזקאל א׳:ט״ז) מַרְאֶה הָאוֹפַנִּים וּמַעֲשֵׂיהֶם כְּעֵין תַּרְשִׁישׁ. וְאִלֵּין אִינּוּן אוֹפַנִּים דִּמְלַהֲטָן אֶשָּׁא, וְקַיְימִין בְּשִׁירָתָא.</p>\n<p>כֵּיוָן דְּאִתְבְּסָמוּ רוּחָא בְּרוּחָא, וְאִתְכְּלִילוּ כַּחֲדָא, כְּדֵין נָפְקָא חַד נְהִירוּ דְּסַלְּקָא וְנַחְתָּא, וּמִתְיַשְּׁבָא עַל אַרְבַּע שׁוּרִין דְּאוֹפַנִים, וְאִיהוּ חַד חֵיוָתָא דְּשַׁלְטָא עָלַיְיהוּ, וְאִקְרֵי בָּזָק, הַאי בָּזָק נָהִיר בִּנְהוֹרָא דְּנָצִיץ גּוֹ שַׁלְהוֹבָא, וְשַׁלְטָא עַל כָּל אִינּוּן אוֹפַנִּים.</p>\n<p>וְאִתְפָּשַּׁט מִנֵּיהּ חַד רְקִיעָא, דְּקַיְּימָא עַל תְּרֵין סַמְכִין, וְאִינּוּן תְּרֵין סַמְכִין אִינּוּן תְּרֵין כְּרוּבִין, חַד מִסִּטְרָא דָּא, וְחַד מִסִּטְרָא דָּא. וְהַאי רָקִיעַ עַל רֵישַׁיְיהוּ, כְּמָה דִּכְתִּיב, (יחזקאל י׳:א׳) וָאֶרְאֶה וְהִנֵּה אֶל הָרָקִיעַ אֲשֶׁר עַל רֹאשׁ הַכְּרוּבִים. וְלָאו הַאי רָקִיעַ דְּעַל רֵישׁ חֵיוָתָא. וְהַאי בָּזָק מְמָנָא עָלֵיהּ, וְרוּחָא עִלָּאָה דְּאִתְכְּלִיל, עַל כֹּלָּא.</p>\n<p>כָּל אִינּוּן צְלוֹתִין, דִּמְקַדְּמֵי עַל לָא סַיְימֵי יִשְׂרָאֵל כֻּלְּהוּ צְלוֹתֵהוֹן, מִתְעַכְּבֵי בְּהַאי רְקִיעָא, וְהַאי בָּזָק דְּשַׁלְטָא עַל הַאי רְקִיעָא, מְתַקֵּן לוֹן. עַד דְּאָתָא סַנְדַּלְ\"פוֹן רַב מְמָנָא, רוּחַ עִלָּאָה, דְּשַׁלִּיט עַל כֹּלָּא, וְכַד סַיְימֵי יִשְׂרָאֵל כֻּלְּהוּ צְלוֹתִין, נָטִיל לוֹן מֵהַאי רְקִיעָא, וְסַלְּקָא וְקָשִׁיר לוֹן קִשְׁרִין (וכתרין) לְמָארֵיהּ כְּמָה דְּאוּקְמוּהָ.</p>\n<p>הַאי בָּזָק, קָאִים לְמִמְנֵי כָּל אִינּוּן צְלוֹתִין דְּסַלְקָן, וְכָל אִינּוּן מִלֵּי דְּאוֹרַיְיתָא דְּמִתְעַטְּרָן בְּלֵילְיָא, כַּד רוּחָא דְּצָפוֹן אַתְעַר, וְלֵילְיָא אִתְפְּלַג כָּל מַאן דְּקָאִים בְּהַהִיא שַׁעֲתָא, וְאִתְעֲסָק בְּאוֹרַיְיתָא, כָּל אִינּוּן מִלִּין סַלְּקִין, וְנָטִיל לוֹן הַאי בָּזָ\"ק, וְאָנַח לוֹן בְּהַאי רְקִיעָא, עַד דְּסַלְּקָא יְמָמָא.</p>\n<p>וּלְבָתַר דְּסָלִיק יְמָמָא, סַלְקָן אִינּוּן מִלִּין, וְשָׁארָן בַּאֲתָר דִּרְקִיעָא, דְּבֵיהּ (בראשית ל\"א ע\"א) תַּלְיָין כֹּכָבַיָא וּמַזָּלֵי שִׁמְשָׁא וְסִיהֲרָא. וְהַאי אִקְרֵי (ע' ע\"א) סֵפֶר הַזִּכָּרוֹן, דִּכְתִּיב, (מלאכי ג׳:ט״ז) וַיִּכָּתֵב סֵפֶר זִכָּרוֹן לְפָנָיו. לְפָנָיו, בְּגִין דְּסֵפֶר וְזִכָּרוֹן כְּתָב בְּקִשּׁוּרָא חֲדָא.</p>\n<p>אִינּוּן אַרְבַּע גַּלְגַּלִּין, אִינּוּן נַטְלִין עַל תְּרֵיסָר סַמְכִין. אִלֵּין ד', אַהֲנִיאֵ\"ל. קְדוּמִיאֵ\"ל (ס\"א קדומי\"א מלכיא\"ל) יְאֲהַדוֹנָהִ\"י, (ר\"מ ע\"ב) יְהֲדוֹנִיָּ\"ה. דִּי מַפְתְּחָאן דִּשְׁמָא קַדִּישָׁא בִּידַיְיהוּ.</p>\n<p>וְאִלֵּין אַרְבַּע אִינּוּן כְּלִילָן <Nonei></i>בְּרָזָא דְּאַתְוָון (ר\"ס ע\"א) אֲדֹנָ\"י, דִּי סַנְדַּלְפוֹ\"ן מָארֵי רְתִיכִין. מִשְׁתַּמֵשׁ בְּהוּ. אִלֵּין אַרְבַּע אַתְוָון פַּרְחִין בַּאֲוִירָא, דְּהַהוּא אֲוִירָא כָּלִיל בְּאַתְוָון דִּשְׁמָא קַדִּישָׁא, יְהוָֹ\"ה, יוֹ\"ד הֵ\"א וָא\"ו הֵ\"א. וְהַהוּא אֲוִירָא כָּלִיל לוֹן, וְאִתְכְּלִילוּ אִלֵּין בְּאִלֵּין. וְאִלֵּין ד' נַטְלִין לוֹן, בְּרָזָא דְּהַהוּא בָּזָק.</p>\n<p>וְאִלֵּין ד' עָאלִין בְּד', אִלֵּין בְּאִלֵּין, דִּכְתִּיב, (שמות כ״ו:ה׳) מַקְבִּילוֹת הַלּוּלָאוֹת אֶחָת אֶל אֶחָת. וְהָא אוֹקִימְנָא, וְרָזָא אִיהוּ לְאִתְכַּלְּלָא אִלֵּין בְּאִלֵּין, וּלְשַׁלְּבָא אִלֵּין בְּאִלֵּין, בְּרָזָא דְּהַהוּא רוּחָא דְּכָלִיל בְּרָזָא דִּשְׁמָא קַדִּישָׁא. דְּכָלִיל שְׁמָא דָּא בִּשְׁמָא דָּא.</p>\n<p>וְכֹלָּא בְּהַאי הֵיכָלָא מִתְנַהֲגֵי, וְנַטְלֵי בְּהַהוּא רוּחָא, בְּרָזָא דִּשְׁמָא קַדִּישָׁא דְּשַׁלִּיט עַל כֹּלָּא. בְּהַאי הֵיכָלָא אִיהוּ יְאַהֲדוֹנָהִ\"י, כְּלָלָא דִּתְרֵין שְׁמָהָן, מִגּוֹ דְּאִיהוּ רוּחָא בְּרוּחָא. וְכַד שְׁמָא דָּא, דְּכָלִיל בְּרָזָא דְּרוּחָא בְּרוּחָא, וְכָלִיל דָּא בְּדָא. נָהִיר דָּא בְּדָא, כְּדֵין נָהִיר כֹּלָּא, וְסַלְּקָא נְהוֹרָא וְנַחְתָּא, כִּנְהוֹרָא דְּשִׁמְשָׁא גּוֹ מַיָּא ואוֹקִימְנָא.</p>\n<p>וּכְדֵין (כד) הַאי רוּחָא נָטִיל, כֹּלָּא נַטְלִין בְּגִינֵיהּ, דִּכְתִּיב, (יחזקאל א׳:י״ב) אֶל אֲשֶׁר יִהְיֶה שָּׁמָּה הָרוּחַ לָלֶכֶת יֵלֵכוּ לא יִסַּבּוּ בְּלֶכְתָּן. וְכַד רוּחָא דָּא נָהִיר בִּשְׁמָא דָּא, כְּדֵין עָאלִין כֻּלְּהוּ דָּא בְּדָא, וְאִתְקַשָּׁרוּ כֻּלְּהוּ כַּחֲדָא, לְסַלְּקָא לְעֵילָּא, בְּרָזָא דִּשְׁמָא דָּא קַדִּישָׁא.</p>\n<p>בְּאֶמְצָעִיתָא דְּהֵיכָלָא דָּא, קַיְּימָא חַד עַמּוּדָא, נָעִיץ מֵהֵיכָלָא דָּא לְהֵיכָלָא תִּנְיָינָא, בְּהַאי סָלִיק רוּחָא דִּלְתַּתָּא לְגַבֵּי רוּחָא דִּלְעֵילָּא, לְאִתְאַחֲדָא רוּחָא בְּרוּחָא, וְכֵן עַד לְעֵילָּא מְכֻּלְּהוּ, לְמֶהֱוֵי כֻּלְּהוּ רוּחָא חֲדָא, כְּמָה דְאַתְּ אָמֵר וְרוּחַ אֶחָד לָהֶם (לכל).</p>\n<p>עַמּוּדָא דָּא דְּקַיְּימָא בְּאֶמְצָעִיתָא, אַדְרָהָנִי\"אֵל שְׁמֵיהּ, וְרָזִין דְּמַפְתְּחָן דִּשְׁמָא קַדִּישָׁא בִּידֵיהּ. כַּד צְלוֹתִין סַלְּקָאן וּמָטָאן לְהַאי עַמּוּדָא, כְּדֵין נַטְלֵי כֻּלְּהוּ דְּאִינּוּן בְּהֵיכָלָא דָּא, לְגוֹ הֵיכָלָא תִּנְיָינָא, לְאִתְאַחֲדָא דָּא בְּדָא, לְמֶהֱוִי כֹּלָּא בְּרָזָא חֲדָא, לְאִתְיַיחֲדָא עֵילָּא וְתַתָּא כַּחֲדָא לְמֶהֱוֵי שְׁמָא קַדִּישָׁא שְׁלִים כְּדְקָא יֵאוֹת.</p>"],[9520011922,"<p><Noneb>היכל עצּם השמים הו\"ד</b> הֵיכָלָא תִּנְיָינָא הֵיכָלָא דָּא, קַיְּימָא גּוֹ רָזָא דִּמְהֵימְנוּתָא, לְאִתְאַחֲדָא בְּרָזָא דִּלְעֵילָּא. הַאי הֵיכָלָא, טָמִיר וְגָנִיז יַתִיר מִן קַדְמָאָה. בְּהֵיכָלָא דָּא, אִית תְּלַת פִּתְחִין, וְחַד שַׁמָשָׁא מְמָנָא עָלַיְיהוּ, אוּרְפָנִי\"אֵל שְׁמֵיהּ. הַאי מְמָנָא, שַׁלִּיט עַל תְּלַת סִטְרֵי עָלְמָא, דָּרוֹם וְצָפוֹן וּמִזְרָח. דָּרוֹם מֵהַאי סִטְרָא, וְצָפוֹן מֵהַאי סִטְרָא, וּמִזְרָח בְּאֶמְצָעִיתָא.</p>\n<p>אִלֵּין תְּלַת פִּתְחִין, לִתְלַת סִטְרִין אִלֵּין. תְּרֵין סְתִימִין, וְחַד בְּאֶמְצָעִיתָא פָּתִיחַ, בְּרָזָא דִּכְתִיב, (שמות כ״ד:י׳) וּכְעֶצֶם הַשָּׁמַיִם לָטֹהַר. הַאי מְמָנָא אִתְפְּקַד וְקַיְּימָא בְּהַהוּא פִּתְחָא דְּאִיהוּ פָּתִיחַ, וּתְחוֹת יְדֵיהּ תְּרֵין מְמָנָן אַחֲרָנִין, דִּמְמָנָן עַל אִינּוּן פִּתְחִין אַחֲרָנִין סְתִימִין.</p>\n<p>וְכָל אִינּוּן נִשְׁמָתִין, דְּאִינּוּן קְטוּלֵי בֵּית דִּין, אוֹ אִינּוּן קְטוּלֵי שְׁאַר עַמִּין, כֻּלְּהוּ אִתְמָנָן תְּחוֹת יְדֵיהוֹן, וְהַאי מְמָנָא דְּעָלַיְיהוּ, חָקִיק לוֹן לְדִיּוּקְנֵיהוֹן בִּלְבוּשׁוֹי, דְּאִינּוּן נוּר דָּלִיק, וְסָלִיק לוֹן לְעֵילָּא, וְאַחְמֵי לוֹן לְמָארֵיהּ, וּכְדֵין נָטִיל לוֹן, וְחָקִיק לוֹן בְּפוּרְפּוּרוֹי, לְאִינּוּן קְטוּלֵי שְׁאַר עַמִּין.</p>\n<p>וְאִינּוּן קְטוּלֵי בֵּית דִּין, נָחִית לוֹן הַאי מְמָנָא, וְאָעִיל לוֹן בָּתַר אִינּוּן תְּרֵין פִּתְחִין סְתִימִין, דְּאִינּוּן תְּרֵין מְמָנָן אַחֲרָנִין קַיְימִין עָלַיְיהוּ, וְתַמָּן חָמָאן יְקָרָא דְּכָל אִינּוּן דְּקַיְימוּ אוֹרַיְיתָא, וְנָטְרוּ פִּקּוֹדוֹי, וְאִינּוּן כְּסִיפִין בְּגַרְמַיְיהוּ, וְנִכְוִין מֵחוּפָּה דִּלְהוֹן. עַד דְּהַאי מְמָנָא דְּקַיְּימָא עָלַיְיהוּ, פָּתַח לוֹן תַּרְעָא דְּמִזְרָח, וְנָהִיר לוֹן, וְיָהִיב לוֹן חַיִּים דְּאִתְפָּתָחוּ בְּהַהוּא תַּרְעָא דְּמִזְרָח. וּבִידָא דְּהַהוּא מְמָנָא חַד כַּסָּא דְּחַיִּין, דְּאִיהוּ מַלְיָא נְהוֹרִין, וְהַאי אִקְרֵי כּוֹס תַּנְחוּמִין, כַּסָא דְּחַיֵּי. (נ\"א ונהיר ויהיב לון חיים) דְּהָא בְּגִין כַּסָּא אַחֲרָא דְּשָׁתוּ בְּקַדְמִיתָא, זָכוּ לְהַאי.</p>\n<p>כְּגַוְונָא דָּא אִית בְּסִטְרָא אַחֲרָא, בְּהֵיכָלָא דִּמְסָאֲבָא, מְמָנָא אַחֲרָא, וּבִידֵיהּ כּוֹס דְּאִקְרֵי (ויקרא י\"ב ע\"ב, רס\"ד ע\"א) כּוֹס תַּרְעֵלָה, כּוֹס חֲמָתוֹ. כְּמָה דְּתָנֵינָן, אִית יַיִן וְאִית יַיִן, הָכִי נָמֵי אִית כּוֹס וְאִית כּוֹס, וְכֹלָּא, דָּא לְטָב, וְדָא לְבִישׁ. יַיִן לְטָב, דִּכְתִּיב, (תהילים ק״ד:ט״ו) וְיַיִן יְשַׂמַּח לְבַב אֱנוֹשׁ. וְיַיִן לְבִישׁ, דִּכְתִּיב, (תהילים ע״ה:ט׳) וְיַיִן חָמַר מָלֵא מֶסֶךְ וְגוֹ'. כּוֹס לְטָב, דִּכְתִּיב, (תהילים קט״ז:י״ג) כּוֹס יְשׁוּעוֹת אֶשָּׂא. כּוֹס <Nonei></i>לְבִישׁ, דִּכְתִּיב, (ישעיהו נ״א:י״ז) כּוֹס חֲמָתוֹ כּוֹס הַתַּרְעֵלָה.</p>\n<p>כְּמָה דְּאִית בְּסִטְרָא דִּקְדוּשָּׁה, הֵיכָלִין וּמְמָנָן כֹּלָּא לְטָב, וְרוּחִין קַדִּישִׁין וְכָל סִטְרִין קַדִּישִׁין. הָכִי נָמֵי אִית בִּסְטָר מְסַאֲבָא, הֵיכָלִין וּמְמָנָן כֻּלְּהוּ לְבִישׁ, וְרוּחִין מִסְאָבִין, מְמָנָן, וְכָל סִטְרִין מִסְאָבִין. וְדָא לָקֳבֵל דָּא, כְּגוֹן יֵצֶר הַטּוֹב וְיֵצֶר הָרָע, וְכֹלָּא בְּרָזָא חֲדָא.</p>\n<p>הֵיכָלָא דָּא אִקְרֵי הֵיכָל זוֹהַר, בְּגִין דְּאִית בֵּיהּ רוּחָא, דְּאִקְרֵי אוּרְפָנִיאֵ\"ל. וְאִיהוּ זוֹהַר דְּלָא אִשְׁתַּנִּי, וְקַיְּימָא בִּנְהִירוּ סְתִימָא, דְּנָהִיר מֵעֵילָּא, וּבִנְהִירוּ דְּנָהִיר לְתַתָּא. וְכַד בָּטַשׁ נְהִירוּ דִּלְתַתָּא בִּנְהִירוּ עִלָּאָה, (נ\"א וכד נהיר נהורא בנהורא) נָהִיר הַאי רוּחָא, כְּגַוְונָא דְּחֵיזוּ דְּעֵינָא, דְּכַד מִתְגַּלְגְּלָא, כְּדֵין אַפִּיק נְהוֹרָא דְּנָצִיץ וְזָהֲרָא, הָכִי נָמֵי הַאי רוּחָא. וְעַל דָּא, הֵיכָלָא דָּא אִקְרֵי זוֹהַר.</p>\n<p>הַאי רוּחָא דְּאִקְרֵי אוּרְפָנִי\"אֵל, הַאי אִיהוּ דְּנָהִיר לְהֵיכָלָא דָּא, וְנָהִיר לְהֵיכָלָא קַדְמָאָה, בְּגִין דְּהַהוּא רוּחָא דְּהֵיכָלָא קַדְמָאָה, נָהִיר בְּאִתְגַּלְיָא, בֵּהַאי (ד\"א מהאי) רוּחָא דְּאִיהוּ סְתִימָאָה. דָּא רוּחָא נָטִיל לְעֵילָּא וְנָטִיל לְתַתָּא, בְּרָזָא דִּכְתִּיב, (שיר השירים ז׳:ב׳) חַמּוּקֵי (רנ\"ח ע\"א) יְרֵכַיִךְ כְּמוֹ חֲלָאִים. וּמַה דְּאָמַר חַמּוּקֵי יְרֵכַיִךְ. בְּגִין דְּאִית רוּחָא אַחֲרָא דְּנָפִיק מִנֵּיהּ לִסְטַר שְׂמָאלָא, וְאִתְקָשַׁר בַּהֲדֵיהּ. וְעַל דָּא כְּתִיב חַמּוּקֵי תְּרֵין. וְהַאי רוּחָא שְׂמָאלָא אִקְרֵי הֲדַרְנִיאֵ\"ל, וְאִתְכְּלִילוּ דָּא בְּדָא, כְּלִילָן כַּחֲדָא, וְאִינּוּן עֶצֶם הַשָּׁמַיִם, דִּכְלִילָא בְּאֵשׁ וּמַיִם.</p>\n<p>כְּתִיב (יחזקאל א׳:כ״ח) כְּמַרְאֵה הַקֶּשֶׁת אֲשֶׁר יִהְיֶה בֶעָנָן בְּיוֹם הַגֶּשֶׁם וְגוֹ'. הַאי רוּחָא קַדְמָאָה אוּרְפָנִיאֵ\"ל, דְּאִיהוּ סָתִים בֵּין עֵילָּא וְתַתָּא, וְנָהִיר, אִיהוּ (יחזקאל א׳:כ״ז) כְּעֵין חַשְׁמָל, הַאי אִיהוּ כְּעֵין חַשְׁמָל, וּלְזִמְנִין אִיהוּ חַשְׁמָל. בְּגִין דְּמִנֵּיהּ קַיְימִין כָּל אִינּוּן שְׂרָפִים (פ\"א ע\"ב) חֵיוָון אֶשָּׁא מְמַלְּלָן, חֵיוָון דְּקַיְימֵי וְלָא קַיְימֵי, וְעַל דָּא אִיהוּ חַשְׁמָל.</p>\n<p>אוּרְפָנִיאֵ\"ל דְּקָאָמַרָן, בְּדָא אִשְׁתְּמוֹדְעָן חַיִּין לְעָלְמָא. כַּד אִתְּדָן עָלְמָא לְטָב, כְּדֵין נָהִיר רוּחָא דָּא, וְכָל חַיִּין וְכָל חִדוּ אִשְׁתְּכַח, דְּהָא כֵּיוָן דִּזְכוּתָא נָפְקָא, וּנְהִירוּ דִּינִין כְּדֵין רוּחָא דָּא אַנְהִיר. וְסִימָנִךְ (משלי ט״ז:ט״ו) בְּאוֹר פְּנִי מֶלֶךְ חַיִּים.</p>\n<p>וְכַד אִתְּדָּן עָלְמָא בְּדִינָא, (בההוא זכותא) כְּדֵין הַהוּא סִטְרָא אַחֲרָא מְסַאֲבָא, שַׁלְטָא וְאִתָּקַף, (ס\"א וכד אתדן עלמא בדינא בההוא זכותא, כדין ההוא רוחא אחרא שלטא ואתקף) וְהַאי רוּחָא אִגְנִיז וְאִתְחֲשָׁךְ, וּכְדֵין כָּל עָלְמָא קַיְּימָא בְּדִינָא וְאִתְּדָּן. וְכֹלָּא קַיְּימָא בְּהַאי רוּחָא. וְסִימָנִיךְ (דניאל ה׳:ו׳) וְאַרְכֻּבָתֵיהּ דָּא לְדָא נָקְשָׁן.</p>\n<p>הָכָא קַיְימָן, כָּל אִינּוּן מַלְבּוּשִׁין דְּנִשְׁמָתְהוֹן דְּצַדִּיקַיָּיא, דְּסַלְּקִין לְאִתְחֲזָאָה קַמֵּי מָארִיהוֹן, וּלְקַיְּימָא קַמֵּיהּ. וְכַד נִשְׁמְתָא סַלְּקָא וּמָטֵי לְהַאי הֵיכָלָא, כְּדֵין אִזְדָּמַן חַד מְמָנָא, דְּאִתְפְּקַד עַל אִינּוּן לְבוּשִׁין, וְצִדְקִיאֵ\"ל שְׁמֵיהּ. דְּהָא בְּזִמְנָא דְּבַּר נָשׁ עָבִיד פִּקוּדִין דְּאוֹרַיְיתָא בְּהַאי עָלְמָא, כְּגַוְונָא דְּאִיהוּ אִשְׁתָּדַּל גַּרְמֵיהּ, הָכִי אִתְעָבִיד לֵיהּ בְּהַאי הֵיכָלָא לְעֵילָּא, מַלְבּוּשָׁא לְאִתְלַבְּשָׁא בֵּיהּ, בְּהַהוּא עָלְמָא.</p>\n<p>וְכַד נִשְׁמְתָא סַלְּקָא, הַהוּא מְמָנָא נָטִיל הַהוּא לְבוּשָׁא דִּילָהּ, וְאָזִיל עִמָּהּ עַד דִּי מָטָא לְנָהָר דִּינוּר, דִּי נִשְׁמְתָא אִצְטְרִיכָא לְאִתְסַחְיָיא וּלְאִתְלַבְּנָא תַּמָּן, וּלְזִמְנִין דְּטַבְעָא הַהִיא נִשְׁמְתָא תַּמָּן וְאִתּוֹקְדָא, וְלָא סַלְּקָא כֹּלָּא יוֹמָא, עַד בְּצַפְרָא, כַּד אַתְעַר רוּחָא דְּסִטְרָא דְּדָרוֹם, כְּדֵין קַיְימֵי כֻּלְּהוּ וּמִתְחַדְּשָׁן, וְאַמְרֵי שִׁירָתָא, וּמְזַמְּרָן כְּגַוְונָא דְּאִינּוּן מַלְאֲכִין דְּאִתְעֲבָר (צו ל\"ב ע\"ב) שֻׁלְטָנֵהוֹן וְאִתּוֹקְדָן, וְקַיְימָן וּמִתְחַדְּשָׁן כְּמִלְּקַדְּמִין, וְאַמְרֵי שִׁירָתָא, (ואזלי לון) הָכִי נָמֵי אִלֵּין נִשְׁמָתִין.</p>\n<p>וְאִי זַכָּאָת הַאי נִשְׁמְתָא וְסַלְקַת. הַאי מְמָנָא צִדְקִיאֵ\"ל, נָטִיל לָהּ לְהַאי נִשְׁמְתָא, וְאַלְבִּישׁ לָהּ בְּהַהוּא לְבוּשָׁא, וְאִתַּקְנָת בֵּיהּ, וְסַלְּקָא לְקָרְבָּנָא עַל יְדָא דְּמִיכָאֵל כַּהֲנָא, לְקַיְּימָא תָּדִיר כָּל יוֹמִין קָמֵי עַתִּיק יוֹמִין, זַכָּאָה חוּלָקָא דְּהַאי נִשְׁמְתָא, דְּקַיְּימָא וְזָכָאת לְהַאי.</p>\n<p>וּבְכֹלָּא, אִתְמָנָא הַאי רוּחָא אוּרְפָנִיאֵ\"ל דְּקָאָמַרָן, וְאִיהוּ שַׁלִּיט עַל הַאי הֵיכָלָא. מִכְּלָלָא דָּא, כַּד אִתְכְּלִיל רוּחָא בְּרוּחָא, וּבָטַשׁ דָּא בְּדָא לְאִתְכַּלְּלָא כַּחֲדָא, אִתְבְּרִיאוּ אִינּוּן שַׁלִּיטִין אַחֲרָנִין דְּאִתְמְנָן עַל עָלְמָא, וְאִלֵּין אִינּוּן שְׂרָפִים דְּשִׁית גַּדְפִּין. דִּמְקַדְּשֵׁי לְמָרֵיהוֹן תְּלַת <Nonei></i>זִמְנִין בְּיוֹמָא. וְאִלֵּין אִינּוּן דִּמְדַקְדְקֵי עִם צַדִּיקַיָּיא, אֲפִילּוּ כְּחַד נִימָא דְּשַׂעֲרָא. וְאִלֵּין אִינּוּן דְּקַיְימֵי לְאַעְנָשָׁא, בְּהַאי עָלְמָא וּבְעָלְמָא דְּאָתֵי. וּלְאִינּוּן דִּמְזַלְזְלֵי לְבַּר נָשׁ דְּאוֹלִיפוּ מִנֵּיהּ אֲפִילּוּ מִלָּה חֲדָא בְּאוֹרַיְיתָא, וְלָא מְנָהֲגֵי בֵּיהּ יְקָר. וּלְכָל אִינּוּן דְּמִשְׁתַּמְשֵׁי, בְּמַאן דְּקָארִי שִׁית סִדְרֵי מִשְׁנָה, לְיַחֲדָא יִחוּדָא דְּמָארֵיהוֹן.</p>\n<p>כַּד מִתְיַשְּׁבָן רוּחָא בְּרוּחָא, וְאִתְנָהֲרָן כַּחֲדָא. מֵהַהוּא נְהִירוּ נָפְקָא חֵיוָתָא חֲדָא, דְּשַׁלְטָא עַל אִינּוּן שְׂרָפִים, וְאַרְבַּע תְּחוֹתָהּ, דְּאַנְפַּיְיהוּ אַנְפִּין דְּנֶשֶׁר, הַאי חֵיוָתָא יוֹפִיאֵ\"ל שְׁמֵיהּ, וְאִיהִי קַיְּימָא בְּכָל רָזֵי דְּחָכְמְתָא, לְכָל אִינּוּן מַפְתְּחָאן דְּחָכְמְתָא קַיְימִין בֵּיהּ.</p>\n<p>הַאי חֵיוָתָא, קַיְּימָא לְמִתְבַּע אַגְרָא מֵעִם קוּדְשָׁא בְּרִיךְ הוּא, לְמֵיהַב לְכָל אִינּוּן דְּרַדְפֵי בָּתַר כָּל מָארֵיהוֹן דְּחָכְמָה, וַאֲפִילּוּ מִכָּל בַּר נָשׁ, וְאוֹלְפֵי חָכְמָה לְמִנְדַּע לְמָארֵיהוֹן, וְהַהוּא אַגְרָא דְּיָהִיב לִבְנֵי נָשָׁא דְּרַדְפֵי בָּתַר חָכְמָה לְמִנְדַּע לְמָארֵיהוֹן.</p>\n<p>דְּכַד נָפַק בַּר נָשׁ מֵהַאי עָלְמָא, הַאי חֵיוָתָא נָפְקָא עַל ד' שְׂרָפִים מְעֹפְפִין, וְטָאסַת קַמֵּיהּ, וְלָא שָׁבִיק כָּל אִינּוּן גַּרְדִּינֵי נִימוּסִין דִּי בְּסִטְרָא אַחֲרָא, לְמִקְרַב בַּהֲדֵיהּ, וְכַמָּה אִינּוּן שְׁלִיחָן דִּשְׁלָם, סַחֲרָנֵיהּ. וְאִלֵּין שְׂרָפִים כַּד נַטְלִין וְאִתְחַזְּיָין, אִתְכַּפְיָין אִינּוּן שְׂרָפִים נְחָשִׁים, דְּנַפְקָן מֵהַהוּא נָחָשׁ דְּגָרִים מוֹתָא לְכָל עָלְמָא.</p>\n<p>הַאי חֵיוָתָא קַדִּישָׁא קַיְּימָא כַּד נִשְׁמְתָא סַלְּקָא וּמָטָאת לְגַבֵּיהּ, כְּדֵין שָׁאַל לָהּ בְּרָזָא דְּחָכְמְתָא דְּמָארֵיהּ, וּכְפוּם הַהִיא חָכְמְתָא דְּרָדִיף אֲבַתְרָהּ וְאַדְבַּק (ס\"א בה), הָכִי יַהֲבֵי לֵיהּ אַגְרֵיהּ. וְאִי יָכִיל לְאַדְבְּקָא וְלָא אַדְבַּק, דָּחֵי לֵיהּ לְבַר, וְלָא עַיְילָה, וְקַיְּימָא תְּחוֹת הַהוּא הֵיכָלָא בִּכְסִיפוּ, וְכַד נַטְלֵי גַּדְפַיְיהוּ, אִלֵּין שְׂרָפִים דִּתְחוֹתָהּ, כְּדֵין כֻּלְּהוּ בַּטְשֵׁי בְּגַדְפַיְיהוּ, וְאוֹקְדוּן לָהּ וְאִתּוֹקְדַת וְלָא אִתּוֹקְדַת, וְקַיְּימָא וְלָא קַיְּימָא, וְהָכִי אִתְּדָנָת בְּכָל יוֹמָא, נְהִירַת וְלָא נְהִירַת.</p>\n<p>וְאַף עַל גַּב דְּעוֹבָדִין טָבִין אִית לָהּ, בְּגִין (בראשית קל\"ב) דְּלֵית אַגְרָא בְּהַהוּא עָלְמָא, כְּאִינּוּן דְּמִשְׁתַּדְּלֵי בְּחָכְמְתָא, לְאִסְתַּכְּלָא בִּיקָרָא דְּמָארֵיהוֹן, וְלֵית שִׁיעוּרָא לְאַגְרָא, דְּאִינּוּן דְּיַדְעֵי חָכְמְתָא, לְאִסְתַּכְּלָא בִּיקָרָא דְּמָארֵיהוֹן. זַכָּאָה חוּלָקֵיהוֹן בְּעָלְמָא דֵּין, וּבְעָלְמָא דְּאָתֵי, דִּכְתִּיב, (משלי ג׳:י״ג) אַשְׁרֵי אָדָם מָצָא חָכְמָה וְאָדָם יָפִיק תְּבוּנָה.</p>\n<p>רוּחָא דָּא, שַׁלְטָא עַל כֹּלָּא. כֹּלָּא כְּלִילָן בָּהּ, כֹּלָּא אִסְתַּכְיָין לְגַבָּהּ. הַאי חֵיוָתָא, שַׁלְטָא עַל אַרְבַּע אַחֲרָנִין, וְאַרְבַּע גַּלְגַּלִּין לְכָל חַד וְחַד. גַּלְגַּלָּא חֲדָא אִסְתָּכֵי לִסְטַר מִזְרָח. וְגַלְגַּלָּא חֲדָא אִסְתָּכֵי לִסְטַר צָפוֹן. וְגַלְגַּלָּא חֲדָא אִסְתָּכֵי לִסְטַר דָּרוֹם. וְגַלְגַּלָּא חֲדָא אִסְתָּכֵי לִסְטַר מַעֲרָב. וְכָל חַד וְחַד בִּתְלַת סַמְכִין. גַּלְגַּלָּא דְּלִסְטַר מִזְרָח. חַנִיאֵ\"ל שְׁמֵיהּ. גַּלְגַּלָּא דְּלִסְטַר צָפוֹן, קַרְשִׁיאֵ\"ל שְׁמֵיהּ. גַּלְגַּלָּא דְּלִסְטַר דָּרוֹם, עַזְרִיאֵ\"ל שְׁמֵיהּ. גַּלְגַּלָּא דְּלִסְטַר מַעֲרָב, עָנִיאֵ\"ל שְׁמֵיהּ. וְאִינּוּן תְּלַת סַמְכִין דְּאִינּוּן לְכָל חַד וְחַד, כֻּלְּהוּ אִסְתַּכְיָין לְאֶמְצָעִיתָא. בְּגִין דְּאֶמְצָעִיתָא אִיהוּ נָטִיל לוֹן, וְכֻלְּהוּ נַטְלוּ בְּגִינֵיהּ דְּאֶמְצָעִיתָא.</p>\n<p>אִלֵּין דְּקַיְימֵי בְּאֶמְצָעִיתָא, כֻּלְּהוּ מְמָנָן בְּשִׁירָתָא. וְאִלֵּין דִּימִינָא אָמְרֵי שִׁירָתָא, דְּסַלְּקָא רְעוּתָא לְעֵילָּא, וְאָמְרֵי קָדוֹשׁ. וְאִלֵּין דִּשְׂמָאלָא אָמְרֵי שִׁירָתָא, וְסַלְקֵי רְעוּתָא לְעֵילָּא, וְאַמְרֵי בָּרוּךְ. קָדוֹשׁ לְעֵילָּא, וּבָרוּךְ לְתַתָּא. אִלֵּין דְּקַיְימֵי לְעֵילָּא לִסְטַר יְמִינָא, נַטְלֵי קְדוּשָּׁה, וּמִתְחַבְּרָאן בִּקְדוּשָּׁה, בְּכָל אִינּוּן דְּיַדְעֵי לְקַדְּשָׁא לְמָארֵיהוֹן, בְּיִחוּדָא בְּרָזָא דְּחָכְמְתָא. וְאִלֵּין דְּקַיְימֵי בִּשְׂמָאלָא, נַטְלֵי קְדוּשָּׁה, וּמִתְחַבְּרָאן בְּכָל אִינּוּן דְּלָא יַדְעֵי לְקַדְּשָׁא לְמָארֵיהוֹן כַּדְקָא יֵאוֹת. וְכֻלְּהוּ כְּלִילָן אִלֵּין בְּאִלֵּין בְּיִחוּדָא חֲדָא, וּמִתְקַשְּׁרָאן דָּא בְּדָא, עַד דְּכֻלְּהוּ אִתְעָבִידוּ קִשּׁוּרָא חֲדָא, וְרוּחָא חֲדָא, וּמִתְקַשְּׁרָן בְּאִינּוּן דִּלְעֵילָּא, לְמֶהֱוִי כֹּלָּא חַד, לְאִתְכַּלְּלָא דָּא בְּדָא.</p>\n<p>מֵאֲתָר דָּא, יַנְקֵי כָּל אִינּוּן מָארֵיהוֹן דְּחָכְמְתָא, דְּקַיְימָן לְמִנְדַּע (וישב קנ\"א ע\"ב, רנ\"ז ע\"ב) בְּמַרְאֶה, אוֹ בְּרָזָא (תיקון י\"א ע\"ב, כ\"א, רנ\"ח ע\"א, ע\"א ע\"ב, רס\"ב ע\"א) דְּחֶלְמָא, בְּגִין דִּנְבִיאִים יַנְקֵי מִלְעֵילָּא. וְאִלֵּין מָארֵי דְּחֶלְמָא, אוֹ דְּמַרְאֶה, יַנְקֵי מֵהָכָא. וְכַד מִתְחַבְּרָא אַתְרָא דָּא בְּאַתְרָא דִּלְעֵילָּא בְּקִשּׁוּרָא חֲדָא, כְּדֵין נְבִיאִים, יַנְקֵי מֵעֵילָּא וּמִתַּתָּא, בְּקִשּׁוּרָא חֲדָא.</p>\n<p><Nonei></i>וּבְגִין כָּךְ, אִית מָשָׁל בְּמִלַּיְיהוּ, דְּלָא צַחְצְחָא נְבוּאַתְהוֹן כְּדְקָא יֵאוֹת, כְּמָה דְּהֲוָה בֵּיהּ בְּמֹשֶׁה, דְּהֲוָה צִחְצוּחָא בִּנְבוּאָתֵיהּ בְּכֹלָּא. בְּגִין דִּנְהִירוּ נָפִיק מֵעֵילָּא, מֵאֲתָר דְּכָל נְהוֹרִין נָפְקִין מִנֵּיהּ, וּמָטָא לְדַרְגֵּיהּ, וּמִתַּמָּן יָנִיק נְבוּאָתֵיהּ, וְנָהִיר, מַה דְּלָא הֲוָה כְּדֵין לְכֹלָּא, לְכָל שְׁאַר נְבִיאִין. אִינּוּן מָארֵיהוֹן דְּחֶלְמָא, מָארֵיהוֹן דְּמַרְאֶה, כֻּלְּהוּ יַנְקֵי מֵאֲתָר דָּא לְתַתָּא, בְּלָא חִבּוּרָא דִּלְעֵילָּא, עַל יְדָא דְּדַרְגָא אַחֲרָא תַּתָּאָה מִינֵּיהּ דְּאִיהוּ לְבַר.</p>\n<p>כְּמָה דְּדַרְגָא דִּנְבִיאִים דִּלְעֵילָּא, לָא הֲווֹ חָמָאן לֵיהּ נְבִיאִים, בַּר עַל יְדָא דְּדַרְגָא אַחֲרָא תַּתָּאָה. הָכִי נָמֵי אִלֵּין, דַּרְגָּא דִּיְנִיקוּ דִּילְהוֹן אִיהוּ לְעֵילָּא, בְּהַאי דַּרְגָּא תַּתָּאָה, אֲבָל לָא אִתְגַּלְיָא לוֹן, אֶלָּא עַל יְדָא דְּדַרְגָא אַחֲרָא לְבַר, דְּאִיהוּ תַּתָּאָה מִנֵּיהּ, בְּגִין דְּנָפְקָא מֵהַאי הֵיכָלָא, וּמָטָא מִלָּה עַד הַהוּא מְמָנָא דְּקַיְּימָא עַל תַּרְעָא דְּהֵיכָלָא דָּא, וּמִתַּמָּן לְהַהוּא מְמָנָא דִּתְחוֹת יְדֵיהּ, וְכֵן עַד (ס\"א כלהו) דְּכַמָּה אִינּוּן דְּנַטְלֵי הַהִיא מִלָּה, וְאִתְעָרְבוּ בַּהֲדָהּ. וְעַל דָּא כַּד מָטָא לְגַבֵּיהּ דְּבַר נָשׁ, כַּמָה אִינּוּן דְּאִתְעַרְבֵי בַּהֲדָהּ, וְעַל דָּא לָא צַחְצְחָא מִלָּה כַּדְקָא יֵאוֹת.</p>\n<p>כַּד מִתְחַבְּרִין אִלֵּין אַרְבַּע גַּלְגַּלִּין, בְּאַרְבַּע אִינּוּן דִּי בְּאֶמְצָעִיתָא, כְּדֵין כֻּלְּהוּ אִקְרוּן חֲמוּדוֹת. וְאִינּוּן מָארִיהוֹן, דְּמַרְאֶה. וּבְגִין כָּךְ, הַאי חֵיוָתָא דְּקַאמְרָן, שַׁלְטָא עָלַיְיהוּ. וּבְגִין כָּךְ, אִקְרֵי דָּנִיאֵל, אִישׁ חֲמוּדוֹת. דִּכְתִּיב, (דניאל ט׳:כ״ג) כִּי חֲמוּדוֹת אָתָּה. וְכֹלָּא רָזָא כְּדְקָא יֵאוֹת. זַכָּאִין אִינּוּן דְּיַדְעִין רָזֵי דְּמָארֵיהוֹן, לְמֵיהַךְ בְּאֹרַח קְשׁוֹט, בְּעָלְמָא דֵּין וּבְעָלְמָא דְּאָתֵי.</p>"],[9520011923,"<p><Noneb>היכל נוגה נצּ\"ח</b> הֵיכָלָא תְּלִיתָאָה. הֵיכָלָא דָּא, הֵיכָלָא דְּקַיְּימָא בִּנְהִירוּ עִלָּאָה, יַתִיר עַל כָּל אִלֵּין קַדְמָאֵי. בְּהֵיכָלָא דָּא קַיְימִין אַרְבַּע פִּתְחִין, חַד לִסְטַר דָּרוֹם, וְחַד לִסְטַר מִזְרָח, וְחַד לִסְטַר צָפוֹן, וְחַד לִסְטַר מַעֲרָב. בְּכָל פִּתְחָא וּפִתְחָא אִית מְמָנָא חֲדָא, דְּקַיְּימָא מְמָנָא עַל כָּל פִּתְחָא וּפִתְחָא.</p>\n<p>פִּתְחָא קַדְמָאָה, דָּא פִּתְחָא דְּקַיְּימָא בֵּיהּ חַד מְמָנָא, מַלְכִּיאֵ\"ל שְׁמֵיהּ. וְאִיהוּ שַׁלִּיטָא עַל כָּל אִינּוּן פִּתְקִין, דְּנַפְקֵי מִבֵּי דִּינָא דְּמַלְכָּא, לְאִתְדְּנָא עָלְמָא. (בההוא פתקא) בְּגִין דְּהַאי אִיהוּ מְמָנָא לְאַשְׁגָחָא בְּהוּ בְּאִינּוּן פִּתְקִין, וּתְרֵין סוֹפְרִין תְּחוֹת יְדֵיהּ, חַד מִימִינָא וְחַד מִשְּׂמָאלָא.</p>\n<p>לְהַאי, אִתְיְיהִיבוּ תִּקּוּנֵי פִּתְקִין לְאַתְקְנָא, עַד לָא יִפְקוּן מֵהַאי תַּרְעָא לְבַר, וְיִתְמְסָרוּ בִּידָא דְּהַהוּא מְמָנָא, דִּי בְּהֵיכָלָא קַדְמָאָה. דְּהָא מִזִּמְנָא דְּאִתְמְסָרוּ בִּידָא דְּהַהוּא מְמָנָא דִּבְהֵיכָלָא קַדְמָאָה, הָא נַפְקֵי מִתַמָּן, וְלֵית רְשׁוּ לְאָתָבָא לוֹן.</p>\n<p>דְּהָא מִיַּד אִזְדָמַן מְמָנָא דְּסִטְרָא אַחֲרָא מְסַאֲבָא, מָארֵיהּ דְּדִינָא קַשְׁיָא תַּקִּיפָא, דְּלָא מְרַחֵם, וְסַנְגַדִיאֵ\"ל (ס\"א וסהדיאל) שְׁמֵיהּ, וְאִיהוּ מְמָנָא עַל תַּרְעָא דְּהֵיכָלָא קַדְמָאָה (ס\"א גריס אחרא, ולא גריס קדמאה) דִּי בְּסִטְרָא אַחֲרָא, דְּאִיהוּ גֵּיהִנָּם, וְכַמָּה אִינּוּן גַּרְדִּינִי נִימוּסִין מְמָנָן לְשַׁטְיָא בְּעָלְמָא, וּזְמִינִין לְמֶעְבַּד דִּינָא.</p>\n<p>וּבְגִין כַּךְ, קַיְּימָא הַהוּא מְמָנָא לְעַיְינָא בְּפִתְקִין, וְאִינּוּן תְּרֵין סוֹפְרִין דְּקַיְימֵי תְּחוֹת מְמָנָא דָּא, שַׁמָּשִׁיאֵ\"ל וְקָמוּאֵ\"ל, אִלֵּין סוֹפְרִין לְאַתְקְנָא פִּתְקִין, וְהַהוּא מְמָנָא עָלַיְיהוּ דְּאִיהוּ מַלְכִּיאֵ\"ל. בְּגִין דִּבְאִינּוּן הֵיכָלִין דִּי בִּסְטַר אַחֲרָא מְסַאֲבָא, אִתְפְּקִידוּ מְמָנָן יְדִיעָאן, בְּהִפּוּכָא מֵאִלֵּין מְמָנָן דִּי בְּהֵיכָלִין אִלֵּין, וְכָל אִינּוּן רוּחִין וְכָל אִינּוּן מְמָנָן, דְּתַמָּן, כֻּלְּהוּ לְאַבְאָשָׁא.</p>\n<p>תָּא חֲזֵי, הַאי סַנְגַדִיאֵ\"ל (ס\"א סהדיאל) כַּד נָטִיל פִּתְקָא, מִסִּטְרָא דְּהַהוּא מְמָנָא דְּקַיְּימָא לְפִתְחָא קַדְמָאָה, פָּתַח חַד פִּתְחָא, לְסִטְרָא דַּחֲשׁוֹכָא, דְּאִקְרֵי בְּאֵר שַׁחַת, וְתַמָּן מְמָנָן אֶלֶף וְרִבְבָן זְמִינִין לְנַטְלָא אִינּוּן פִּתְקִין, וְהַאי מְמָנָא עָלַיְיהוּ. וּכְדֵין כָרוֹזִין נָפְקִין, וְכַמָּה גַּרְדִּינֵי שַׁטְיָין <Nonei></i>בְּעָלְמָא, וְהַהוּא דִּינָא אִשְׁתְּלִים, וְעַל דָּא, מְמָנָא דָּא קַיְּימָא לְעַיְינָא בְּפִתְקִין, וּלְאַתְקְנָא נִימוּסֵי פִּתְקִין, עַד לָא נַפְקוּ מֵהַאי פִּתְחָא, וְהַאי פִּתְחָא אִיהוּ פִּתְחָא דְּדָרוֹם.</p>\n<p>פִּתְחָא תִּנְיָינָא, דָּא פִּתְחָא דְּחַיִּין וּמוֹתִין תַּלְיָין בֵּיהּ, בְּגִין דְּהַאי פִּתְחָא, חַתְמִין חַתִימִין דְּכָל פִּתְקִין, דְּכֵיוָן דְּפִתְקִין אִתְּקָנוּ כְּדְקָא יֵאוֹת, חַד שַׁמָשָׁא זַמִּין, גַּזְרִיאֵ\"ל שְׁמֵיהּ, וְנָטִיל פִּתְקִין בְּהַאי פִּתְחָא תִּנְיָינָא, וְתַמָּן חַתְמִין לְהוּ.</p>\n<p>מְמָנָא חֲדָא קַיְּימָא עַל הַהוּא פִּתְחָא, וְעַזְרִיאֵ\"ל שְׁמֵיהּ, וְכָל פִּתְחָא וּפִתְחָא אִתְקְרֵי עַל שְׁמָא דְּהַהוּא מְמָנָא דְּאִתְפַּקְּדָא עָלֵיהּ. הַאי מְמָנָא תְּחוֹת שׁוּלְטָנֵיהּ, וּתְחוֹת יְדֵיהּ, תְּרֵין שַׁמָּשִׁין דִּי שְׁמָהוֹן (ס\"א סטרי\"ה) סָנוּרִיָּ\"א, עָדִיאֵ\"ל. חַד מִימִינָא וְחַד מִשְּׂמָאלָא. הַהוּא מִימִינָא, בֵּיהּ תַּלְיָין חַיִּין. וְהַהוּא דִּשְׂמָאלָא, בֵּיהּ תַּלְיָא מוֹתָא. וּתְרֵין חוֹתָמִין בִּידַיְיהוּ, חוֹתָם חַיִּים וְחוֹתָם מָוֶת. דָּא קָאִים לְסִטְרָא דָּא, וְדָא קָאִים לְסִטְרָא דָּא.</p>\n<p>הַאי פִּתְחָא סָתִים כָּל יוֹמֵי שַׁתָּא, וּבְיוֹמָא דְּשַׁבְתָא, וּבְיוֹמֵי דְּחָדְשָׁא אִתְפְּתַח, לְאַחֲזָאָה חַיִּים בְּהַהוּא חוֹתָמָא, דְּתַלְיָין בֵּיהּ חַיִּים, בְּגִין דְּשַׁבָּת וְחֹדֶשׁ חוֹתָמָא דְּחַיִּים אִתְקְיָּים בְּהוּ.</p>\n<p>בְּיוֹמָא דְּכִפּוּרֵי, דְּיִשְׂרָאֵל כֻּלְּהוּ קַיְימֵי בִּצְלוֹתִין וּבָעוּתִין, וּמִשְׁתַּדְּלֵי בְּפוּלְחָנָא דְּמָארֵיהוֹן, סָתִים הַהוּא פִּתְחָא, עַד שַׁעֲתָא דִּצְלוֹתָא דְּמִנְחָה. כֵּיוָן דְּאַעְבַר הַאי צְלוֹתָא דְּמִנְחָה, מֵאֲתָר בֵּי דִּינָא דְּהֵיכָלָא דִּזְכוּתָא, חַד אֲוִירָא נָפְקָא, וּפִתְחָא דָּא אִתְפְּתַח, וְהַאי מְמָנָא דְּהֵיכָלָא דָּא קַיְּימָא, וְאִינּוּן תְּרֵין שַׁמָּשִׁין חַד מִימִינָא וְחַד מִשְּׂמָאלָא, וְחוֹתָמֵי דְּחַיִּים וּמוֹתָא בִּידַיְיהוּ, וְכָל פִּתְקִין דְּעָלְמָא קַמַּיְיהוּ, וּכְדֵין אַחְתִימוּ הֵן לַחַיִּים הֵן לַמָוֶת. וְדָא הוּא פִּתְחָא דְּמִזְרָח.</p>\n<p>פִּתְחָא תְּלִיתָאָה, דָּא פִּתְחָא דְּקַיְּימָא בְּקִיּוּמָא, לְמִנְדַּע כָּל אִינּוּן דִּי דִּינָא יַעְבַר עָלַיְיהוּ, בֵּין לְמַרְעִין, בֵּין לְמַכְאוֹבִין, בֵּין לְמִסְכְּנוּ. דִּינָא דְּלָא קַיְּימָא לְמוֹתָא. כַּד תַּרְעָא דְּפִתְחָא דָּא סָגִיר, כְּדֵין דִּינָא אִתְרְשִׁים עַל בַּר נָשׁ, דְּלָא תַּיְיבִין לֵיהּ, בַּר בְּחֵילָא דִּצְלוֹתָא תַּקִּיפָא, וְתִיוּבְתָא שְׁלִים. דִּכְתִיב (איוב י״ב:י״ד) יִסְגּוֹר עַל אִישׁ וְלא יִפָּתֵחַ.</p>\n<p>חַד מְמָנָא קַיְּימָא עַל פִּתְחָא דָּא, וְקַפְצִיאֵ\"ל שְׁמֵיהּ, וְהַאי מְמָנָא עַל פִּתְחָא דָּא, בְּגִין לְסַגְרָא הַאי פִּתְחָא, עַל הַהוּא בַּר נָשׁ, דְּאִתְחָזֵי לְאִתְעַנְּשָׁא, בְּגִין דְּלָא יִתְקָבַּל בִּצְלוֹתָא, עַד דְּיֵתוּב לְקָמֵי מָארֵיהּ.</p>\n<p>וּבְהַהוּא זִמְנָא דְּאִתְגְּזַר דִּינָא בִּבְנוֹי דְּלָא חָאבוּ, בְּאִינּוּן רַבְיָין זְעִירִין, חַד מְמָנָא שַׁמָשָׁא תְּחוֹת יְדֵיהּ, עִירִיאֵ\"ל שְׁמֵיהּ, וְנָפַק וְכָרִיז לִסְטַר שְׂמָאלָא, עַד דְּאִתְעַר חַד רוּחָא, דְּאִיהוּ רוּחָא דִּפְגִּימוּ, (רס\"ד ע\"ב) אִתְבְּרֵי בִּפְגִּימוּ דְּסִיהֲרָא, וְאִקְרֵי אַסְכָּרָ\"א, וְהַאי אִיהוּ רוּחָא דְּקַיְּימָא עַל דַּרְגָא (ס\"א פתחא) רְבִיעָאָה, בְּהֵיכָלָא תְּלִיתָאָה, דִּי בִּסְטַר מְסַאֲבָא, וְדָא קַיְּימָא עַל קִטּוּלָא דִּלְהוֹן, וְיִתְחָזֵי לוֹן לְרַבְיֵי, כְּאִתְּתָא דִּרְבִיאַת לְרַבְיֵי, וַאֲחִידַת לוֹן, וְקַטְלַת לוֹן.</p>\n<p>וּכְדֵין הַהִיא נִשְׁמְתָא, סַלְּקָא, וְאָחִיד לָהּ הַאי מְמָנָא, וְסַלְּקָא לָהּ לַמְמָנָא דְּקַיְּימָא עַל הֵיכָלָא רְבִיעָאָה, וְהַהוּא מְמָנָא מְגַדְּלָא לוֹן, וְאִשְׁתַּעְשַׁע בְּהוּ, וְסָלִיק לוֹן לְאִתְחֲזָאָה קַמֵּי מַלְכָּא קַדִישָׁא, בְּכָל שַׁבָּת וְשַׁבָּת, וּבְכָל רֵישׁ יַרְחָא וְרֵישׁ יַרְחָא, וְאִתְחָזוּן קָמֵיהּ, וְאִתְבָּרְכוּן מִנֵּיהּ. וּבְשַׁעֲתָא דְּרוּגְזָא שַׁלְטָא, אִסְתָּכַּל בְּהוּ קוּדְשָׁא בְּרִיךְ הוּא, וְחָיִּיס עַל עָלְמָא.</p>\n<p>וְכָל אִינּוּן רַבְיָין, דְּלָא אַשְׁלִימוּ שְׁנִין, עַד תְּלֵיסָר שְׁנִין וְיוֹמָא חַד, כֻּלְּהוּ אִתְמְסָרוּ בִּידָא דְּהַאי, (רס\"ד ע\"ב) מִתְּלֵיסַר שְׁנִין עַד עֶשְׂרִין, כֻּלְּהוּ אִתְמְסָרוּ עַל יְדָא דְּרוּחָא אַחֲרָא, דְּאִקְרֵי אָגִירְיסוֹ\"ן, דְּנָפְקָא מֵהַאי נָחָשׁ (ס\"א עקימא) עֲמִיקָא, דְּגָרִים מוֹתָא לְכָל עָלְמָא, וְאִיהוּ יֵצֶר הָרָע. מֵעֶשְׂרִין שְׁנִין וּלְעֵילָּא, אִתְדָּן בַּר נָשׁ מִבֵּי דִּינָא, אֲתָר דְּאִקְרֵי זְכוּתָא, אִיהוּ בְּגַרְמֵיהּ אָתָא, וּבְחוֹבוֹי אִתְדָּן, וְאִתְמְסָר בִּידָא דְּהַאי חִוְיָא דְּאִיהוּ מַלְאָךְ הַמָּוֶת.</p>\n<p>(בגין דהא מעשרין שנין ולתתא, עד תליסר שנין), הַאי רוּחָא דְּקַיְּימָא <Nonei></i>בֵּיהּ כְּנָחָשׁ, אָזִיל אֲבַתְרֵיהּ, דָּא אָגִירִיסוֹ\"ן דְּקָאָמַרָן. בְּגִין דְּלָא אִתְנְטִיר כַּד הֲוָה רַבְיָא דָּקִיק כְּדְקָא יֵאוֹת. וְחָמֵי בֵּיהּ סִימַן דְּיִתְפְּגִים לְבָתַר. וְהַאי אִתְנְטִיל בְּלָא רְשׁוּ, וְעַל דָּא כְּתִיב, (משלי י״ג:כ״ג) וְיֵשׁ נִסְפֶּה בְּלֹא מִשְׁפָּט. וְרָזָא דָּא כְּתִיב (בראשית א׳:ל״א) וְהִנֵּה טוֹב מְאֹד, וְתָנֵינָן, וְהִנִּה טוֹב מְאֹד, דָּא מַלְאָךְ הַמָּוֶת, דְּאַקְדִים לֵיהּ עַד לָא יִתְפְּגִים לְבָתַר. וְהַאי מְמָנָא דְּקָאִים עַל הַאי פִּתְחָא, אָעִיל נִשְׁמָתֵיהּ וְסַלְּקָא לָהּ לְעֵילָּא.</p>\n<p>מִתְּלֵיסַר שְׁנִין וּלְתַתָּא, אִתְדָּן עַל חוֹבוֹי דְּאָבוֹי, וְאִתְמְסָר בִּידָא דְּהַאי אַסְכָּרָא דְּקָאָמַרָן. וְכָל חַד וְחַד, הֵיכָלָא דָּא לָקֳבֵל הֵיכָלָא דָּא. דָּא בְּהִפּוּכָא מִן דָּא, כִּדְקַאמְרָן, וְהַאי פִּתְחָא אִיהוּ לִסְטַר צָפוֹן.</p>\n<p>פִּתְחָא רְבִיעָאָה, פִּתְחָא דָּא קַיְּימָא לְאַסְוָותָא, וְאִקְרֵי פִּתְחָא דְּאַסְוָותָא, בְּהַאי פִּתְחָא קַיְּימָא חַד מְמָנָא, (רנ\"ב ע\"א) פְּדָיאֵ\"ל שְׁמֵיהּ. וְהַאי קַיְּימָא עַל כָּל אִינּוּן אַסְוָותִין דְּעָלְמָא, וּלְאַעֲלָא צְלוֹתִין דְּכָל אִינּוּן מָארֵי דְּמַכְאוֹבִין וּמַרְעִין וְצַעְרִין, וְהַאי אִיהוּ סָלִיק בְּכָל (נ\"א לכל) אִינּוּן צְלוֹתִין, וְאָעִיל לוֹן קָמֵי קוּדְשָׁא בְּרִיךְ הוּא.</p>\n<p>וְהַאי אִיהוּ (איוב ל״ג:כ״ג) מַלְאָךְ מֵלִיץ אֶחָד מִנִּי אָלֶף, בְּגִין דְּאִינּוּן אֶלֶף קַיְימִין בְּהַהוּא פִּתְחָא, וְהַאי חַד מִנַּיְיהוּ, וּכְתִיב וַיְחֻנֶּנּוּ וַיֹּאמֶר פְּדָעֵהוּ מֵרֶדֶת שַׁחַת מָצָאתִי כֹפֶר. בְּגִין דְּסָלִיק בְּהַאי (נ\"א להאי) צְלוֹתָא, וְקַיְּימָא מֵלִיץ טוֹב עָלֵיהּ דְּבַר נָשׁ, וְאַדְכַּר זְכוּתֵיהּ דְּעָבַד קָמֵי מַלְכָּא קַדִישָׁא, בְּגִין דְּהַאי אִיהוּ דְּקַיְּימָא תָּדִיר לְטָב, וְעַל דָּא, כָּל אַסְוָותָא קַיְּימָא בְּהַאי פִּתְחָא דִּי פְּדָיאֵ\"ל מְמָנָא בֵּיהּ. פִּתְחָא דָּא אִיהוּ לִסְטַר מַעֲרָב. וּבְגִין דָּא, אִלֵּין אַרְבַּע פִּתְחִין קַיְימִין בְּהֵיכָלָא דָּא.</p>\n<p>בְּהֵיכָלָא דָּא קַיְּימָא רוּחָא חֲדָא דְּאִקְרֵי נֹגַהּ, הַאי אִיהוּ רוּחָא שַׁלִּיטָא בְּהַאי הֵיכָלָא, כָּל זִיוָא וְכָל תִּיאוּבְתָא קַיְּימָאן בֵּיהּ. הַאי רוּחָא אִיהוּ קַיְּימָא לְכָל אִינּוּן דְּאִית לוֹן חוּלָקָא בְּעָלְמָא דְּאָתֵי, דָּא אַעְטָּר לְאִינּוּן נִשְׁמָתִין בְּזִיוָא דִּיְקָרָא, בְּגִין לְמִנְדַע כָּל אִינּוּן רוּחִין דִּי בְּהֵיכָלִין אַחֲרָנִין, דְּדָא אִיהוּ בַּר עָלְמָא דְּאָתֵי, וְיַּעְבַר בְּכֻלְּהוּ, וְלֵית מַאן דְּיִמְחֵי בִּידֵיהּ.</p>\n<p>הַאי רוּחָא, אִיהוּ רוּחָא דַּכְיָא, בָּרִיר מֵאִלֵּין תַּתָאִין, זָהֲרִיאֵ\"ל שְׁמֵיהּ, מֵהַהוּא מִשְׁחָא דִּרְבוּת קוּדְשָׁא דְּנָגִיד מֵעָלְמָא דְּאָתֵי, נָגִיד בֵּיהּ, וּמֵהַהוּא מִשְׁחָא אִתְבָּרֵי (נ\"א אתרבי) וְאַצְמַח. וְהַאי אִיהוּ נֵר, כְּמָה דְּאַתְּ אָמֵר (תהילים קל״ב:י״ז) עָרַכְתִּי נִר לִמְשִׁיחִי. בְּגִין דְּהַאי אִיהוּ סִדּוּרָא לְאַדְלְקָא בּוּצִינִין מִתַתָּא לְעֵילָּא, כַּד שָׁרָא עָלֵיהּ נְהִירוּ דְּנָגִיד מִלְּעֵילָּא, בְּגִין דְּהַאי אִתְסָדָר, כַּד אִתְכְּלִילוּ בֵּיהּ כָּל אִינּוּן תַּתָּאִין לְתַתָּא.</p>\n<p>וְכַד אִתְסָדָר הַאי רוּחָא בְּכָל אִינּוּן תַּתָּאִין, וְנָהִיר, כְּדֵין אַפִיק מִנֵּיהּ נְהוֹרָא חַד, דִּי שְׁמֵיהּ אַקֲרִיאֵ\"ל (ס\"א אהדיא\"ל) וְהַאי כָּלִיל בְּרוּחָא דָּא, הַאי קַיְּימָא תְּחוֹת (ס\"א האי) רוּחָא, לְאֲמְשְׁכָא (ס\"א לאמשחא) לְכָל אִינּוּן נִשְׁמָתִין דְּסַלְּקִין, דְּאִית לוֹן חוּלָקָא בְּעָלְמָא דְּאָתֵי, וְאִתְחָזוּן לְסַלְּקָא לְעֵילָּא.</p>\n<p>בְּגִין דְּכַד נִשְׁמְתָא סַלְּקָא, וְעָאלַת בְּאִינּוּן הֵיכָלִין תַּתָּאִין, רְשִׁימָא אִיהִי בְּעֶשְׂרִין (ר\"י ע\"א) וּתְרֵין אַתְוָון דְּאוֹרַיְיתָא, דִּרְשִׁימִין בְּהַאי נִשְׁמְתָא. וְכַד נִשְׁמְתָא זַכָאת וְקָמַת קַמֵּיהּ דְּהַהוּא רוּחָא, דָּא מְמָנָא אַהֲדִיאֵ\"ל מָשַׁח לוֹן. וְסַלְקִין וְעָאלִין בְּהַהוּא נְהַר דִּינוּר וְסַלְּקִין וְאִתְקְרִיבוּ לְקָרְבָּנָא.</p>\n<p>הַאי נְהוֹרָא כָּלִיל בִּתְלַת נְהוֹרִין, בְּגִין דְּהַהוּא רְבוּת מִשְׁחָא, אִתְכְּלִיל בִּתְלַת גְּוָונִין. וְכַד נָצִיץ הַאי נְהוֹרָא, נָצִיץ מִנֵּיהּ עֶשְׂרִין וּתְרִין (אתוון) נְהוֹרִין, לָקֳבֵל כ\"ב אַתְוָון דְּאוֹרַיְיתָא, דִּרְשִׁימִין בְּהַאי נִשְׁמְתָא. וְאִלֵּין עֶשְׂרִין וּתְרֵין נְהוֹרִין, כֻּלְּהוּ מְמָנָן שַׁמָּשִׁין דְּקַיְימֵי עִמֵּיהּ, וְכֻלְּהוּ אִתְקְרוּן עַל שְׁמָא דְּהַאי נְהוֹרָא דְּעָלַיְיהוּ, וְכֻלְּהוּ אִתְכְּלִילוּ בֵּיהּ. הַאי נְהוֹרָא בְּכָל אִינּוּן נְהוֹרִין, אִתְכְּלִיל בְּהַאי רוּחָא, וְהַאי רוּחָא כָּלִיל בֵּיהּ, וְאִסְתָּכֵי לְאִתְיַשְּׁבָא גּוֹ הֵיכָלָא רְבִיעָאָה.</p>\n<p>רוּחָא דָּא, כַּד אִתְכְּלִיל מִנְּהוֹרָא דָּא, וּמִכֻלְּהוּ נְהוֹרִין, כַּד דָּחֲיָּין (נ\"א דחקין) לְאִתְנַצְּצָא <Nonei></i>נָפְקָא מִנַּיְיהוּ חַד חֵיוָתָא קַדִישָׁא, כְּלִילָא בִּתְרֵי גְּוָונֵי, אַרְיָא וְנִשְׁרָא, וְאִיהִי חַד דִּיּוּקְנָא, וְהַאי אִקְרֵי אֲהִיאֵ\"ל. (ס\"א אתיא\"ל)</p>\n<p>וְהַאי חֵיוָתָא קַדִישָׁא, נַפְקֵי מִנְּצִיצוּ דִּילָהּ, כַּד מָטֵי נְהִירוּ דְּהַאי רוּחָא עִלָּאָה בָּהּ, אַרְבַּע אוֹפַנִּים, כְּלִילָן בְּכָל גְּוָונִין, וְאִינּוּן הַדְרִיאֵ\"ל, יְהֲדְרִיאֵ\"ל, אַהֲדוֹרִיָ\"א, (הקדמה י\"ד ע\"ב) אָסִימוֹ\"ן (נ\"א אטימו\"ן). כָּל אִלֵּין בִּתְמַנְיָא גַּדְפִּין, וְאִלֵּין אִינּוּן מְמָנָן, עַל כָּל חֵילֵי שְׁמַיָא, מַגִּיחֵי קְרָבָא. בְּגִין דְּלָא אִשְׁתְּכַח קְרָבָא בְּעָלְמָא, אוֹ עֲקִירוּ דְּמַלְכוּתָא מֵאַתְרַיְיהוּ, עַד דְּחֵילֵי שְׁמַיָא, וְכֹכָבַיָּא דִּשְׁאַר רְקִיעִין, כֻּלְּהוּ אַחְזִיוּ קְרָבִין וְסִכְסוּכִין אִלֵּין בְּאִלֵּין. וְאִלֵּין אַרְבַּע אוֹפַנִּים, קַיְימֵי עָלַיְיהוּ לְאַרְבַּע סִטְרִין דְּעָלְמָא.</p>\n<p>אִלֵּין אַרְבַּע, כַּד נַטְלִין לְאַגָּחָא קְרָבִין, מֵרָזָא דְּהֵיכָלָא דִּלְעֵילָּא נַטְלִין, דְּאִיהוּ בֵּי דִּינָא, וְאִקְרֵי זְכוּתָא. מִזִּיעָא דִּלְהוֹן אַפִּיקוּ כַּמָה חֵילִין וּמַשִּׁרְיָין דְּלֵית לוֹן חוּשְׁבָּנָא. וְכֻלְּהוּ קַיְימֵי תְּחוֹת אִלֵּין אוֹפַנִּים.</p>\n<p>מִנְּהוֹן קַיְימֵי עַל שִׁירָתָא, וּמִנְּהוֹן שְׁלִיחָן עַל עָלְמָא. לָקֳבֵל אִינּוּן שְׁלִיחָן דְּלִסְטַר מְסַאֲבָא, דְּנַפְקֵי מִגּוֹ הַהוּא הֵיכָלָא תְּלִיתָאָה דִּילָהּ, וְאִינּוּן מְקַטְרְגֵי עָלְמָא לְאַבְאָשָׁא. וְאִלֵּין אִשְׁתְּכָחוּ לָקֳבְלַיְיהוּ, דְּלָא יִשְׁלְטוּן לְגַבֵּי אִינּוּן דְּמִשְׁתַּדְּלֵי בְּאוֹרַיְיתָא, כְּמָה דְאַתְּ אָמֵר (תהילים צ״א:י״ב) כִּי מַלְאָכָיו יְצַוֶּה לָךְ וְגוֹ'. וּכְתִיב עַל כַּפַּיִם יִשָּׂאוּנְךָ פֶּן תִּגוֹף בָּאֶבֶן וְגוֹ'. דָּא (ישעיהו ח׳:י״ד) אֶבֶן נֶגֶף צוּר מִכְשׁוֹל. הַאי אִקְרֵי אֶבֶן נֶגֶף צוּר מִכְשׁוֹל. וְהַאי אִקְרֵי (ישעיהו כ״ח:ט״ז) אֶבֶן בֹּחַן פִּנַּת יִקְרַת, (ישעיהו כ״ח:ט״ז) צוּר יִשְׂרָאֵל. וְכֹלָּא קַיְּימָא דָּא לָקֳבֵל דָּא.</p>\n<p>מֵרָזָא דְּהֵיכָלָא תְּלִיתָאָה דִּי בְּסִטְרָא אַחֲרָא, נַפְקֵי תְּרֵין רוּחִין, דְּאִקְרוּן אַ\"ף וְחֵמָ\"ה, וּמִתְּרֵין אִלֵּין, נָפְקִין כָּל אִינּוּן שְׁלִיחָן דְּאָזְלִין לְאַסְטָאָה בְּנִי נָשָׁא מֵאָרְחָא דִּקְשׁוֹט, וְאִלֵּין אִינּוּן דְּקַיְּימָאן, וְאַקְדִּימוּ עַל בַּר נָשׁ, דְּקָא אָזִיל לְאוֹרְחָא דְּמִצְוָה. וְעַל דָּא אִלֵּין אוֹפַנִּים קַיְימָן לָקֳבְלַיְיהוּ, בְּגִין לְאַגָּנָא עָלֵיהּ דְּבַּר נָשׁ דְּלָא יִתְנָזְקוּן. מֵאִלֵּין תְּרֵין רוּחִין דָּחִיל מֹשֶׁה, כַּד הֲוָה נָחִית מִן טוּרָא, דִּכְתִּיב, (דברים ט׳:י״ט) כִּי יָגֹרְתִּי מִפְּנֵי הָאַף וְהַחֵמָה.</p>\n<p>בְּאֶמְצָעִיתָא דְּהֵיכָלָא דָּא, אִית אַתְרָא אַחֲרָא, דְּקַיְּימָא לְעֵילָּא לְעֵילָּא, בְּאַרְבַּע פִּתְחִין, לְאַרְבַּע סִטְרֵי עָלְמָא, עֶשֶׂר מְמָנָן לְכָל פִּתְחָא וּפִתְחָא, וְחַד מְמָנָא עָלַיְיהוּ. וְהַאי כָּלִיל בִּנְהוֹרָא דְּאִקְרֵי אַהֲדִיאֵ\"ל, וְהַאי אִיהוּ אוֹפָן בְּתוֹךְ הָאוֹפָן, מְשֻׁלָּבָן דָּא בְּדָא.</p>\n<p>אִלֵּין אַרְבְּעִין, נַטְלֵי דִּינָא מִבֵּי זְכוּתָא, לְאַלְקָאָה לְהַאי נִשְׁמְתָא דְּחָבָאת (ס\"א ובעאת) לְאַלְקָאָה. וְאִלֵּין קַיְימֵי בְּשַׁלְהוֹבֵי נוּרָא לְגַבֵּי אִינּוּן נִשְׁמָתִין, וְטָאסִין לְבַר מֵהֵיכָלָא דָּא, וְאַלְקָאן לְנִשְׁמְתָא דָּא, וְקַיְּימָא נְזִיפָא לְבַר, כָּל אִינּוּן יוֹמִין דְּאִתְגְּזָרַת עָלָהּ, וְלָא עָאלַת לְפַרְגּוֹדָא.</p>\n<p>וְאִלֵּין אַרְבָּעִים, אִינּוּן דְּקַיְימִין וַאֲנְזִיפוּ וּמְנַדִּין, לְכָל אִינּוּן דְּאַפִּיקוּ מִפּוּמַיְיהוּ מִלָּה דְּלָא אִצְטְרִיכָא, וּבָתַר דָּא אַפִּיקוּ מִפּוּמַיְיהוּ מִלָּה קַדִּישָׁא, מִלָּה דְּאוֹרַיְיתָא, וּמְטָנְפֵי פּוּמַיְיהוּ בָּהּ. וְאִלֵּין קַיְימֵי, וּמְנַדִּין לוֹן, וְקַיְימֵי בְּהַאי נִדּוּיָיא אַרְבְּעִין יוֹמִין, דְּלָא אִשְׁתְּמַע צְלוֹתְהוֹן.</p>\n<p>וְכֵן לְכָל אִינּוּן דְּחָאבוּ אִינּוּן חוֹבִין, דְּבַעְיָין לְנַזְפָא, עֲשָׂרָה כָּרוֹזִין נַפְקֵי בְּכָל יוֹמָא, וּמַכְרְזֵי בְּכָל אִינּוּן רְקִיעִין, וּבְכָל אִינּוּן חֵילִין וּמַשִּׁרְיָין, אִזְדְּהָרוּ בִּפְלַנְיָא דְּאִיהוּ נְזִיפָא. נְזִיפָא אִיהוּ עַל חוֹבָא פְּלוֹנִי דְּעֲבַד, עַד דְּתָב קַמֵּי מָארִיהּ, רַחֲמָנָא לִישֵׁזְבָן.</p>\n<p>כַּד תָּב מֵהַהוּא חוֹבָא, מִתְכַּנְּפֵי אִלֵּין אַרְבְּעִין, וְשָׁרָאן לֵיהּ. וּכְדֵין אַכְרִיזוּ עָלֵיהּ, פְּלַנְיָא שָׁרָא נְזִיפָא. מִכָּאן וּלְהָלְאָה צְלוֹתָא עָאלַת. וְעַד לָא תָּב, נָזִיף אִיהוּ לְעֵילָּא וְתַתָּא, וּנְטִירוּ דְּמָארֵיהּ אִתְעָדֵי מִנֵּיהּ. וַאֲפִילּוּ בְּלֵילְיָא נִשְׁמָתֵיהּ נְזִיפָא, דְּסָתְמִין לָהּ כָּל תַּרְעֵי שְׁמַיָּא וְלָא סַלְּקָא, וְדַחְיָין לָהּ לְבַר.</p>\n<p>הַאי אוֹפָן דְּקַיְּימָא עַל אִלֵּין אַרְבְּעִין, כַּד נָטִיל מָטָא לְהַהוּא אֲתָר דְּאִקְרֵי (מלכים א י״ד:כ״ח) תָּא הָרָצִי\"ם. וְכַד עָאל, עָאלוּ עִמֵּיהּ אִינּוּן אַרְבְּעִין, דִּי מְמָנָן בְּאַרְבַּע פִּתְחִין, וְסַלְּקִין כָּל אִינּוּן מְגִינִּין דִּי דַּהֲבָא. וְאִלֵּין אִינּוּן מַלְאֲכִין דְּאִקְרוּן חַשְׁמַלִי\"ם. וְאִינּוּן מְגִינִּין וְסַיְיפִין וְרוּמְחִין, דְּרַהֲטֵי לְאַגָּנָא עָלַיְיהוּ דְּיִשְׂרָאֵל מִשְּׁאַר <Nonei></i>עַמִּין, וּלְאַגָּחָא קְרָבָא בְּהוּ, וּלְנַקְמָא לוֹן כְּפוּם שַׁעֲתָא, בְּלָא אֲרִיכוּ.</p>\n<p>וּבְגִין כָּךְ אִקְרֵי תָּא הָרָצִים, אֲתָר דְּאִינּוּן רָצִים רַהֲטֵי, וְאוֹחוּ לְאַגָּחָא, וּלְנָקְמָא נוּקְמִין לָקֳבֵל רָצִים אַחֲרָנִין, דְּרַהֲטֵי לְאַבְאָשָׁא וּלְאַתְרְעָא מַזָּלִין, לְשַׁלְּטָאָה עָלַיְיהוּ. וְרָזָא דָּא, (אסתר ג׳:ט״ו) הָרָצִים יָצְאוּ דְּחוּפִים. רָצִים מִסִּטְרָא דָּא, וְרָצִים מִסִּטְרָא דָּא, וּבְגִינֵהוֹן, (אסתר ח׳:ט״ו) וְהָעִיר שׁוּשָׁן צָהֲלָה וְשָׂמֵחָה, אוֹ (אסתר ג׳:ט״ו) נָבוֹכָה. אִי מְקַדְּמֵי אִלֵּין דְּהָכָא, הָעִיר שׁוּשָׁן שָׂמֵחָה. וְאִי מְקַדְּמֵי אִלֵּין דְּסִטְרָא אַחֲרָא, הָעִיר שׁוּשָׁן נָבוֹכָה.</p>\n<p>וְהָא אוֹקִימְנָא, דִּבְכֹלָּא קַיְימִין אִלֵּין לָקֳבֵל אִלֵּין, סִטְרָא דָּא לָקֳבֵל סִטְרָא דָּא. וּבְגִין כָּךְ, אִלֵּין אִינּוּן מְגִינִּין לְכֹלָּא. כַּד סַלְּקִין אִלֵּין בְּאִלֵּין, נָפַק חַד אֲוֵירָא דִּלְעֵילָּא, וְאִתְעָבִידוּ כֻּלְּהוּ מָגֵן חַד. וְסִימָנִךְ, (בראשיתטו) אָנֹכִי מָגֵן לָךְ.</p>\n<p>תְּרֵיסָר גַּלְגַּלִּין, אִינּוּן דְּסַחֲרָאן גּוֹ הֵיכָלָא דָּא, וְאִינּוּן אִקְרוּן שְׂרָפִים, דִּתְרֵין גַּוְונִין, חִוָּור וְסוּמָק, רַחֲמֵי וְדִינָא, אִלֵּין אִינּוּן קַיְימֵי לְאַשְׁגָּחָא תָּדִיר, עַל כָּל אִינּוּן מָארֵי דְּצַעֲרָא, דְּצַעְרִין לוֹן שְׁאַר עַמִּין, וְדַחֲקִין לוֹן, וְאִקְרוּן חַלּוֹנוֹת. וְהַיְינוּ דִּכְתִּיב, (שיר השירים ב׳:ט׳) מַשְׁגִּיחַ מִן הַחַלּוֹנוֹת.</p>\n<p>וְאִלֵּין קַיְימֵי לְאִסְתַּכְּלָא, כָּל אִינּוּן דִּמְצַלָּאן צְלוֹתַיְיהוּ, דִּמְקַדְּמֵי לְבֵי כְּנִישְׁתָּא, וְאִתְמְנוּן מֵאִינּוּן עֲשָׂרָה קַדְמָאֵי. כְּדֵין סַלְּקִין וְכַתְבִין לוֹן לְעֵילָּא, בְּגִין דְּאִלֵּין אִקְרוּן חֲבֵרִים לְגַבַּיְיהוּ. הֲדָא הוּא דִכְתִיב, (שיר השירים ח׳:י״ג) חֲבֵרִים מַקְשִׁיבִים לְקוֹלֵךְ הַשְׁמִעִינִי.</p>\n<p>זַכָּאִין אִינּוּן צַדִּיקַיָּיא, דְּיַדְעֵי לְסַדְּרָא צְלוֹתְהוֹן כְּדְקָא יֵאוֹת, בְּגִין דְּכַד הַאי צְלוֹתָא שָׁרָאת לְאִסְתַּלְּקָא, אִלֵּין סַלְּקִין בְּהַאי צְלוֹתָא, וְעָאלִין בְּכָל אִינּוּן רְקִיעִין, וּבְכָל אִינּוּן הֵיכָלִין, עַד תַּרְעָא דְּפִתְחָא עִלָּאָה, וְעָאלַת הַהִיא צְלוֹתָא קָמֵי מַלְכָּא, לְאִתְעַטְּרָא. כְּמָה דְּאִתְּמַר.</p>\n<p>תָּא חֲזֵי, כָּל אִינּוּן דִּמְצַלָּאן צְלוֹתִין, וּמְקַדְּשֵׁי לְמָרֵיהוֹן בִּרְעוּתָא שְׁלִים, הַאי צְלוֹתָא בַּעְיָא לְאַפָּקָא לָהּ מִגּוֹ מַחֲשָׁבָה, וּבִרְעוּתָא דְּמִלוּלָא וְרוּחָא, וּכְדֵין אִתְקַדָּשׁ שְׁמֵיהּ דְקוּדְשָׁא בְּרִיךְ הוּא. וְכַד מָטָאת לְגַבֵּי אִלֵּין חֲבֵרִים, כֻּלְּהוּ נַטְלֵי לְהַהִיא צְלוֹתָא, וְאַזְלָן בַּהֲדָהּ עַד הֵיכָלָא רְבִיעָאָה, בְּהַהוּא פִּתְחָא. וְאִלֵּין מְשַׁבְּחִין בְּהַהוּא זִמְנָא דִּמְצַלָּאן צְלוֹתִין, וּמְקַדְּשֵׁי בְּהַהוּא זִמְנָא, אִלֵּין אִינּוּן דִּי מְמָנָן בִּימָמָא בְּהוּ בְּיִשְׂרָאֵל, לְמֶהֱוֵי עִמְּהוֹן חֲבֵרִים. (ס\"א ולאו בליליא כאינון) וּבְלֵילְיָא, בְּאִינּוּן אַחֲרָנִין, דְּאַמְרֵי שִׁירָתָא בְּלֵילְיָא.</p>\n<p>וְתָא חֲזֵי כְּתִיב, (משלי כ״ח:כ״ד) גּוֹזֵל אָבִיו וְאִמּוֹ וְאוֹמֵר אֵין פָּשַׁע חָבֵר הוּא לְאִישׁ מַשְׁחִית. וְהָא אוֹקְמוּהָ, בְּגִין דְּמָנַע בִּרְכָאן דְקוּדְשָׁא בְּרִיךְ הוּא, דְּאִיהוּ אָבִיו. כְּמָה דִּכְתִּיב, (דברים לכ) שְׁאַל אָבִיךָ וְיַגֵּדְךָ. וּכְתִּיב (משלי כ״ג:כ״ה) יִשְׂמַח אָבִיךָ. וְאוּקְמוּהָ.</p>\n<p>חָבֵר הוּא לְאִישׁ מַשְׁחִית, מַאן אִישׁ מַשְׁחִית. דָּא אִיהוּ הַהוּא אִישׁ, דְּפָגִים לְסִיהֲרָא. וְאִקְרֵי (משלי ט״ז:כ״ח) אִישׁ תַּהְפּוּכוֹת. (תהילים ק״מ:י״ב) אִישׁ לָשׁוֹן. (בראשית כ״ה:כ״ז) אִישׁ יוֹדֵעַ צַיִד אִישׁ שָׂדֶה. וְהַאי אִיהוּ אִישׁ מַשְׁחִית, דְּהַאי אִיהוּ מָנַע בִּרְכָאן מֵעָלְמָא. אוּף הָכִי, מַאן דְּמָנַע בִּרְכָאן מֵעָלְמָא, חָבֵר הוּא לְהַאי אִישׁ מַשְׁחִית כִּדְקַאמְרָן. וְדָא הוּא רָזָא, בְּגִין דְּאִצְטְרִיךְ לֵיהּ לְבַּר נָשׁ לְבָרְכָא לְּקוּדְשָׁא בְּרִיךְ הוּא, וּלְצַלָּאָה צְלוֹתָא כַּדְקָא יֵאוֹת. בְּגִין דְּיִתְבָּרַךְ שְׁמֵיהּ קַדִּישָׁא, וְיִתְחַבָּר בְּאִלֵּין חֲבֵרִין קַדִּישִׁין, וְלָא יִפְגוֹם צְלוֹתֵיהּ. בְּגִין דְּיִמְנַע בִּרְכָאן מֵעָלְמָא, וְיִתְחַבָּר בְּהַהוּא חָבֵר אִישׁ מַשְׁחִית דְּאִיהוּ מָנַע בִּרְכָאן מֵעָלְמָא, וְגָרִים מוֹתָא לְכֻלְּהוּ.</p>\n<p>כְּתִיב (דברים י״ח:י״א) וְחוֹבֵר חָבֶר, מַאי וְחוֹבֵר חָבֶר. הַהוּא מַאן דְּאָזִיל בָּתַר סִטְרָא אַחֲרָא, וְחָרָשׁ חַרְשִׁין, אִיהוּ מָשִׁךְ עָלֵיהּ רוּחָא אַחֲרָא מְסַאֲבָא, וְאִתְחַבָּר בְּהַהוּא חַבְרוּתָא דְּהַהוּא חָבֵר רָע, וְשָׁאֲרִי בְּחַבְרוּתָא בַּהֲדֵיהּ, הַהוּא חָבֵר אִישׁ מַשְׁחִית. אֲמַאי אִקְרֵי חָבֵר. בְּגִין דִּבְשַׁעֲתָא דְּאִתְיְילִיד בַּר נָשׁ אִתְחַבָּר עִמֵּיהּ. וְתָדִיר קַיְימָא בַּהֲדֵיהּ חָבֵר. לְבָתַר, אִתְהַפָּךְ לֵיהּ חָבֵר, אִישׁ מַשְׁחִית.</p>\n<p>וְהָכִי אִית בְּסִטְרָא דִּקְדוּשָּׁה, בְּסִטְרָא דִּימִינָא, חָבֵר טוֹב, דְּעָבִיד טִיבוּ עִמֵּיהּ דְּבַר נָשׁ בְּעָלְמָא דֵּין וּבְעָלְמָא דְּאָתֵי. וְאִלֵּין חֲבֵרִים קַיְימֵי תָּדִיר עָלֵיהּ דְּבַּר נָשׁ, בְּחַבְרוּתָא חֲדָא, לְשֵׁיזָבָא לֵיהּ, וּלְאַגָּנָא עָלֵיהּ, וּלְמֶהוֵי עִמֵּיהּ חֲבֵרִים, לְקַדְּשָׁא שְׁמָא דְּמָארֵיהוֹן, וּלְזַמְּרָא וּלְשַׁבְּחָא קַמֵּיהּ. תָּדִיר.</p>\n<p>מֵאִלֵּין נַפְקֵי <Nonei></i>אַרְבַּע סַמְכִין אַחֲרָנִין, לְאִינּוּן תְּרֵיסָר דְּקָאָמַרָן, הָנֵי חֲבֵרִים. וְאִלֵּין אִינּוּן קַיְימֵי לְגַבֵּי אִינּוּן דְּיַעְטִין עֵיטָא לְאַבְאָשָׁא לְצַדִּיקַיָּיא. אַף עַל גַּב דְּלָא עַבְדֵּי, וְסַלְקֵי וְאוֹדְעֵי מִלָּה לְעֵילָּא, וּבַטְלֵי לְהַהוּא עֵיטָא, וְאִלֵּין אִקְרוּן אֶרְאֶלִּי\"ם וְאַף עַל גַּב דְּכֻלְּהוּ אִתְמְנוּן לְדָא, כָּל חַד וְחַד אִתְמָנָא וְאִתְפְּקַד עַל מִלִּין יְדִיעָאן. וּתְחוֹת אִלֵּין לֵית לוֹן חוּשְׁבָּנָא.</p>\n<p>אִלֵּין אַרְבַּע, קַיְימֵי לְאַרְבַּע סִטְרֵי עָלְמָא, וְכָל חַד קָאִים לְאַשְׁגָּחָא עָלַיְיהוּ דְּיִשְׂרָאֵל. וְאִלֵּין אִקְרוּן חֲרַכִּים, כְּמָה דְּאַתְּ אָמֵר (שיר השירים ב׳:ט׳) מֵצִיץ מִן הַחֲרַכִּים. שְׁמָא דְּאִלֵּין אַרְבַּע דְּאִקְרוּן חֲרַכִּים, עִיגָאֵ\"ל. עִירִיָ\"ה (נ\"א עזרי\"ה). עָרִיאֵ\"ל. יְהִירָאֵ\"ל. עִיגָאֵ\"ל, אִיהוּ קָאִים לִסְטַר מִזְרָח, וְדָא קַיְּימָא לְאַשְׁגָּחָא עַל כָּל אִינּוּן דְּעַבְדִין עוֹבָדִין טָבִין, וְעַל כָּל אִינּוּן דִּמְחַשְּׁבֵי מַחֲשָׁבָה דְּמִצְוָה, אַף עַל גַּב דְּלָא יַכְלֵי לְמֶעְבַּד.</p>\n<p>עִירִיָ\"ה, קַיְּימָא לִסְטַר דָּרוֹם. וְדָא קַיְּימָא לְאַשְׁגָּחָא, לְכָל אִינּוּן דִּמְנַחֲמֵי לְמִסְכְּנָא, אוֹ דְּצַעֲרֵי לִבַּיְיהוּ עָלֵיהּ, אַף עַל גַּב דְּלָא יַכְלֵי לְמֵיהַב לֵיהּ. וּלְאִינּוּן דְּאַזְלֵי לְאוֹרְחָא דְּמִצְוָה. וּלְאִינוּן דְּעַבְדֵי חֶסֶד עִם מֵתִים. וְאִיהוּ קַיְּימָא קִיוּמָא דֶּאֱמֶת. וְהַאי אִתְמָנָא לְאַדְכְּרָא לֵיהּ לְעֵילָּא, וּלְאַחֲקָא דִּיּוּקְנֵיהּ לְעֵילָּא, לְאַעֲלָא לֵיהּ לְעָלְמָא דְּאָתֵי.</p>\n<p>עָרִיאֵ\"ל, קַיְּימָא לִסְטַר צָפוֹן. וְדָא קַיְּימָא לְאַשְׁגָּחָא לְכָל אִינּוּן דַּחֲשִׁיבוּ לְמֶעְבַּד בִּישִׁין, וְלָא עַבְדֵי. אוֹ בָּעָאן לְמֶחטֵי, וְאָתוּ לְמֶעְבַּד, וְאִתָּקַף בְּיִצְרֵיהּ וְלָא עָבִיד.</p>\n<p>יְהִירָאֵ\"ל, קַיְּימָא לִסְטַר מַעֲרָב. וְהַאי קַיְּימָא לְאַשְׁגָּחָא לְכָל אִינּוּן דְּלָעָאן בְּאוֹרַיְיתָא. וְעַיְילֵי בְּנַיְיהוּ לְמִלְעֵי בְּאוֹרַיְיתָא לְבֵי רַב. וּלְכָל אִינּוּן דְּמִסְתַּכְּלֵי עַל מְרַע, כַּד אִיהוּ בְּבֵי מַרְעֵיהּ. וְאַשְׁגָּחוּ עָלֵיהּ, וְאוֹדִעוּ לֵיהּ דְּיִסְתָּכַּל בְּחוֹבוֹי וּבְעוֹבָדוֹי, וְיֵתוּב מִנַּיְיהוּ לְמָארֵיהּ. בְּגִין דְּכָל מַאן דְּיִשְׁתָּדַּל בְּהַהוּא מְרַע, דְּיִסְתָּכַּל בְּעוֹבָדוֹי, וְיֵתוּב בְּתִיּוּבְתָּא קָמֵי קוּדְשָׁא בְּרִיךְ הוּא, אִיהוּ גָּרִים לֵיהּ לְאִשְׁתְּזָבָא, וּלְאָתָבָא לֵיהּ רוּחֵיהּ. וְעַל דָּא כְּתִיב (תהילים מ״א:ב׳) אַשְׁרִי מַשְׂכִּיל אֶל דָּל בְּיוֹם רָעָה יְמַלְּטֵהוּ יְיָ'. מַאי בְּיוֹם רָעָה, בְּיוֹם רָע מִבָּעֵי לֵיהּ. אֶלָּא בְּיוֹם רָעָה, בְּיוֹמָא דְּשַׁלְטָא הַהוּא רָעָה לְמֵיסַב נִשְׁמָתֵיהּ. אַשְׁרֵי מַשְׂכִּיל אֶל דָּל, דָּא הוּא מְרַע. כְּמָה דְאַתְּ אָמֵר, (שמואל ב י״ג:ד׳) מַדוּעַ אַתָּה כָּכָה דַּל בֶּן הַמֶּלֶךְ. וּבְגִין כָּךְ, בְּיוֹם רָעָה יְמַלְּטֵהוּ יְיָ'.</p>\n<p>וְאִלֵּין (ס\"א אינון דמסתכלי) דְּאִינּוּן מִסְתַּכְּלֵי בְּהַהוּא מְרַע, לְאָתָבָא לֵיהּ מֵחוֹבוֹי גַּבֵּי קוּדְשָׁא בְּרִיךְ הוּא, כְּמָה דְּאוֹקִימְנָא. בְּהֵיכָלָא דָּא קַיְּימָא עָלֵיהּ, לְאַשְׁגָּחָא. וּבְיוֹמָא דְּשַׁרְיָא דִּינָא עַל עָלְמָא, יִשְׁתְּזִיב מִנֵּיהּ, כְּמָה דְאַתְּ אָמֵר בְּיוֹם רָעָה יְמַלְּטֵהוּ יְיָ'. יוֹמָא דְּאִתְּמְסַר דִּינָא לְהַהִיא רָעָה לְשַׁלְּטָאָה בֵּיהּ (על עלמא) וְכֻלְּהוּ אִלֵּין קַיְימֵי לְאַשְׁגָּחָא. וְעַל דָּא אִקְרוּן חֲרַכִּים.</p>\n<p>בְּיוֹמָא דְּרֹאשׁ הַשָּׁנָה, כַּד קוּדְשָׁא בְּרִיךְ הוּא קָאִים בְּדִינָא עַל עָלְמָא, וְהַהוּא סִטְרָא בִּישָׁא אָתֵי לְאַסְטָאָה, כְּדֵין מִתְכַּנְּפֵי כָּל הָנֵי, וְקַיְימָן קָמֵי קוּדְשָׁא בְּרִיךְ הוּא. וּכְדֵין מִתְעַטְּרָן כֻּלְּהוּ, וְקַיְימָן קָמֵי קוּדְשָׁא בְּרִיךְ הוּא. בְּהַהוּא זִמְנָא מַה כְּתִיב, מַשְׁגִּיחַ מִן הַחַלּוֹנוֹת מֵצִיץ מִן הַחֲרַכִּים. מֵצִיץ: כְּמַאן דְּאַשְׁגַּח מֵאֲתָר דָּקִיק, דְּחָמֵי וְלָא חָמֵי כָּל מַה דְּאִצְטְרִיךְ. וּלְבָתַר, מַשְׁגִּיחַ מִן הַחַלּוֹנוֹת, אֲתָר אַשְׁגָּחוּתָא יַתִּיר, דְּפָתַח פִּתְחִין לְרַחֲמָא עַל כֹּלָּא, וְכַד קוּדְשָׁא בְּרִיךְ הוּא אַשְׁגַּח עַל עָלְמָא, אִסְתָּכַּל בְּאִלֵּין חַלּוֹנוֹת, וּבְאִלֵּין חֲרַכִּים, וְחָיִיס עַל כֹּלָּא.</p>\n<p>וּכְדֵין כַּד יִשְׂרָאֵל תַּקְעִין בְּהַהוּא שׁוֹפָר וְאִתְּעַר מִתַּתָּא הַהוּא קוֹל דְּנָפִיק מִשּׁוֹפָר, כָּלִיל מֵאֶשָּׁא וּמַיָא וְרוּחָא, וְאִתְעָבִיד מִכֹּלָּא הַהוּא קוֹל, בְּגִין לְאִתְּעָרָא קוֹל עִלָּאָה, דְּנָפְקָא מִגּוֹ הַהוּא שׁוֹפָר, דְּאִיהוּ כְּגַוְונָא דָּא, כָּלִיל בְּאֶשָּׁא וּבְמַּיָא וְרוּחָא. כְּדֵין כָּרוֹזָא נָפְקָא, וְאַכְרִיז בְּכֻלְּהוּ רְקִיעִין, וְאָמַר קוֹל דּוֹדִי הִנֵּה זֶה בָּא וְגוֹ', מַשְׁגִּיחַ מִן הַחַלּוֹנוֹת מֵצִיץ מִן הַחֲרַכִּים.</p>\n<p>וּכְדֵין יַדְעֵי כֻּלְּהוּ, דְּהָא קוּדְשָׁא בְּרִיךְ הוּא חָיִיס עָלַיְיהוּ דְּיִשְׂרָאֵל, וְאַמְרֵי זַכָּאִין אִינּוּן יִשְׂרָאֵל, דְּאִית לוֹן עֵיטָא בְּאַרְעָא, בְּגִין לְאִתְּעָרָא רַחֲמֵי מִלְּעֵילָּא, כְּדֵין כְּתִיב (תהילים פ״ט:ט״ז) אַשְׁרֵי הָעָם יוֹדְעֵי תְרוּעָה, יוֹדְעֵי תְרוּעָה וַדַּאי, <Nonei></i>יוֹדְעֵי תְרוּעָה: מְתַבְּרֵי הַאי תְּרוּעָה, דְּאִיהוּ דִּינָא קַשְׁיָא, דְּכֹלָּא אִתְדָּנוּ בֵּהּ. זַכָּאִין אִינּוּן יִשְׂרָאֵל בְּעָלְמָא דֵּין, וּבְעָלְמָא דְּאָתֵי, בְּגִין דְּאִינּוּן יַדְעֵי אָרְחוֹי דְקוּדְשָׁא בְּרִיךְ הוּא, וְיַדְעֵי לְמֵהַךְ בְּאָרְחוֹי, וּלְיַחֲדָא יִחוּדָא כְּדְקָא יֵאוֹת.</p>\n<p>אִלֵּין חַלּוֹנוֹת, וְאִלֵּין חֲרַכִּים, קַיְימֵי כֻּלְּהוּ לְאַחֲדָא כָּל צְלוֹתִין, דְּסַלְּקִין מִתַּתָּא לְעֵילָּא, וּלְאַשְׁגָּחָא בְּהוּ, לְאַעֲלָא לוֹן קָמֵי קוּדְשָׁא בְּרִיךְ הוּא. וְעַל דָּא כָּל בֵּית הַכְּנֵסֶת דְּלָאו בֵּיהּ חַלּוֹנוֹת, לָאו אֲתָר לְצַלָּאָה בֵּיהּ כְּדְקָא יֵאוֹת.</p>\n<p>דְּהָא בֵּית הַכְּנֵסֶת לְתַתָּא, לָקֳבֵל בֵּית הַכְּנִסֶת דִּלְעֵילָּא. בֵּית הַכְּנֵסֶת דִּלְעֵילָּא דְּאִית בֵּיהּ (נ\"ט ע\"ב) חַלּוֹנוֹת כְּמָה דְּאַמָרָן, הָכִי נָמֵי לְתַתָּא. לְעֵילָּא כְּנֶסֶת הַגְּדוֹלָה, אִית בֵּיהּ תְּרֵיסָר חַלּוֹנוֹת עִלָּאִין, הָכִי נָמֵי לְהַאי בֵּית הַכְּנֵסֶת תַּתָּאָה. וְכֹלָּא קַיְּימָאן דָּא לָקֳבֵל דָּא, בְּגִין דְּעָלְמִין קַיְימִין אִלֵּין בְּגַוְונָא דְּאִלֵּין, וְקוּדְשָׁא בְּרִיךְ הוּא סָלִיק יְקָרֵיהּ בְּכֹלָּא. וְעַל דָּא בְּיוֹם רָעָה יְמַלְּטֵהוּ יְיָ', כַּד שַׁלְטָא הַהִיא סִטְרָא בִּישָׁא, יְמַלְּטֵהוּ יְיָ'.</p>\n<p>כְּגַוונָא דָּא, הַאי מְמָנָא יְהִירָאֵ\"ל, קַיְּימָא עַל כָּל אִינּוּן דְּחַיְיסֵי עַל מִסְכְּנֵי, כְּמָה דְאַתְּ אָמֵר אַשְׁרֵי מַשְׂכִּיל אֶל דָּל. וּבְגִין דָּא כֹּלָּא קַיְּימָא בְּהֵיכָלָא דָּא, וְהֵיכָלָא דָּא אִתְכְּלִיל בְּהֵיכָלָא אַחֲרָא רְבִיעָאָה, דְּתַמָּן הוּא גִּזְרִין וְדִינִין לְכֹלָּא. זַכָּאָה חוּלָקֵיהּ מַאן דְּיָדַע גִּנְזֵי דְּמָארֵיהּ, לְיַחֲדָא לֵיהּ, וּלְקַדְּשָׁא שְׁמֵיהּ דְּמָארֵיהּ תְּדִירָא, לְמִזְכֵּי לֵיהּ בְּעָלְמָא דֵּין וּבְעָלְמָא דְּאָתֵי.</p>"],[9520011924,"<p><Noneb>היכל הזכות גבור\"ה</b> הֵיכָלָא רְבִיעָאָה. הֵיכָלָא דָּא, דִּי קוּדְשָׁא בְּרִיךְ הוּא אִשְׁתְּמוֹדַע שׁוּלְטָנֵיהּ בְּאַרְעָא בְּגִינֵיהּ. וְדָא אִיהוּ הֵיכָלָא, דְּקַיְּימָא לְמֵטַר אָרְחוֹי דְּאוֹרַיְיתָא. דָּא הֵיכָלָא אִקְרֵי דִּזְכוּת, דְּבֵיהּ אִתְדָּנוּ כָּל דִּינִין דְּעָלְמָא, וְכָל זַכְיָין, וְכָל חוֹבִין, וְכָל עוֹנָשִׁין, וְכָל אֲגָר טַב, לְאִינּוּן דְּנַטְרֵי פִּקּוּדֵי אוֹרַיְיתָא.</p>\n<p>הֵיכָל דָּא דִּזְכוּת, מְשַׁנְיָיא מִכָל שְׁאַר הֵיכָלִין, וְהַאי הֵיכָלָא, כְּלִילָן בֵּיהּ אַרְבַּע הֵיכָלִין, מְשַׁנְיָין דָּא מִן דָּא, וְכֻלְּהוּ חַד הֵיכָלָא. בְּהֵיכָלָא דָּא אִית רוּחָא חֲדָא, דְּאִקְרֵי זְכוּ\"ת אֵל. וְהֵיכָלָא דָּא אִקְרֵי עַל שְׁמֵיהּ זְכוּת, וְהַאי אִיהוּ אֵל. וְהָכָא אִתְדָנוּ כָּל דִּינִין דְּעָלְמָא, וְהַאי אִיהוּ רָזָא דִּכְתִיב, (תהלים ז) וְאֵל זוֹעֵם בְּכָל יוֹם.</p>\n<p>ד' הֵיכָלִין, ד' אִלֵּין דְּאִינּוּן בְּהֵיכָלָא דָּא, דָּא לְגוֹ מִן דָּא, כֻּלְּהוּ כְּלִילָן דָּא בְּדָא, וְכֻלְּהוּ חַד הֵיכָלָא, וְאִקְרֵי זְכוּתָא. אַרְבַּע הֵיכָלִין אִלֵּין, אִית לְהוּ פִּתְחִין. חַד מְמָנָא עִלָּאָה דְּקַיְּימָא לְבַר לְפִתְחָא קַדְמָאָה דְּהֵיכָלָא דָּא, סַנְסָנִיָּ\"הּ שְׁמֵיהּ, וְעַל שְׁמָא דָּא, אִית מְמָנָא אַחֲרָא לְסִטְרָא אַחֲרָא דִּשְׂמָאלָא, דְּנָטִל דִּינִין בְּהַהוּא הֵיכָלָא דִּילֵיהּ, לְאַתְעֲרָא לְמֶעְבַּד בְּעָלְמָא. וּבְגִין דְּנָטִיל מִנֵּיהּ, אִקְרֵי עַל שְׁמֵיהּ, סַנְסָנִיָּ\"הּ. וְאִיהוּ שַׁלִּיט עַל הַהוּא אַסְכָּרָ\"א דְּרַבְיֵי.</p>\n<p>וְהַאי מְמָנָא עִלָּאָה סַנְסָנִיָּ\"הּ, כַּד נָטִיל דִּינָא, אַכְרִיז לְאִינּוּן מְמָנָן דְּקַיְימִין עַל תְּרֵיסָר פִּתְחִין, וְאִינּוּן כָּרוֹזִין דְּמַכְרְזֵי כָּל אִינּוּן דִּינִין, דְּאִתְדָּנוּ מְהֵיכָלָא דִּזְכוּתָא דָּא.</p>\n<p>רוּחָא דָּא דְּנָטִיל כֹּלָּא, דְּאִקְרֵי זְכוּת אֵ\"ל דְּקָאָמַרָן, כֹּלָּא כָּלִיל בֵּיהּ. מִנֵּיהּ נַפְקוּ שִׁבְעִין נְהוֹרִין נְצִיצִין, וְכֻלְּהוּ בְּעִגוּלָא קַיְימֵי, בְּגִין לְאַחֲזָאָה דָּא בְּדָא דְּלָא אִתְכַּסֵי דָּא מִן דָּא. כָל זַכְיָין, וְכָל עוֹנָשִׁין, וְכָל דִּינִין, קָמֵי כֻּלְּהוּ נְהוֹרִין אִלֵּין קַיְימִין.</p>\n<p>מִנַּיְיהוּ נַפְקֵי תְּרֵין נְהוֹרִין, דְּקַיְימֵי קָמַיְיהוּ תָּדִיר. וְאִלֵּין ע' נְהוֹרִין, וּתְרֵין נְהוֹרִין דְּקַיְימֵי קָמַיְיהוּ, אִינּוּן לְגוֹ בְּאֶמְצָעִיתָא דְּהֵיכָלָא. וְעַל רָזָא דְּהֵיכָלָא דָּא כְּתִיב, (שיר השירים ז׳:ג׳) שָׁרְרֵךְ אֲגַן הַסַּהַר אַל יֶחְסַר הַמָּזֶג.</p>\n<p>לָקֳבֵל אִינּוּן נַפְקֵי שִׁבְעִין וּתְרֵין נְהוֹרִין אַחֲרָנִין, מִסִּטְרָא דִּימִינָא. וְשִׁבְעִין וּתְרֵין נְהוֹרִין אַחֲרָנִין, מִסִּטְרָא דִּשְׂמָאלָא. וְאִלֵּין קַדְמָאֵי אִינּוּן פְּנִימָאֵי לְגוֹ, בְּאֶמְצָעִיתָא דְּהֵיכָלָא. לְקַמֵּי נְהוֹרִין אִלֵּין, עָאלִין כָּל זַכְוָון וְכָל חוֹבִין לְאִתְדַכָּאָה. כָּל עוֹבָדִין דְּעָלְמָא, מֵאִלֵּין פְּנִימָאֵי נַפְקֵי. אִשְׁתְּכָחוּ כָּל נְהוֹרִין דְּנַפְקֵי מֵרוּחָא דָּא עִלָּאָה, מָאתָן וְשִׁית סְרֵי נְהוֹרִין, וְכֻלְּהוּ כְּלִילָן בְּרוּחָא דָּא.</p>\n<p>אִינּוּן תְּרֵי נְהוֹרִין, דְּקַיְימֵי קָמֵי אִינּוּן שִׁבְעִין, אִינּוּן סַהֲדֵי סַהֲדוּתָא תָּדִיר, וְכַתְבֵי פִּתְקֵי דִּינָא דִּזְכוּ אוֹ דְּחוֹבָה. אִלֵּין שִׁבְעִין אִינּוּן גִּזְרִין גַּזְרֵי וְדַיְינִין דִּינִין. וְכָל דִּינִין דְּעָלְמָא הֵן לְטָב הֵן לְבִישׁ הָכָא אִיהוּ.</p>\n<p>רוּחָא דָּא, דְּאִיהוּ זְכוּת אֵ\"ל כִּדְקַאמְרָן, בֵּיהּ רְשִׁימִין תְּלַת אַתְוָון, דְּמִתְדַּבְּקָן בֵּיהּ מִלְּעֵילָּא, דְּאִינּוּן יה\"ו. וְהָא אוֹקִימְנָא דְּכַד אִלֵּין אַתְוָון מִתְדַּבְּקָאן בְּהַאי אֲתָר, <Nonei></i>דְּאִתְדַבְּקוּתָא דִּדְכוּרָא בְּנוּקְבָּא. כְּדֵין אִתְרְשִׁימוּ בְּהַאי רוּחָא, אִינּוּן אַתְוָון. וְהָכָא אָמַר דָּוִד, (תהילים צ״ד:כ״ב) וֵאלֹהַי לְצוּר מַחְסִי. רָזָא דְּרוּחָא דָּא דְּאִקְרֵי אֵ\"ל וְרָזָא דְּאִינּוּן אַתְוָון דִּרְשִׁימִין בֵּיהּ, דְּאִקְרוּן יה\"ו, אִלֵּין תְּלַת סִטְרִין דִּנְהוֹרִין דְּקָאָמַרָן.</p>\n<p>אִינּוּן תְּלַת בָּתֵי דִּינִין, דְּמִתְפַּלְּגֵי בְּדִינִין אַחֲרָנִין, בְּמִילֵּי דְּעָלְמָא, בְּעוּתְרָא, בְּמִסְכְּנוּ, בְּמַרְעִין, בִּשְׁלִימוּ, דְּאִינּוּן אַרְבַּע הֵיכָלִין דְּאִינּוּן מְתַקְּנָן לְכָל אִינּוּן אַחֲרָנִין, תְּרִין הֵיכָלִין לְאִלֵּין תְּרֵי סִטְרֵי נְהוֹרִין אַחֲרָנִין, וְחַד הֵיכָלָא לְכָל אִינּוּן מָארֵי דְּעַיְינִין, דְּעַבְדֵי חוּשְׁבָנָא מִכָל עוֹבָדִין דְּעָלְמָא. וְחַד הֵיכָלָא, לְסוֹפְרִין אַחֲרָנִין, דִּי תְּחוֹת אִלֵּין קַדְמָאֵי פְּנִימָאֵי. אִלֵּין אַרְבַּע הֵיכָלִין, כְּלִילָן בְּהֵיכָלָא דָּא, דְּאִקְרֵי עַל שְׁמָא דְּהַאי רוּחָא זְכוּתָא, כִּדְקַאמְרָן.</p>\n<p>בְּכָל פִּתְחָא וּפִתְחָא דְּאִלֵּין הֵיכָלִין, אִית מְמָנָא חַד, בְּפִתְחָא קַדְמָאָה אִית מְמָנָא חֲדָא, דִּשְׁמֵיהּ אִקְרֵי גַּזְרִיאֵ\"ל. (לפתחא קדמאה דשמיה דכלא סנסני\"ה דמינה נטיל) הַאי מְמָנָא אַחֲרָא, הַהוּא מְמָנָא אִיהוּ לְגַלָּאָה דִּינִין, דְּאִתְדָּנוּ וְאִתְגְּזָרוּ לְהַהוּא מְמָנָא קַדְמָאָה, דִּשְׁמֵיהּ סַנְסָנִיָּ\"הּ דְּמִנֵּיהּ נָטִיל הַאי מְמָנָא אַחֲרָא, דְּקַיְּימָא עַל הֵיכָלָא דְּסִטְרָא אַחֲרָא, וְקַיְּימָא עַל אַסְכָּרָה דְּרַבְיֵי, כִּדְקַאמְרָן.</p>\n<p>וְהַאי מְמָנָא גַּזְרִיאֵ\"ל, נָטִיל מִלָּה דְּבֵי דִּינָא פְּנִימָאָה. דְּכֹלָּא, אִתְגְזַר תַּמָּן, וּכְדֵין אוֹדִיעַ מִלָּה לְהַאי מְמָנָא דִּלְבַר, וְכָל אִינּוּן כָּרוֹזֵי מַכְרְזֵי וְאַמְרֵי בְּכָל רְקִיעִין, כַּךְ וְכַךְ אִתְגְּזַר מִבֵּי מַלְכָּא, עַד דְּנַטְלֵי הַהִיא מִלָּה בְּהֵיכָלָא דִּלְתַתָּא, וּמִתַּמָּן נַפְקֵי וּמַכְרְזֵי מִלָּה, עַד דְּאִשְׁתְּמַע בְּכֻלְּהוּ רְקִיעִין תַּתָאִין, וְנַחְתֵּי וְאוֹדְעֵי מִלָּה, לְכֻלְּהוּ דִּלְתַתָּא.</p>\n<p>וְנַטְלֵי מִלָּה כֻּלְּהוּ תַּתָּאִין, מִדַרְגָא לְדַרְגָא, אֲפִילּוּ צִפֳּרֵי שְׁמַיָא, וְעוֹפֵי דְּאַרְעָא, כֻּלְּהוּ נַטְלֵי מִלָּה, וְאוֹדְעֵי לָהּ בְּעָלְמָא. עַד דְּנַטְלֵי מִלָּה כָּל אִינּוּן גַּרְדִּינֵי נִימוּסִין, וְאַחְזְיָין בְּחֶלְמָא לִבְנֵי נָשָׁא, וְאַתְיָא הַהִיא מִלָּה לִזְמַן קָרִיב.</p>\n<p>וּלְזִמְנִין דְּהַהִיא מִלָּה דְּאִצְטְרִיכָא לְמַלְכֵי אַרְעָא, דְּאִינּוּן מְמָנָן לְאַתְזְנָא, וּלְדַבְּרָא עַמִין. דְּאוֹדְעִין הַהִיא מִלָּה עַד רְקִיעָא דְּשִׁמְשָׁא דִּלְתַתָּא, וְקַיְּימָא תַּמָּן. עַד דְּאִינּוּן מְמָנָן שִׁמְשָׁא, דְּאִתְמָנוּן עַל שִׁמְשָׁא, נַטְלֵי הַהִיא מִלָּה, וְאוֹדְעֵי לָהּ לְאִינּוּן מְמָנָן עִלָּאִין דִּי בְּסִטְרָא אַחֲרָא, וְאִינּוּן מוֹדִעִין הַהִיא מִלָּה לְמַלְכֵי אַרְעָא, דְּאִינּוּן בְּסִטְרָא דִּלְהוֹן.</p>\n<p>וְכַד הֲווֹ נְבִיאִים בְּהוּ בְּיִשְׂרָאֵל, הֲווֹ נַטְלִין נְבוּאָה דִּלְהוֹן, מִתְּרֵין עַמּוּדִין עִלָּאִין דְּאוֹרַיְיתָא סָמִיךְ עָלַיְיהוּ. לְבָתַר דְּאִסְתָּלָקוּ נְבִיאִים מֵעָלְמָא, וְאָתוּ מָארֵי דְּמַרְאֶה, וּמָארֵי דְּחֶלְמָא, נַטְלֵי מִלָּה מֵאַתְרֵיהּ כִּדְקָאָמְרָן. וְכַד מַלְכֵי הֲווֹ בֵּינַיְיהוּ דְּיִשְׂרָאֵל, וּנְבִיאִים אִסְתָּלָקוּ, וּמָארֵי דְּחֶלְמָא וּמַרְאֶה לָא אִשְׁתְּכָחוּ, אוֹדְעִין מִלָּה לְאִינּוּן מַלְכִין, מֵהַאי פִּתְחָא כִּדְקָאָמְרָן.</p>\n<p>וְאִי תֵּימָא הֵיךְ נָטִיל מִלָּה מֵהַאי אֲתָר. תָּא חֲזֵי, כָּל דַּרְגָא וְדַרְגָּא, וְכָל פִּתְחָא וּפִתְחָא, כֻּלְּהוּ אִית לוֹן לְבַר, מְמָנָן יְדִיעָן, דְּאִתְמָנוּן (בסטרא דלהון) בְּכָל אִינּוּן רְקִיעִין, עַד דְּנַחְתֵי לְתַתָּא בִּרְקִיעִין תַּתָּאִין וְאוֹדְעִין מִלָּה לְאִינּוּן דְּאִצְטְרִיךְ בְּגִין דְּהָא מֵאִלֵּין הֵיכָלִין דְּאִינּוּן סִטְרָא דִּקְדוּשָּׁה וְרָזָא דִּמְהֵימְנוּתָא, אִתְפְּרָשׁוּ דַּרְגִּין לְתַתָּא, כֻּלְּהוּ בְּרָזָא דִּמְהֵימְנוּתָא, וְנַחְתּוּ דַּרְגִּין עַל דַּרְגִּין, עַד דְּפַרְחִין מֵהַאי עָלְמָא, וְאִתְמְנוּן בֵּיהּ.</p>\n<p>מִנְּהוֹן, לְנַטְרָא בְּנֵי נָשָׁא מִסִּטְרָא אַחֲרָא, וּמִנְּזִיקֵי עָלְמָא, וּבְאִינּוּן אָרְחֵי דְּקָא אָזְלֵי. וּמִנְּהוֹן, לְסַיְּיעָא לִבְנֵי נָשָׁא, כַּד אָתָאן לְאִתְדַּכְאָה. וּמִנְּהוֹן, לְמֶעְבַּד אָתִין וְנִסִּין בְּעָלְמָא. וּמִנְּהוֹן דְּקַיְימֵי לְאַשְׁגָחָא בְּעוֹבָדִין דִּבְנֵי נָשָׁא, לְמִסְהַד סַהֲדוּתָא. וְכֵן (בגוונא דא) מִתְפָּרְשִׁין כַּמָה דַּרְגִּין לְסִטְרַיְיהוּ, וְכֻלְּהוּ בְּרָזָא דִּמְהֵימְנוּתָא עִלָּאָה, בִּקְדוּשָּׁה עִלָּאָה.</p>\n<p>כְּגַוְונָא דָּא בְּסִטְרָא אַחֲרָא, סִטְרָא מְסַאֲבָא, מִתְפָּרְשִׁין דַּרְגִּין מֵאִינּוּן הֵיכָלִין לְתַתָּא, כֻּלְּהוּ דַּרְגִּין לְאַבְאָשָׁא, וּלְאַסְטָאָה עָלְמָא: מִנְּהוֹן, קַיְימֵי לְאַסְטָאָה בְּנִי נָשָׁא, מֵאֹרַח טַב לְאֹרַח בִּישָׁא. וּמִנְּהוֹן קַיְימֵי לְסָאֲבָא בְּנִי <Nonei></i>נָשָׁא, לְאִינּוּן דְּאָתוּ לְאִסְתַּאֲבָא, כְּמָה דְּתָנֵינָן, אָתָא בַּר נָשׁ לְאִסְתַּאֲבָא, מְסָאֲבִין לֵיהּ בְּהַאי עָלְמָא, וּמְסָאֲבִין לֵיהּ בְּהַהוּא עָלְמָא, וְאִינּוּן אִקְרוּ צוֹאָה רוֹתַחַת. כְּמָה דְאַתְּ אָמֵר (ישעיהו ל׳:כ״ב) צֵא תֹּאמַר לוֹ. וְאִינּוּן דַּרְגִּין דְּקַיְימָן לְסָאֲבָא יַתִיר, וּבְגִין כַּךְ, אִלֵּין תָּדִיר לָקֳבֵל אִלֵּין, וְכֹלָּא אִיהוּ בְּדַרְגִּין יְדִיעָאן כַּדְקָא חֲזֵי.</p>\n<p>פִּתְחָא תִּנְיָינָא. בְּהַאי פִּתְחָא אִית מְמָנָא, דַּהֲרִיאֵ\"ל שְׁמֵיהּ. וְאִיהוּ לִסְטַר יְמִינָא, וְהַאי אִיהוּ מְמָנָא, לְאַעֲלָא כָּל זְכוּתִין דְּזָכוּ בְּהוּ בְּנֵי נָשָׁא, בְּגִין דְּיִתְדָּן בַּר נָשׁ לְטָב עָלַיְיהוּ כַּד אִתְּדָן לְטָב, וְאִינּוּן זַכְיָין קַיְימָן סַגִיאָן עַל חוֹבֵי בְּנֵי נָשָׁא, כְּדֵין הַאי מְמָנָא, פָּקִיד עַל אַגְרָא וְחוּלָקָא דְּאִינּוּן זַכְיָין וְאַגְרָן לְטָב.</p>\n<p>וְאַפִּיק הַהוּא דִּינָא, וּמָנֵי לֵיהּ לְהַהוּא מְמָנָא, דְּאִקְרֵי פְּדָיאֵ\"ל, דִּי בְּהֵיכָלָא תְּלִיתָאָה. וּכְדֵין אֲמַר לֵיהּ, (איוב ל״ג:כ״ד) פְּדָעֵהוּ מֵרֶדֶת שַׁחַת. בְּגִין דְּכַד בַּר נָשׁ קָאִים בְּבֵי מַרְעֵיהּ, וְאִתְפַּס בִּתְפִיסוּ דְּמַלְכָּא, כְּדֵין אִתְדָּן בַּר נָשׁ. וְכָל זְכוּ וְכָל חוֹבָה דְּעֲבַד בְּהַאי עָלְמָא, כֹּלָּא עָאל בְּהַאי הֵיכָלָא לְאִתְדְּנָא.</p>\n<p>וְכַד אִתְדָּן לְטָב, בְּהַאי פִּתְחָא נָפַק דִּינֵיהּ לְטָב, לִימִינָא דְּהַאי מְמָנָא דַּהֲרִיאֵ\"ל, דְּקַיְּימָא בֵּיהּ, וְאוֹדְעִין דִּינִיהּ לְטָב, עַד דְּאִשְׁתְּזִיב. וְנַחְתָּא הַהוּא דִּינָא, בְּכָל אִינּוּן מְמָנָן, דַּרְגִּין דְּאִשְׁתְּמוֹדָעוּ לְטָב לְתַתָא, כֻּלְּהוּ דַּרְגִין עַל דַּרְגִין, וְכֹלָּא, בֵּין לְטָב בֵּין לְבִישׁ, מִבֵּי מַלְכָּא אִתְדָּן הַהוּא בַּר נָשׁ.</p>\n<p>פִּתְחָא תְּלִיתָאָה. בְּהַאי פִּתְחָא אִית מְמָנָא חַד, גַּדִיאֵ\"ל שְׁמֵיהּ. וְאִיהוּ לִסְטַר שְׂמָאלָא, וְהַאי אִיהוּ מְמָנָא, לְאַעֲלָא (ס\"א לאתקלא) כָּל חוֹבִין וְכָל בִּישִׁין, דְּבַּר נָשׁ אַסְטֵי אֲבַתְרַיְיהוּ בְּהַאי עָלְמָא. וְנָחִית לוֹן גּוֹ מַתְקְלָא לְאַתְקְלָא, בְּאִינּוּן זַכְיָין דְּעָאלוּ בִּידָא דְּהַהוּא מְמָנָא אַחֲרָא דְּקָאָמַרָן.</p>\n<p>וְהַהוּא מַתְקְלָא קַיְּימָא גּוֹ פִּתְחָא רְבִיעָאָה, וְתַמָּן אִתְקָלוּ זַכְיָין וְחוֹבִין כַּחֲדָא. מַאן דְּנָצַח מִנַּיְיהוּ, הָכִי אִית לֵיהּ מְמָנָן בְּהַהוּא סִטְרָא. אִי נַצְחָן זַכְיָין, כַּמָה מְמָנָן אִית בִּסְטַר דִּימִינָא, וְנַטְלֵי הַהוּא דִּינָא, וּמַעֲבִרִין בִּישִׁין וּמַרְעִין מֵהַהוּא בַּר נָשׁ, עַד דְּאִשְׁתְּזִיב. אִי נַצְחָן חוֹבִין, כַּמָה מְמָנָן אִית לֵיהּ בְּהַהוּא סִטְרָא דִּשְׂמָאלָא, עַד דְּנַטְלֵי מִלָּה הַהוּא סִטְרָא אַחֲרָא, וְכָל אִינּוּן גַּרְדִּינִי נִמּוּסִין, עַד דְּאִתְרַע מַזָּלֵיהּ. וּכְדֵין נַחְתָּא הַהוּא סִטְרָא אַחֲרָא, וְנָטִיל נִשְׁמְתָא. זַכָּאָה חוּלָקֵיהוֹן דְּצַדִּיקַיָּיא בְּעָלְמָא דֵּין וּבְעָלְמָא דְּאָתֵי.</p>\n<p>פִּתְחָא רְבִיעָאָה. בְּהַאי פִּתְחָא, קַיְּימָא חַד מְמָנָא, ואזני\"ה (ס\"א מאזני\"ה) שְׁמֵיהּ. וְהַאי אִיהוּ מַתְקְלָא, דְּנַטְלָא (ס\"א דתקיל) זַכְיָין וְחוֹבִין, וּבֵיהּ אִתְּקָלוּ כֻּלְּהוּ כַּחֲדָא. וְדָא אִקְרֵי (רנ\"ה ע\"א) מֹאזְנֵי צֶדֶק. כְּדִכְתִיב (ויקרא י״ט:ל״ו) מֹאזְנִי צֶדֶק. בְּהַאי אִתְּקָלוּ כֻּלְּהוּ לְאִתְּדְּנָא.</p>\n<p>תְּחוֹת הַאי מְמָנָא, אִית תְּרֵין מְמָנָן, חַד לִימִינָא וְחַד לִשְׂמָאלָא. חַד לִימִינָא, הֲרִיאֵ\"ל שְׁמֵיהּ. חַד לִשְׂמָאלָא, גְּדוּדִיאֵ\"ל שְׁמֵיהּ. וְכַד אִתְּקָלוּ זַכְיָין וְחוֹבִין, דָּא אַכְרַע לִסְטַר יְמִינָא, וְדָא אַכְרַע לִסְטַר שְׂמָאלָא. וְכֻלְּהוּ אִתְכְּלִילוּ בְּהַאי רוּחָא דְּאִקְרֵי זְכוּ\"ת אֵל.</p>\n<p>וְכַד אִתְכְּלִילָן כֻּלְּהוּ בֵּיהּ, אַפִּיק (ס\"א חד) חֵיוָתָא, קַדִּישָׁא, וְהַאי חֵיוָתָא מְלָהֲטָא, וְאִקְרֵי שְׁמֵיהּ, תּוּמִיאֵ\"ל. הַאי חֵיוָתָא, אִיהִי חֵיוָתָא דְּקַיְּימָא לְאַשְׁגָּחָא בְּעָלְמָא, בְּאִינּוּן עֵינִי יְיָ', דְּאַזְלָן וְשָׁטָאן בְּעָלְמָא. וְאִינּוּן עֵינֵי יְיָ', כֻּלְּהוּ נַטְלוּ אַשְׁגָּחוּתָא, מֵאִינּוּן עוֹבָדִין טָבִין דְּאִתְעָבֵידוּ בִּטְמִירוּ, וּלְאַשְׁגָּחָא בְּאִינּוּן עוֹבָדִין דְּאִינּוּן בִּשְׁלִימוּ דְּלִבָּא, וְאַף עַל גַּב דְּלָא אִתְעָבִידוּ כַּדְקָא יֵאוֹת.</p>\n<p>הַאי חֵיוָתָא אִיהִי קַיְּימָא בְּאַשְׁגָּחוּתָא דִּצְלוֹתִין. בְּגִין דְּאִינּוּן שְׁאֶלְתִּין דְּשָׁאֲלֵי בְּנִי נָשָׁא בִּצְלוֹתֵהוֹן, כֻּלְּהוּ קַיְימֵי בִּידָא דְּהַאי חֵיוָתָא, וְאָנַח לְהוּ בְּהַאי הֵיכָלָא, וְקַיְימִין אִינּוּן שְׁאֶלְתִּין בְּהַאי הֵיכָלָא עַד אַרְבְּעִין יוֹמִין, לְאַשְׁגָּחָא בְּהוּ.</p>\n<p>דְּהָא (בסוף ארבעין יומין) בְּכָל אַרְבְּעִין וְאַרְבְּעִין, נָפְקָא הַאי חֵיוָתָא, וְנָטִיל לְכָל אִינּוּן שְׁאֶלְתִּין, וְאָנַח לוֹן קָמַיְיהוּ דְּאִינּוּן שִׁבְעִין וּתְרֵין נְהוֹרִין, וְדַיְינִין לוֹן. וּכְדֵין הַאי רוּחָא דְּאִקְרֵי זְכוּ\"ת אֵל, <Nonei></i>מְעַיֵּין בְּהוּ, אִי זָכֵי אִי לָא זָכֵי. אִי זָכֵי, נָפְקָא הַאי צְלוֹתָא, וּמִתְגַּלְגְּלָא הַאי שְׁאֶלְתָּא, וְנָפְקָן עִמָּהּ תְּרֵיסָר מְמָנָן, וְכָל חַד וְחַד תַּבְעִין מֵעִם הַהוּא רוּחָא, קִיוּמָא בְּהַאי שְׁאֶלְתָּא, וְאִתְקַיְּימָא בְּהוּ.</p>\n<p>תְּחוֹת הַאי חֵיוָתָא, אַרְבָּעָה שְׂרָפִין מְלַהֲטָן, שְׂרַפְאֵ\"ל, בַּרְקִיאֵ\"ל, קְרִישִׁיאֵ\"ל קְדוּמְיָּ\"הּ. וְאִלֵּין אַרְבַּע תְּחוֹת הַאי חֵיוָתָא קַיְימִין לְאַרְבַּע סִטְרֵי עָלְמָא, אִלֵּין ד' קַיְימֵי לְד' סִטְרֵי עָלְמָא, וְאִינּוּן מְמָנָן לְאַשְׁגָּחָא בְּכָל אִינּוּן דְּנַטְרֵי יוֹמָא דְּשַׁבְּתָא, וּמְעַנְּגֵי שַׁבְּתָא כְּדְקָא יֵאוֹת.</p>\n<p>מֵאִלֵּין אַרְבַּע כַּד נַטְלֵי, נַפְקֵי שְׁבִיבִין דְּאֶשָּׁא, וּמֵאִלֵּין שְׁבִיבִין אִתְעָבִידוּ שִׁבְעִין וּתְרֵין גַּלְגַּלִּין, מְלַהֲטָן בְּאֶשָּׁא. מֵהָכָא אִתְעָבִיד נְהַר דִּינוּר. אֶלֶף אַלְפִין יְשַׁמְּשׁוּנֵיהּ לְהַהוּא נַהֲרָא, כָּל אִינּוּן דִּמְעַנְּגֵי שַׁבְּתָא, אִלֵּין אַרְבַּע מְמָנָן מַשְׁגְּחָן בְּכָל אִינּוּן דִּמְעַנְּגֵי שַׁבְּתָא, וְהַאי חֵיוָתָא קַיְּימָא עָלַיְיהוּ, וְנַטְלֵי בְּגִינָהּ תְּחוֹתָהּ.</p>\n<p>בְּכָל יוֹמָא וְיוֹמָא, נָגִיד הַהוּא נְהַר דִּינוּר, וְאוֹקִיד לְכַמָּה רוּחִין, וּלְכַמָה שַׁלִּיטִין. וְכַד עָיִיִל שַׁבְּתָא, כָּרוֹזָא נָפְקָא, וְשָׁכִיךְ הַהוּא נְהַר דִּינוּר, וְזַעְפִּין וְזִיקִין וּשְׁבִיבִין אִשְׁתְּכָכוּ. וְהַאי חֵיוָתָא אַזְלָא וְסַלְּקָא עַל אַרְבָּעָה אִלֵּין שְׂרָפִים דְּקָאָמַרָן. וְעָאל גּוֹ אֶמְצָעִיתָא דְּהֵיכָלָא דָּא, בְּהַהוּא אֲתַר דְּאִקְרֵי עֹנֶג.</p>\n<p>בְּגִין דִּבְהַאי אֲתָר, כַּד עָיֵיל שַׁבְּתָא, מִתְסַדְּרָאן תַּמָּן כָּל פָּתוֹרֵי דִּבְנֵי עָלְמָא, דְּאִקְרוּ בְּנֵי הֵיכָלָא דְּמַלְכָּא, וְאֶלֶף אַלְפִין, וְרִבּוֹ רִבְּוָון מְמָנָן, קַיְימֵי עַל אִינּוּן פָּתוֹרֵי. וְהַאי חֵיוָתָא עִלָּאָה עַל אִלֵּין אַרְבָּעָה שְׂרָפִים, וְעָאל בְּהַהוּא אֲתָר, וְחָמָא כָּל אִינּוּן פָּתוֹרֵי, (וכל אינון דקיימא עלייהו) וְאַשְׁגַּח בְּכָל פָּתוֹרָא וּפָתוֹרָא, וְהֵיךְ מְעַנְּגֵי לֵיהּ לְכָל פָּתוֹרָא וּפָתוֹרָא, וְקַיְּימָא וּבָרִיךְ לֵיהּ לְהַהוּא פָּתוֹרָא. וְכָל אִינּוּן אֶלֶף אַלְפִין, וְרִבּוֹא רִבְּבָן, כֻּלְּהוּ פַּתְחֵי וְאַמְרֵי אָמֵן.</p>\n<p>וּמַה בְּרָכָה הִיא דְּבָרִיךְ עַל הַאי פָּתוֹרָא דְּמִתְסָדָר וְאִתְעַנְּגָא כְּדְקָא יֵאוֹת. (ישעיהו נ״ח:י״ד) אָז תִּתְעַנַּג עַל יְיָ' וְגוֹ' כִּי פִּי יְיָ' דִּבֵּר. וְכֻלְּהוּ אַמְרֵי, (ישעיהו נ״ח:י״ט) אָז תִּקְרָא וַיְיָ' יַעֲנֶה וְגוֹ'. רוּחָא עִלָּאָה דְּאִקְרֵי זְכוּ\"ת אֵל, כַּד הַהוּא פָּתוֹרָא אִתְעַנָּג בְּכֻלְּהוּ סְעוּדָתֵי, בִּסְעוּדָתָא בַּתְרָאָה תְּלִיתָאָה מְסַיֵּים וְאָמַר, עַל כָּל אִינּוּן קַדְמָאֵי, וְאָמַר (ישעיהו נ״ח:ח׳) אָז יִבָּקַע כַּשַׁחַר אוֹרֶךָ וְגוֹ', כְּבוֹד יְיָ' יַאַסְפֶּךָ. כָּל אִינּוּן שִׁבְעִין נְהוֹרִין אַחֲרָנִין בְּכָל סִטְרִין, פַּתְחֵי וְאַמְרֵי, (תהילים קכ״ח:ד׳) הִנֵּה כִּי כֵן יְבוֹרַךְ גָּבֶר יְרֵא יְיָ'.</p>\n<p>וְכַד פָּתוֹרָא דְּבַר נָשׁ לָא קַיְּימָא בְּהַהוּא אֲתָר בְּסִדּוּרָא דְּעִנּוּגָא כְּדְקָא יֵאוֹת, כְּדֵין הַאי חֵיוָתָא, וְאִינּוּן אַרְבַּע דִּתְחוֹתָהּ, וְכָל אִינּוּן אֶלֶף אַלְפִין וְרִבּוֹ רִבְּבָן, כֻּלְּהוּ דַּחְיָין לֵיהּ לְבַר, לְהַהוּא סִטְרָא אַחֲרָא, וּכְמָּה גַּרְדִּינִי נִימוּסִין, כֻּלְּהוּ נַטְלֵי לֵיהּ וְעַיְילֵי לֵיהּ לְהַהוּא אֲתָר, דְּאִיהוּ בְּהִפּוּכָא מִן דָּא, וְאִקְרֵי נֶגַע. וְכַד עַיִיִל לָהּ תַּמָּן, (ס\"א פתחי) וְאַמְרֵי (תהילים ק״ט:י״ז) וַיֶאֱהַב קְלָלָה וַתְּבוֹאֵהוּ וְלֹא חָפֵץ בִּבְרָכָה וַתִּרְחַק מִמֶּנּוּ. (תהילים ק״ט:י״ז) יְנַקֵּשׁ נוֹשֶׁה לְכָל אֲשֶׁר לוֹ וְגוֹ', אַל יְהִי לוֹ מוֹשֵׁךְ חָסֶד וְגוֹ'. רַחֲמָנָא לִשֵׁזְבָן.</p>\n<p>בְּגִין דְּעִנּוּגָא דְּשַׁבְּתָא, וּמְהֵימְנוּתָא דְקוּדְשָׁא בְּרִיךְ הוּא (ס\"א האי איהו אלין פתורי דעינוגא דשבתא וזמנין וחגין כולהו חדוותא דקודשא בריך הוא) אִיהוּ. וּבְגִין דָּא, כָּל אִינּוּן דִּמְעַנְגֵי עִנּוּגָא דְּשַׁבְּתָא וְזִמְנֵי וּמוֹעֲדֵי, אִלֵּין אַרְבַּע דְּקַיְימֵי תְּחוֹת הַאי חֵיוָתָא, קַיְּימָא לָקֳבֵל הַהוּא נְהַר דִּינוּר, וְלָא שַׁבְקֵי לְאִתּוֹקְדָא בֵּיהּ, לְכָל אִינּוּן דְּמִתְעַנְּגֵי עִנּוּגַיְיהוּ כְּדְקָא יֵאוֹת.</p>\n<p>תְּחוֹת אִלֵּין אַרְבַּע, אִית מְמָנָן אַחֲרָנִין, דְּקַיְימֵי לְבַר, דְּאִשְׁתְּמוֹדְעָאן מִסִּטְרָא דְּהֵיכָלָא דָּא (וכל כרוזין לבר) וּמַכְרְזֵי לְכֹלָּא אִינּוּן דִּינִין, וְכָל אִינּוּן גִּזְרִין דְּאִתְגְּזָרוּ בְּהַאי הֵיכָלָא.</p>\n<p>כֹּלָּא אִתְּדָּן הָכָא, בַּר תְּלַת מִלִּין, דְּלָא אִתְיְיהִיב רְשׁוּ הָכָא בְּהֵיכָלָא דָּא דְּאִקְרֵי זְכוּתָא. ואִלֵּין (בראשית מ\"ג ע\"ב, קפ\"א ע\"א, ויקרא כ\"ה ע\"ב) אִינּוּן: בְּנֵי, חַיֵּי, וּמְזוֹנֵי. דְּהָא אִלֵּין תְּלָתָא, לָא קַיְימֵי הָכָא, בְּגִין דְּהָא בְּמַזָּלָא תַּלְיָאן. דְּהָא הַהוּא נָהָר דְּנָגִיד וְנָפִיק, תַּמָּן תַּלְיָין חַיִּין דִּלְעֵילָּא, וְתַמָּן תַּלְיָין מְזוֹנֵי, וְתַמָּן תַּלְיָין בְּנֵי, דְּהָא אִלֵּין תְּלָתָא מִתַּמָּן נַפְקֵי, וְנַגְדֵּי וְאִתְמַשְּׁכָאן לְתַתָּא. וּבְגִין כַּךְ, כֹּלָּא קַיְּימָא בְּהֵיכָלָא דָּא, בַּר הָנֵי תְּלָתָא.</p>\n<p>בַּר נָשׁ כַּד אִיהוּ בְּבֵי מַרְעֵיהּ, הָכָא אִתְּדָּן, וְכָל שְׁאַר דִּינִין דְּעָלְמָא. ואִי תֵּימָא, בַּר נָשׁ בְּבֵי <Nonei></i>מַרְעֵיהּ, אִי אִתְּדָּן לַחַיִּים יָהֲבִין לֵיהּ. לָאו דְּחַיִּין תַּלְיָין הָכָא, אֶלָּא כַּד אִתְּדָּן הָכָא לְחַיִּים, כְּדֵין נַגְדִּין חַיִּים מִלְּעֵילָּא, וְיָהֲבֵי לֵיהּ. (ואי לא לא יהבין) זַכָּאָה חוּלָקֵיהוֹן דְּצַדִּיקַיָּיא דְּיַדְעֵי אָרְחוֹי דְּאוֹרַיְיתָא, וְזַכָּאן בָּהּ לְחַיֵּי עָלְמָא, עָלַיְיהוּ כְּתִיב (ישעיהו ס׳:כ״א) וְעַמֵּךְ כּוּלָם צַדִּיקִים לְעוֹלָם יִרְשׁוּ אָרֶץ וגו'.</p>"],[9520011925,"<p><Noneb>היכל אהבה חס\"ד</b> הֵיכָלָא חֲמִישָׁאָה, הֵיכָלָא דָּא קַיְּימָא לְאַנְהָרָא לְאִלֵּין תַּתָּאֵי. וְהַאי אִיהוּ הֵיכָלָא דְּקַיְּימָא לְאַנְהָרָא בְּרָזָא דִּמְהֵימְנוּתָא. פִּתְחָא חֲדָא קַיְּימָא בְּהַאי הֵיכָלָא, וְחַד מְמָנָא עָלֵיהּ, וְהַהוּא מְמָנָא אִקְרֵי סָנִיגוֹרְיָ\"ה. הַאי מְמָנָא קַיְּימָא עַל פִּתְחָא דָּא, בְּגִין לְמֵילַף (ס\"א סניגוריא עלייהו דישראל ובגין דא אקרי שמיה כך דהא איהו ממנא על כל אינון טבין דישראל למיעל) סַנֵּיגוֹרָא דִּלְהוֹן, קַמֵּיהּ דְּמָארֵיהוֹן. וְלָא יִשְׁלוֹט עָלַיְיהוּ סִטְרָא אַחֲרָא.</p>\n<p>בְּהֵיכָלָא דָּא, קַיְּימָא חַד רוּחָא, דְּכָלִיל בְּאַרְבַּע, דְּהָא רוּחָא דָּא כָּלִיל בְּאַרְבַּע גְּוָונִין, חִוָּור וְאוּכָם יָרוֹק וְסוּמָק. וְהַאי אִיהוּ רוּחָא דְּקַיְּימָא כָּלִיל בְּכֹלָּא, וְאִקְרֵי סוּרִיָּ\"ה, רַב עַל כָּל אִינּוּן חַיָּילִין תַּתָּאִין. וְכֻלְּהוּ קַיְימִין תְּחוֹתֵיהּ, וּמְמָנָן תְּחוֹת יְדֵיהּ.</p>\n<p>הַאי רוּחָא, דְּסָגִיר וּפָתַח. כָּל מַפְתְּחָאן עִלָּאִין כֻּלְּהוּ אִתְמַסְרָן בִּידֵיהּ. (תלת זמנין ביומא) כָּל חַיָּילִין תַּתָּאִין, כֻּלְּהוּ אִתְכְּלִילָן וְקַיְימָן תְּחוֹתֵיהּ, וּמִנֵּיהּ אִתְזָנוּ. הַאי קַיְּימָא בְּכָל רָזִין דְּמָארֵיהּ, כָּל גְּנִזִין עִלָּאִין כֻּלְּהוּ אִתְמַסְרָן בִּידֵיהּ.</p>\n<p>הַאי רוּחָא אִקְרֵי אַהֲבָה. וּבְגִין דָּא, אִקְרֵי הֵיכָל דָּא, הֵיכָל אַהֲבָה. בְּגִין דְּהָכָא אִתְגְנִיזוּ כָּל רָזָא דְּרָזִין, לְמַאן דְּאִצְטְרִיךְ לְאִתְדַּבְּקָא בֵּיהּ. וְהָכָא הוּא רָזָא דִּכְתִיב, (שיר השירים ז׳:י״ג) שָׁם אֶתֵּן אֶת דּוֹדִי לָךְ.</p>\n<p>רוּחָא דָּא, אִיהוּ נָטִיר כָּל נְטִירוּ דִּלְעֵילָּא, וְדָא אִקְרֵי (תהלים קכא) שׁוֹמֵר יִשְׂרָאֵל. (דברים ז׳:ט׳) שׁוֹמֵר הַבְּרִית. בְּגִין דְּהָכָא אִיהוּ נְטִירוּ דְּכָל גִּנְזִין עִלָּאִין, וְעַל דָּא גְּנִיזִין דְּמָארֵיהּ גְּנִיזִין בֵּיהּ. מֵהַאי נַפְקֵי שְׁבִילִין וְאָרְחִין לְאִינּוּן דִּלְתַתָּא, בְּגִין לְאַתְעֲרָא בְּהוּ רוּחָא דִּרְחִימוּתָא.</p>\n<p>אִלֵּין ד' גְּוָונִין דְּבֵיהּ, אִתְּכְלִילָן דָּא בְּדָא. וְכַד בָּעָאן לְאַכְלְלָא, בָּטַשׁ דָּא בְּדָא, וְנָפַק מִכֻּלְּהוּ חַד חֵיוָתָא קַדִישָׁא, דְּאִקְרֵי זֹהַר. וְהַאי חֵיוָתָא עַל דָּא כְּתִיב, (יחזקאל י׳:כ״ב) הִיא הַחַיָּה אֲשֶׁר רָאִיתִי עַל נְהַר כְּבָר.</p>\n<p>מֵהֵיכָלָא דָּא, נָפְקִין כָּל רוּחִין קַדִישִׁין דְּקַיְימִין בְּקִיּוּמָא דְּנְשִׁיקִין (עלאין). דְּהָא מֵאִינּוּן נְשִׁיקִין, נָפְקָא אֲוֵירָא דְּרוּחָא, לְקִיּוּמָא דְּנַפְשָׁא לְכָל אִינּוּן נִשְׁמָתִין עִלָּאִין, דְּאִתְיְיהִיבוּ בִּבְנֵי נָשָׁא. וְרָזָא הַהוּא דִּכְתִיב, (דברים ח׳:ג׳) כִּי עַל כָּל מוֹצָא פִּי יְיָ' יִחְיֶה הָאָדָם. בְּגִין דִּבְהַאי הֵיכָלָא קַיְימִין כָּל נִשְׁמָתִין, וְכָל רוּחִין, דִּזְמִינִין לְנַחְתָּא בִּבְנִי נָשָׁא, מִיּוֹמָא דְּאִתְבְּרֵי עָלְמָא. וְעַל דָּא, הֵיכָלָא דָּא נַקְטָא, כָּל אִינּוּן נִשְׁמָתִין דְּנָפְקִין מֵהַהוּא נָהָר דְּנָגִיד וְנָפִיק. וּבְגִין דָּא, הֵיכָלָא דָּא לָא קַיְּימָא לְעָלְמָא בְּרֵיקָנַיָּיא.</p>\n<p>וּמִיּוֹמָא דְּאִתְחָרַב בֵּי מַקְדְשָׁא, לָא עָאלוּ הָכָא נִשְׁמָתִין אַחֲרָנִין. וְכַד יִסְתַּיְימוּן אִלֵּין, הֵיכָלָא קַיְּימָא בְּרֵיקָנַיָּא, וְיִתְפְּקַד מִלְּעֵילָּא, וּכְדֵין יֵיתֵי מַלְכָּא מְשִׁיחָא. וְאַתְעַר הֵיכָלָא דָּא לְעֵילָּא, וְיִתְעַר הֵיכָלָא לְתַתָא.</p>\n<p>וּבְרָזָא דְּהֵיכָלָא דָּא כְּתִיב, (שיר השירים ד׳:ה׳) שְׁנִי שָׁדַיִךְ כִּשְׁנִי עֳפָרִים וְגוֹ'. בְּגִין דִּבְהֵיכָלָא דָּא הַהוּא רוּחָא דְּקָאָמַרָן, וְהַהוּא חֵיוָתָא, אַפִיק תְּרֵין נְהוֹרִין כְּלִילָן דָּא בְּדָא, מִתְקַשְּׁרָן דָּא בְּדָא, וְאִקְרוּן אֵ\"ל שַׁדַּ\"י. אִלֵּין אִקְרוּן שַׁדַּ\"י, וְאֵ\"ל דִּלְתַּתָּא, מִתְחַבְּרָן דָּא בְּדָא, וְאָעִיל דָּא בְּדָא, וְאִקְרֵי אֵ\"ל שַׁדָ\"י. בְּגִין דְּנָפַק מִכְלָלָא דְּאִלֵּין שָׁדַיִם.</p>\n<p>וְהַאי אֵ\"ל דְּאִיהוּ מִסִּטְרָא דִּימִינָא, נָטִיל מֵאֲתָר דָּא, כָּל אִינּוּן רַחֲמִין, דְּקַיְימֵי לְאַתְזָנָא הַהוּא הֵיכָלָא דִּלְתַתָא, דְּאִקְרֵי זְכוּתָ\"א, עַל שְׁמָא דְּהַאי רוּחָא דְּבֵיהּ דְּקָאָמַרָן. הַאי שַׁדַּי, יָנִיק לְכָל אִינּוּן תַּתָּאִין, וּלְכָל אִינּוּן הֵיכָלִין, וּלְכָל אִינּוּן דִּלְבַר, דְּקַיְימֵי מִסִּטְרָא דָּא, דְּאִקְרוּן יִתְדוֹת הַמִּשְׁכָּן, כְּמָה דְּאוֹקִימְנָא. וְעַל דָּא אִקְרֵי שַׁדַּי, בְּגִין דִּמְסַפְּקָא מְזוֹנָא לְכֻלְּהוּ תַּתָּאֵי, כְּמָה דְּאִיהוּ מְקַבְּלָא, מִסִּטְרָא דִּימִינָא.</p>\n<p>מֵהָכָא, נָפְקוּ אִינּוּן נְהוֹרִין, דְּאִקְרוּן (בראשית ג׳:כ״ד) לַהַט הַחֶרֶב הַמִּתְהַפֶּכֶת. בְּגִין דְּמִתְהַפְּכָא לְכַמָּה גְּוָונִין, וְהָא אוֹקִימְנָא, דְּאִלֵּין מִתְעָרֵי דִּינָא בִּשְׁלִיחוּתָא דִּלְעֵילָּא, וְאִינּוּן בְּעָלְמָא <Nonei></i>מִסְּטָר שְׂמָאלָא, כַּד אִתְפְּרַשׁ (ס\"א אתפשט) רוּחָא דָּא, וּבָטַשׁ לְאַפָקָא נְהוֹרִין לְכָל סִטְרִין, כְּאִינּוּן שָׁדַיִם דְּרָמָאן חֲלָבָא לְכָל סְטָר, הָכִי נָמֵי מֵהַאי רוּחָא, נַפְקֵי לְכָל סְטָר, וְאַפִיקוּ חַד חֵיוָתָא אַחֲרָא, דִּי מְמָנָא עַל אִלֵּין, דְּאִקְרֵי לַהַט הַחֶרֶב הַמִּתְהַפֶּכֶת. וְדָא אִקְרֵי. (חסר) (ס\"א שבע ודא איהו דממנא)</p>\n<p>וְהַהוּא וְהַאי דִּמְמָנָא עַל עָלְמָא. בְּזִמְנָא דִּי מְמָנָא כַּפְנָא עַל עָלְמָא וְאִתְדָּן בֵּיהּ, כְּדֵין הַאי חֵיוָתָא אִתְפָּקְדָא עַל עָלְמָא, וְאַפִיק רוּחָא דִּמְזוֹנָא, לְכָל אִינּוּן בְּנֵי מְהֵימְנוּתָא, דְּלָא יְמוּתוּן בְּכַפְנָא, וְסָעִיד לִבַּיְיהוּ. בְּגִין דְּהָא מִסִּטְרָא אַחֲרָא, כַּד שַׁלְטָא כַּפְנָא בְּעָלְמָא, נַפְקֵי מֵהַאי סִטְרָא תְּרֵין רוּחִין מִסְאֲבִין, וְאִקְרוּן שׁוֹד וְכָפָן. וְדָא אִיהוּ רָזָא, (איוב ה׳:כ״ב) לְשׁוֹד וּלְכָפָן תִּשְׂחָק. בְּגִין דְּאִלֵּין קַיְימִין בְּעָלְמָא, וְעַבְדִין לוֹן לִבְנֵי נָשָׁא קִטְרוּגָא. חַד, הַהוּא דְּקָא מְשַׁדֵּר לְהוּ כַּפְנָא, וּמַיְיתִי. וְחַד, דְּקָא אַכְלֵי בְּנֵי נָשָׁא וְלָא שַׂבְעִין, בְּגִין דְּהָא רוּחָא בִּישָׁא שַׁלְטָא בְּעָלְמָא.</p>\n<p>חֵיוָתָא דָּא, אַפִיק חַד נִיצוֹצָא, דְּקָא נָפִיק מִנְּצִיצוּ דִּתְרֵין נִיצוֹצִין דְּאַמָרָן, דְּאִינּוּן מִתְהַפְּכָאן לְכַמָּה גְּוָונִין. וְהַאי נִיצוֹצָא אִקְרֵי שְׂרָפִים, וְהַאי אָחִיד בְּהוֹן, וְלָהִיט לוֹן.</p>\n<p>בְּהֵיכָלָא דָּא אִית תְּרֵין מְמָנָן, נְהוֹרִין דְּקַיְימִין עַל אֶלֶף וְרִבּוֹא רִבְּבָן דְּאִקְרוּן גְּפָנִים, וְאֶלֶף וְרִבּוֹא רִבְּבָן דְּאִקְרוּן רִמּוֹנִים, וְכֻלְּהוּ קַיְימִין בַּחֲבִיבוּתָא, וְאִלֵּין אִינּוּן דְּאַעֲלֵי רְחִימוּתָא בֵּין יִשְׂרָאֵל לְתַתָּא, וְקוּדְשָׁא בְּרִיךְ הוּא לְעֵילָּא. וְכֻלְּהוּ מִתְעָרֵי רְחִימוּתָא, וְקַיְימָן בִּרְחִימוּ. וְכַד אַתְעַר רְחִימוּ מִתַּתָּא לְעֵילָּא, וּמֵעֵילָּא לְתַתָּא, כְּדֵין אִתְמַלְיָא הֵיכָלָא, דָּא, מִכַּמָּה טָבִין, מִכַּמָּה חֲסָדִין, מִכַּמָּה רַחֲמִין וּכְדֵין רְחִימוּ דִּלְתַתָּא, גּוֹ רְחִימוּ עִלָּאָה, אִתְדַּבָּק דָּא בְּדָא.</p>\n<p>מֵהָכָא נַפְקֵי תְּרֵין מְמָנָן, וְאִקְרוּן אַהֲבָה, עַל שְׁמָא דְּהֵיכָלָא. וְאִלֵּין קַיְימִין לְאַשְׁגָּחָא עַל כָּל אִינּוּן דִּמְיַחְדֵּי יִחוּדָא דְּמָארֵיהוֹן בִּרְחִימוּ, וּמַסְרֵי נַפְשַׁיְיהוּ עָלֵיהּ בִּרְחִימוּ, וְסַלְקֵי וְאַסְהִידוּ לְעֵילָּא וְכָל אִינּוּן דְּעַבְדֵּי חֶסֶד בְּעָלְמָא, אִינּוּן חֲסָדִין סַלְּקִין וְעָאלִין גּוֹ הַאי הֵיכָלָא, וּמִתְעַטְּרֵי תַּמָּן, וְסַלְקֵי לְאִתְעַטְּרָא גּוֹ אַהֲבָה עִלָּאָה. וְעַל דָּא כְּתִיב, (תהילים ק״ח:ה׳) כִּי גָּדוֹל מֵעַל שָׁמַיִם חַסְדֶּךָ. בְּהֵיכָלָא דָּא כְּתִיב, (שיר השירים ח׳:ז׳) מַיִם רַבִּים לֹא יוּכְלוּ לְכַבּוֹת אֶת הָאַהֲבָה וּנְהָרוֹת לא יִשְׁטְפוּהָ וגוֹ'.</p>"],[9520011926,"<p><Noneb>היכל הרצון תפאר\"ת</b> הֵיכָלָא שְׁתִיתָאָה. דָּא הוּא הֵיכָלָא דְּאִקְרֵי הֵיכָלָא דְּרָצוֹן, דְּאִיהוּ רַעֲוָא, דְּאִקְרֵי (דברים ח׳:ג׳) מוֹצָא פִי יְיָ', חֶדְוָה דְּאִתְדַּבְּקוּתָא דְּכֹלָּא. וְהָכָא אִיהוּ רַעֲוָא דְּרַעֲוִין, בְּרָזָא דִּכְתִיב, (שיר השירים ד׳:ג׳) כְּחוּט הַשָּׁנִי שִׂפְתוֹתַיִךְ. רַעֲוָא דְּכָל נִשְׁמָתִין, דְּנַפְקֵי מֵהַהוּא מוֹצָא פִי יְיָ'.</p>\n<p>הַאי הֵיכָלָא, הֵיכָלָא דְּרַעֲוָא. דְּקַיְימָן הָכָא כָּל שְׁאֶלְתִין, וְכָל בָּעוּתִין דְּעָלְמָא. בְּגִין דְּרַעֲוָא דְּכָל רַעֲוִין, כַּד נְשִׁיקִין אִשְׁתְּכָחוּ, בְּרָזָא דִּכְתִּיב, (בראשית כ״ט:י״א) ויִּשַּׁק יַעֲקֹב לְרָחֵל. וּכְדֵין כַּד נָשִׁיק דָּא לְדָא, כְּדֵין אִקְרֵי עֵת רָצוֹן. בְּגִין דְּהָא כְּדֵין שְׁלִימוּ אִשְׁתְּכַח, וְכָל אַנְפִין נְהִירִין. וְכַד צְלוֹתִין סַלְּקִין, כְּדֵין אִיהוּ עֵת רָצוֹן לְאִשְׁתַּכְחָא, וְעַל דָּא כְּתִיב (תהילים ס״ט:י״ד) וַאֲנִי תְפִלָּתִי לְךָ יְיָ' עֵת רָצוֹן. דְּאִיהוּ חִבּוּרָא דָּא עִם דָּא.</p>\n<p>בְּהֵיכָלָא דָּא קַיְימָן שִׁית פִּתְחִין, ד' פִּתְחִין לְד' סִטְרִין דְּעָלְמָא, וְחַד לְעֵילָּא, וְחַד לְתַתָּא. בְּאִלֵּין פִּתְחִין אִתְמָנָא חַד רוּחָא, דְּאִיהוּ רַב עַל כֻּלְּהוּ דִּי מְמָנָן בְּכָל אִלֵּין פִּתְחִין, וְרָזִיאֵ\"ל שְׁמֵיהּ. וְהַאי אִתְמָנָא וְאִתְפְּקַד בְּכָל אִינּוּן רָזִין עִלָּאִין, דְּפוּמָא לְפוּמָא מְמַלְלָן, דְּנַשְׁקִין דָּא דְּלָא בִּרְחִימוּ דִּרְחִימוּתָא.</p>\n<p>רָזִין אִלֵּין לָא קַיְימָן לְגַלָּאָה, אֲבָל כַּד תַּרְעִין אִתְפְּתָחוּ, כְּדֵין יַדְעִין כֻּלְּהוּ הֵיכָלִין, וְכָל אִינּוּן רוּחִין, וְכָל אִינּוּן מַשִּׁרְיָין, דְּהָא תַּרְעֵי דְּרָצוֹן אִתְפְּתָחוּ. וְלָא עָאלִין בְּאִלֵּין תַּרְעִין, אֶלָּא רַעֲוֵי דִּצְלוֹתִין, רַעֲוֵי דִּשְׁבָחָא, רַעֲוֵי דְּנִשְׁמָתִין קַדִישִׁין עִלָּאִין.</p>\n<p>הַאי אִיהוּ הֵיכָלָא דְּמֹשֶׁה, בְּהַאי הֵיכָלָא אִתְכְּנִישׁ מֹשֶׁה בִּרְחִימוּ, וְנָשִׁיק נְשִׁיקִין. בְּהַאי הֵיכָלָא, (שמות י״ט:י״ט) מֹשֶׁה יְדַבֵּר וְהָאֱלֹהִים יַעֲנְנּוּ בְקוֹל.</p>\n<p>כַּד אִתְדָּבָּקוּ נְשִׁיקִין בִּנְשִׁיקִין, <Nonei></i>דָּא עִם דָּא, וְעַל דָּא כְּתִיב, (שיר השירים א׳:ב׳) יִשָּׁקֵנִי מִנְּשִׁיקוֹת פִּיהוּ וְגוֹ'. לֵית נְשִׁיקִין דְּחֶדְוָה וּרְחִימוּתָא אֶלָּא כַּד מִתְדַּבְּקָן דָּא בְּדָא, פּוּמָא בְּפוּמָא, רוּחָא בְּרוּחָא, דִּכְדֵין רָוָואן דָּא עִם דָּא, בְּתַפְנוּקִין דְּכֹלָּא, וּבְחֶדְוָה, מִנְּהִירוּ עִלָּאָה.</p>\n<p>תָּא חֲזֵי, מֹשֶׁה יְדַבֵּר, דִּכְתִּיב, (שיר השירים א׳:ט״ו) הִנָּךְ יָפָה רַעְיָתִי, וּכְתִיב (שיר השירים ד׳:ג׳) כְּחוּט הַשָּׁנִי שִׂפְתוֹתַיִךְ. וְהָאֱלֹהִים יַעֲנֶנּוּ בְקוֹל, דִּכְתִּיב, (שיר השירים א׳:ט״ז) הִנְּךָ יָפֶה דּוֹדִי אַף נָעִים, וּכְתִיב (שיר השירים ה׳:י״ג) שִׂפְתוֹתָיו שׁוֹשַׁנִּים נוֹטְפוֹת מוֹר עוֹבֵר.</p>\n<p>הַאי רוּחָא, אִתְמְסָרוּ בִּידֵיהּ, כָּל רָזִין דְּאִינּוּן נִשְׁמָתִין עִלָּאִין, דְּמִתְעָרֵי תִּיאוּבְתָא דִּרְחִימוּ דִּלְעֵילָּא וְתַתָּא כַּחֲדָא. אִינּוּן נִשְׁמָתִין עִלָּאִין, כְּגוֹן רִבִּי עֲקִיבָא וְחַבְרוֹי, דְּאִלֵּין לָא אִתְקְרִיבוּ לְאִסְתַּחֲאָה בִּנְהַר דִּינוּר, כְּמָה דִּשְׁאַר נִשְׁמָתִין אִסְתַּחְיָין תַּמָּן וְעָבְרוּ בֵּיהּ, וְהָא אוֹקִימְנָא.</p>\n<p>(תא חזי), רוּחָא דָּא, אַפִיק תְּרֵיסָר נְהוֹרִין, וְכֻלְּהוּ קַיְימֵי בְּרָזָא דִּתְחוֹת הַאי רוּחָא. בְּאַרְבַּע סִטְרִין דְּעָלְמָא, קַיְימִין ד' נְהוֹרִין עִלָּאִין, דְּשַׁלְטִין לְאַרְבַּע סִטְרִין. בְּסִטְרָא דְּדָרוֹם, קַיְּימָא חַד נְהוֹרָא עִלָּאָה יְמִינָא דְּכָל עָלְמָא, דְּהָא מִנֵּיהּ שָׁרָאן יִשְׂרָאֵל לְאִתְאַחֲדָא בְּרָזָא דִּמְהֵימְנוּתָא, וְאִיהוּ מִיכָאֵל, רַב חֵילָא דִּנְהוֹרָא עִלָּאָה, דְּנַחְתָא מִסִּטְרָא דְּדָרוֹם, דְּתַמָּן נְהוֹרָא קַיְּימָא בְּתוּקְפֵּיהּ.</p>\n<p>הַאי מִיכָאֵל, נְהוֹרָא יְמִינָא, אַפָטְרוֹפוֹסָא רַבָּא דְּיִשְׂרָאֵל. בְּגִין, דְּכַד סִטְרָא אַחֲרָא קַיְּימָא לְאַסְטָאָה עָלַיְיהוּ דְּיִשְׂרָאֵל, כְּדֵין מִיכָאֵל טָעַן עִמֵּיהּ, וְאִתְעָבִיד סַנֵּיגוֹרְיָא עָלַיְיהוּ דְּיִשְׂרָאֵל, וְאִשְׁתְּזִבָן מֵהַהוּא קַטֵיגוֹרְיָא דְּמָארֵי בַּעֲלֵי דְּבָבוּ דְּיִשְׂרָאֵל.</p>\n<p>בַּר בְּזִמְנָא דְּאִיחְרַב יְרוּשָׁלַם, דְּהָא כְּדֵין אִתְגַבָּרוּ חוֹבִין וּמִיכָאֵל לָא יָכִיל בַּהֲדֵיהּ דְּסִטְרָא אַחֲרָא, דְּטַעֲנָתֵיהּ דְּמִיכָאֵל תְּבִירָא עָלַיְיהוּ דְּיִשְׂרָאֵל, וּכְדֵין (איכה ב׳:ג׳) הֵשִׁיב אָחוֹר יְמִינוֹ מִפְּנֵי אוֹיֵב.</p>\n<p>בְּסִטְרָא דְּצָפוֹן, קַיְּימָא נְהוֹרָא אַחֲרָא, דְּהָא אִיהוּ קַיְּימָא (ס\"א לנטלא) לְבַטְּלָא דִּינָא מִבֵּי הֵיכָלָא רְבִיעָאָה. וְיָהַב לַמְמָנָא דְּפִתְחָא דִּבְהַהוּא פִּתְחָא קַיְּימָא מְמָנָן אַחֲרָן דְּאִינּוּן דְּבִסְטַר מְסַאֲבָא, מְחַכָּאן לְהַהוּא מְמָנָא וְנַטְלֵי דִּינָא. וּלְזִמְנִין דְּהַאי נְהוֹרָא דְּבְסִטְרָא דְּצָפוֹן, אִיהוּ עָבִיד דִּינָא, וְלָא יִתְמְסָר בִּידָא דְּסִטְרָא אַחֲרָא. בְּגִין דְּכָל דִּינִין דְּאִתְעָבֵידוּ בֵּיהּ, אִית לוֹן אַסְוָותָא. וְקוּדְשָׁא בְּרִיךְ הוּא עָבִיד חֶסֶד בְּאִינּוּן אַתְרֵי.</p>\n<p>גַּבְרִיאֵ\"ל אִיהוּ הַאי נְהוֹרָא דִּבְסִטְרָא דְּצָפוֹן, וּבְכָל אֲתָר דְּאִיהוּ מָחֵי, שָׁרֵי בֵּיהּ חֶסֶד. בְּגִין דְּגַבְרִיאֵ\"ל בִּתְרֵין סִטְרִין, כָּלִיל בְּתַרְוַויְיהוּ, וְעַל דָּא, מַחְיָא וְאַסְוָותָא בֵּיהּ. בְּסִטְרָא דָּא קַיְּימָא רָזָא דִּכְתִּיב, (דברים ח׳:ה׳) כִּי כַּאֲשֶׁר יְיַסֵּר אִישׁ אֶת בְּנוֹ יְיָ' אֱלֹהֶיךָ מְיַסְּרֶךָּ. וְאִלֵּין יִסּוּרִין דִּרְחִימוּתָא, דִּכְלִילָן בְּסִטְרָא דָּא וּבְסִטְרָא דָּא.</p>\n<p>בְּסִטְרָא דְּמִזְרָח, קַיְּימָא נְהוֹרָא אַחֲרָא, דְּאִיהוּ קַיְּימָא בְּכָל מִלֵּי דְּאַסְוָותָא, לְמֵיעַל קַמֵּי מָארֵיהּ, כָּל אִינּוּן דְּאִתְנַשְׁיָין בְּבֵי מַרְעַיְיהוּ, וּלְקָרְבָא זִמְנִין וְקִצִין לְאִינּוּן מַרְעִין דְּאִשְׁתְּלִימוּ מְהֵימְנוּתַיְיהוּ. וְאַסְחַר עָלְמָא בְּכָל יוֹמָא וְיוֹמָא, בְּגִין לְאַשְׁלְמָא אַסְוָותָא בְּפִקּוּדָא דְּמָארִיהּ, וְהַאי (איהו) נְהוֹרָא רְפָאֵ\"ל שְׁמֵיהּ. וְאַף עַל גַּב דְּהָא אוֹקִימְנָא לֵיהּ לְסִטְרָא אַחֲרָא. וְדָא אָחִיד לְסִטְרָא דָּא, וּלְסִטְרָא דָּא, לְסִטְרָא דְּמִיכָאֵל, וּלְסִטְרָא דְּגַבְרִיאֵל.</p>\n<p>וְהַאי אִיהוּ מְמָנָא, בְּשַׁעֲתָא דְּאִתְדָּן בַּר נָשׁ בְּהֵיכָלָא רְבִיעָאָה לַחַיִּים, כְּדֵין אִיהוּ אַקְדִים בְּאַסְוָותָא. וְהַאי אַסְוָותָא מִגּוֹ דְּחִיקוּ נָפְקָא, בְּגִין דְּמִתְּרֵין סִטְרִין נָפְקָא, וְהַאי דְּחִיקוּ אַתְיָא מִגּוֹ סְטָר שְׂמָאלָא, וְאַסְוָותָא מִגּוֹ סְטָר יְמִינָא. וְעַל דָּא, הַהוּא מְרַע כַּד אַתְיָא לֵיהּ אַסְוָותָא, מִגּוֹ דְּחִיקוּ סַגִּיא אַתְיָא לֵיהּ.</p>\n<p>וְהָכִי הוּא מִסִּטְרָא דְּמַעֲרָב, וְאַף עַל גַּב דְּאַמָרָן דִּרְפָאֵל בִּסְטָר מִזְרָח, וְאוּקְמוּהָ בִּסְטָר דָּא דְּמַעֲרָב, אַסְוָותָא וְחַיִּין לָאו אִיהוּ אֶלָּא מִסְּטָר מִזְרָח, דְּהָא (רמ\"ו ע\"ב) מִתַמָּן אִתְמַשְּׁכָאן חַיִּין לְתַתָא.</p>\n<p>(ובהאי סטרא דמערב), נְהוֹרָא חַד וְנוּרִיאֵ\"ל שְׁמֵיהּ, וְאִיהוּ אוּרִיאֵ\"ל. וְדָא אִיהוּ כָּלִיל מִכֻּלְּהוּ, וְקַיְּימָא שְׁלִיחָא בְּכֹלָּא. וְאִית לֵיהּ ג' סִטְרִין, אֲבָל תְּרֵין אִינּוּן, בְּגִין דְּכָל חַד מֵאִלֵּין כָּלִיל בְּחַבְרֵיהּ, <Nonei></i>דְּאִינּוּן אַרְבַּע יְסוֹדִין תַּתָּאִין, מֵאִינּוּן אַרְבַּע יְסוֹדֵי עָלְמָא, עִלָּאִין עַל כֹּלָּא. וּבְגִין דְּכֻלְּהוּ מִתְקַשְּׁרָן דָּא בְּדָא, רָמַז קְרָא וְאָמַר, (שיר השירים ו׳:י״א) אֶל גִּנַּת אֱגוֹז יָרַדְתִּי לִרְאוֹת.</p>\n<p>אִינּוּן תְּרֵיסָר נְהוֹרִין, קַיְימִין בְּהַהוּא רוּחָא דְּקַאמְרָן, וְהַהוּא רוּחָא עָלַיְיהוּ בִּשְׁלִימוּ, אִלֵּין אַרְבַּע נְהוֹרִין עִלָּאִין, אִית תְּחוֹתַיְיהוּ תְּמַנְיָא אַחֲרָנִין, לְמֶהֱוֵי בִּשְׁלִימוּ, וּבְכֻלְּהוּ שְׁלִימוּ חַד (ירדתי לראות אלין ארבע נהורין עלאין אית תחותייהו תמניא אחרנין ואינון תריסר נהורין דקימין תחות ההוא רוחא דקאמרן וההוא רוחא עלייהו בשלימו למהוי בכלהו שלימו חד), וְכַד מִתְפָּרְשִׁין כֻּלְּהוּ, אִינּוּן תְּלַת לְכָל סְטָר.</p>\n<p>אִלֵּין אַרְבַּע סַמְכִין, קַיְימִין לְסַלְּקָא וּלְאִתְאַחֲדָא הַאי הֵיכָלָא לְעֵילָּא, בַּאֲתָר דְּאִקְרֵי שָׁמַיִם, לְאִתְחַבְּרָא נְשִׁיקִין אִלֵּין בְּאִלֵּין כַּחֲדָא. תְּחוֹת אִלֵּין, כַּמָה דַּרְגִּין לְדַרְגִּין, כֻּלְּהוּ נַפְקֵי מִנַּיְיהוּ, מֵאִלֵּין יְסוֹדִין תַּתָּאִין, מִנַּיְיהוּ מִסִּטְרָא דְּמַיָּא, וּמִנַּיְיהוּ מִסִּטְרָא דְּאֶשָּׁא, וּמִנַּיְיהוּ מִסִּטְרָא דְּרוּחָא, וּמִנַּיְיהוּ מִסִּטְרָא דְּעַפְרָא.</p>\n<p>כְּגַוְונָא דָּא תָּנִינָן, אַרְבָּעָה נִכְנְסוּ לַפַּרְדֵס, וְכֻלְּהוּ אִתְבְּרִירוּ לְדוּכְתָּא דָּא, לְאִלֵּין אַרְבַּע יְסוֹדֵי. וְכָל חַד וְחַד אִתְקָשָּׁר בְּדוּכְתֵּיהּ, דָּא בְּסִטְרָא דְּאֶשָּׁא, וְדָא בְּסִטְרָא דְּמַיָּא, וְדָא בְּסִטְרָא דְּרוּחָא, וְדָא בְּסִטְרָא דְּעַפְרָא. וְכֻלְּהוּ אַטְבָּעוּ בִּיסוֹדָא דִּילֵיהּ, כְּמָה דְּאָעֲלוּ. בַּר הַהוּא שְׁלֵימָא חֲסִידָא, דְּאַתְיָא בְּסִטְרָא דִּימִינָא, וְאִתְדָּבַּק בִּימִינָא, וְסָלִיק לְעֵילָּא.</p>\n<p>וְכַד מָטָא לְהַאי אֲתָר דְּאִקְרֵי הֵיכָל אַהֲבָה, אִתְדָּבַּק בֵּיהּ בִּרְעוּ דְּלִבָּא. אָמַר, הַאי הֵיכָלָא, צְרִיכָא אִיהוּ לְדַבְּקָא לֵיהּ, בְּהֵיכָלָא דִּלְעֵילָּא, בְּאַהֲבָה רַבָּה. כְּדֵין אִשְׁתְּלִים בְּרָזָא דִּמְהֵימְנוּתָא, וְאִיהוּ סָלִיק וְאַשְׁלִים אַהֲבָה זוּטָא בְּאַהֲבָה רַבָּא, כַּדְקָא חֲזֵי. וְעַל דָּא מִית בְּאַהֲבָה, וְנָפַק נִשְׁמָתֵיהּ בְּהַאי קְרָא, (דברים ו) וְאָהַבְתָּ. זַכָּאָה חוּלָקֵיהּ.</p>\n<p>כָּל אִינּוּן אַחֲרָנִין, נַחְתוּ לְתַתָא כָּל חַד וְחַד, וְאִתְעֲנָשׁוּ בְּהַהוּא יְסוֹדָא דְּנָחַת לְתַתָא. אֱלִישָׁע נָחַת לְתַתָא בִּסְטָר שְׂמָאלָא, דְּאִיהוּ אֶשָּׁא, וְנָחִית בֵּיהּ וְלָא סָלִיק, וְאִעְרַע בְּהַהוּא סִטְרָא אַחֲרָא, דְּאִקְרֵי אֵל אַחֵר. וְאִתְמְנַע מִנֵּיהּ תְּשׁוּבָה, וְאִתְתָרַךְ בְּגִין דְּאִתְדָּבַּק בֵּיהּ, וְעַל דָּא אִקְרֵי אַחֵר, וְאוֹקִימְנָא.</p>\n<p>בֶּן עֲזָאי, נָחִית בִּיסוֹדָא דְּעַפְרָא, וְעַד לָא מָטָא לְאוֹקִידוּ דְּעַפְרָא, דְּמָטֵי לְהַהוּא סְטָר אַחֲרָא, אַטְבַע בְּהַהוּא עַפְרָא, וּמִית. וְעַל דָּא כְּתִיב, (תהילים קט״ז:ט״ו) יָקָר בְּעֵינֵי יְיָ' הַמָּוְתָה לַחֲסִידָיו.</p>\n<p>בֶּן זוֹמָא, נָחִית בִּיסוֹדָא דְּרוּחָא, וְאִעְרַע בְּרוּחָא אַחֲרָא, דְּמָטָא לִסְטַר מְסַאֲבָא, דְּאִקְרֵי פֶּגַע רַע, וּבְגִין כַּךְ פָּגַע בֵּיהּ, וְלָא אִתְיָישָׁב בֵּיהּ, וְכֻלְּהוּ לָא אִשְׁתֵּזָבָן מֵעוֹנְשָׁא. וְעַל דָּא אָמַר שְׁלמֹה, (קהלת ח׳:י״ד) יֵשׁ הֶבֶל אֲשֶׁר נַעֲשָׂה עַל הָאָרֶץ אֲשֶׁר יֵשׁ צַדִּיקִים שֶׁמַּגִיעַ אֲלֵיהֶם כְּמַעֲשֵׂה הָרְשָׁעִים. בְּגִין דְּאִלֵּין נַחְתוּ בְּדַרְגִּין אִלֵּין, וְאִתְעֲנָשׁוּ.</p>\n<p>תָּא חֲזֵי, בְּגִין דְּרִבִּי עֲקִיבָא סָלִיק לְעֵילָּא כְּדְקָא יֵאוֹת, עָאל בִּשְׁלָם וְנָפַק בִּשְׁלָם. דָּוִד שָׁאִיל שְׁאֶלְתָּא, וְלָא אִתְפְּרַשׁ, דִּכְתִיב (תהילים י״ז:י״ד) מִמְתִים יָדְךָ יְיָ' מִמְתִים מֵחֶלֶד חֶלְקָם בַּחַיִּים. (ס\"א תוהא) עַל מַה דָּא אִלֵּין דְּאִתְקְטָלוּ בְּקָטוּלֵי עָלְמָא צַדִיקַיָּיא, זַכָּאִין דְּלָא חָאבוּ חוֹבָה בְּגִין דְּיִתְעָנְשׁוּן. תָּא חֲזֵי, מִמְתִים יָדְךָ יְיָ', מִמְתִים מֵחֶלֶד חֶלְקָם בַּחַיִּים, הָכָא אִיהוּ תְּרֵי סִטְרֵי, יָדְךָ יְיָ'. וְחֶלֶד. יָדְךָ יְיָ', דָּא קוּדְשָׁא בְּרִיךְ הוּא, דְּנִשְׁמְתָא אִתְכְּנִישׁ לְגַבֵּיהּ. מִמְתִים מֵחֶלֶד, דָּא סִטְרָא אַחֲרָא, דְּגוּפָא אִיהוּ שַׁלְטָא עֲלוֹי, דִּכְתִיב (ישעיהו ל״ח:י״א) לא אַבִּיט אָדָם עוֹד עִם יוֹשְבֵי חָדֶל.</p>\n<p>תָּא חֲזֵי, נִשְׁמְתָא דְּאִלֵּין, לְאַשְׁלָמוּתָא דְּרוּחָא קַדִישָׁא, דִּלְהוֹן עֲשָׂרָה רוּחִין מִתַּתָא כְּדְקָא יֵאוֹת, וְגוּפָא דִּלְהוֹן יִתְמְסָר לְמַלְכוּ חַיָּיבָא. כָּל חַד נָטִיל חוּלָקֵיהּ, בְּרָזָא דְּקָרְבְּנִין.</p>\n<p>וְתָא חֲזֵי, רֵישָׁא שֵׁירוּתָא דִּמְהֵימְנוּתָא, גּוֹ מַחֲשָׁבָה, בָּטַשׁ בּוּצִינָא דְּקַרְדִינוּתָא, וְסָלִיק גּוֹ מַחֲשָׁבָה, (ס\"א ואפיק) נִצוֹצִין, נְצִיצִין זָרִיק (ויקרא רצ\"ב ע\"ב) לִתְלַת מֵאָה וְעֶשְׂרִין עֵיבָר, וּבָרִיר פְּסוֹלֶת מִגּוֹ מַחֲשָׁבָה, וְאִתְבְּרִיר.</p>\n<p>אוּף הָכִי, כְּגַוְונָא דָּא סָלִיק בְּמַחֲשָׁבָה, כְּמָה דְּאִתְבְּרַר בֵּיהּ פְּסוֹלֶת, (ס\"א ויתבריר אוף הכי, אלין בהו אשתלים מאן דאצטריך, ודאי כך סליק במחשבה וכלא) וְיִתְבְּרִיר אִלֵּין, בְּהוּ אִשְׁתְּלִים מַאן דְּאִצְטְרִיךְ, ודָאי כַּד סָלִיק, בְּמַחֲשָׁבָה סָלִיק וְכֹלָּא <Nonei></i>כְּמָה דְּאִצְטְרִיךְ. חִידוּ מִסִּטְרָא דָּא, וַעֲצִיבוּ מִסִּטְרָא דָּא.</p>\n<p>כְּתִיב (קהלת ח׳:ט״ו) וְשִׁבַּחְתִּי אֲנִי אֶת הַשִּׂמְחָה אֲשֶׁר אֵין טוֹב לָאָדָם תַּחַת הַשֶּׁמֶשׁ כִּי אִם לֶאֱכוֹל וְלִשְׁתּוֹת וְלִשְׂמוֹחַ וְהוּא יִלְוֶנּוּ בַּעֲמָלוֹ יְמֵי חַיָיו אֲשֶׁר נָתַן לוֹ הָאֱלהִים תַּחַת הַשָּׁמֶשׁ. וְשִׁבַּחְתִּי אֲנִי אֶת הַשִּׂמְחָה, וְכִי שְׁלמֹה מַלְכָּא מְשַׁבַּח דָּא. אֶלָּא וְשִׁבַּחְתִּי אֲנִי אֶת הַשִּׂמְחָה, דָּא חֶדְוָותָא דְּמַלְכָּא קַדִישָׁא, בְּזִמְנָא דְּאִיהוּ שַׁלְטָא, בְּשַׁבְּתָא וּבְיוֹמִין טָבִין, דְּמִכָּל עוֹבָדִין טָבִין דְּבַּר נָשׁ עָבִיד, אֵין טוֹב לָאָדָם תַּחַת הַשֶּׁמֶשׁ, כִּי אִם לֶאֱכוֹל וְלִשְׁתּוֹת, וּלְאַחְזָאָה חֶדְוָותָא בְּהַהוּא, (נ\"א זמנא) סִטְרָא בְּגִין דִּיְהֵא לֵיהּ חוּלָקָא לְעָלְמָא דְּאָתֵי.</p>\n<p>וְהוּא יִלְוֶנּוּ בַּעֲמָלוֹ. מַאן. דָּא קוּדְשָׁא בְּרִיךְ הוּא, הוּא יִלְוֶנּוּ, וְיֵהַךְ עִמֵּיהּ לְאַעֲלָא לֵיהּ לְעָלְמָא דְּאָתֵי. דָּבָר אַחֵר וְהוּא יִלְוֶנּוּ, מַאן הוּא. הַהוּא בַּר נָשׁ דְּאָכִיל וְשָׁתֵי וְחַדֵי, כָּל מַאי דְּאַפִיק לְמֵיכַל וּלְמִשְׁתֵּי, הוּא יִלְוֶנּוּ לְּקוּדְשָׁא בְּרִיךְ הוּא בְּהַלְוָאָה, וְאִיהוּ יָהִיב לֵיהּ כִּפְלֵי כִּפְלַיִם, מִכָּל מַה דְּאַפִיק בְּהַאי. בִּתְרֵין אִלֵּין, אוֹזִיף בַּר נָשׁ לְּקוּדְשָׁא בְּרִיךְ הוּא, כַּד חַיִּיס לֵיהּ לְמִסְכְּנָא. וְכַד אַפִיק בְּשַׁבָּתֵי וְזִמְנֵי. דְּהָא כֹּלָּא אוֹזִיף לְּקוּדְשָׁא בְּרִיךְ הוּא, כְּמָה דְאַתְּ אָמֵר (משלי י״ט:י״ז) מַלְוֶה יְיָ' חוֹנֵן דָּל וּגְמוּלּוֹ יְשַׁלֶּם לוֹ.</p>\n<p>וּבְגִין כָּךְ, דָּא שִׂמְחָה, וְדָא עֲצִיבוּ. דָּא חַיִּים וְדָא מָוֶת. דָּא טוֹב, וְדָא רָע, דָּא גַּן עֵדֶן, וְדָא גֵּיהִנָּם. וְכֹלָּא, דָּא בְּהִפּוּכָא דְּדָא, וְעַל דָּא גּוּפָא דִּלְהוֹן הֲוָה בַּעֲצִיבוּ, וְנִשְׁמְתָא בְּחֶדְוָה. וְכַד הֲווֹ אִלֵּין עֲשָׂרָה דְּאִקְרוּן הֲרוּגֵי מַלְכוּת, הֲרוּגִים הֲווֹ מִסִּטְרָא אַחֲרָא, וְאַשְׁלִימוּ אֲתָר אַחֲרָא דִּקְדוּשָּׁה. וּבְגִין כָּךְ, כֹּלָּא גַּלֵּי קָמֵי קוּדְשָׁא בְּרִיךְ הוּא, וְאִתְעָבִיד כְּדְקָא יֵאוֹת.</p>\n<p>בְּהֵיכָלָא דָּא קַיְימִין אִינּוּן תְּרֵיסָר. אַרְבַּע אִלֵּין לְעֵילָּא, וּתְמַנְיָא עִמְּהוֹן. בְּגִין דְּכָל חַד, נָטִיל עִמֵּיהּ תְּרִין, כְּמָה דְּאִיהוּ סִדוּרָא (דתרין) דִּדְגָלִים וְכֵן בְּסִדוּרָא דִּלְתַתָּא, עַד סוֹף דְּכָל דַּרְגִין.</p>\n<p>בְּהֵיכָלָא דָּא, עָאלִין כָּל אִינּוּן צְלוֹתִין, וְכָל אִינּוּן רַעֲוִין דִּשְׁבָחִין דְּאִתְעָבֵידוּ בִּרְחִימוּ, וְכַד עָאלִין בְּהַאי הֵיכָלָא, כֻּלְּהוּ מִתְדַּבְּקָן בֵּיהּ. (בקודשא בריך הוא) וּבְכָל יוֹמָא, וּבְכָל זִמְנָא דְּנְשִׁיקִין אִתְחַבָּרוּ, כְּדֵין אִיהוּ זִמְנָא, דְקוּדְשָׁא בְּרִיךְ הוּא אִשְׁתַּעְשַׁע בְּנִשְׁמָתִין דְּצַדִּיקַיָּיא, וּמַהוּ הַשַׁעְשׁוּעַ דְּמִתְעֲרִין אִינּוּן נְשִׁיקִין, וְאִינּוּן אַקְדִּימוּ לְהַהוּא עִנּוּגָא, וְעַל דָּא כְּתִיב (ישעיהו נ״ח:י״ד) אָז תִּתְעַנַּג עַל יְיָ', וְאוֹקִימְנָא.</p>\n<p>הֵיכָלָא דָּא, כְּלָלָא דְּכָל אִינּוּן הֵיכָלִין תַּתָּאִין, כֻּלְּהוּ כְּלִילָן בְּהַאי הֵיכָלָא. הֵיכָלָא קַדְמָאָה, דְּתַמָּן קַיְּימָא הַהוּא רוּחָא דְּקַאמְרָן, וְכָל אִינּוּן חֵיוָון דְּבֵיהּ, אִסְתְּמִיךְ בִּתְרֵין סַמְכִין לִסְטַר מִזְרָח, וּבִתְרֵין סַמְכִין לִסְטַר דָּרוֹם, וּבִתְרֵין סַמְכִין לִסְטַר מַעֲרָב, וּבִתְרֵין סַמְכִין לִסְטַר צָפוֹן, וְאִינּוּן תְּמַנְיָא. וְאִלֵּין אִקְרוּן יְתֵדוֹת הַמִּשְׁכָּן, וְקַיְימֵי לְבַר.</p>\n<p>כַּד מַלְכָּא עִלָּאָה אָתֵי, נַטְלֵי אִינּוּן יְתֵדוֹת, וְאִתְעַקְרָן מֵאַתְרַיְיהוּ אִינּוּן מֵיתָרִים, דְּאִינּוּן תְּמַנְיָא אַחֲרָנִין, בַּר מֵאִינּוּן יְתֵדוֹת דְּקָא אַמָרָן. וְהַהוּא רוּחָא קַדְמָאָה דִּי בְּגוֹ הֵיכָלָא דָּא, קָדִים וְעָאל, וְאִתְכְּלִיל בְּגוֹ הַהוּא (ס\"א תניינא ברוחא אחרא דביה) רוּחָא תִּנְיָינָא דְּבֵיהּ.</p>\n<p>אִינּוּן תְּרֵין סַמְכִין דְּלִסְטַר מִזְרָח, אִינּוּן קַרְעִיאֵ\"ל, דְּאִתְמַנָא לְבַר עַל תְּרֵיסָר אַלְפֵי מְמָנָן, דְּכֻלְּהוּ אִקְרוּן יְתֵדוֹת הַמִּשְׁכָּן, דָּא לִימִינָא. לִשְׂמָאלָא שַׁמְעִיאֵ\"ל, וְאִתְמָנָא עַל תְּרֵיסָר אַלְפֵי מְמָנָן אַחֲרָנִין, וְכֻלְּהוּ יְתֵדוֹת כִּדְקַאמְרָן. (אינון ממנן אחרנין) סַמְכִין דְּאִתְמָנוּן לִסְטַר דָּרוֹם, חַד סַעֲדִיאֵ\"ל, וְחַד סְטָרִיאֵ\"ל, (נ\"א סעריהא\"ל) כָּל חַד וְחַד, עַל תְּרֵיסָר אַלְפֵי מְמָנָן אַחֲרָנִין. אִלֵּין לָא אִתְעֲדוּן מִשׁוּלְטָנֵהוֹן לְעָלְמִין.</p>\n<p>אִלֵּין כֻּלְּהוּ, מְמָנָן עַל קִיוּמָא דְּעָלְמָא, אִלֵּין (מאינון דקיימן בקיומא דאינון דאתנסיבו דשקלי (קט\"ו ע\"ב) במתקלא דוכרין ונוקבין דא עם דא) (ס\"א אינון דתקלי במתקלא דכורין ונוקבין, לאתנסבא דא עם דא). וְאִלֵּין אִקְרוּן מֹאזְנַיִם, עַל דָּא כְּתִיב, (תהילים ס״ב:י׳) בְּמֹאזְנַיִם לַעֲלוֹת, וְלָא אִינּוּן דִּכְתִּיב בְּהוּ (רנ\"ב ע\"א) (ויקרא י״ט:ל״ו) מֹאזְנֵי צֶדֶק, דְּקַאמְרָן. כָּל אִינּוּן דִּשְׁקִילִין דָּא עִם דָּא, וְלָא שָׁקִיל דָּא יַתִיר מִן דָּא, סַלְּקִין וְאִתְחַבְּרָן כַּחֲדָא, וְאִינּוּן חִבּוּרָא <Nonei></i>דִּדְכַר וְנוּקְבָּא כַּחֲדָא, וְעַל דָּא בְּמֹאזְנַיִם לַעֲלוֹת. וְאַף עַל גַּב דִּלְזִמְנִין מִסְתַּיְּיעָא מִלְּתָא, וְשָׁקִיל דָּא יַתִיר מִן דָּא, סַלְּקִין וּמִתְחַבְּרָן כַּחֲדָא, וְהָא אוֹקִימְנָא.</p>\n<p>אִינּוּן תְּרֵין סַמְכִין דְּלִסְטַר צָפוֹן, פַּתְחִיאֵ\"ל, עֲטָרִיאֵ\"ל. וּמְמָנָן כָּל חַד וְחַד, עַל תְּרֵיסָר אַלְפִין מְמָנָן אַחֲרָנִין, וְאִינּוּן יְתֵדוֹת הַמִּשְׁכָן, וּבְאִלֵּין אַחֲרָנִין דְּקַאמְרָן. אִינּוּן מְמָנָן תְּרֵין סַמְכִין אַחֲרָנִין דְּלִסְטַר מַעֲרָב, אִינּוּן פְּדָתִיאֵ\"ל תּוֹמִיהָאֵ\"ל, וְאִתְמְנוּן כָּל חַד עַל תְּרֵיסָר אַלְפֵי מְמָנָן אַחֲרָנִין, וְכֻלְּהוּ יְתֵדוֹת הַמִּשְׁכָּן כִּדְקַאמְרָן.</p>\n<p>אִלֵּין אִינּוּן דְּאוֹשְׁדֵי דִּמְעִין, עַל כָּל אִינּוּן דִּמְתָרְכֵי נְשֵׁיהוֹן קָמַיְיתָא. בְּגִין דְּאִינּוּן שֶׁבַע בִּרְכָאן דְּאִתְמְסָרוּ לָהּ, אִתְעֲדָן, וְלָא אִתְקְיָּימוּ, בְּגִין דְּאִתְתָּרָכָא, וְלָא אִתְדְּבָקוּ בַּעְלָהּ וְאִתְּתָא כַּחֲדָא. וְעַל דָּא כֻּלְּהוּ אוֹשְׁדֵי דִּמְעִין, דְּאַחְזֵי תִּירוּכִין, דְּאִינּוּן שֶׁבַע בִּרְכָאן כְּמָה דְּאִתְעֲדָּן מֵאֲתָר אַחֲרָא. כְּדֵין בְּהַהִיא שַׁעֲתָא קָלָא נָפַק וְאָמַר, (ישעיהו נ׳:א׳) אֵי זֶה סֵפֶר כְּרִיתוּת אִמְּכֶם אֲשֶׁר שִׁלַּחְתִּיהָ.</p>\n<p>הֵיכָלָא תִּנְיָינָא, דְּקָא אַמָרָן דְּכָלִיל לְהֵיכָלָא קַדְמָאָה, לְאִתְיַיחֲדָא בֵּיהּ. וְכָל אִינּוּן חֵיוָון, הָכִי נָמֵי אִית לֵיהּ תְּמַנְיָא סַמְכִין כְּקַדְמָאֵי. וְכוּלְהוּ מְמָנָן, כָּל חַד וְחַד, עַל תְּרֵיסָר אַלְפֵי מְמָנָן אַחֲרָנִין, כְּאִלֵּין קַדְמָאֵי כִּדְקַאמְרָן. תְּרֵין סַמְכִין אִינּוּן לִסְטַר מִזְרָח, תְּרֵין סַמְכִין לִסְטַר דָּרוֹם, וּתְרֵין סַמְכִין לִסְטַר צָפוֹן, וּתְרֵין סַמְכִין לִסְטַר מַעֲרָב.</p>\n<p>אִלֵּין תְּרֵין סַמְכִין דְּלִסְטַר מִזְרָח, יְהָדָנִיאֵ\"ל, גְּזוּרִיָּ\"ה. תְּרֵיסָר אַלְפֵי מְמָנָן דְּכָל חַד, וְכֻלְּהוּ יְתֵדוֹת. אִינּוּן תְּרֵין סַמְכִין דְּלִסְטַר דָּרוֹם, אָהֲרִיאֵ\"ל, בָּרְהִיאֵ\"ל. כָּל חַד וְחַד, אִינּוּן עַל תְּרֵיסָר אַלְפִין כְּקַדְמָאֵי.</p>\n<p>אִלֵּין מְמָנָן עַל מַשְׁבֵּר, וְנַטְלֵי אִינּוּן קַלֵי דְּנָשִׁין, וּמַנְחָן לוֹן קָמֵי הַהוּא הֵיכָלָא. וְכַד הַהוּא סִטְרָא אַחֲרָא אָתֵי לְקַטְרְגָא בְּהַאי שַׁעֲתָא, דְּאִיהוּ שַׁעֲתָא דְּסַכָּנָה, קַיְימֵי אִלֵּין, וְעָאלִין הָנֵי קָלֵי לַמְמָנָא דְּעַל פִּתְחָא, וְלָא יָכִיל הַהוּא סִטְרָא אַחֲרָא לְקַטְרְגָא. וּלְזִמְנִין דְּקָדִים הַהוּא סְטָר אַחֲרָא וְעָאל וְקַטְרִיג, וְיָכִיל לְנַזְקָאָה.</p>\n<p>אִלֵּין תְּרֵין סַמְכִין דְּלִסְטַר צָפוֹן, חַלְחָלִיאֵ\"ל (ס\"א סלסליא\"ל), קַרְסָפִיהָאֵ\"ל, אִינּוּן מְמָנָן כָּל חַד עַל תְּרֵיסָר אַלְפִין אַחֲרָנִין. דְּלִסְטַר מַעֲרָב אִינּוּן, סוּגַדְיָ\"ה (ס\"א סוגרי\"א). גְּדַרְיָ\"ה. וְאִלֵּין עַל תְּרֵיסָר אַלְפֵי אַחֲרָנִין.</p>\n<p>וְאִלֵּין מְמָנָן עַל הַהוּא דָּמָא דִּבְרִית, כַּד אִתְגְזַר הַהוּא וַלְדָא לִתְמַנְיָּא יוֹמִין וְאִלֵּין נַטְלֵי הַהוּא דָּמָא, וּמַנְחָן לֵיהּ קָמֵי הַאי הֵיכָלָא. וְכַד רוּגְזָא אַתְעַר בְּעָלְמָא, אַשְׁגַח קוּדְשָׁא בְּרִיךְ הוּא עַל הַהוּא דָּמָא, וְלָא אִתְיְיהִיב לְהַהוּא סִטְרָא אַחֲרָא רְשׁוּ לְאַעַלָא תַּמָּן.</p>\n<p>תָּא חֲזֵי, בְּזִמְנָא דְּאִתְגְּזַר הַהוּא בַּר נָשׁ לִתְמַנְיָּא יוֹמִין, וְשָׁרַאת עָלֵיהּ שַׁבָּת, מַלְכוּת קַדִישָׁא, הַהִיא עָרְלָה דְּגַזְרִין וְשָׁדָאן לֵיהּ לְבַר, כְּדֵין קַיְּימָא הַהוּא סִטְרָא אַחֲרָא, וְחָמָא דְּהַאי אִיהוּ חוּלָקֵיהּ מִקָּרְבְּנָא דָּא, כְּדֵין אִתְבַּר, וְלָא יָכִיל לְשַׁלְּטָאָה וּלְקַטְרֵגָא עֲלוֹי, וְסָלִיק וְאִתְעֲבָד סַנֵּיגוֹרְיָא עַל יִשְׂרָאֵל, קָמֵי קוּדְשָׁא בְּרִיךְ הוּא.</p>\n<p>הֵיכָלָא תְּלִיתָאָה. הֵיכָלָא דָּא דְּקַיְּימָא לְאַכְלְלָא, וּלְיַחֲדָא בֵּיהּ הַהוּא הֵיכָלָא תִּנְיָינָא, וְהַהוּא רוּחָא, וְכָל אִינּוּן חֵיוָון דְּבֵיהּ, כֻּלְּהוּ כְּלִילָן וְאִתְיַיחֲדָן דָּא בְּדָא. וְאִינּוּן חַד רוּחָא דְּכָלִיל דָּא בְּדָא, הָכִי נָמֵי אִית לֵיהּ תְּמַנְיָא סַמְכִין, לְאַרְבַּע סִטְרִין דְּעָלְמָא, וְכֻלְּהוּ אִקְרוּן יְתֵדוֹת הַמִּשְׁכָּן. תְּרֵין סַמְכִין דְּלִסְטַר דָּרוֹם, אִינּוּן שַׁכְנִיאֵ\"ל, עֲזוּזְיָ\"ה. (ס\"א ואינון ממנן על תריסר אלפי ממנן אחרנין כל חד כאינון אחרנין) תְּרֵין סַמְכִין דְּלִסְטַר מִזְרָח, יְהוֹדִיָ\"ה עַזְרִיאֵ\"ל. וְאִלֵּין קַיְימֵי כָּל חַד וְחַד, עַל י\"ב אַלְפֵי מְמָנָן אַחֲרָנִין, וְכֻלְּהוּ אִקְרוּן יְתֵדוֹת הַמִּשְׁכָּן.</p>\n<p>וְאִלֵּין אִתְמָנוּן עַל הַהוּא הֲבָל דְּתִינוֹקוֹת דְּלָעָאן בְּאוֹרַיְיתָא, לְקַיְּימָא עָלְמָא. וְאִלֵּין נַטְלֵי הַהוּא הֲבָל, וְסַלְקֵי לֵיהּ לְעֵילָּא. וְכָל הֲבָל וַהֲבָל דְּאִינּוּן תִּינוֹקוֹת דְּלָעָאן בְּאוֹרַיְיתָא לְקַיְּימָא עָלְמָא, אִתְעָבִיד מִנֵּיהּ רוּחָא חֲדָא, וְסַלְּקָא הַהוּא רוּחָא לְעֵילָּא, וְאִתְעַטָּר בְּעַטָרָא קַדִישָׁא, וְאִתְמָנָא נְטוּרָא דְּעָלְמָא, וְכֵן כֻּלְּהוּ.</p>\n<p>תְּרֵין סַמְכִין דְּאִינּוּן לִסְטַר צָפוֹן, עַזְפִּיאֵ\"ל (ס\"א קטצירהא\"ל), קְטָטָרִיהָאֵ\"ל. וְאִינּוּן מְמָנָן <Nonei></i>עַל תְּרֵיסָר אַלְפֵי מְמָנָן אַחֲרָנִין כָּל חַד וְחַד כִּדְקַאמְרָן. תְּרֵין סַמְכִין דְּלִסְטַר מַעֲרָב, אִינּוּן עֲסִסְנִיָּ\"הּ, אַדִירִירִיָּ\"ה (נ\"א אדירי\"ה). וְאִלֵּין מְמָנָן עַל תְּרֵיסָר אַלְפִין מְמָנָן אַחֲרָנִין, כָּל חַד וְחַד כִּדְקַאמְרָן.</p>\n<p>אִלֵּין אִתְמָנוּן לְאַכְרְזָא בְּכָל רְקִיעִין, לְכָל אִינּוּן דִּמְעַבְרִין בְּנַיְיהוּ מֵאוֹרַיְיתָא, וְסַלְּקִין לוֹן דְּלָא יִלְעוּן בָּהּ, כְּדֵין נַפְקֵי כָּל הָנֵי מְמָנָן וּמַכְרִזֵי וְאַמְרֵי, וַוי לִפְלָנַיָא דְּאַעְבָּר בְּרֵיהּ מֵאוֹרַיְיתָא, וַוי לֵיהּ דְּקָא אִתְאַבִיד מֵעָלְמָא דֵּין, וּמֵעָלְמָא דְּאָתֵי.</p>\n<p>הֵיכָלָא רְבִיעָאָה. הֵיכָלָא דָּא הֵיכָלָא דְּקַיְּימָא בִּנְהִירוּ יַתִיר. הֵיכָלָא דָּא, סָחֲרִין לֵיהּ תְּלָתִין וּתְרֵין יְתֵדוֹת עִלָּאִין, וְחָמֵשׁ מֵאָה אֶלֶף אַחֲרָנִין דִּמְמָנָן תְּחוֹת אִלֵּין. וְאַרְבַּע אַחֲרָנִין, עִלָּאִין עַל כֻּלְּהוּ, וְכֻלְּהוּ יְתֵדוֹת דְּהֵיכָלָא דָּא. אִלֵּין אַרְבַּע אִינּוּן: חַסְדִיהָאֵ\"ל. קָסִירִיָּ\"הּ (נ\"א קסדי\"ה). קְדוּמְיָּ\"הּ. דַּהֲרִיאֵ\"ל. אִלֵּין אַרְבַּע מְמָנָן עַל כֻּלְּהוּ, וְכֻלְּהוּ אַחֲרָנִין, כֻּלְּהוּ מְמָנָן תְּחוֹתַיְיהוּ.</p>\n<p>וְעַל יְדָא דְּאִלֵּין, אִתְיְדַע דִּינָא לְמֶעְבַּד בְּעָלְמָא, וְעַל אִלֵּין כְּתִיב (דניאל ד׳:י״ד) וּמֵאַמַר קַדִּישִׁין שְׁאֵלְתָּא. לְהָנִי אַרְבַּע, אַתְיָין כָּל אִינּוּן חַיָּילִין, דִּי מְמָנָן עַל דִּינָא, לְשָׁאֲלָא הֵיךְ אִתְגְזַר דִּינָא בְּעָלְמָא. כָּל אִינּוּן דִּינִין דְּלָא אִתְיְיהִיבוּ בְּפִתְקִין, לְקִיּוּמָא דְּעָלְמָא, וְעַל דָּא כֻּלְּהוּ אַתְיָין לְשָׁאֲלָא. וּבְגִין כַּךְ כֻּלְּהוּ מְמָנָן עַל דָּא.</p>\n<p>אִינּוּן תְּלָתִין וּתְרֵין אַחֲרָנִין, אִינּוּן מְמָנָן עַל כָּל אִינּוּן דְּלָעָאן בְּאוֹרַיְיתָא תָּדִיר, וְלָא פַּסְקֵי בִּימָמָא וּבְלֵילְיָא, וְאִלֵּין אַחֲרָנִין כֻּלְּהוּ דִּתְחוֹתַיְיהוּ, אִינּוּן מְמָנָן עַל כָּל אִינּוּן דְּקַבְעִין זִמְנִין יְדִיעָאן לְאוֹרַיְיתָא. וְעַל דָּא אִינּוּן מְמָנָן כֻּלְּהוּ, וּלְאַעְנְשָׁא כֻּלְּהוּ, לְכָל אִינּוּן דְּיַכְלֵי לְאִשְׁתַּדְלָא בְּאוֹרַיְיתָא, וְלָא מִשְׁתַּדְלֵי.</p>\n<p>הֵיכָלָא חֲמִישָׁאָה. הֵיכָלָא דָּא, קַיְימִין בֵּיהּ תְּלַת מֵאָה וְשִׁתִּין וְחָמֵשׁ מְמָנָן, כְּחוּשְׁבָן יְמֵי שַׁתָּא. וְעֵילָּא מִנַּיְיהוּ אַרְבַּע סַמְכִין עִלָּאִין עַל כֻּלְּהוּ. וְאִלֵּין אִינּוּן: קְרָשִׁיהָאֵ\"ל. סַרְטִיהָאֵ\"ל. עֲסִירִיָּ\"ה. קַדְמִיאֵ\"ל. וְאִלֵּין אִקְרוּן יְתֵדוֹת דְּהֵיכָלָא דָּא.</p>\n<p>אִלֵּין אִתְמְנוּן לְבַדְחָא עָלְמָא (אלין). כַּד נִשְׁמְתָא אִתוֹסְפָת מֵעֶרֶב שַׁבָּת לְעֶרֶב שַׁבָּת. וְאִיהִי נַפְקַת, כַּד אִיהִי נַפְקַת, נָפְקִין אִלֵּין עִמָּהּ, וּמְעַבְרֵי מִיִשְׂרָאֵל כָּל עֲצִיבוּ, וְכָל יְגִיעָא, וְכָל מְרִירוּ דְּנַפְשָׁא, וְכָל רוּגְזָא דְּעָלְמָא, וְאִלֵּין אִינּוּן בְּדִיחֵי עָלְמָא.</p>\n<p>כָּל אִינּוּן דִּלְתַתָּא מֵאִלֵּין אַרְבָּעָה, כֻּלְּהוּ אִתְמָנוּן לְאַעְבְּרָא דִּינָא, מֵאִינּוּן מָארֵי דְּדִינָא, וּמֵאִינּוּן דְּטַרְדֵי לוֹן בְּגֵיהִנָּם, דִּיסַלְקוּן דִּינָא מִנַּיְיהוּ. וְעַל דָּא, כָּל אִלֵּין יְתֵדוֹת כֻּלְּהוּ קַיְימֵי בְּחֶדְוָה, וּמֵחֶדְוָה נַפְקֵי, וְכֻלְּהוּ הֵיכָלִין קַיְימֵי לְאִתְעַטְרָא לְעֵילָּא. כְּמָה דְּאִתְּמַר.</p>\n<p>הֵיכָלָא שְׁתִיתָאָה. הֵיכָלָא דָּא, הֵיכָלָא דְּקַיְּימָא עַל כָּל הֵיכָלִין תַּתָאִין. בְּהַאי, מֵאָה אַחֲרָנִין דְּקַיְּימָאן לְבַר, דְּאִקְרוּן יְתֵדוֹת כְּאִינּוּן אַחֲרָנִין. וְאִינּוּן מֵאָה לִסְטַר יְמִינָא, וּמֵאָה אַחֲרָנִין לִסְטַר שְׂמָאלָא.</p>\n<p>תְּרֵין מְמָנָן עִלָּאִין לִסְטַר יְמִינָא, וּתְרֵין מְמָנָן אַחֲרָנִין עִלָּאִין לִסְטַר שְׂמָאלָא. אִלֵּין דִּימִינָא אִינּוּן: מַלְכִּיאֵ\"ל. שְׁמַעְיָהאֵ\"ל. וְאִלֵּין דִּשְׂמָאלָא, אִקְרוּן מִסַרְסָנִיָּ\"הּ. צַפְצָפִיָּ\"הּ. אִלֵּין אִינּוּן יְתֵדוֹת עִלָּאִין, מִימִינָא וּמִשְּׂמָאלָא.</p>\n<p>וְאִלֵּין אִינּוּן קַיְימֵי וּזְמִינִין בְּעָלְמָא. בְּהַהוּא זִמְנָא, דְּצַדִּיקָא מָטָא זִמְנֵיהּ לְאִסְתַּלְּקָא מֵעָלְמָא, וְאִתְיְיהִיב רְשׁוּ לְסִטְרָא אַחֲרָא. אִלֵּין אַרְבַּע קַיְימֵי לְאִתְעַתְדָא תַּמָּן, בְּגִין דְּתִפוּק נִשְׁמָתֵיהּ בִּנְשִׁיקָה, וְלָא תִּצְטַעֵר בְּשׁוּלְטָנוּ דְּסִטְרָא אַחֲרָא. זַכָּאִין אִינּוּן צַדִיקַיָּיא בְּעָלְמָא דֵּין, וּבְעָלְמָא דְּאָתֵי. דְּמָארֵיהוֹן אַקְדִים עָלַיְיהוּ שׁוּלְטָנֵיהוֹן, לְמֶהֱוִי נְטִירָן בְּעָלְמָא דֵּין, וּבְעָלְמָא דְּאָתֵי.</p>\n<p>מֵהֵיכָלָא דָּא, שָׁרָאן כָּל רָזִין, וְכָל דַּרְגִין עִלָּאִין וְתַתָאִין, לְאִתְחַבְּרָא. בְּגִין דְּיִשְׁתְּכַח כֹּלָּא עֵילָּא וְתַתָא בִּשְׁלִימוּ, לְמֶהוֵי כֹּלָּא חַד, וְחִבּוּרָא חַד, לְאִתְיַיחֲדָא שְׁמָא קַדִישָׁא כְּדְקָא יֵאוֹת, וּלְאִשְׁתַּלְמָא, לְאַנְהָרָא נְגִידוּ עִלָּאָה בְּתַתָאָה, (נ\"א לנגדא נהירי עלאה לתתא) וּנְהִירוּ דְּבוּצִינִין כְּחָד, (נ\"א ונהרי בוצינין כולהו כחדא) דְּלָא תַּעְדֵי דָּא מִן דָּא. וּכְדֵין נָגִיד וְאִתְמְשַׁךְ מַאן דְּאִתְמְשָׁךְ, דְּלָא אִתְיְדַע וְלָא אִתְגַלְיָיא, בְּגִין דְּיִתְקָרֵב (נ\"א דיתקדש) <Nonei></i>וְיִתְיַיחֵד דָּא עִם דָּא, לְמֶהֱוֵי כֹּלָּא בְּיִחוּדָא שְׁלִים כְּדְקָא יֵאוֹת.</p>\n<p>זַכָּאָה חוּלָקֵיהּ, מַאן דְּיָדַע בְּרָזִין דְּמָארֵיהּ, לְאִשְׁתְּמוֹדְעָא לֵיהּ כְּדְקָא יֵאוֹת. דְּהָא אִינּוּן אַכְלִין חוּלָקֵיהוֹן בְּעָלְמָא דֵּין, וּבְעָלְמָא דְּאָתֵי. עַל דָּא כְּתִיב (ישעיהו ס״ה:י״ג) הִנֵּה עֲבָדַי יֹאכֵלוּ. זַכָּאִין אִינּוּן צַדִיקַיָּיא דְּמִשְׁתַּדְלֵי בְּאוֹרַיְיתָא יְמָמָא וְלֵילֵי. בְּגִין דְּאִינּוּן יַדְעֵי אוֹרְחוֹי דְקוּדְשָׁא בְּרִיךְ הוּא, וְיַדְעֵי לְיַחֲדָא יִחוּדָא קַדִּישָׁא כְּדְקָא יֵאוֹת, דְּכָל דְּיָדַע לְיַחֲדָא שְׁמָא קַדִּישָׁא בִּשְׁלִימוּ כַּדְקָא חֲזֵי, זַכָּאָה אִיהוּ בְּעָלְמָא דֵּין, וּבְעָלְמָא דְּאָתֵי.</p>\n<p>קִשּׁוּרָא דְּכָל הָנֵי הֵיכָלִין, הָכָא מִתְקַשְּׁרָן. (יעקב קשירו דכל מהימנותא רוח דקיימא לקבלא רוח דאיהו לתתא והאי רוחא דאיהו לעילא קיימא לקבלא רוח עילאה דכל רוחין קיימין ביה דא איהו יעקב דאיהו רוח אמצעיתא דכל רוחין ואיהו נטיל האי היכלא שתיתאה באינון נשיקין לאתדבקא רוחא ברוחא כמה דאת אמר (שיר השירים א׳:ב׳) ישקני מנשיקות פיהו, וכל נשיקה איהו (ס\"א הכא קשירו דכל מהימנותא יעקב דאיהו רוח אמצעיתא דכל רוחין איהו נטיל האי היכלא שתיתאה באינון נשיקין)) לְאִתְדַּבְּקָא רוּחָא בְּרוּחָא, תַּתָאָה בְּעִלָּאָה. וּבְאִלֵּין נְשִׁיקִין אִסְתָּלַּק רוּחָא דִּלְתַתָא לְאִתְדַּבְּקָא בְּרוּחָא דִּלְעֵילָּא. וְכַד מִתְדַּבְּקָן רוּחָא בְּרוּחָא, כְּדֵין רוּחָא עִלָּאָה סְתִימָאָה שָׁאֲרִי עַל הַאי רוּחָא דְּאֶמְצָעִיתָא. וְעַד לָא אַתְעַר לְאִתְדַּבְּקָא רוּחָא בְּרוּחָא, רוּחָא עִלָּאָה. לָא שַׁרְיָא עַל (ההיא) רוּחָא דְּאֶמְצָעִיתָא.</p>\n<p>וְרָזָא דָּא, כַּד אִתְאֲחִיד רוּחָא בְּרוּחָא, כְּדֵין שָׁרָאן נְשִׁיקִין לְאִתְחַבְּרָא וּמִתְעָרִין שְׁאַר שַׁיְיפִין בְּתִיאוּבְתָא, וְרוּחָא דָּא מִתְדַּבְּקָא בְּדָא. וּכְדֵין, שַׁיְיפִין כֻּלְּהוּ מִתְעָרֵי אִלֵּין בְּאִלֵּין, לְאִתְקַשְּׁרָא שַׁיְיפָא בְּשַׁיְיפֵיהּ.</p>\n<p>וְאִי תֵּימָא, מַאן אַתְעַר שַׁיְיפֵי תַּתָאֵי, אוֹ שַׁיְיפֵי עִלָּאֵי. שַׁיְיפֵי תַּתָאֵי מִתְעָרֵי תָּדִיר לְגַבֵּי עִלָּאֵי, מַאן דְּאִיהוּ בַּחֲשׁוֹכָא, תָּאִיב תָּדִיר לְמֶהֱוֵי בִּנְהוֹרָא. שַׁלְהוֹבָא אוּכָמָא דִּלְתַתָא, אַתְעַר תָּדִיר לְגַבֵּי (בראשית נ\"א ע\"א) שַׁלְהוֹבָא חִוָּורָא דִּלְעֵילָּא, בְּגִין לְאִתְדַּבְּקָא בֵּיהּ, וּלְמִשְׁרֵי תְּחוֹתֵיהּ, וְרָזָא דָּא, (תהלים פג א) אֱלהִים אַל דֳּמִי לָךְ אַל תֶּחרַשׁ וְאַל תִּשְׁקוֹט אֵל.</p>\n<p>כַּד נָטִיל יַעֲקֹב הַאי הֵיכָלָא שְׁתִיתָאָה, כְּדֵין אִקְרֵי (רי\"ג ע\"א) בִּשְׁמָא קַדִישָׁא עִלָּאָה שְׁלֵימָא, וַיְיָ'. וְאִי תֵּימָא שְׁלֵימָא דְּכֹלָּא. לָאו הָכִי, אֶלָּא כַּד אִשְׁתְּלִימוּ כֻּלְּהוּ הֵיכָלִין אִלֵּין בְּאִלֵּין, כְּדֵין אִקְרֵי כֹּלָּא בִּשְׁמָא שְׁלִים, יְדוָֹ\"ד אֱלהִים. וְדָא הוּא (רנ\"ח ע\"ב, בראשית ע\"ח ע\"א) שְׁמָא שְׁלִים מִכֹּלָּא. וְעַד לָא אִתְחַבְּרוּ דָּא עִם דָּא, הֵיכָלִין בְּהֵיכָלִין, לָא אִקְרֵי בִּשְׁמָא שְׁלֵימָא דָּא. וְכַד מִתְחַבְּרָן כַּחֲדָא אִלֵּין בְּאִלֵּין, כְּדֵין אִשְׁתְּלִים כֹּלָּא מֵעֵילָּא וְתַתָא. וּנְהִירוּ דְּעֵילָּא לְעֵילָּא, נַחְתָּא וְשַׁרְיָא עַל כֹּלָּא, וְאִתְקָשַׁר כֹּלָּא כַּחֲדָא, לְמֶהֱוֵי כֹּלָּא חַד.</p>\n<p>וְרָזָא דְּמִלָּה, יַעֲקֹב נָטִיל אַרְבַּע נָשִׁין, וְכָלִיל לוֹן בְּגַוֵיהּ. וְאַף עַל גַּב דְּאוֹקִימְנָא לְהַאי מִלָּה בְּרָזָא אַחֲרָא, דְּאִיהוּ קַיְּימָא בֵּין (ויצא קנ\"ג ע\"ב) תְּרֵין עָלְמִין. וְרָזָא דְּכֹלָּא, כַּד יַעֲקֹב נָטִיל הַאי הֵיכָלָא, דְּאִיהוּ שְׁתִיתָאָה, נָטִיל וְכָלִיל בְּגַוֵּיהּ כָּל אִינּוּן אַרְבַּע נָשִׁין, אַרְבַּע מַלְאָכִין, וְכֻלְּהוּ דַּבְקֵי בְּהֵיכָלָא דָּא. אִלֵּין אִינּוּן (רנ\"ד ע\"א) אַרְבַּע רֵישֵׁי נַהֲרִין, דִּכְתִּיב, (בראשית ב׳:י׳) וּמִשָּׁם יִפָּרֵד וְהָיָה לְאַרְבָּעָה רָאשִׁים. אִלֵּין אַרְבַּע רֵישִׁין, אִינּוּן אַרְבַּע נָשִׁין נָטִיל לוֹן יַעֲקֹב, (כדקאמרן וליה אצטריך ואיהו) נָטִיל הֵיכָלָא דָּא.</p>\n<p>וּכְדֵין אִקְרֵי הַאי הֵיכָלָא וַיְיָ', כַּד אִיהוּ לְטָב כְּמָה דְאַתְּ אָמֵר (שמות י״ג:כ״א) וַיְיָ הוֹלֵךְ לִפְנֵיהֶם יוֹמָם. (בראשית י״ח:י״ז) וַיְיָ' אָמָר הַמְכַסֶּה אֲנִי מֵאַבְרָהָם. וְכַד אִתְחֲבָּר יִצְחָק, בְּהֵיכָלָא דְּבֵי דִּינָא, דְּאִקְרֵי זְכוּתָ\"א, כְּדֵין אִקְרֵי כֹּלָּא וַיְיָ', לְאַעְנְשָׁא לְחַיָּיבַיָּא, כְּמָה דְאַתְּ אָמֵר (בראשית י״ט:כ״ד) וַיְיָ' הִמְטִיר עַל סְדוֹם וְגוֹ', וְכֹלָּא בְּרָזָא חֲדָא כְּדְקָא יֵאוֹת.</p>\n<p>וְכַד יַעֲקֹב נָטִיל הֵיכָלָא דָּא, כְּדֵין אִקְרֵי כֹּלָּא רָצוֹן שָׁלוֹם. (וסימניך (אסתר ב׳:ט״ו) ובהגיע תור אסתר) וְדָא הוּא עֵת רָצוֹן. וּמִכָּאן וּלְהָלְאָה, שָׁרָאן הֵיכָלִין לְאִתְחַבְּרָא וּלְאִתְקַשְּׁרָא אִלֵּין בְּאִלֵּין. וְאַף עַל גַּב דְּתָנֵינָן (ויקרא ק\"כ ע\"א) דְּרוֹמִית מִזְרָחִית. וְכֹלָּא אִיהוּ כַּחֲדָא, הָכָא אִיהוּ רוּחָא בְּרוּחָא, דְּבֵקוּתָא חֲדָא.</p>\n<p>מִכָּאן שָׁרֵי אַבְרָהָם, דְּאִיהוּ יְמִינָא, דְּאִקְרֵי אַהֲבָה (רבה דקאמרן. ואיהו נטיל היכלא דאקרי אהב\"ה). כְּדֵין, (יחזקאל ט״ז:ז׳) שָׁדַיִם נָכוֹנוּ, וְאִתְמַלְּיָין מִכָל טוּב, לְסַפָּקָא וּלְאַתְזְנָא כֹּלָּא מֵהָכָא. וְכַד אִלֵּין (פקודי רנ\"ג ע\"א) שָׁדַיִם נָכוֹנוּ וְאִתְמַלְּיָין מִגוֹ רְחִימוּ עִלָּאָה, כְּדֵין אִקְרֵי הֵיכָלָא דָּא אֵל שַׁדַּ\"י כִּדְקַאמְרָן. וּבְהַאי אִסְתַּפָּק כָּל <Nonei></i>עָלְמָא כַּד אִתְבְּרֵי. דְּהָא כַּד אִתְבְּרֵי עָלְמָא, לָא יָכִיל לְמֵיקָם בְּקִיּוּמָא, וְלָא הֲוָה קָאִים, עַד דְּאִתְגְּלֵי הֵיכָלָא דָּא דְּנָטִיל אַבְרָהָם, וְכַד אִתְגְּלֵי אַבְרָהָם בְּהַאי הֵיכָלָא, (נ\"א כדי לעלמא דיהא ספוקא וכו') כְּדֵין אָמַר לְעָלְמָא דַּי, הָא סִפּוּקָא לְאַתְזְנָא מִנֵּיהּ עָלְמָא וּלְאִתְקַיְּימָא. וּבְגִין כָּךְ, אֵל שַׁדַּי אִקְרֵי, אֵ\"ל שַׁדַּ\"י לְכֹלָּא בֵּיהּ. (נ\"א ולאתזנה מניה תא חזי היכלא דא זמין וכו').</p>\n<p>וְזַמִּין קוּדְשָׁא בְּרִיךְ הוּא לְמַלְיָּא לֵיהּ, (נ\"א ביה) וּלְאַתְקְנָא לֵיהּ לְזִמְנָא דְּאָתֵי דִּכְתִיב (ישעיהו ס״ו:י״א) לְמַעַן תִּינְקוּ וּשְׂבַעְתֶּם מִשֹּׂד תַּנְחֻמֶיהָ לְמַעַן תָּמוֹצּוּ וְהִתְעַנַּגְתֶּם מִזִּיז כְּבוֹדָהּ. שֹׁד תַּנְחֻמֶיהָ וְזִיז כְּבוֹדָהּ, כֹּלָּא אִיהוּ בְּהַאי הֵיכָלָא. וּכְדֵין בְּהַהוּא זִמְנָא כְּתִיב, (בראשית כ״א:ז׳) מִי מִלֵּל לְאַבְרָהָם הֵנִיקָה בָנִים שָׂרָה, דְּהָא יְנִיקָא תַּלְיָא בֵּיהּ בְּאַבְרָהָם.</p>\n<p>יִצְחָק דְּאִיהוּ שְׂמָאלָא דְקוּדְשָׁא בְּרִיךְ הוּא, אֲתָר דְּמִנֵּיהּ מִתְעֲרִין כָּל דִּינִין דְּעָלְמָא, וְאִיהוּ דְּרוֹעָא דִּשְׂמָאלָא, שֵׁירוּתָא דְּכָל דִּינִין, וְכָל דִּינִין מִתְעָרֵי מִתַמָּן, הַאי אִיהוּ נָטִיל וְאָחִיד הַהוּא הֵיכָלָא דְּאִקְרֵי זְכוּתָא, לְאִתְחַבְּרָא דִּינָא בְּדִינָא, וּלְמֶהֱוֵי כֹּלָּא קִשּׁוּרָא חֲדָא, בְּגִין דְּהַאי אִיהוּ דִּינָא דִּלְעֵילָּא, וּרְשִׁימִין דְּדִינִין קַיְימִין בֵּיהּ.</p>\n<p>וְהָכָא אִתְרְשִׁים שְׁמָא קַדִישָׁא, דְּאִקְרֵי אֱלהִים. בְּגִין דְּאִית אֱלהִים חַיִּים, דְּאִיהוּ לְעֵילָּא לְעֵילָּא, סָתִים מִכֹּלָּא. וְאִית אֱלהִים, דְּאִיהוּ בֵּי דִּינָא דִּלְעֵילָּא. וֵאלֹהִים, דְּאִיהוּ בֵּי דִּינָא דִּלְתַתָא. הֲדָא הוּא דִכְתִיב, (תהילים נ״ח:י״ב) אַךְ יֶשׁ אֱלהִים שׁוֹפְטִים בָּאָרֶץ. אֱלהִים עִלָּאָה, רָזָא דֶּאֱלֹהִים חַיִּים, כָּלִיל לְאִלֵּין דִּלְתַתָא, וְכֹלָּא אִיהוּ חַד.</p>\n<p>בְּהַאי הֵיכָלָא, אַתְעַר יִצְחָק, וְכֻלְּהוּ שִׁבְעִין וּתְרֵין נְהוֹרִין דִּכְלִילָן בֵּיהּ, דְּמִנַּיְיהוּ אִתְגְּזָרוּ כָּל דִּינִין (ס\"א דעלמא דלתתא) דִּלְתַתָא דְּעָלְמָא, דִּכְתִּיב, (דניאל ד׳:י״ד) בִּגְזֵרַת עִירִין פִּתְגָּמָא. וַאֲמַאי אִקְרוּן עִירִין. אֶלָּא בְּגִין דְּכֻלְּהוּ קַיְימִין בְּהַאי עִיר. (תהילים מ״ח:ט׳) עִיר יְיָ' צְבָאוֹת. עִיר אֱלהֵינוּ. כָּל אִינּוּן הֵיכָלִין לְעֵילָּא, כָּל חַד וְחַד אִקְרֵי עִיר, כְּמָה דְאַתְּ אָמֵר (דניאל ד׳:י׳) עִיר וְקַדִּישׁ. וְאִלֵּין אִינּוּן עִירִין, דְּקַיְימִין לְגוֹ בְּגוֹ דְּהֵיכָלָא, דְּקַיְימִן בְּעִיר, בְּגִין כָּךְ אִקְרוּן עִירִי\"ן.</p>\n<p>הַאי הֵיכָלָא, אִתְכְּלִיל בְּיִצְחָק, וְכֹלָּא אִיהוּ בְּהֵיכָלָא דְּאַבְרָהָם, בְּגִין דִּימִינָא אַכְלִיל לִשְׂמָאלָא. וְתָא חֲזֵי, כָּל חַד וְחַד כָּלִיל לְחַבְרֵיהּ. וְהָא אוֹקִימְנָא, דְּבְּגִין דָּא אַבְרָהָם עָקַד לְיִצְחָק, בְּגִין לְאַכְלְלָא בֵּיהּ דִּינָא, (נ\"א בימינא) וּלְאִשְׁתַּכְחָא שְׂמָאלָא כָּלִיל בִּימִינָא (ס\"א ולאשתכחא ימינא על שמאלא ולאשלטא וכו') וּלְאַשְׁלְטָא יְמִינָא עַל שְׂמָאלָא.</p>\n<p>וְעַל דָּא קוּדְשָׁא בְּרִיךְ הוּא פָּקִיד לֵיהּ לְאַבְרָהָם, לְקָרְבָא בְּרֵיהּ לְדִינָא, וּלְאַתְקָפָא עֲלוֹי, וְלָא פָּקִיד לְיִצְחָק, אֶלָּא לְאַבְרָהָם. וְעַל דָּא אִשְׁתְּכַח, דָּא בְּדִינָא, וְדָא בְּחֶסֶד, וְכֹלָּא חַד, וְאִתְכְּלִיל דָּא בְּדָא. וְהָכִי, אִתְכְּלִילוּ הֵיכָלִין תַּתָאִין בְּעִלָּאִין.</p>\n<p>כַּד נָטִיל יִצְחָק הֵיכָלָא דָּא, כְּדֵין כֹּלָּא אִיהוּ לְטָב. דִּינָא בִּזְכוּתָא. וְעַל דָּא, בָּעֵי בַּר נָשׁ דְּדָאִין דִּינָא, לְמֵידָן דִּינָא בִּזְכוּתָא. בְּגִין דְּאִיהוּ רָזָא עִלָּאָה, שְׁלִימוּ דְּדִינָא. בְּגִין דְּלֵית שְׁלִימוּ דְּדִינָא, אֶלָּא בִּזְכוּתָא, דָּא בְּלָא דָּא לָאו אִיהוּ שְׁלִימוּ. דִּינָא בִּזְכוּתָא, דָּא אִיהוּ שְׁלִימוּ דִּמְהֵימְנוּתָא, כְּגַוְונָא דִּלְעֵילָּא.</p>\n<p>בְּיוֹמָא דְרֹאשׁ הַשָּׁנָה, כַּד דִּינָא אַתְעַר בְּעָלְמָא, בָּעָאן יִשְׂרָאֵל לְתַתָא, לְאַתְעֲרָא רַחֲמֵי מִגּוֹ שׁוֹפָר, כְּגַוְונָא דְּרָזָא עִלָּאָה. וְהָא אוֹקִימְנָא. וּבָעֵינָא לְחַבְּרָא דִּינָא לָקֳבֵל זְכוּתָא, בְּגִין דְּכַד קַיְּימָא דִּינָא בִּזְכוּתָא, כֹּלָּא אִיהוּ בְּחִבּוּרָא חֲדָא. וְעֵילָּא וְתַתָא בִּשְׁלִימוּ. וּכְדֵין, (איוב ה׳:ט״ז) וְעוֹלָתָה קָפְצָה פִּיהָ, דְּלֵית לָהּ רְשׁוּ לְאַסְטָאָה וּלְקַטְרְגָא בְּעָלְמָא. וּכְדֵין כֹּלָּא בְּיִחוּדָא חֲדָא כְּדְקָא יֵאוֹת. וְדִינָא בְּלָא זְכוּ לָאו אִיהוּ דִּינָא.</p>\n<p>וְדָא אִיהוּ דְּיִשְׂרָאֵל, דְּאִית לוֹן דִּינָא בִּזְכוּתָא. אֲבָל שְׁאַר עַמִּין, לָא אִית לוֹן דִּינָא בִּזְכוּתָא, וְעַל דָּא אָסִיר לָן, לְסַדְּרָא דִּינִין דִּילָן בְּעַרְכָּאֵי דְּעַמִּין עוֹבְדֵי עֲבוֹדָה זָרָה, דְּהָא לֵית לוֹן חוּלָקָא בִּסְטָר מְהֵימְנוּתָא דִּילָן. דִּכְתִיב, (תהילים קמ״ז:כ׳) לָא עָשָׂה כֵן לְכָל גּוֹי וּמִשְׁפָּטִים בַּל יְדָעוּם. וּמִסִּטְרָא דְּיִשְׂרָאֵל כָּל מַאן דְּדָאִין דִּינָא, וְלָא אַכְלִיל בֵּיהּ זְכוּת, דָּא אִיהוּ חָטֵי, דְּקָא גָּרַע רָזָא דִּמְהֵימְנוּתָא, וְאַסְטֵי גַּרְמֵיהּ לְהַהוּא סִטְרָא, דְּאִית בֵּיהּ דִּינָא בְּלָא זְכוּת.</p>\n<p>וְתָּא חֲזֵי, כַּד קַיְימֵי סַנְהֶדְרִין לְתַתָא, לְמֵידָן דִּינֵי נְפָשׁוֹת, אִצְטְרִיכוּ לְמִפְתַח בִּזְכוּתָא. בְּגִין לְאַכְלְלָא זְכוּתָא בְּדִינָא. וְתוּ, דְּהָא אִקְרוּן מִבֵּי (רנ\"א ע\"א) זְכוּתָא. וְעַל דָּא, אִשְׁתַּדְּלוּתָא דִּילְהוֹן, לְמִפְתַּח בִּזְכוּתָא, וְשָׁרָאן בִּזְכוּתָא מִזְּעֵירָא, וּלְבָתַר אִשְׁתְּלִים דִּינָא מֵעִלָּאָה. לְמֶהֱוֵי זְכוּתָא כָּלִיל בְּדִינָא. דָּא לְעֵילָּא, וְדָא לְתַתָא. דִּינָא בִּזְכוּתָא, שְׁלִימוּ דְּדִינָא. דָּא בְּלָא דָּא, לָאו אִיהוּ שְׁלִימוּ. וּבְגִין כַּךְ, יִצְחָק <Nonei></i>וְרִבְקָה כַּחֲדָא אִינּוּן, דָּא דִּינָא, וְדָא זְכוּתָא, לְמֶהֱוֵי שְׁלִימוּ כַּחֲדָא. זַכָּאָה חוּלָקֵיהוֹן דְּיִשְׂרָאֵל, דְּקוּדְשָׁא בְּרִיךְ הוּא יָהַב לוֹן אוֹרַיְיתָא שְׁלֵימָתָא, לְמֵיהַךְ בְּאֹרַח קְשׁוֹט, כְּגַוְונָא דִּלְעֵילָּא.</p>\n<p>תָּא חֲזֵי, דְּאִינּוּן לָא דַּיְינִין דִּינָא, אֶלָּא בִּזְכוּ, וּלְעַיְינָא זְכוּתָא בְּקַדְמִיתָא, לְמֶהוֵי כָּלִיל דָּא בְּדָא. וְסַנְהֶדְרִין קָא מְהַפְּכֵי בִּזְכוּתָא בְּדִינָא, לְאַכְלְלָא כֹּלָּא כַּחֲדָא, בְּגִין דְּלָא יִשְׁלוֹט סִטְרָא אַחֲרָא. דְּהָא כַּד זְכוּתָא לָא אִשְׁתְּכַח, סִטְרָא אַחֲרָא אִשְׁתְּכַח, דְּאִקְרֵי חוֹבָה, וְאִתְחֲבְּרַת בְּדִינָא, וְאִתַתְקְפַת וְדָא הוּא דִּינָא בְּחוֹבָה.</p>\n<p>וְעַל דָּא, בְּיוֹמָא דְּרֹאשׁ הַשָּׁנָה, בָּעֵינָא לְחַבְּרָא זְכוּתָא בְּדִינָא, וְלָא יִתְגַּבָּר חוֹבָה. וּבְגִין כַּךְ, בָּעֵינָא זְכוּתָא וְדִינָא לְמֶהֱוֵי כַּחֲדָא, בְּגִין דְּאִיהוּ שְׁלִים. דְּכַד סִטְרָא אַחֲרָא שַׁלְטָא, לָאו אִיהוּ שְׁלִים, אֶלָּא קִטְרוּגָא, כְּמָה דְּאִיהוּ קִטְרוּגָא, וְאִינּוּן אַרְבַּע מִיתוֹת, וְכַד סִטְרָא דְּאִיהוּ זְכוּת שַׁלְטָא, כֹּלָּא אִיהוּ שְׁלִים, (מלכים ב כ׳:י״ט) שָׁלוֹם וְאֱמֶת (תהילים ק״ג:ד׳) חֶסֶד וְרַחֲמִים.</p>\n<p>וְכַד אִתְחַבְּרַת סִטְרָא אַחֲרָא בְּדִינָא, שַׁלְטָא בְּקִטְרוּגָא, בְּאִינּוּן אַרְבַּע מִיתוֹת בַיִת דִּין: סְקִילָה, שְׂרֵיפָה, הֶרֶג, וְחֶנְק. כֻּלְּהוּ שׁוּלְטָנוּתָא דְּקִטְרוּגָא בִּישָׁא. סְקִילָה, בְּגִין דְּאִיהוּ (ישעיה ח) אֶבֶן נֶגֶף. שְׂרֵיפָה, בְּגִין דְּאִיהוּ (ישעיהו ח׳:י״ד) צוּר מִכְשׁוֹל, אֶשָּׁא תַּקִיפָא. הֶרְג, דָּא (דברים ל״ב:מ״ב) חֶרֶב תֹּאכַל בָּשָׂר. תֹּאכַל בָּשָׂר וַדָאי, דְּשַׁלְטָא (שלח ק\"ע ע\"א) בְּבִשְׂרָא, וְדָא הוּא (בראשית ו׳:י״ג) קֵץ כָּל בָּשָׂר. חֶנֶק, בְּגִין דְּאִיהוּ (דברים כ״א:כ״ג) קִלְּלַת אֱלֹהִי\"ם, הַהוּא דְּשַׁלְטָא עַל חֶנֶק, עַל צְלִיבוּ. וְאוֹקִימְנָא, בְּגִין דְּלָא יִשְׁתְּאַר אֶלָּא בִּשְׂרָא בִּלְחוֹדוֹי, וְהַהוּא קִלְּלַת אֱלֹהִים, שַׁלְטָא בְּבִשְׂרָא, מָרָה חֲשׁוֹכָא. וּבְגִין כַּךְ, דָּא לְטָב וְדָא לְבִישׁ.</p>\n<p>וְאִצְטְרִיכוּ יִשְׂרָאֵל דְּרָזָא דִּמְהֵימְנוּתָא בְּהוּ, לְאִסְתַּמְרָא, בְּגִין דְּיִשְׁלוֹט סִטְרָא דִּמְהֵימְנוּתָא, וְלָא יַהֲבוּן דּוּכְתָּא לְסִטְרָא אַחֲרָא לְשַׁלְּטָאָה זַכָּאִין אִינּוּן בְּעָלְמָא דֵּין, וּבְעָלְמָא דְּאָתֵי, עָלַיְיהוּ כְּתִיב (ישעיהו ס׳:כ״א) וְעַמֵּךְ כֻּלָּם צַדִּיקִים וְגוֹ'.</p>\n<p>נְבִיאִין, דְּאִינּוּן סִטְרִין עִלָּאִין, תְּרֵין יַרְכִין דְּסַמְכִין לְאוֹרַיְיתָא קַדִישָׁא, אִינּוּן נַטְלִין לְהֵיכָלָא דִּתְרֵין רוּחִין בֵּיהּ, דְּאִינּוּן נֹגַהּ וְזֹהַר. וְאִינּוּן תְּרֵין יַרְכִין לְתַתָא, לְסַמְכָא לְאִינּוּן הֵיכָלִין דִּלְעֵילָּא, דְּאִקְרוּן תּוֹרָה שֶׁבְּעַל פֶּה. כְּמָה דְּאִית סַמְכִין לְאוֹרַיְיתָא דְּאִיהִי תּוֹרָה שֶׁבִּכְתָב, כַּךְ אִית סַמְכִין קַיְימִין לְאוֹרַיְיתָא דְּאִיהִי תּוֹרָה שֶׁבְּעַל פֶּה. וְאִתְכְלִילוּ דָּא בְּדָא. כְּדֵין אִלֵּין תְּרֵין סַמְכִין דִּלְתַתָּא, כַּד מִתְחַבְּרָן בְּאִלֵּין עִלָּאִין, אִתְרְשִׁים בְּהוּ סִטְרָא דִּנְבוּאָה, וּמַאן אִיהוּ. (רמז) מַרְאֶה, דְּאִיהוּ כְּגַוְונָא דִּנְבוּאָה.</p>\n<p>וְכָל אִינּוּן מָארֵיהוֹן דְּמַרְאֶה, מֵהָכָא יַנְקִין. לְעֵילָּא נְבוּאָה, הָכָא מַרְאֶה. וְעַל דָּא, אִיהוּ דָּא כְּגַוְונָא דָּא, וְדָא כְּגַוְונָא דָּא. וְכַד מִתְחַבְּרָן דָּא בְּדָא, כְּדֵין שַׁלִּיט עַל הַאי אֲתָר, (אתרשים) שְׁמָא קַדִישָׁא, דְּאִקְרֵי צְבָאוֹת. בְּגִין דְּכָל אִינּוּן חַיָּילִין קַדִישִׁין, כֻּלְּהוּ קַיְימֵי הָכָא, וְכֻלְּהוּ אִקְרוּן מִסִּטְרָא דִּנְבוּאָה, מַרְאֶה וְחֶלְמָא מִסִּטְרָא דִּנְבוּאָה הֲווֹ.</p>\n<p>וְאַף עַל גַּב דְּקָא אַמְרֵינָן, דִּי בְּגוֹ הַהוּא אוֹת קַיָּימָא קַדִּישָׁא, שַׁרְיָא שְׁמָא דָּא. בְּגִין דְּכֻּלְּהוּ חַיָּילִין נַפְקֵי מֵהַאי אוֹת. עִם כָּל דָּא, יַרְכִין דְּאִינּוּן קַיְימִין לְבַר, קָרֵינָן עַל שְׁמָא דָּא, וְאִלֵּין אִינּוּן דְּאִקְרוּן בָּרַיְיתֵי, דְּהָא בָּרַיְיתָא לְבַר מִמִּשְׁנָה. מַתְנִיתִין קַיְּימָא לְגוֹ בָּרַיְיתֵי, וְאִקְרוּן יַרְכִין בָּתֵּי בָּרָאי, כְּגַוְונָא דִּי לְעֵילָּא.</p>\n<p>מַתְנִיתִין אִיהוּ רָזָא דְּקַיְּימָא לְגוֹ, דְּאוֹלְפֵי תַּמָּן עִקָּרָא דְּכֹלָּא, וְעַל תָנָאֵי, וְרָזָא (דא) דְּהַךְ, (שיר השירים ח׳:ב׳) אֶנְהָגְךָ אֲבִיאֲךָ אֶל בֵּית אִמִּי תְּלַמְּדֵנִי. אֶל בֵּית אִמִּי: דָּא קֹדֶשׁ הַקָּדָשִׁים. תְּלַמְּדֵנִי: דָּא הוּא רָזָא דְּמַתְנִיתִין. דְּכַד עָאל דָּא נָהָר דְּנָגִיד וְנָפִיק, בְּהַהוּא בֵּית קֹדֶשׁ הַקָּדָשִׁים, כְּתִיב תְּלַמְּדֵנִי. וְדָא הוּא רָזָא, דְּאִקְרֵי מִשְׁנָה. כְּמָה דְאַתְּ אָמֵר (דברים י״ז:י״ח) אֶת מִשְׁנֵה הַתּוֹרָה הַזֹּאת.</p>\n<p>כַּד אִתְמַשְּׁכָא לְבַר, אִקְרֵי בָּרַיְיתָא. תְּרֵין יַרְכִין אִינּוּן בָּרַיְיתֵי, רָזָא דְּרָזִין דְּלָא אִתְיְיהִיב לְאִתְגַּלָּאָה. בְּגִין דְּלָא אִתְמְסַר רָזָא בַּר לְחַכִּימֵי עֶלְיוֹנִין. וַוי אִי אִתְגְּלֵי, וַוי אִי לָא אִתְגְּלֵי, בְּגִין דְּאִיהוּ רָזָא מֵרָזִין עִלָּאִין דְקוּדְשָׁא בְּרִיךְ הוּא אַנְהִיג בֵּיהּ עָלְמָא.</p>\n<p>בַּיִת רִאשׁוֹן קַיְּימָא בִּימֵי שְׁלֹמֹה, לָקֳבֵל עָלְמָא עִלָּאָה, וְאִיהוּ אִקְרֵי בַּיִת רִאשׁוֹן, וְאִשְׁתָּמַשׁ כֹּלָּא בְּבֵית קֹדֶשׁ הַקָּדָשִׁים, אֲתָר דְּאִשְׁתַּמֵּשׁ בֵּיהּ שִׁמְשָׁא <Nonei></i>בְּסִיהֲרָא. וְרָזִין עִלָּאִין כֻּלְּהוּ בִּשְׁלִימוּ, וְקַיְּימָא עָלְמָא בְּאַשְׁלְמוּתָא. וּלְבָתַר גָּרְמוּ חוֹבִין, וְאִתְמְשָׁכוּ רָזִין, וְאִתְדַּחְיָין מִבֵּית קֹדֶשׁ הַקָּדָשִׁים לְבַר. כַּד אִתְדָּחוּ לְיַרְכִין, כְּדֵין קַיְימוּ לְבַר, דְּאִקְרוּן בָּתֵּי בָּרָאי, וְאִצְטְרִיכוּ לְבָרַיְיתֵי.</p>\n<p>בַּיִת שֵׁנִי קַיְימוּ בְּבָתֵּי בָּרָאי בְּיַרְכִּין, וּמִנַּיְיהוּ אָהַדְרוּ וְשָׁאֲרוּ (האי) בְּבֵית קֹדֶשׁ הַקָּדָשִׁים וְאִיהוּ בַּיִת שֵׁנִי. וְאִינּוּן אַחֲרָנִין אִשְׁתָּאֲרוּ בְּבָרַיְיתָא לְבַר, בֵּינֵי יַרְכִין. (ס\"א והני עקרא דלהון מתניתין דאיהו בית שני וברייתא אינון דשרו בבי ירכין והוו וכו') וַהֲווּ אוֹלְפִין מִמַּתְנִיתִין, וְאִתְנְהִיגוּ מִינָּהּ, וְהַיְינוּ רָזָא דִּכְתִּיב, (ישעיהו ב׳:ג׳) כִּי מִצִּיּוֹן תֵּצֵא תּוֹרָה.</p>\n<p>וּלְבָתַר כַּד גָּרְמוּ חוֹבִין, אִתְעָדֵי שׁוּלְטָנוּתָא דְּהַאי בַּיִת שֵׁנִי, (ואף על גב) דְּשׁוּלְטָנָא דִּילֵיהּ לָא הֲוָה כְּבַיִת רִאשׁוֹן, דְּהֲוָה בֵּיהּ שְׁלָמָא תָּדִיר, בְּגִין דְּמַלְכָּא דִּשְׁלָמָא דִּילֵיהּ תָּדִיר הֲוָה בְּגַוֵּויהּ, וְעַל דָּא הֲוָה בִּשְׁלָם. בַּיִת שֵׁנִי לָא הֲוָה בֵּיהּ שְׁלָם הָכִי, בְּגִין דְּעָרְלָה קִטְרוּגָא בֵּיהּ תָּדִיר, וְעַל דָּא הֲווֹ כַּהֲנֵי זְמִינִין בְּגַוֵּיהּ, לְקַטְרְגָא בְּהַאי עָרְלָה, וּלְהוּ אִצְטְרִיךְ מִלָּה, לְקַטְרְגָא בַּהֲדָהּ, וּלְאַגָּנָא עַל בַּיִת שֵׁנִי. וְכֹלָּא בְּרָזָא כַּדְקָא חֲזֵי.</p>\n<p>לְבָתַר גָּרְמוּ חוֹבִין, וְשַׁלְטָא הַהִיא עָרְלָה, וְאִתְדַּחְיָין מִבַּיִת שֵׁנִי לְבַר, וְנַחְתּוּ מִתַּמָּן לְחַמּוּקֵי יַרְכִין, לְתַתָּא, (נ\"א ולבתר נחתי מתמן ואתדחו מאינון חמוקי דלתתא) עַד דִּי שָׁרוּן לְתַתָּא בְּרַגְלִין. וְכַד יִתְבוּן בְּרַגְלִין, כְּדֵין, (זכריה י״ד:ד׳) וְעָמְדוּ רַגְלָיו בַּיוֹם הַהוּא, וְעָלְמָא בְּכֹלָּא יִתְנְהִיג בְּרָזָא עִלָּאָה כַּדְקָא חֲזֵי. וְאַף עַל גַּב דְּאִתְדַּחוּ וְלָא אִשְׁתְּבָקוּ מִנֵּיהּ, וּלְעָלְמִין אִתְאֲחִידוּ בֵּיהּ.</p>\n<p>וּמַאן דְּיָדַע וּמָדִיד בְּשִׁיעוּרָא (רל\"ג ע\"א) דְּקַו הַמִּדָּה, אַרְכָּא דִּמְשִׁיכוּ דְּיַרְכִּין עַד רַגְלִין, יָכִיל לְמִנְדַּע (ויקרא ר\"ס ע\"א) מְשִׁיחָא דְּגָלוּתָא דְּאִתְמְשָׁךְ. וְרָזָא אִיהוּ בֵּין מְחַצְּדֵי חַקְלָא, וְכֹלָּא בְּרָזָא עִלָּאָה. וּבְגִין דָּא, כֻּלְּהוּ בָּרַיְיתֵי, וְכֻלְּהוּ תָּנָאֵי, וְכֻלְּהוּ אֱמוֹרָאֵי, קַיְימֵי בְּדוּכְתַּיְיהוּ כַּדְקָא חֲזֵי, אִלֵּין לְגוֹ, וְאִלֵּין לְבַר, בְּאִינּוּן חַמּוּקֵי יַרְכִין (ואלין לבר) וּלְתַתָּא מְבָרְכִין. וּבְכֻלְּהוּ אִקְרֵי תּוֹרָה שֶׁבְּעַל פֶּה. וּבְכֻלְּהוּ נַחְתֵּי יִשְׂרָאֵל וְאִתְגָּלוּ.</p>\n<p>וּכְדֵין כַּד יִסְתַּיֵים גָּלוּתָא, בִּמְשִׁיכוּ דְּרַגְלִין, כְּדֵין וְעָמְדוּ רַגְלָיו בַּיוֹם הַהוּא, וְיִתְעֲבָר הַהוּא רוּחָא מְסַאֲבָא עָרְלָה מִן עָלְמָא, וְיִתְהַדְרוּן יִשְׂרָאֵל בִּלְחוֹדַיְיהוּ לְשַׁלְּטָאָה כְּדְקָא יֵאוֹת, בְּגִין דְּהַהוּא עָרְלָה, נָחִית לוֹן לְתַתָּא, עַד הַשְׁתָּא. וּמִכָּאן וּלְהָלְאָה, דְּהַאי עָרְלָה אִתְקְצָץ וְאִתְעֲבָר מִגּוֹ עָלְמָא, כְּדֵין (דברים ל״ג:כ״ח) וַיִשְׁכּוֹן יִשְׂרָאֵל בֶּטַח בָּדָד עֵין יַעֲקֹב. בְּהַהוּא עֵין יַעֲקֹב, וְלָא אִשְׁתְּכַח מְקַטְרְגָא עָלַיְיהוּ. זַכָּאָה חוּלָקֵיהוֹן דְּיִשְׂרָאֵל בְּעָלְמָא דֵּין בְּעָלְמָא דְּאָתֵי.</p>\n<p>יוֹסֵף הַצַּדִיק, עַמּוּדָא דְּעָלְמָא, אִיהוּ נָטִיל בִּרְשׁוּתָא הֵיכָלָא טָמִיר וְגָנִיז, וּבִרְשׁוּתֵיהּ קַיְּימָא הֵיכָלָא שְׁבִיעָאָה. וְאַף עַל גַּב דְּקָא אַמָרָן דְּהֵיכָלָא (רמ\"ו ע\"א, רס\"ו ע\"א, בראשית מ\"ה ע\"א) דְּלִבְנַת הַסַּפִּיר בִּרְשׁוּתֵיהּ קַיְּימָא, הָכִי הוּא דְּבֵיהּ מְתַקֵּן. אֲבָל תָּא חֲזֵי, נְבִיאִים דְּקָא אַמָרָן. כַּד מִתְחַבְּרֵי לְתַתָּא, תְּרֵין דַּרְגִּין מִתְפָּרְשִׁין מִנַּיְיהוּ, מַרְאֶה וַחֲלוֹם, וְקַיְימֵי בְּיַרְכִין. בְּאִינּוּן חַמּוּקִין קַיְימֵי מַרְאֶה, וְהַהוּא דְּאִקְרֵי נְבוּאָה קְטַנָּה. מְיַרְכִין וּלְתַתָּא (ס\"א לתתא) (רס\"ב ע\"א רמ\"ז ע\"ב) קָאִים חֲלוֹם, עַד דְּמָאטוּ רַגְלִין בְּרַגְלִין. וְתַמָּן קָאִים הֵיכָלָא תַּתָּאָה וְאִקְרֵי לִבְנַת הַסַּפִּיר.</p>\n<p>כֹּלָּא יַרְכִין בְּיַרְכִין, לְאִשְׁתַּלְּמָא חַד בְּחַד, וְכֻלְּהוּ דַּרְגִּין דִּנְבוּאָה, דְּהָא מִתַּמָּן נַפְקֵי וְשָׁרָאן, וְאִתְעָבִידוּ מִנַּיְיהוּ מַרְאֶה, וְשָׁרָאן עַל הַאי אֲתָר, וְאִתְעָבִיד מִנַּיְיהוּ חֲלוֹם. יוֹסֵף הַצַּדִיק, אִיהוּ שְׁלֵימָא דְּכֹלָּא, אִיהוּ נָטִיל כֹּלָּא. בְּגִין דְּכֹלָּא אִתְקַּן בְּגִינֵיהּ, כֹּלָּא תָּאִיב בְּתִיאוּבְתָּא בְּגִינִיהּ.</p>\n<p>תָּא חֲזֵי, בְּשַׁעֲתָא דְּיוֹסֵף הַצַּדִיק קַיְּימָא לְאַתְקְנָא כֹּלָּא, כְּדֵין אִיהוּ נָטִיל כֹּלָּא. וְכַד אִתְחַבָּר בְּהֵיכָלֵיהּ, כְּדֵין מִתְעָרֵי כֻּלְּהוּ, לְנַטְלָא תִּיאוּבְתָּא וּרְעוּתָא, עִלָּאֵי וְתַתָּאֵי, וְכֹלָּא אִינּוּן בִּרְעוּתָא חֲדָא וּשְׁלִימוּ חַד, לְמֶחְדֵּי (למהוי) עִלָּאֵי וְתַתָּאֵי, רְעוּתָא חֲדָא כְּדְקָא יֵאוֹת. וְכֻלְּהוּ תַּתָּאֵי קַיְימֵי בְּקִיּוּמָא בְּגִינֵיהּ, וְעַל דָּא כְּתִיב, (משלי י׳:כ״ה) וְצַדִּיק יְסוֹד עוֹלָם. וְעַל הַאי יְסוֹדָא קָאִים הַאי עָלְמָא.</p>\n<p>הַאי לִבְנַ\"ת הַסַּפִּי\"ר, לָא קָאִים בְּקִיּוּמֵיהּ, עַד דְּהַאי יוֹסֵף הַצַּדִיק. אִתְתָּקַּן. וְכַד אִיהוּ אִתְתָּקַּן, כֹּלָּא מִתְתַּקְנִי דָּא הוּא יְסוֹדָא דְּכֻּלְּהוּ בִּנְיָינָא. וְעַל דָּא כְּתִיב, (בראשית ב׳:כ״ב) וַיִּבֶן יְיָ' אֱלֹהִים אֶת הַצֵּלָע, וְלָא כְּתִיב וַיִּיצֶר, וְלָא כְּתִיב וַיִּבְרָא. בְּגִין דְּהַאי קַיְּימָא עַל יְסוֹדָא, וּלְבָתַר דִּיְסוֹדָא אִתְקַּן, כֹּלָּא אִתְבְּנֵי <Nonei></i>עָלֵיהּ. וּבְגִין דָּא, כֻּלְּהוּ קַיְימִין בְּהַאי, וְהָא אוֹקִימְנָא.</p>\n<p>תָּא חֲזֵי, כְּתִיב (בראשית ב׳:כ״ב) וַיִּבֶן יְיָ' אֱלֹהִים אֶת הַצֵּלָע, דַּהֲוַת מִסִּטְרָא דְּאֲחוֹרָא, וְאַתְקִין לָהּ לְאָהַדְּרָא אַנְפִּין בְּאַנְפִּין. הָכִי אוֹקִימְנָא. אֲבָל וַיִּבֶן, אִסְתָּכַּל לְסַלְּקָא לָהּ בְּהַהוּא דַּרְגָּא דְּעָלְמָא עִלָּאָה שַׁרְיָא בֵּיהּ, לְמֶהוֵי דָּא כְּגַוְונָא דְּדָא.</p>\n<p>תּוּ וַיִּבֶן, אִסְתָּכַּל בְּסִטְרוֹי, וְאַתְקִין וְכַוִּין כָּל רוּחוֹתֶיהָ, לְמִזְרַע וּלְאַשְׁקָאָה וּלְאוֹלָדָא, לְמֶעְבַּד לָהּ כָּל צָרְכוֹי, כְּמָה דְּאִצְטְרִיךְ. וּלְבָתַר וַיְבִיאֶהָ, בְּמָה. בְּהַאי צַדִּיק. דִּכְתִּיב, (רס\"א ע\"א) (אסתר ב׳:י״ג) וּבָזֶה הַנַּעֲרָה בָּאָה אֶל הַמֶּלֶךְ, דְּהַאי אַמְשִׁיךְ לְכֹלָּא, לְסַלְּקָא לְאִתְעַטְּרָא בִּשְׁלִימוּ. הָכָא מְנִיעוּ דְּכָל חוֹבִין, הָכָא מְנִיעוּ דְּכָל תִּיאוּבְתִּין בִּישִׁין.</p>\n<p>מַה דְּלָא אִיהוּ בְּהַהוּא הֵיכָלָא שְׁתִיתָאָה, בְּסִטְרָא אַחֲרָא, דְּתַמָּן כָּל עִנּוּגִין בִּישִׁין, וְכָל סִטְרִין דְּתִיאוּבְתִּין דְּעִנּוּגָא דְּהַאי עָלְמָא, וְכַד הַאי עָלְמָא אִתְנְהִיג בְּהוּ, בְּנִי נָשָׁא כַּשְׁלֵי בְּהוּ (נ\"א ובגין דבני נשא טעיין בהו כשלין בהו) לְהַהוּא עָלְמָא. דְּחָמָאן כַּמָה עִנּוּגִין וְתִיאוּבְתִּין, דְּגוּפָא אִתְהֲנִי וְאִתְעַנִיג מִנַּיְיהוּ, וְטַעְיָין אֲבַתְרַיְיהוּ. הֲדָא הוּא דִכְתִיב, (בראשית ג׳:ו׳) וַתֵּרֶא הָאִשָּׁה כִּי טוֹב הָעֵץ לְמַאֲכָל וְגוֹ'. דְּהָא כָּל תִּיאוּבְתִּין וְכָל עִנּוּגִין דְּעָלְמָא בֵּיהּ תַּלְיָין.</p>\n<p>וְעַל דָּא, כְּגַוְונָא דָּא, אִית מִלִּין דְּגוּפָא אִתְהֲנֵי בְּהוּ, וְעַיְילֵי לְגוּפָא, וְלָא לְנִשְׁמְתָא. וְאִית מִלִּין דְּנִשְׁמְתָא אִתְהֲנֵי מִנַּיְיהוּ, וְלָא גּוּפָא. וְעַל דָּא, דַּרְגִּין פְּרִישִׁין דָּא מִן דָּא. זַכָּאִין אִינּוּן צַדִּיקַיָּיא, דְּנַטְלֵי אוֹרַח מֵישָׁר, וּמַנְעֵי גַּרְמַיְיהוּ מֵהַהוּא סִטְרָא, וּמִתְדַּבְּקָן בְּסִטְרָא דִּקְדוּשָׁה.</p>\n<p>בְּהֵיכָלָא דָּא, כְּלִילָן כָּל שְׁאַר שְׁמָהָן, דְּכָל אִלֵּין הֵיכָלִין (נ\"א וחיילין) דִּלְתַתָּא. תְּרֵי שְׁמָהָן אִינּוּן דִּכְלִילוּ שְׁאַר שְׁמָהָן אַחֲרָנִין. חַד דְּכַד אִתְחַבָּר עֵילָּא בְּתַתָּא, וְיַעֲקֹב נָטִיל הֵיכָלֵיהּ, בְּאִינּוּן נְשִׁיקִין, בְּרָזָא עִלָּאָה. כְּדֵין כָּלִיל כָּל שְׁאַר שְׁמָהָן, וְאִקְרֵי יְהוָֹ\"ה אֱלהִי\"ם, וְדָא אִקְרֵי שֵׁם מָלֵּא, כְּמָה (בראשית מ\"ח ע\"ב, רמ\"ו ע\"ב) דְּאוֹקִימְנָא. וְחַד, כַּד אִתְחַבָּר יְסוֹדָא דְּעָלְמָא בְּהֵיכָלֵיהּ, וְכֻלְּהוּ מִתְעָרֵי בַּחֲבִיבוּתָא וּבְתִּיאוּבְתָּא לְגַבֵּיהּ, וְכֻלְּהוּ כְּלִילָן בֵּיהּ, כְּדֵין כָּלִיל שְׁאַר שְׁמָהָן, וְאִקְרֵי יְהוָֹ\"ה צְבָאוֹת. וְדָא אִקְרֵי שְׁמָא קַדִּישָׁא שְׁלִים, וְלָאו אִיהוּ שְׁלִים כְּהַאי אַחֲרָא.</p>\n<p>מַה בֵּין הַאי לְהַאי. דָּא שַׁלִּיט עִלָּאָה בְּתַתָּאָה, גּוּפָא בְּגוּפָא (ודא איהו שליט בכלא) כִּדְקַאמְרָן. וְדָא שַׁלִּיט מֵאֲתָר דְּסִיוּמָא דְּגוּפָא וּלְתַתָּא, בְּאִינּוּן הֵיכָלִין וּבְכֹלָּא דִּלְתַתָּא, וְרָזָא דָּא, בַּיִת רִאשׁוֹן וּבַיִת שֵׁנִי. וּבְגִין דָּא, הֵיכָלָא דָּא כָּלִיל כָּל שְׁאַר שְׁמָהָן דִּלְתַתָּא, (וכלהו שמהן כללינן בהאי שמא כולהו שמהן דלתתא) כְּמָה דְּאוֹקִימְנָא. וְעַל דָּא, שְׁמָהָן אִלֵּין, דָּא סַלְּקָא וְדָא נָחִית. זַכָּאִין אִינּוּן צַדִּיקַיָּיא, דְּיַדְעִין אָרְחוֹי דְּאוֹרַיְיתָא.</p>\n<p>יְסוֹדָא דָּא, אִתְתָּקַּן לִתְרֵין סִטְרִין. חַד, לְאַתְקְנָא כָּל שְׁאַר דִּלְתַתָּא. וְחַד, לְאַתְקְנָא הֵיכָלָא שְׁבִיעָאָה, וּלְאַתְקְנָא דָּא בְּדָא, לְמֶהֱוֵי כֹּלָּא רְעוּ חֲדָא כְּדְקָא יֵאוֹת. עַד הָכָא יִחוּדָא דִּתְרֵין סִטְרִין, דִּלְעֵילָּא וְתַתָּא, לְאִתְיַיחֲדָא כַּחֲדָא בִּשְׁלִימוּ, לְמֵיהַךְ בְּאֹרַח מֵישָׁר.</p>\n<p>זַכָּאָה חוּלָקֵיהּ, מַאן דְּיָדַע לְיַחֲדָא יִחוּדָא, וּלְסָדּוּרֵי סִדּוּרָא דִּמְהֵימְנוּתָא, לְמֵיהַךְ בְּאֹרַח מֵישָׁר. זַכָּאָה אִיהוּ בְּהַאי עָלְמָא, וּבְעָלְמָא דְּאָתֵי. וְעַל דָּא כְּתִיב, (תהילים פ״ה:י״א) חֶסֶד וְאֱמֶת נִפְגָּשׁוּ צֶדֶק וְשָׁלוֹם נָשָׁקוּ. וּכְדֵין (תהילים פ״ה:י״ג) אֱמֶת מֵאֶרֶץ תִּצְמָח וְצֶדֶק מִשָּׁמַיִם נִשְׁקָף. גַּם יְיָ' יִתֵּן הַטּוֹב וְאַרְצֵנוּ תִּתֵּן יְבוּלָהּ.</p>"]]});
